(window.QUESTIONS_PARTS = window.QUESTIONS_PARTS || {})["ph6"] = [{"id":"ph6-105-1-1","subject":"ph6","topic":"藥事法規-藥政管理組織與衛生行政","meta":"105年第1次第1題","year":105,"session":1,"number":1,"question":"衛生福利部為提升血液供輸品質，對於避免患者因輸血後發生溶血反應所採取之方法為：","options":["(A) 對捐血人進行紅血球抗原篩檢","(B) 建立血型資料庫","(C) 加強B型肝炎篩檢","(D) 加強愛滋病毒篩檢"],"answer":0,"image":""},{"id":"ph6-105-1-2","subject":"ph6","topic":"藥事法規-全民健康保險與藥事作業","meta":"105年第1次第2題","year":105,"session":1,"number":2,"question":"有關衛生福利部中央健康保險署組織法之敘述，下列何者錯誤？","options":["(A) 由國營事業改制為行政機關","(B) 設置公務預算以辦理全民健康保險相關業務","(C) 「全民健康保險藥品特材業務之研擬、規劃及執行」為掌理事項之一","(D) 為全民健康保險法所規範之「保險人」"],"answer":1,"image":""},{"id":"ph6-105-1-3","subject":"ph6","topic":"藥事法規-藥政管理組織與衛生行政","meta":"105年第1次第3題","year":105,"session":1,"number":3,"question":"我國對進口牛肉所採取「三管五卡」管制措施，其中所稱之「三管」不包括下列何項？","options":["(A) 管源頭","(B) 管邊境","(C) 管市場","(D) 管餐飲業者"],"answer":3,"image":""},{"id":"ph6-105-1-4","subject":"ph6","topic":"藥事法規-藥政管理組織與衛生行政","meta":"105年第1次第4題","year":105,"session":1,"number":4,"question":"在「食品消費紅綠燈」機制中，下列何者屬「紅燈」？","options":["(A) 超過有效期限","(B) 有致人體健康危害之虞","(C) 標示不全","(D) 具有不安全之疑慮"],"answer":0,"image":""},{"id":"ph6-105-1-5","subject":"ph6","topic":"藥事法規-化粧品衛生安全管理法","meta":"105年第1次第5題","year":105,"session":1,"number":5,"question":"設址於新竹市西區之化粧品色素販賣業者，擬申請歇業，應向何機關辦理？","options":["(A) 新竹市政府","(B) 新竹市政府建設局","(C) 衛生福利部","(D) 衛生福利部食品藥物管理署"],"answer":0,"image":""},{"id":"ph6-105-1-6","subject":"ph6","topic":"藥事法規-新藥臨床試驗與安全監視","meta":"105年第1次第6題","year":105,"session":1,"number":6,"question":"下列有關新藥安全監視之敘述，何者正確？","options":["(A) 為保護市場，監視期間10年","(B) 藥商應於指定期限內提出藥物定期安全性報告","(C) 醫療院所進藥時仍得要求臨床試驗","(D) 於新藥上市前為之"],"answer":1,"image":""},{"id":"ph6-105-1-7","subject":"ph6","topic":"藥事法規-藥師法與執業管理","meta":"105年第1次第7題","year":105,"session":1,"number":7,"question":"有關藥師執業，下列事項何者正確？","options":["(A) 某藥師於某年2月1日自臺北榮總離職，同年6月1日至高雄榮總就職，該藥師應向高雄市政府辦理變更執業處所登記","(B) 某藥師於臺北榮總工作時已加入臺北市藥師公會，後調職於高雄榮總工作，無需再加入高雄市藥師公會","(C) 臺北榮總與高雄榮總同屬輔導會所屬醫院，兩者間藥師調動，無需辦理執業變更登記","(D) 某藥師於高雄榮總執業期間死亡，由高雄市政府註銷執業執照"],"answer":3,"image":""},{"id":"ph6-105-1-8","subject":"ph6","topic":"藥事法規-藥師法與執業管理","meta":"105年第1次第8題","year":105,"session":1,"number":8,"question":"下列何者為藥師法所稱主管機關？","options":["(A) 新北市衛生局","(B) 臺北市藥師公會","(C) 衛生福利部食品藥物管理署","(D) 衛生福利部"],"answer":3,"image":""},{"id":"ph6-105-1-9","subject":"ph6","topic":"藥事法規-藥師法與執業管理","meta":"105年第1次第9題","year":105,"session":1,"number":9,"question":"依藥師法之規定，藥師執行處方調劑，下列何者錯誤？","options":["(A) 依醫師處方","(B) 依管制藥品專用處方","(C) 依中華藥典、國民處方選輯之處方","(D) 依醫師具名僅書寫藥品名稱之字條"],"answer":3,"image":""},{"id":"ph6-105-1-10","subject":"ph6","topic":"藥事法規-藥師法與執業管理","meta":"105年第1次第10題","year":105,"session":1,"number":10,"question":"依藥師法之規定，下列敘述何者錯誤？","options":["(A) 犯管制藥品管理條例之罪，經判刑確定者，應廢止藥師證書","(B) 藥師受懲戒處分者，得廢止藥師證書","(C) 藥師受廢止藥師證書處分時，其兼領有藥劑生證書者，得保有藥劑生證書，不受廢止藥師證書處分影響","(D) 犯毒品危害防制條例之罪，經判刑確定者，應廢止藥師證書"],"answer":2,"image":""},{"id":"ph6-105-1-11","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"105年第1次第11題","year":105,"session":1,"number":11,"question":"下列何種產品之製造，不須聘請藥師駐廠監製？","options":["(A) 衛生棉條","(B) 維士比","(C) 衛生套","(D) 染髮劑"],"answer":2,"image":""},{"id":"ph6-105-1-12","subject":"ph6","topic":"藥事法規-藥師法與執業管理","meta":"105年第1次第12題","year":105,"session":1,"number":12,"question":"有關藥師執業之規定，下述何者錯誤？","options":["(A) 須向執業所在地直轄市、縣（市）主管機關申請執業登記，領有執業執照","(B) 公職藥師得利用公餘，夜間至居家附近診所兼任調劑藥師","(C) 須加入所在地藥師公會","(D) 須依藥師執業登記及繼續教育辦法之規定辦理"],"answer":1,"image":""},{"id":"ph6-105-1-13","subject":"ph6","topic":"藥事法規-醫療器材管理法","meta":"105年第1次第13題","year":105,"session":1,"number":13,"question":"下列何者不得販賣或管理醫療器材？","options":["(A) 藥師","(B) 醫療器材販賣業者","(C) 醫療器材相關技術人員","(D) 西藥販賣業者"],"answer":3,"image":""},{"id":"ph6-105-1-14","subject":"ph6","topic":"藥事法規-化粧品衛生安全管理法","meta":"105年第1次第14題","year":105,"session":1,"number":14,"question":"某市售防曬面霜僅有日文標示，應依下列何種方式處置？","options":["(A) 未依核准擅自輸入之藥品","(B) 未依核准擅自製造之藥品","(C) 未依核准擅自製造之化粧品","(D) 未依主管機關之規定標示"],"answer":3,"image":""},{"id":"ph6-105-1-15","subject":"ph6","topic":"藥事法規-藥師法與執業管理","meta":"105年第1次第15題","year":105,"session":1,"number":15,"question":"藥師執業登錄於下列何者，非屬藥師法所稱「實際調劑經驗」？","options":["(A) 醫院","(B) 藥粧店","(C) 聯合藥局","(D) 診所"],"answer":1,"image":""},{"id":"ph6-105-1-16","subject":"ph6","topic":"藥事法規-藥師法與執業管理","meta":"105年第1次第16題","year":105,"session":1,"number":16,"question":"藥劑生違反藥劑生資格及管理辦法，其處罰方式及額度係依據下列何者？","options":["(A) 藥師法","(B) 藥劑生資格及管理辦法","(C) 藥事法","(D) 藥劑生公會全聯會決議"],"answer":[0,2],"image":"","answer_note":"更正:第16題答Ａ、Ｃ給分。"},{"id":"ph6-105-1-17","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"105年第1次第17題","year":105,"session":1,"number":17,"question":"依藥物優良製造準則之規定，下列何者錯誤？","options":["(A) 原料：指任何用於製造藥品之材質，不包括參與製程但不存在於最終產品之材質","(B) 半製品或中間產品：指任何產品製造過程中所得之產物，其經隨後之製造過程，即可成為產品者","(C) 產品：指經過所有製造過程後，所產生之原料藥或其劑型含有效成分，並常含非有效成分之製劑","(D) 最終產品：指已經完成包裝作業，由外觀及所附資料可確知該包裝內容物相關資訊之藥品"],"answer":0,"image":""},{"id":"ph6-105-1-18","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"105年第1次第18題","year":105,"session":1,"number":18,"question":"下列何項藥品不須經衛生福利部檢驗合格，並加查訖封緘，即可上市銷售？","options":["(A) 疫苗","(B) 青黴素","(C) 第八凝血因子","(D) 肉毒桿菌"],"answer":1,"image":""},{"id":"ph6-105-1-19","subject":"ph6","topic":"調劑學-處方判讀與調劑作業","meta":"105年第1次第19題","year":105,"session":1,"number":19,"question":"依藥品優良調劑作業準則之規定，調劑處所至少應有多少平方公尺作業面積，並應與其他作業處所有適當區隔？","options":["(A) 3","(B) 5","(C) 6","(D) 9"],"answer":2,"image":""},{"id":"ph6-105-1-20","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"105年第1次第20題","year":105,"session":1,"number":20,"question":"依據藥事法之規定，對於查獲之偽藥、禁藥、劣藥或不良醫療器材之處置，下列何者錯誤？","options":["(A) 查獲之偽藥或禁藥，沒入銷燬之","(B) 查獲之劣藥或不良醫療器材，如係本國製造，經檢驗後仍可改製使用者，應由直轄市或縣（市）衛生主管機關，派員監督原製造廠商限期改製","(C) 查獲之劣藥或不良醫療器材，如係本國製造，經檢驗後不能改製或屆期未改製者，沒入銷燬之","(D) 查獲之劣藥或不良醫療器材，如係核准輸入者，應即予以封存，沒入銷燬之"],"answer":3,"image":""},{"id":"ph6-105-1-21","subject":"ph6","topic":"調劑學-藥品包裝標示與儲存","meta":"105年第1次第21題","year":105,"session":1,"number":21,"question":"藥品標示之有效期間或保存期限，是依據下列何項之試驗結果推算？","options":["(A) 藥品優良製造作業確效","(B) 藥品安定性試驗","(C) 藥品安全性試驗","(D) 藥品生體可用率及相等性試驗"],"answer":1,"image":""},{"id":"ph6-105-1-22","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"105年第1次第22題","year":105,"session":1,"number":22,"question":"依據藥事法之規定，下列何者錯誤？","options":["(A) 製造、輸入藥品，應依藥品查驗登記審查準則檢附資料，申請中央衛生主管機關查驗登記，經核准發給藥品許可證後，始得製造或輸入","(B) 藥物製造、輸入許可證有效期間為5年","(C) 經核准製造、輸入之藥物，非經中央衛生主管機關之核准，不得變更原登記事項","(D) 領有輸入許可證之藥品，應由藥品許可證所有人輸入，不得授權他人"],"answer":3,"image":""},{"id":"ph6-105-1-23","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"105年第1次第23題","year":105,"session":1,"number":23,"question":"依藥事法之規定，有關藥商僱用之推銷員，下列何者錯誤？","options":["(A) 應由該藥商向當地之直轄市、縣（市）衛生主管機關登記後，方准執行推銷工作","(B) 以向藥局、藥商、衛生醫療機構、醫學研究機構及經衛生主管機關准予登記為兼售藥物者推銷其受僱藥商所製售或經銷之藥物為限","(C) 得沿途推銷、設攤出售其受僱藥商所製售或經銷之藥物","(D) 不得有擅將藥物拆封、改裝或非法廣告之行為"],"answer":2,"image":""},{"id":"ph6-105-1-24","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"105年第1次第24題","year":105,"session":1,"number":24,"question":"依藥事法之規定，下列何者錯誤？","options":["(A) 管制藥品及毒劇藥品之處方箋、簿冊，均應保存5年","(B) 藥品之調劑，應由藥師為之；但不含麻醉藥品者，得由藥劑生為之","(C) 修習中藥課程達適當標準之藥師，親自主持之藥局，得兼營中藥之調劑、供應或零售業務","(D) 民國78年12月31日前業經核准登記領照營業之西藥販賣業者、西藥種商，其所聘請專任管理之藥師或藥劑生，免受駐店管理及調劑、供應藥品之限制"],"answer":3,"image":""},{"id":"ph6-105-1-25","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"105年第1次第25題","year":105,"session":1,"number":25,"question":"藥事法第40條之2規範的資料專屬權，涵蓋下列何種新藥？","options":["(A) 新成分","(B) 新療效複方","(C) 新使用途徑","(D) 新劑量"],"answer":0,"image":""},{"id":"ph6-105-1-26","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"105年第1次第26題","year":105,"session":1,"number":26,"question":"依據藥事法規定，西藥販賣業者，不得兼售中藥；中藥販賣業者，不得兼售西藥。但何者不在此限？","options":["(A) 成藥","(B) 管制藥品","(C) 指示藥品","(D) 處方藥品"],"answer":0,"image":""},{"id":"ph6-105-1-27","subject":"ph6","topic":"藥事法規-新藥臨床試驗與安全監視","meta":"105年第1次第27題","year":105,"session":1,"number":27,"question":"下列何者適用藥物安全監視管理辦法，須列入監視名單中？①新成分藥品 ②經衛生福利部公告指定之醫療器材 ③新療效複方藥品 ④新使用途徑藥品","options":["(A) 僅①②③","(B) 僅①②④","(C) 僅③④","(D) ①②③④"],"answer":3,"image":""},{"id":"ph6-105-1-28","subject":"ph6","topic":"藥事法規-藥物廣告與稽查","meta":"105年第1次第28題","year":105,"session":1,"number":28,"question":"對於藥物廣告之規定，下列何者錯誤？","options":["(A) 採訪、報導或宣傳，其內容暗示或影射醫療效能者，視為藥物廣告","(B) 可藉由醫療專業人員之名義為其宣傳","(C) 醫師處方之藥物，其廣告以登載於學術性醫療刊物為限","(D) 藥物廣告，經中央或直轄市衛生主管機關核准者，其有效期間為1年"],"answer":1,"image":""},{"id":"ph6-105-1-29","subject":"ph6","topic":"藥事法規-新藥臨床試驗與安全監視","meta":"105年第1次第29題","year":105,"session":1,"number":29,"question":"依藥品優良臨床試驗準則之規定，下列何者錯誤？","options":["(A) 受試者得不附理由隨時退出臨床試驗","(B) 試驗主持人應於臨床試驗進行前，取得受試者自願給予之受試者同意書","(C) 試驗委託者對於受試者可獲得之補助，除小金額外，應於試驗完成後一次給付","(D) 受試者之身分及其臨床試驗相關紀錄，應予保密"],"answer":2,"image":""},{"id":"ph6-105-1-30","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"105年第1次第30題","year":105,"session":1,"number":30,"question":"依藥事法施行細則之規定，藥商登記事項如有變更，藥商應自事實發生之日起幾日內，向原核准登記之衛生主管機關申請辦理變更登記？","options":["(A) 10","(B) 15","(C) 20","(D) 30"],"answer":1,"image":""},{"id":"ph6-105-1-31","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"105年第1次第31題","year":105,"session":1,"number":31,"question":"依藥事法之規定，對於嚴重藥物不良反應未通報者，應如何處置？","options":["(A) 限期改善","(B) 停業處分","(C) 罰鍰處分","(D) 罰金處分"],"answer":2,"image":""},{"id":"ph6-105-1-32","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"105年第1次第32題","year":105,"session":1,"number":32,"question":"下列有關藥品販售之規定，何者錯誤？","options":["(A) 藥品販賣業者，不得兼售毒性化學物質","(B) 經核准輸入之藥物樣品或贈品，不得出售","(C) 輸入製劑之分裝，應先由符合藥品優良製造規範之藥品製造業者分裝，再報請中央衛生主管機關核准，始得販售","(D) 經分裝之原料藥，以銷售藥品製造業者為限"],"answer":2,"image":""},{"id":"ph6-105-1-33","subject":"ph6","topic":"藥事法規-醫療器材管理法","meta":"105年第1次第33題","year":105,"session":1,"number":33,"question":"藥局販賣之衛生棉條，經抽驗，含金黃色葡萄球菌，則該產品為藥事法所稱之：","options":["(A) 妨害衛生之物品","(B) 不良衛生之物品","(C) 不良醫療器材","(D) 劣藥"],"answer":2,"image":""},{"id":"ph6-105-1-34","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"105年第1次第34題","year":105,"session":1,"number":34,"question":"藥事法有關毒劇性中藥之管理，下列敘述何者正確？①中藥販賣業者及中藥製造業者售賣毒劇性之中藥，非有中醫師簽名、蓋章之處方箋，不得出售 ②中藥販賣或製造業者，購存或售賣毒劇性中藥，應將藥品名稱數量詳列簿冊 ③毒劇性中藥應專櫃加鎖儲藏 ④製造毒劇性中藥應先申請製造同意書","options":["(A) 僅①②","(B) 僅②③","(C) 僅①④","(D) ①②③④"],"answer":0,"image":""},{"id":"ph6-105-1-35","subject":"ph6","topic":"藥事法規-藥物廣告與稽查","meta":"105年第1次第35題","year":105,"session":1,"number":35,"question":"下列敘述何者正確？","options":["(A) 衛生主管機關可派員檢查藥物製造業者、販賣業者之處所設施及有關業務","(B) 衛生主管機關抽驗藥物時，依法可直接抽驗不出具單據","(C) 衛生主管機關抽驗時，為避免抽驗檢體不夠，可以抽超過檢驗必需之量","(D) 衛生主管機關抽驗藥物時，必須價購"],"answer":0,"image":""},{"id":"ph6-105-1-36","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"105年第1次第36題","year":105,"session":1,"number":36,"question":"下列有關「劣藥」之敘述，何者正確？","options":["(A) 將他人產品抽換者","(B) 添加非法定著色劑者","(C) 更換有效期間之標示者","(D) 有效成分之名稱，與核准不符者"],"answer":1,"image":""},{"id":"ph6-105-1-37","subject":"ph6","topic":"藥事法規-新藥臨床試驗與安全監視","meta":"105年第1次第37題","year":105,"session":1,"number":37,"question":"得知藥物造成危及生命之嚴重不良反應，下列何者應行通報？①醫療機構 ②藥局 ③持有許可證之藥商 ④病人家屬","options":["(A) 僅①②","(B) 僅①②③","(C) ①②③④","(D) 僅④"],"answer":1,"image":""},{"id":"ph6-105-1-38","subject":"ph6","topic":"藥事法規-管制藥品與毒品危害防制","meta":"105年第1次第38題","year":105,"session":1,"number":38,"question":"有關管制藥品之敘述，下列何者正確？","options":["(A) 管制藥品限供醫藥上之需用，依其成癮性、濫用性及社會危害性之程度，分四級管理","(B) 分級及品項經管制藥品審議委員會審議後，由衛生福利部食品藥物管理署核定公告","(C) 為防止麻醉藥品及影響精神藥品之流用、濫用，制定藥事法嚴加管理","(D) 嗎啡（Morphine）用於治療癌症疼痛，列為第一級管制藥品"],"answer":3,"image":""},{"id":"ph6-105-1-39","subject":"ph6","topic":"藥事法規-管制藥品與毒品危害防制","meta":"105年第1次第39題","year":105,"session":1,"number":39,"question":"某大學教授欲從事愷他命（Ketamine）有關之研究試驗，非經下列何者之核准，不得使用該藥品？","options":["(A) 地方衛生主管機關","(B) 科技部","(C) 衛生福利部","(D) 財團法人國家衛生研究院"],"answer":2,"image":""},{"id":"ph6-105-1-40","subject":"ph6","topic":"藥事法規-管制藥品與毒品危害防制","meta":"105年第1次第40題","year":105,"session":1,"number":40,"question":"有關管制藥品使用執照之敘述，下列何者錯誤？","options":["(A) 藥師調劑第一級至第三級管制藥品，需先取得管制藥品使用執照","(B) 獸醫師使用第一級至第三級管制藥品，需先取得管制藥品使用執照","(C) 醫師未取得管制藥品使用執照即開立管制藥品專用處方箋之罰鍰，由中央衛生主管機關處罰","(D) 醫藥教育研究試驗人員使用管制藥品，需經中央衛生主管機關核准"],"answer":0,"image":""},{"id":"ph6-105-1-41","subject":"ph6","topic":"藥事法規-化粧品衛生安全管理法","meta":"105年第1次第41題","year":105,"session":1,"number":41,"question":"下列何者為化粧品禁用成分？","options":["(A) Sulfur","(B) Hydroquinone","(C) Salicylic acid","(D) Arbutin"],"answer":1,"image":""},{"id":"ph6-105-1-42","subject":"ph6","topic":"藥事法規-藥物廣告與稽查","meta":"105年第1次第42題","year":105,"session":1,"number":42,"question":"有關化粧品網路廣告之規定，下列敘述何者正確？","options":["(A) 網路刊載經確認屬化粧品產品資訊，不需辦理廣告申請","(B) 僅含藥化粧品需辦理廣告申請，一般化粧品不需辦理廣告申請","(C) 不論是刊載產品資訊或實質廣告，均應事前申請核准，始得廣告","(D) 全省各縣市衛生局均受理化粧品廣告申請"],"answer":0,"image":""},{"id":"ph6-105-1-43","subject":"ph6","topic":"藥事法規-化粧品衛生安全管理法","meta":"105年第1次第43題","year":105,"session":1,"number":43,"question":"下列有關化粧品之規定，何者錯誤？","options":["(A) 禁止使用氯仿","(B) 使用Parahydroxybenzoic acid及其酯類，總量為1%","(C) 使用DMDM Hydantoin時，化粧品中游離甲醛（Free Formaldehyde）量，不得超過1,000 ppm","(D) 可使用甲醛，惟含量不得超過1,000 ppm"],"answer":3,"image":""},{"id":"ph6-105-1-44","subject":"ph6","topic":"藥事法規-化粧品衛生安全管理法","meta":"105年第1次第44題","year":105,"session":1,"number":44,"question":"含0.2～0.5%之水楊酸（Salicylic acid）成分之化粧品，其可標示之效能為：","options":["(A) 防腐劑","(B) 防曬效果","(C) 角質軟化劑、面皰預防","(D) 治療雞眼"],"answer":2,"image":""},{"id":"ph6-105-1-45","subject":"ph6","topic":"藥事法規-藥害救濟與罕見疾病","meta":"105年第1次第45題","year":105,"session":1,"number":45,"question":"罕見疾病及藥物審議委員會委員之組成，至少應有二分之一以上為：","options":["(A) 政府機關代表","(B) 具罕見疾病臨床治療、照護經驗或研究之醫事學者專家","(C) 罕見疾病患者家屬代表","(D) 法學專家及社會工作人員"],"answer":1,"image":""},{"id":"ph6-105-1-46","subject":"ph6","topic":"藥事法規-藥害救濟與罕見疾病","meta":"105年第1次第46題","year":105,"session":1,"number":46,"question":"某藥廠領有罕見疾病藥物許可證，經衛生福利部認定其售價顯不合理，得以下列何種方式處置？","options":["(A) 撤銷該藥物許可證","(B) 受理其他同類藥物之查驗登記申請","(C) 由罕見疾病及藥物審議委員會裁定合理價格給付","(D) 中止該藥物許可證展延"],"answer":1,"image":""},{"id":"ph6-105-1-47","subject":"ph6","topic":"藥事法規-藥害救濟與罕見疾病","meta":"105年第1次第47題","year":105,"session":1,"number":47,"question":"下列何者不屬藥害救濟法規定之救濟給付範圍？","options":["(A) 死亡","(B) 障礙","(C) 試驗用藥致癮","(D) 嚴重疾病"],"answer":2,"image":""},{"id":"ph6-105-1-48","subject":"ph6","topic":"藥事法規-藥害救濟與罕見疾病","meta":"105年第1次第48題","year":105,"session":1,"number":48,"question":"罕見疾病藥物許可證之所有人，擬停止製造或輸入該罕見藥物，應如何辦理？","options":["(A) 應於停止前1個月以書面通知該公司轄區衛生主管機關","(B) 應於停止前3個月以書面通知轄區衛生主管機關","(C) 應於停止前6個月以書面通知中央主管機關","(D) 應於停止後向主管機關報備"],"answer":2,"image":""},{"id":"ph6-105-1-49","subject":"ph6","topic":"藥事法規-全民健康保險與藥事作業","meta":"105年第1次第49題","year":105,"session":1,"number":49,"question":"依全民健康保險法之規定，下列何者不屬於保險醫事服務機構可提供之服務？","options":["(A) 門診診療服務","(B) 交付處方箋予病人","(C) 住院診療服務","(D) 人體試驗"],"answer":3,"image":""},{"id":"ph6-105-1-50","subject":"ph6","topic":"藥事法規-全民健康保險與藥事作業","meta":"105年第1次第50題","year":105,"session":1,"number":50,"question":"依全民健康保險法之規定，保險人核付門診藥物費用，下列何者正確？","options":["(A) 門診藥品費用設有獨立總額","(B) 依藥物給付項目及支付標準核付","(C) 支付費用超出預先設定之藥品費用總額時，應自下一季之門診醫療給付費用總額中扣除","(D) 支付費用超出預先設定之藥品費用總額時，立即調整藥物支付標準"],"answer":1,"image":""},{"id":"ph6-105-2-1","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"105年第2次第1題","year":105,"session":2,"number":1,"question":"下列何種產品之製造，不須聘請藥師駐廠監製？","options":["(A) 隱形眼鏡鏡片消毒藥水","(B) 衛生材料","(C) 一般化粧品","(D) 移植器官保存液"],"answer":2,"image":""},{"id":"ph6-105-2-2","subject":"ph6","topic":"藥事法規-新藥臨床試驗與安全監視","meta":"105年第2次第2題","year":105,"session":2,"number":2,"question":"依藥事法之規定，下列何者錯誤？","options":["(A) 衛生主管機關於核發新藥許可證時，應公開申請人檢附之已揭露專利字號或案號","(B) 新藥許可證自核發之日起5年內，其他藥商非經許可證所有人同意，不得引據其申請資料申請查驗登記","(C) 新成分新藥許可證核發之日起5年後，其他藥商得依本法及相關法規有關藥品查驗登記審查之規定提出同成分、同劑型、同劑量及同單位含量藥品之查驗登記申請，符合規定者，得於新成分新藥許可證核發屆滿5年之翌日起發給藥品許可證","(D) 新藥專利權不及於藥商申請查驗登記前所進行之研究、教學或試驗"],"answer":[1,2],"image":"","answer_note":"更正:第2題答Ｂ、Ｃ給分"},{"id":"ph6-105-2-3","subject":"ph6","topic":"藥事法規-化粧品衛生安全管理法","meta":"105年第2次第3題","year":105,"session":2,"number":3,"question":"申請製造化粧品色素查驗登記時，所應檢附之文件中不包含下列何者？","options":["(A) 仿單標籤","(B) 試製紀錄表","(C) 檢驗規格、方法及檢驗成績書","(D) 處方依據文件"],"answer":3,"image":""},{"id":"ph6-105-2-4","subject":"ph6","topic":"藥事法規-化粧品衛生安全管理法","meta":"105年第2次第4題","year":105,"session":2,"number":4,"question":"依化粧品衛生管理條例之規定，下列何種成分禁用於化粧品？","options":["(A) Zinc oxide","(B) Tretinoin","(C) Titanium dioxide","(D) Octyl salicylate"],"answer":1,"image":""},{"id":"ph6-105-2-5","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"105年第2次第5題","year":105,"session":2,"number":5,"question":"藥品經檢驗結果所含有效成分含量與核准不符，係屬下列何者？","options":["(A) 試驗用藥品","(B) 禁藥","(C) 劣藥","(D) 偽藥"],"answer":2,"image":""},{"id":"ph6-105-2-6","subject":"ph6","topic":"藥事法規-新藥臨床試驗與安全監視","meta":"105年第2次第6題","year":105,"session":2,"number":6,"question":"下列何者非屬新成分新藥上市前需審查項目？","options":["(A) 藥理／毒理試驗","(B) 吸收、分佈、代謝、排泄試驗","(C) 生體相等性試驗","(D) 臨床試驗"],"answer":2,"image":""},{"id":"ph6-105-2-7","subject":"ph6","topic":"藥事法規-新藥臨床試驗與安全監視","meta":"105年第2次第7題","year":105,"session":2,"number":7,"question":"藥品人體試驗之審查及監督，係屬下列何者掌理之事項？","options":["(A) 衛生福利部食品藥物管理署","(B) 衛生福利部醫事司","(C) 衛生福利部疾病管制署","(D) 衛生福利部中央健康保險署"],"answer":0,"image":""},{"id":"ph6-105-2-8","subject":"ph6","topic":"藥事法規-藥政管理組織與衛生行政","meta":"105年第2次第8題","year":105,"session":2,"number":8,"question":"衛生福利部中醫藥司業務職掌，下列何者錯誤？","options":["(A) 中藥、植物性藥材之檢驗","(B) 中藥廠GMP制度推動、輔導事項","(C) 中醫藥人力培育、發展之研擬、策劃及推動事項","(D) 中藥（材）、植物性藥材之管理與品質促進政策之規劃、推動及相關法規之研訂"],"answer":0,"image":""},{"id":"ph6-105-2-9","subject":"ph6","topic":"藥事法規-藥政管理組織與衛生行政","meta":"105年第2次第9題","year":105,"session":2,"number":9,"question":"衛生福利部之次級機關及其業務，下列何者錯誤？","options":["(A) 中央健康保險署：規劃及執行全民健康保險事項","(B) 食品藥物管理署：規劃與執行食品、藥物與化粧品之管理、查核及檢驗事項","(C) 國家中醫藥研究所：規劃與執行中醫中藥各項行政事務及研究發展工作","(D) 國民健康署：規劃與執行國民健康促進及非傳染病之防治事項"],"answer":2,"image":""},{"id":"ph6-105-2-10","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"105年第2次第10題","year":105,"session":2,"number":10,"question":"藥商申請停、歇業，應向下列何者提出申請？","options":["(A) 中央衛生主管機關","(B) 食品藥物管理署","(C) 當地工業主管機關","(D) 當地衛生主管機關"],"answer":3,"image":""},{"id":"ph6-105-2-11","subject":"ph6","topic":"藥事法規-新藥臨床試驗與安全監視","meta":"105年第2次第11題","year":105,"session":2,"number":11,"question":"下列何者不屬於藥物安全監控業務？","options":["(A) 市售藥物廣告調查監測","(B) 生物藥品檢驗與封緘作業","(C) 活化藥品不良品通報機制","(D) 中草藥不良反應通報中心"],"answer":0,"image":""},{"id":"ph6-105-2-12","subject":"ph6","topic":"藥事法規-藥政管理組織與衛生行政","meta":"105年第2次第12題","year":105,"session":2,"number":12,"question":"下列有關衛生福利部之敘述何者錯誤？","options":["(A) 配合行政院組織再造，整合行政院衛生署、內政部及教育部相關單位而成","(B) 為全國最高衛生及社會福利行政機關","(C) 已成立國民年金局、疾病管制署及中央健康保險署等次級機關","(D) 對各級地方衛生及社會福利機關有業務指導、監督和協調的責任"],"answer":2,"image":""},{"id":"ph6-105-2-13","subject":"ph6","topic":"藥事法規-藥師法與執業管理","meta":"105年第2次第13題","year":105,"session":2,"number":13,"question":"依藥師法之規定，下列何者非屬藥事照護之業務範圍？","options":["(A) 在醫療機構執行藥品安全監視","(B) 在護理機構執行用藥諮詢","(C) 在老人福利機構執行給藥流程評估","(D) 在醫院將膠囊劑中之藥粉泡入水中，提供灌食餵藥"],"answer":3,"image":""},{"id":"ph6-105-2-14","subject":"ph6","topic":"臨床藥學-藥事照護與用藥評估","meta":"105年第2次第14題","year":105,"session":2,"number":14,"question":"為增進藥品療程之效益及生活品質，考量藥品使用情形及評估療效，係屬下列何種藥事作業？","options":["(A) 藥品調劑","(B) 藥事照護","(C) 藥品管理","(D) 確認藥品之安全及醫療效能"],"answer":1,"image":""},{"id":"ph6-105-2-15","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"105年第2次第15題","year":105,"session":2,"number":15,"question":"依藥事法規定，下列何種藥品不得由藥劑生調劑？","options":["(A) Zolpidem","(B) Pethidine","(C) Digoxin","(D) Botulinum Toxin"],"answer":1,"image":""},{"id":"ph6-105-2-16","subject":"ph6","topic":"調劑學-藥品包裝標示與儲存","meta":"105年第2次第16題","year":105,"session":2,"number":16,"question":"依藥品優良調劑作業準則之規定，藥事人員應於藥品容器包裝上載明事項，下列何者錯誤？","options":["(A) 病患之姓名及性別","(B) 醫療機構或藥局之名稱及地址","(C) 病患之身分證字號","(D) 藥品名稱"],"answer":2,"image":""},{"id":"ph6-105-2-17","subject":"ph6","topic":"藥事法規-醫療器材管理法","meta":"105年第2次第17題","year":105,"session":2,"number":17,"question":"下列何者非屬藥局得兼營零售之藥物？","options":["(A) 血壓計","(B) 心律調節器","(C) 感冒熱飲","(D) 藥用酒精"],"answer":1,"image":""},{"id":"ph6-105-2-18","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"105年第2次第18題","year":105,"session":2,"number":18,"question":"違反藥品優良調劑作業準則之規定，應依下列何者處分？","options":["(A) 依藥師法處罰鍰","(B) 依藥師法處罰金","(C) 依藥事法處罰鍰","(D) 依藥事法處罰金"],"answer":2,"image":""},{"id":"ph6-105-2-19","subject":"ph6","topic":"藥事法規-藥害救濟與罕見疾病","meta":"105年第2次第19題","year":105,"session":2,"number":19,"question":"民眾以手寫處方箋交付，字跡潦草且無處方醫師簽章及所屬醫療機構聯絡電話，藥師將Urosan誤認為Urosin，而調劑交付予民眾，導致民眾送醫急救。下列敘述何者正確？","options":["(A) 民眾係使用合法藥品而受害，故得申請藥害救濟","(B) 因處方醫師字跡潦草，且無聯絡電話，藥師無法確認，始導致調劑錯誤，藥師已善盡其職責，故應由醫師負擔全部責任","(C) 藥師之調劑未符合法定程序，應依藥師法之規定處分藥師","(D) 醫療機構之電話非屬應確認處方之事項"],"answer":2,"image":""},{"id":"ph6-105-2-20","subject":"ph6","topic":"藥事法規-藥師法與執業管理","meta":"105年第2次第20題","year":105,"session":2,"number":20,"question":"臺北市某診所聘有一名藥師及一名藥劑生，該診所備有管制藥品但無麻醉藥品。某日其聘用之藥師臨時因病請假，下列敘述何者正確？","options":["(A) 藥師係臨時請假，故得由醫師親自調劑","(B) 護理師為藥師之代理人，故得由該護理師代理執行調劑業務","(C) 因藥師請假，不能調劑藥品予民眾，故診所應休診","(D) 得由藥劑生執行調劑"],"answer":3,"image":""},{"id":"ph6-105-2-21","subject":"ph6","topic":"藥事法規-藥師法與執業管理","meta":"105年第2次第21題","year":105,"session":2,"number":21,"question":"依藥師法之規定，下列何者非屬社區藥局藥師之業務範圍？","options":["(A) 提供用藥諮詢及藥物治療流程評估","(B) 藥品販賣或管理","(C) 第一等級醫療器材販賣","(D) 病患用特殊營養食品之供應"],"answer":3,"image":""},{"id":"ph6-105-2-22","subject":"ph6","topic":"藥事法規-藥師法與執業管理","meta":"105年第2次第22題","year":105,"session":2,"number":22,"question":"甲經藥師考試及格3年後，始提出申請藥師執照，其需符合下列何者有關藥師繼續教育之規定？","options":["(A) 應檢具申請日前1年內接受繼續教育25點以上之證明文件","(B) 應檢具最近3年內接受繼續教育達150點之證明文件","(C) 應檢具最近3年內接受繼續教育達25點之證明文件","(D) 其藥師考試及格未逾5年，得免檢具繼續教育證明文件"],"answer":3,"image":""},{"id":"ph6-105-2-23","subject":"ph6","topic":"藥事法規-醫療器材管理法","meta":"105年第2次第23題","year":105,"session":2,"number":23,"question":"下列何者非屬藥事法所稱之不良醫療器材？","options":["(A) 含有毒質或有害物質，致使用時有損人體健康者","(B) 超過有效期間或保存期限者","(C) 標示與核定之標籤、仿單內容不符者","(D) 性能或有效成分之質、量或強度，與核准不符者"],"answer":2,"image":""},{"id":"ph6-105-2-24","subject":"ph6","topic":"藥事法規-醫療器材管理法","meta":"105年第2次第24題","year":105,"session":2,"number":24,"question":"有關醫療器材之管理，下列敘述何者錯誤？","options":["(A) 製造、輸入醫療器材，應向衛生福利部申請查驗登記，經核准發給許可證後，始得為之","(B) 製造醫療器材，應向當地衛生主管機關核准登記，領有藥商許可執照，始得為之","(C) 醫療器材販賣業者，應聘藥師專任駐店管理，始能辦理藥商登記","(D) 製造、輸入不良醫療器材者，由直轄市或縣（市）衛生主管機關公告其公司或商號之名稱、地址、負責人姓名、醫療器材名稱及違反情節"],"answer":2,"image":""},{"id":"ph6-105-2-25","subject":"ph6","topic":"藥事法規-醫療器材管理法","meta":"105年第2次第25題","year":105,"session":2,"number":25,"question":"直轄市或縣（市）衛生主管機關查獲本國製造業者將原核准卻已逾保存期限之心導管，自行貼標更改有效期限於外包裝上，下列敘述何者錯誤？","options":["(A) 該產品不能向直轄市或縣（市）衛生局驗章後販賣","(B) 該業者自行貼標之行為，係屬未經核准擅自製造，得將業者移送檢察機關偵辦","(C) 對於該產品，得先行就地封存，並抽取樣品予以檢驗後，再行處理","(D) 該產品不得改製，應予沒入銷燬"],"answer":3,"image":""},{"id":"ph6-105-2-26","subject":"ph6","topic":"藥事法規-新藥臨床試驗與安全監視","meta":"105年第2次第26題","year":105,"session":2,"number":26,"question":"依藥物安全監視管理辦法之規定，下列何者非屬監視品項？","options":["(A) 血管支架","(B) 皮下填補劑","(C) 塗藥血管支架","(D) 角膜塑型鏡片"],"answer":0,"image":""},{"id":"ph6-105-2-27","subject":"ph6","topic":"藥事法規-全民健康保險與藥事作業","meta":"105年第2次第27題","year":105,"session":2,"number":27,"question":"有關保險醫事服務機構申報醫療費用之敘述，下列何者錯誤？","options":["(A) 收治非保險對象，而以保險對象之名義申報，移送司法機關偵辦","(B) 登錄保險對象保險憑證換給非對症之藥品或營養品，移送司法機關偵辦","(C) 以虛偽之證明申請核退費用，移送司法機關偵辦","(D) 容留非藥事人員資格之人員為保險對象調劑，依藥事法罰鍰"],"answer":3,"image":""},{"id":"ph6-105-2-28","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"105年第2次第28題","year":105,"session":2,"number":28,"question":"有關藥品之標籤、仿單、包裝之規定，下列敘述何者錯誤？","options":["(A) 輸入藥品外盒之標示，如係委託製造經衛生福利部核准者，其外盒之受託廠名稱地址得以刊載其所在國別","(B) 貼標籤作業視同製程之一部分","(C) 輸入藥品其製造廠之廠名及廠址之籤條，得委託國內符合藥品優良製造規範之藥廠執行","(D) 以塑膠為包裝容器之大型輸注液，應於容器上標示其與藥品接觸之材質名稱"],"answer":[0,1,2,3],"image":"","answer_note":"送分:第28題一律給分。 (原公告答案 C)"},{"id":"ph6-105-2-29","subject":"ph6","topic":"藥事法規-新藥臨床試驗與安全監視","meta":"105年第2次第29題","year":105,"session":2,"number":29,"question":"某藥商擬進行抗憂鬱新藥之第三期臨床試驗，下列有關招募受試者廣告之敘述，何者最正確？","options":["(A) 不得於國中以下校園內刊登","(B) 應申請中央或直轄市衛生主管機關核准","(C) 得宣稱試驗藥品優於現行之藥物或治療","(D) 廣告以登載於學術性醫療刊物為限"],"answer":0,"image":""},{"id":"ph6-105-2-30","subject":"ph6","topic":"藥事法規-新藥臨床試驗與安全監視","meta":"105年第2次第30題","year":105,"session":2,"number":30,"question":"依藥物優良製造準則之規定，中藥廠對於臨床試驗用藥之管理，下列何者正確？","options":["(A) 臨床試驗用藥之製造程序，須執行確效作業並訂定完整之製造管制標準書方能進行生產製造","(B) 批次製造紀錄保存期限，應於臨床試驗完成或於產品完成後，保存至少3年，二者以期間較長者為準","(C) 臨床試驗用藥標示之有效期間，不得超過原包裝產品原標示之有效期間","(D) 臨床試驗用藥之銷燬紀錄應製作紀錄，並保存至末效期後3年"],"answer":2,"image":""},{"id":"ph6-105-2-31","subject":"ph6","topic":"藥事法規-醫療器材管理法","meta":"105年第2次第31題","year":105,"session":2,"number":31,"question":"下列敘述何者錯誤？","options":["(A) 醫療器材製造工廠，應依藥物製造工廠設廠標準設立","(B) 製造醫療器材，應依藥物優良製造準則之規定，經檢查合格取得藥物製造許可後，始得製造","(C) 未滅菌及不具量測功能之第一等級醫療器材，可無須符合醫療器材優良製造準則之規定","(D) 藥物製造工廠設廠標準，由中央衛生主管機關會同中央工業主管機關定之"],"answer":2,"image":""},{"id":"ph6-105-2-32","subject":"ph6","topic":"藥事法規-醫療器材管理法","meta":"105年第2次第32題","year":105,"session":2,"number":32,"question":"依藥事法之規定，有關醫療器材許可證，下列敘述何者錯誤？","options":["(A) 許可證期滿若需繼續製造及輸入者，應事先申請核准展延之","(B) 許可證有效期間為5年","(C) 屆期未申請展延者，廠商可於許可證逾期6個月內申請展延","(D) 許可證有效期間內，經中央主管機關重新評估確有安全疑慮重大者，得逕予廢止其許可證"],"answer":2,"image":""},{"id":"ph6-105-2-33","subject":"ph6","topic":"藥事法規-藥物廣告與稽查","meta":"105年第2次第33題","year":105,"session":2,"number":33,"question":"報載由某醫學會背書，藝人扮演護士之「打疫苗預防皮蛇廣告」，鼓勵民眾撥打電話諮詢，下列敘述何者正確？","options":["(A) 該則廣告未提及產品名稱，非屬藥物廣告","(B) 藝人代言帶狀泡疹（皮蛇），且經醫學會聯名，鼓勵民眾撥打電話諮詢，非屬藥物廣告","(C) 疫苗屬醫師處方藥品，僅限於學術性醫療刊物刊登廣告","(D) 該廣告是「衛教廣告」不是「藥品廣告」"],"answer":2,"image":""},{"id":"ph6-105-2-34","subject":"ph6","topic":"藥事法規-藥物廣告與稽查","meta":"105年第2次第34題","year":105,"session":2,"number":34,"question":"廠址在苗栗縣之製藥廠，申請藥品廣告應向下列何者為之？","options":["(A) 苗栗縣政府","(B) 苗栗縣政府衛生局","(C) 臺灣省政府","(D) 衛生福利部"],"answer":3,"image":""},{"id":"ph6-105-2-35","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"105年第2次第35題","year":105,"session":2,"number":35,"question":"下列何者非屬藥事法有關藥物標籤、仿單或包裝應刊載之事項？","options":["(A) 品名及許可證字號","(B) 主治效能、性能或適應症","(C) 主要成分含量、用量及用法","(D) 重量、容量及出廠日期"],"answer":3,"image":""},{"id":"ph6-105-2-36","subject":"ph6","topic":"藥事法規-醫療器材管理法","meta":"105年第2次第36題","year":105,"session":2,"number":36,"question":"有關「隱形眼鏡」之販賣及廣告規定，下列何者正確？","options":["(A) 隱形眼鏡屬醫師處方醫療器材","(B) 每日拋棄型廣告，應在學術性雜誌登載","(C) 長戴型隱形眼鏡廣告可在電視刊播","(D) 一般眼鏡行能張貼各式隱形眼鏡廣告"],"answer":0,"image":""},{"id":"ph6-105-2-37","subject":"ph6","topic":"藥事法規-藥師法與執業管理","meta":"105年第2次第37題","year":105,"session":2,"number":37,"question":"連鎖藥粧店販售藥物及化粧品，下列敘述何者正確？","options":["(A) 應於總店聘專任藥師，負責全公司之藥品管理及各分店藥品之買賣業務","(B) 總店及各分店均應領有藥品販賣業藥商許可執照，並各聘專任藥師管理","(C) 只販售含藥化粧品，不論總店或是分店均應聘專任藥師管理","(D) 總店及各分店均應領有藥品販賣業藥商許可執照及化粧品販賣業許可執照，並各聘專任藥師管理"],"answer":1,"image":""},{"id":"ph6-105-2-38","subject":"ph6","topic":"藥事法規-藥師法與執業管理","meta":"105年第2次第38題","year":105,"session":2,"number":38,"question":"藥劑生執業時違反藥劑生資格及管理辦法之規定，應依下列何項法規處分？","options":["(A) 藥師法及藥事法","(B) 藥師法及醫療法","(C) 藥師法及藥劑生資格及管理辦法","(D) 藥事法及醫療法"],"answer":0,"image":""},{"id":"ph6-105-2-39","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"105年第2次第39題","year":105,"session":2,"number":39,"question":"下列敘述何者錯誤？","options":["(A) 藥物之委託製造，僅得將藥物之製程，全程委託他廠製造","(B) 藥物之檢驗得委託他廠執行","(C) 製造廠受託製造藥物應申請中央衛生主管機關核准","(D) 藥物委託製造之產品責任由委託者負責"],"answer":0,"image":""},{"id":"ph6-105-2-40","subject":"ph6","topic":"藥事法規-管制藥品與毒品危害防制","meta":"105年第2次第40題","year":105,"session":2,"number":40,"question":"有關管制藥品使用執照，下列敘述何者錯誤？","options":["(A) 醫師、牙醫師使用第一級至第三級管制藥品，應先領有管制藥品使用執照","(B) 藥師調劑處方需購買管制藥品，應申請管制藥品使用執照","(C) 醫藥教育研究試驗人員經核准使用管制藥品，不須領有管制藥品使用執照","(D) 開立管制藥品專用處方箋，應先領有管制藥品使用執照"],"answer":1,"image":""},{"id":"ph6-105-2-41","subject":"ph6","topic":"藥事法規-管制藥品與毒品危害防制","meta":"105年第2次第41題","year":105,"session":2,"number":41,"question":"有關新興濫用藥物，下列敘述何者錯誤？","options":["(A) 甲氧基甲基卡西酮（Methoxymethcathinone）常因其作用時間短或致死劑量小，追加劑量仍不易造成中毒","(B) Mephedrone（俗稱喵喵）具成癮性，過度使用易導致死亡","(C) 3,4-亞甲基雙氧甲基卡西酮（Methylone）常以搖頭丸（MDMA）名義販賣","(D) 愷他命（Ketamine）屬中樞神經抑制劑，長期使用會產生耐受性及心理依賴性"],"answer":0,"image":""},{"id":"ph6-105-2-42","subject":"ph6","topic":"藥事法規-管制藥品與毒品危害防制","meta":"105年第2次第42題","year":105,"session":2,"number":42,"question":"某診所醫師為病人使用吩坦尼（Fentanyl）針劑，下列敘述何者錯誤？","options":["(A) 醫師必須領有管制藥品使用執照才能使用該藥品","(B) 醫師開立之專用處方箋，不限調劑1次","(C) 藥劑生不得調劑該藥品","(D) 該藥品應由領受人憑身分證明簽名領受"],"answer":1,"image":""},{"id":"ph6-105-2-43","subject":"ph6","topic":"藥事法規-藥害救濟與罕見疾病","meta":"105年第2次第43題","year":105,"session":2,"number":43,"question":"下列何者並非我國認定罕見疾病的指標？","options":["(A) 遺傳性","(B) 致癌性","(C) 治療困難性","(D) 罕見性"],"answer":1,"image":""},{"id":"ph6-105-2-44","subject":"ph6","topic":"藥事法規-藥害救濟與罕見疾病","meta":"105年第2次第44題","year":105,"session":2,"number":44,"question":"對適應症外使用藥品，只要符合用藥當時醫學原理，並具用藥適當性，仍可申請藥害救濟。所謂「符合當時醫學原理」的認定之主要依據為：","options":["(A) 動物毒理學與藥動學報告","(B) 當時具公信力的醫學文獻個案","(C) 第三期臨床試驗結果","(D) 藥物安全監視結果"],"answer":1,"image":""},{"id":"ph6-105-2-45","subject":"ph6","topic":"藥事法規-新藥臨床試驗與安全監視","meta":"105年第2次第45題","year":105,"session":2,"number":45,"question":"某人參加第四期降血糖藥臨床試驗，並由委託試驗廠商代投保一千萬元。試驗期間因服藥發生血糖過低，致中樞神經系統不可逆損傷。下列敘述何者最正確？","options":["(A) 該受害人得由法定代理人代位請求賠償","(B) 第四期臨床試驗使用上市後藥品，所需藥費不得由健保給付","(C) 若事實認定藥害產生應由該委託廠商負責，則可依法申請藥害救濟","(D) 該委託廠商應於事實發生半年內，將保額支付受害人或其法定繼承人"],"answer":1,"image":""},{"id":"ph6-105-2-46","subject":"ph6","topic":"藥事法規-全民健康保險與藥事作業","meta":"105年第2次第46題","year":105,"session":2,"number":46,"question":"有關全民健康保險給付藥品之敘述，下列何者正確？","options":["(A) 凡領有藥品許可證之藥品，均予以給付","(B) 非屬醫療所必需之藥品，亦均予以給付","(C) 不符藥品許可證所載適應症及藥品給付規定者，一律不予給付","(D) 診斷用藥已含於醫療服務給付項目及支付標準相關費用，不另支付"],"answer":3,"image":""},{"id":"ph6-105-2-47","subject":"ph6","topic":"藥事法規-全民健康保險與藥事作業","meta":"105年第2次第47題","year":105,"session":2,"number":47,"question":"依全民健康保險法相關規定，不予支付之項目為？①義肢 ②避孕用藥 ③黑斑漂白劑 ④藥癮治療 ⑤鎮靜安眠類藥品 ⑥ 預防接種所用之疫苗","options":["(A) ①②③⑤","(B) ②③④⑥","(C) ②④⑤⑥","(D) ③④⑤⑥"],"answer":1,"image":""},{"id":"ph6-105-2-48","subject":"ph6","topic":"藥事法規-全民健康保險與藥事作業","meta":"105年第2次第48題","year":105,"session":2,"number":48,"question":"依全民健康保險醫療辦法之規定，保險對象持處方天數28日之慢性病連續處方箋調劑，須俟上次給藥期間屆滿前幾日內，始得憑原處方箋再次調劑？","options":["(A) 3","(B) 10","(C) 15","(D) 2"],"answer":1,"image":""},{"id":"ph6-105-2-49","subject":"ph6","topic":"藥事法規-全民健康保險與藥事作業","meta":"105年第2次第49題","year":105,"session":2,"number":49,"question":"依全民健康保險醫事服務機構特約及管理辦法之規定，申請保險特約藥局有下列何種情事，不予特約？","options":["(A) 負責藥師之執業執照逾有效期限未辦理更新","(B) 對衛生福利部中央健康保險署負有債務未結清，同意由應支付之醫療費用中扣抵","(C) 負責藥師罹患疾病，經衛生福利部中央健康保險署實地訪查，並請相關專科醫師認定能執行業務","(D) 容留受違約處分執行完成之藥師"],"answer":0,"image":""},{"id":"ph6-105-2-50","subject":"ph6","topic":"藥事法規-全民健康保險與藥事作業","meta":"105年第2次第50題","year":105,"session":2,"number":50,"question":"某保險特約藥局受理保險對象之處方調劑服務，處方箋記載為四種處方藥，實際交付五種處方藥，並申報五種藥費，依全民健康保險醫事服務機構特約及管理辦法之規定，應如何處辦？","options":["(A) 終止特約","(B) 停止特約1年","(C) 扣減其申報該處方調劑費用之10倍金額","(D) 違約記點"],"answer":2,"image":""},{"id":"ph6-106-1-1","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"106年第1次第1題","year":106,"session":1,"number":1,"question":"下列何者須經由立法院三讀通過，總統公布？","options":["(A) 管制藥品管理條例","(B) 藥物製造工廠設廠標準","(C) 藥品優良臨床試驗準則","(D) 藥劑生資格及管理辦法"],"answer":0,"image":""},{"id":"ph6-106-1-2","subject":"ph6","topic":"藥事法規-藥政管理組織與衛生行政","meta":"106年第1次第2題","year":106,"session":1,"number":2,"question":"衛生福利部食品藥物管理署所掌理事項不包括下列何項？","options":["(A) 化粧品業者之生產流程管理","(B) 第二級管制藥品之販賣","(C) 食品消費者保護措施之推動","(D) 中藥材基源鑑定、種源保存及培育之研究"],"answer":3,"image":""},{"id":"ph6-106-1-3","subject":"ph6","topic":"藥事法規-藥政管理組織與衛生行政","meta":"106年第1次第3題","year":106,"session":1,"number":3,"question":"下列何種食品不屬於特殊營養食品？","options":["(A) 嬰兒配方食品","(B) 較大嬰兒配方食品","(C) 特定疾病配方食品","(D) 運動員增強表現之食品"],"answer":3,"image":""},{"id":"ph6-106-1-4","subject":"ph6","topic":"藥事法規-藥政管理組織與衛生行政","meta":"106年第1次第4題","year":106,"session":1,"number":4,"question":"下列何者與衛生福利部食品藥物管理署為直接隸屬關係？","options":["(A) 財團法人藥害救濟基金會","(B) 管制藥品製藥工廠","(C) 財團法人醫藥品查驗中心","(D) 各地方政府衛生局"],"answer":1,"image":""},{"id":"ph6-106-1-5","subject":"ph6","topic":"藥事法規-藥政管理組織與衛生行政","meta":"106年第1次第5題","year":106,"session":1,"number":5,"question":"我國老年人口比率突破7%進入高齡化國家，是在民國幾年？","options":["(A) 72","(B) 82","(C) 92","(D) 102"],"answer":1,"image":""},{"id":"ph6-106-1-6","subject":"ph6","topic":"藥事法規-藥政管理組織與衛生行政","meta":"106年第1次第6題","year":106,"session":1,"number":6,"question":"下列何種疾病在臺灣已被世界衛生組織認定為根除？","options":["(A) 日本腦炎","(B) 腸病毒","(C) 瘧疾","(D) 肺結核"],"answer":2,"image":""},{"id":"ph6-106-1-7","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"106年第1次第7題","year":106,"session":1,"number":7,"question":"下列何種犯罪不罰過失犯？","options":["(A) 製造偽藥罪","(B) 未經核准擅自製造醫療器材罪","(C) 藥品擅自添加非法定防腐劑罪","(D) 擅用或冒用他人藥物之名稱罪"],"answer":3,"image":""},{"id":"ph6-106-1-8","subject":"ph6","topic":"藥事法規-藥師法與執業管理","meta":"106年第1次第8題","year":106,"session":1,"number":8,"question":"藥師法有關藥師之懲戒方式，下列何者錯誤？","options":["(A) 受廢止藥師證書之懲戒者，其兼領有之藥劑生證書無須廢止","(B) 予以警告","(C) 予以廢止執業執照","(D) 限制執業範圍"],"answer":0,"image":""},{"id":"ph6-106-1-9","subject":"ph6","topic":"藥事法規-藥師法與執業管理","meta":"106年第1次第9題","year":106,"session":1,"number":9,"question":"依藥師法之規定，有關藥師執業執照，下列何者正確？","options":["(A) 經廢止藥師執業執照未滿6個月者，不得發給執業執照","(B) 應向所在地直轄市或縣（市）主管機關送驗藥師證書，申請登記，發給執業執照","(C) 經撤銷藥師執業執照未滿2年者，不得發給執業執照","(D) 廢止執業執照應由中央主管機關為之"],"answer":1,"image":""},{"id":"ph6-106-1-10","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"106年第1次第10題","year":106,"session":1,"number":10,"question":"某民眾持慢性病處方箋至社區藥局調劑領藥，該藥局因缺乏某項處方藥品，向領有藥商許可執照之某藥品物流公司購買後，再由該藥局藥師交付該民眾，下列何者錯誤？","options":["(A) 該藥品物流公司領有藥商登記，並聘有臨床藥師，可調劑該處方供應予該社區藥局","(B) 藥局調劑處所應符合「藥局設置作業注意事項」","(C) 藥局藥師執行調劑業務應符合「藥品優良調劑作業準則」","(D) 該藥品物流公司領有藥商登記聘請藥劑生管理，僅可批發、零售，但不得調劑藥品"],"answer":0,"image":""},{"id":"ph6-106-1-11","subject":"ph6","topic":"藥事法規-藥師法與執業管理","meta":"106年第1次第11題","year":106,"session":1,"number":11,"question":"下列敘述何者錯誤？","options":["(A) 藥師應向中央主管機關申請執業登記","(B) 藥師執業應接受繼續教育，並每6年提出完成繼續教育證明文件辦理執照更新","(C) 請領藥師證書應具申請書及資格證明文件，送請中央主管機關核發之","(D) 領有藥師證書得使用藥師名稱"],"answer":0,"image":""},{"id":"ph6-106-1-12","subject":"ph6","topic":"調劑學-藥品包裝標示與儲存","meta":"106年第1次第12題","year":106,"session":1,"number":12,"question":"下列何者非屬藥師於藥劑之容器包裝上，應記明之警語或副作用？","options":["(A) 服藥期間避免開車及操作機具","(B) 接受任何手術或拔牙前，請告知醫師正在服用本藥","(C) 本藥適用於格蘭氏陽性菌感染治療","(D) 服藥期間應避免曬太陽"],"answer":2,"image":""},{"id":"ph6-106-1-13","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"106年第1次第13題","year":106,"session":1,"number":13,"question":"藥局設置必須符合下列何者？","options":["(A) 藥局設立應依藥事法規定由藥師或藥劑生親自主持","(B) 藥局設置總面積需有8平方公尺以上","(C) 藥局空間應有調劑處所，但無需候藥區","(D) 藥局可在醫療機構內以隔間方式設置，無需獨立出入口"],"answer":0,"image":""},{"id":"ph6-106-1-14","subject":"ph6","topic":"調劑學-處方判讀與調劑作業","meta":"106年第1次第14題","year":106,"session":1,"number":14,"question":"民眾至醫院就醫領藥，發現藥品劑量與藥袋標示不同，下列何者錯誤？","options":["(A) 該民眾應依藥袋指示服用方法將該藥吃完","(B) 民眾應向醫院藥師詢問","(C) 藥師違反記明藥品劑量義務","(D) 藥師應受藥師法之處分"],"answer":0,"image":""},{"id":"ph6-106-1-15","subject":"ph6","topic":"藥事法規-醫療器材管理法","meta":"106年第1次第15題","year":106,"session":1,"number":15,"question":"下列何種醫療器材之製造，應聘請藥師駐廠監製？","options":["(A) 血袋","(B) 注射針","(C) 塑膠注射筒","(D) 移植器官保存液"],"answer":3,"image":""},{"id":"ph6-106-1-16","subject":"ph6","topic":"調劑學-處方判讀與調劑作業","meta":"106年第1次第16題","year":106,"session":1,"number":16,"question":"藥品優良調劑作業準則規範「必要時，應使用有安全瓶蓋之容器」，其理由為：","options":["(A) 用藥適當評估","(B) 考量藥物安定性","(C) 無菌操作技術規定","(D) 防止兒童取得藥品"],"answer":3,"image":""},{"id":"ph6-106-1-17","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"106年第1次第17題","year":106,"session":1,"number":17,"question":"依據藥事法之規定，原領有許可證，經公告禁止製造或輸入者，其製造或輸入之業者，應即通知醫療機構、藥局及藥商回收市售品，中央衛生主管機關所訂回收期限，最長不得超過幾個月？","options":["(A) 1","(B) 2","(C) 3","(D) 6"],"answer":1,"image":""},{"id":"ph6-106-1-18","subject":"ph6","topic":"藥事法規-新藥臨床試驗與安全監視","meta":"106年第1次第18題","year":106,"session":1,"number":18,"question":"持有藥物許可證之藥商於得知嚴重藥物不良反應之日起幾日內，應依嚴重藥物不良反應通報辦法填具通報書，連同相關資料，向中央衛生主管機關或其委託機構通報？","options":["(A) 3","(B) 5","(C) 7","(D) 15"],"answer":3,"image":""},{"id":"ph6-106-1-19","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"106年第1次第19題","year":106,"session":1,"number":19,"question":"下列何者非屬西藥販賣業者之經營項目？","options":["(A) 西藥之批發","(B) 西藥之零售","(C) 西藥之調劑","(D) 西藥之輸入及輸出"],"answer":2,"image":""},{"id":"ph6-106-1-20","subject":"ph6","topic":"藥事法規-醫療器材管理法","meta":"106年第1次第20題","year":106,"session":1,"number":20,"question":"有關販賣醫療器材之規定，下列何者正確？","options":["(A) 取得藥師執業執照，即可販賣各等級醫療器材","(B) 販賣衛生材料類醫療器材，應聘專任藥師駐店始得營業","(C) 醫療器材販賣業藥商應申請中央衛生主管機關核准登記，繳納執照費，領得許可執照後，方准營業","(D) 醫療器材販賣業藥商僱用之推銷員，應由該業者向當地之直轄市、縣（市）衛生主管機關登記後，方准執行推銷工作"],"answer":3,"image":""},{"id":"ph6-106-1-21","subject":"ph6","topic":"藥事法規-新藥臨床試驗與安全監視","meta":"106年第1次第21題","year":106,"session":1,"number":21,"question":"依藥物安全監視管理辦法之規定，經衛生福利部公告指定之醫療器材，其安全監視期間為自發證日起幾年？","options":["(A) 3","(B) 5","(C) 7","(D) 10"],"answer":0,"image":""},{"id":"ph6-106-1-22","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"106年第1次第22題","year":106,"session":1,"number":22,"question":"依據藥事法之規定，新成分新藥得有幾年之資料專屬權保護？","options":["(A) 3","(B) 5","(C) 7","(D) 10"],"answer":1,"image":""},{"id":"ph6-106-1-23","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"106年第1次第23題","year":106,"session":1,"number":23,"question":"核准之藥品經稽查或檢驗發現其所含有效成分之名稱，與核准不符者，係屬藥事法所稱之：","options":["(A) 偽藥","(B) 劣藥","(C) 禁藥","(D) 仿冒藥"],"answer":0,"image":""},{"id":"ph6-106-1-24","subject":"ph6","topic":"藥事法規-醫療器材管理法","meta":"106年第1次第24題","year":106,"session":1,"number":24,"question":"下列何者非屬藥事法所稱之不良醫療器材？","options":["(A) 使用時易生危險，或可損傷人體，或使診斷發生錯誤者","(B) 未經核准，擅自製造者","(C) 含有毒質或有害物質，致使用時有損人體健康者","(D) 超過有效期間或保存期限者"],"answer":1,"image":""},{"id":"ph6-106-1-25","subject":"ph6","topic":"調劑學-處方判讀與調劑作業","meta":"106年第1次第25題","year":106,"session":1,"number":25,"question":"依藥品優良調劑作業準則之規定，下列何者不是藥事人員應於藥品容器包裝上載明事項？","options":["(A) 藥品單位含量及數量","(B) 調劑者聯絡電話","(C) 調劑者姓名","(D) 調劑或交付日期"],"answer":1,"image":""},{"id":"ph6-106-1-26","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"106年第1次第26題","year":106,"session":1,"number":26,"question":"依藥事法之規定，藥商登記事項如有變更時，應於事實發生之日起幾天內，向原核准登記之衛生主管機關申請辦理變更登記？","options":["(A) 15","(B) 20","(C) 25","(D) 30"],"answer":0,"image":""},{"id":"ph6-106-1-27","subject":"ph6","topic":"藥事法規-醫療器材管理法","meta":"106年第1次第27題","year":106,"session":1,"number":27,"question":"下列何者屬於體外診斷醫療器材（In Vitro Diagnostic, IVD）？","options":["(A) 聽診器","(B) 驗孕棒","(C) 壓舌板","(D) 血壓機"],"answer":1,"image":""},{"id":"ph6-106-1-28","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"106年第1次第28題","year":106,"session":1,"number":28,"question":"依藥事法之規定，下列何者錯誤？","options":["(A) 所稱試驗用藥物，係指醫療效能及安全尚未經證實，專供動物毒性藥理評估或臨床試驗用之藥物","(B) 所稱藥事，指藥物、藥商及藥師等有關事項","(C) 所稱製劑，係指以原料藥經加工調製，製成一定劑型及劑量之藥品","(D) 所稱醫療器材，係用於診斷、治療、減輕、直接預防人類疾病、調節生育，或足以影響人類身體結構及機能，且非以藥理、免疫或代謝方法作用於人體，以達成其主要功能之儀器、器械、用具、物質、軟體、體外試劑及其相關物品"],"answer":1,"image":""},{"id":"ph6-106-1-29","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"106年第1次第29題","year":106,"session":1,"number":29,"question":"下列何者不是依據藥事法所訂定之法規？","options":["(A) 藥品優良臨床試驗準則","(B) 醫療器材管理辦法","(C) 藥師於執業處所外執行業務管理辦法","(D) 藥品優良調劑作業準則"],"answer":2,"image":""},{"id":"ph6-106-1-30","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"106年第1次第30題","year":106,"session":1,"number":30,"question":"下列那一項係控釋劑型學名藥查驗登記應檢附之資料？","options":["(A) 藥品安全監視報告","(B) 藥品廣告資料","(C) 藥品生體相等性資料","(D) 藥品價格資料"],"answer":2,"image":""},{"id":"ph6-106-1-31","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"106年第1次第31題","year":106,"session":1,"number":31,"question":"依成藥及固有成方製劑管理辦法之規定，下列何者錯誤？","options":["(A) 成藥之標籤、仿單或包裝應標明甲類成藥或乙類成藥","(B) 所稱固有成方係指我國固有醫藥習慣使用，具有療效之中藥處方，並經中央衛生主管機關選定公布者而言","(C) 固有成方製劑應標明名稱及固有成方字樣","(D) 甲類成藥得由百貨店、雜貨店及餐飲服務商兼營零售之"],"answer":3,"image":""},{"id":"ph6-106-1-32","subject":"ph6","topic":"藥事法規-新藥臨床試驗與安全監視","meta":"106年第1次第32題","year":106,"session":1,"number":32,"question":"依藥品優良臨床試驗準則之規定，有關參與藥品臨床試驗之受試者權益，下列何者錯誤？","options":["(A) 受試者為自願性參與試驗，可不同意參與試驗或隨時退出試驗，而不受到處罰或損及其應得之利益","(B) 試驗主持人應於臨床試驗進行前，取得受試者自願給予之受試者同意書","(C) 非經人體試驗委員會之核准，不得進行藥品臨床試驗","(D) 辨認受試者身分之紀錄應保密。但如果為發表試驗結果，受試者之身分可適度公開"],"answer":3,"image":""},{"id":"ph6-106-1-33","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"106年第1次第33題","year":106,"session":1,"number":33,"question":"核准之藥品經稽查或檢驗，發現其所含有效成分之質、量或強度，與核准不符，係屬藥事法所稱之：","options":["(A) 偽藥","(B) 禁藥","(C) 劣藥","(D) 假藥"],"answer":2,"image":""},{"id":"ph6-106-1-34","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"106年第1次第34題","year":106,"session":1,"number":34,"question":"下列何者為藥事法中對毒劇藥品之規範？①購存或販售應將藥品名稱、數量，詳列簿冊 ②購存或販售之簿冊應保存3年 ③ 應專設櫥櫃加鎖儲藏 ④中藥販賣業者販售毒劇性之中藥，非有中醫師簽名、蓋章之處方箋，不得出售","options":["(A) ①②","(B) 僅③④","(C) 僅①④","(D) ①③④"],"answer":2,"image":""},{"id":"ph6-106-1-35","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"106年第1次第35題","year":106,"session":1,"number":35,"question":"下列敘述何者正確？","options":["(A) 藥商分設營業處所，可以不必再申請藥商許可執照","(B) 西藥販賣業者聘請推銷員執行推銷工作，可以不必向當地之直轄市、縣（市）衛生機關辦理登記","(C) 藥師修習中藥課程達適當標準，於親自主持之藥局得兼營中藥之調劑、供應或零售","(D) 藥商販售醫療器材無須登記"],"answer":2,"image":""},{"id":"ph6-106-1-36","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"106年第1次第36題","year":106,"session":1,"number":36,"question":"藥事法所稱之「檢驗」，係指下列何者？","options":["(A) 關於GMP藥廠藥品之查詢事項","(B) 關於藥品有無經審查檢驗核准上市之事項","(C) 關於醫療器材有無經審查檢驗核准上市之事項","(D) 關於醫療器材之化學、物理、機械、材質等鑑定事項"],"answer":3,"image":""},{"id":"ph6-106-1-37","subject":"ph6","topic":"藥事法規-醫療器材管理法","meta":"106年第1次第37題","year":106,"session":1,"number":37,"question":"檢測B型肝炎之體外檢驗試劑屬於：","options":["(A) 需辦理查驗登記之醫療器材","(B) 需辦理查驗登記之藥品","(C) 毋需辦理查驗登記之醫療器材","(D) 毋需辦理查驗登記之藥品"],"answer":0,"image":""},{"id":"ph6-106-1-38","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"106年第1次第38題","year":106,"session":1,"number":38,"question":"下列敘述何者違反藥事法？","options":["(A) 甲藥商批發處方藥予乙藥商","(B) 機構購買處方藥從事學術研究","(C) 防範新型流感，藥局自行販售克流感藥品予民眾備用","(D) 社區藥局之藥師依國民處方選輯處方，調劑藥品予民眾"],"answer":2,"image":""},{"id":"ph6-106-1-39","subject":"ph6","topic":"藥事法規-管制藥品與毒品危害防制","meta":"106年第1次第39題","year":106,"session":1,"number":39,"question":"某藥局失竊佐沛眠（Zolpidem）100粒，下列敘述何者正確？","options":["(A) 該藥品非屬於苯二氮平類（Benzodiazepines）藥物，不必依管制藥品之規定辦理","(B) 應立即報請當地衛生主管機關查核，並自減損之日起10日內，將減損品量提出申報","(C) 該藥局應將減損藥品品量，向當地警察機關申報","(D) 應保留現場，立即向當地警察機關報案，並取得證明文件"],"answer":3,"image":""},{"id":"ph6-106-1-40","subject":"ph6","topic":"藥事法規-管制藥品與毒品危害防制","meta":"106年第1次第40題","year":106,"session":1,"number":40,"question":"管制藥品買賣之單據，依規定應保存幾年？","options":["(A) 3","(B) 5","(C) 7","(D) 10"],"answer":1,"image":""},{"id":"ph6-106-1-41","subject":"ph6","topic":"藥事法規-化粧品衛生安全管理法","meta":"106年第1次第41題","year":106,"session":1,"number":41,"question":"含下列何種美白成分之美白化粧品，上市前應辦理含藥化粧品查驗登記，取得許可證，始得製造或輸入販售？","options":["(A) Kojic acid","(B) Ascorbyl Tetraisopalmitate","(C) Magnesium ascorbyl phosphate","(D) Arbutin"],"answer":1,"image":""},{"id":"ph6-106-1-42","subject":"ph6","topic":"藥事法規-化粧品衛生安全管理法","meta":"106年第1次第42題","year":106,"session":1,"number":42,"question":"下列何項產品之製造應聘請藥師駐廠監督調配製造？","options":["(A) 衛生棉","(B) 一般化粧品","(C) 輸血袋","(D) 含藥化粧品"],"answer":3,"image":""},{"id":"ph6-106-1-43","subject":"ph6","topic":"藥事法規-化粧品衛生安全管理法","meta":"106年第1次第43題","year":106,"session":1,"number":43,"question":"下列何者不是化粧品衛生管理條例所規範之用途範圍？","options":["(A) 潤澤髮膚","(B) 影響身體結構","(C) 刺激嗅覺","(D) 修飾容貌"],"answer":1,"image":""},{"id":"ph6-106-1-44","subject":"ph6","topic":"藥事法規-藥害救濟與罕見疾病","meta":"106年第1次第44題","year":106,"session":1,"number":44,"question":"有關罕ྏ疾病防治及藥物法之制訂，下࠻敘述何者錯誤？","options":["(A) 為防治罕ྏ疾病之發生，及早診斷罕ྏ疾病，加強照顧罕ྏ疾病病人","(B) 為協助病人取得罕ྏ疾病適用藥物及維持生命所需之特殊營養食品","(C) 為加強我國新藥安全監視，促進國際醫ऋ援助，ղ與國際衛生組織","(D) 為獎߭與保障罕ྏ疾病適用藥物及食品之供應、製造及研究發展"],"answer":2,"image":""},{"id":"ph6-106-1-45","subject":"ph6","topic":"藥事法規-藥害救濟與罕見疾病","meta":"106年第1次第45題","year":106,"session":1,"number":45,"question":"依藥害救濟法之規定，下࠻那些屬於藥害救濟給付範圍？①死亡給付 ②障礙給付 ③嚴重疾病給付 ④傷殘給付","options":["(A) ①③④","(B) ②③④","(C) ①②④","(D) ①②③"],"answer":3,"image":""},{"id":"ph6-106-1-46","subject":"ph6","topic":"藥事法規-藥害救濟與罕見疾病","meta":"106年第1次第46題","year":106,"session":1,"number":46,"question":"有關藥害救濟之敘述，下࠻何者錯誤？","options":["(A) 藥害救濟之請求權，自請求權人知有藥害時起，因3ࠕ間Әཊ使而消滅","(B) 藥害救濟法施ཊ前已發現之藥害，Ә得申請藥害救濟","(C) 藥害救濟審議委員會受਺藥害救濟案件後，應於收受之日起6個月內作成審定","(D) 因使用試驗用藥物而受害者，Ә得申請藥害救濟"],"answer":2,"image":""},{"id":"ph6-106-1-47","subject":"ph6","topic":"藥事法規-藥害救濟與罕見疾病","meta":"106年第1次第47題","year":106,"session":1,"number":47,"question":"下列何者非屬罕見疾病防治及藥物法所規定之內容？","options":["(A) 依本法查驗登記發給藥物許可證者，其許可證有效期間10年內，中央主管機關對於同類藥物之申請，應不予受理","(B) 依本法設置之「罕見疾病及藥物審議會」，其任務包括治療特定疾病之非罕見疾病藥物之審議","(C) 為維護病患隱私及其人格自主，醫事人員發現罹患罕見疾病之病人者，得不通報中央主管機關","(D) 中央主管機關應獎勵各級醫療機構、研究機構及罕見疾病相關團體從事罕見疾病防治工作"],"answer":2,"image":""},{"id":"ph6-106-1-48","subject":"ph6","topic":"藥事法規-全民健康保險與藥事作業","meta":"106年第1次第48題","year":106,"session":1,"number":48,"question":"下列何藥品得申請全民健康保險給付？","options":["(A) 戒菸用貼片","(B) 生髮劑","(C) 黑斑漂白劑","(D) 罕見疾病用藥"],"answer":3,"image":""},{"id":"ph6-106-1-49","subject":"ph6","topic":"藥事法規-全民健康保險與藥事作業","meta":"106年第1次第49題","year":106,"session":1,"number":49,"question":"下列敘述何者錯誤？","options":["(A) 學名藥品如實施BE後得重新建議核價","(B) BA/BE以不超過同成分原開發廠藥品支付價格為原則","(C) 新申請通過BA/BE藥品，檢討後可高於藥品支付標準內原收載之已實施BA/BE之同成分、規格、劑型、劑量之最低支付價格","(D) 一般學名藥品之支付價格不得大於BA/BE之藥品支付價格"],"answer":2,"image":""},{"id":"ph6-106-1-50","subject":"ph6","topic":"藥事法規-新藥臨床試驗與安全監視","meta":"106年第1次第50題","year":106,"session":1,"number":50,"question":"藥品優良臨床試驗準則之英文簡稱，下列何者正確？","options":["(A) GPP","(B) GDP","(C) GCP","(D) GAP"],"answer":2,"image":""},{"id":"ph6-106-2-1","subject":"ph6","topic":"藥事法規-藥政管理組織與衛生行政","meta":"106年第2次第1題","year":106,"session":2,"number":1,"question":"「食品藥物化粧品實驗室管理與認證業務之規劃及執行」係屬衛生福利部食品藥物管理署轄下何單位之掌理事項：","options":["(A) 藥品組","(B) 醫療器材及化粧品組","(C) 企劃及科技管理組","(D) 風險管理組"],"answer":3,"image":""},{"id":"ph6-106-2-2","subject":"ph6","topic":"藥事法規-藥政管理組織與衛生行政","meta":"106年第2次第2題","year":106,"session":2,"number":2,"question":"日本核能電廠輻射物質外洩污染海域，對進口海鮮食品進行通關檢驗以確保進口海鮮無輻射污染問題，其權責機關或單位為：","options":["(A) 衛生福利部食品藥物管理署","(B) 經濟部標準檢驗局","(C) 行政院農業委員會","(D) 行政院原子能委員會"],"answer":0,"image":""},{"id":"ph6-106-2-3","subject":"ph6","topic":"藥事法規-藥政管理組織與衛生行政","meta":"106年第2次第3題","year":106,"session":2,"number":3,"question":"動物用藥品之中央主管機關在美國為U.S. Food and Drug Administration，在我國之主管機關則為：","options":["(A) 衛生福利部食品藥物管理署","(B) 經濟部標準檢驗局","(C) 行政院農業委員會","(D) 行政院消費者保護會"],"answer":2,"image":""},{"id":"ph6-106-2-4","subject":"ph6","topic":"藥事法規-藥政管理組織與衛生行政","meta":"106年第2次第4題","year":106,"session":2,"number":4,"question":"在一個5,000人的社區中，進行全面糖尿病的篩檢工作，篩檢結果超出正常值的有500人，其中100人是在這次篩檢中第一次被篩檢出來，則此次篩檢糖尿病的盛行率為何？","options":["(A) 2%","(B) 8%","(C) 10%","(D) 12%"],"answer":2,"image":""},{"id":"ph6-106-2-5","subject":"ph6","topic":"藥事法規-藥政管理組織與衛生行政","meta":"106年第2次第5題","year":106,"session":2,"number":5,"question":"下列何種疾病不屬於近五年之十大死因之一？","options":["(A) 登革熱","(B) 惡性腫瘤","(C) 心臟疾病","(D) 腦血管疾病"],"answer":0,"image":""},{"id":"ph6-106-2-6","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"106年第2次第6題","year":106,"session":2,"number":6,"question":"下列何種犯罪不罰過失犯？","options":["(A) 輸入禁藥罪","(B) 醫療器材含有毒質致損人體健康罪","(C) 醫療器材使診斷發生錯誤罪","(D) 製造化粧品未經領有工廠登記罪"],"answer":3,"image":""},{"id":"ph6-106-2-7","subject":"ph6","topic":"藥事法規-全民健康保險與藥事作業","meta":"106年第2次第7題","year":106,"session":2,"number":7,"question":"甲繳納全民健康保險費，因病至A醫院看診，取得處方箋，至B藥局調劑取藥，B藥局再向中央健康保險署申請藥事服務費及藥費，依據全民健康保險法之規定，下列關係何者正確？","options":["(A) 甲為保險人","(B) 中央健康保險署為被保險人","(C) A醫院為藥事服務費及藥費之申請支付機構","(D) B藥局為保險醫事服務機構"],"answer":3,"image":""},{"id":"ph6-106-2-8","subject":"ph6","topic":"藥事法規-藥師法與執業管理","meta":"106年第2次第8題","year":106,"session":2,"number":8,"question":"可將藥師移付懲戒者，下列何者錯誤？","options":["(A) 藥師公會","(B) 縣市政府","(C) 衛生福利部","(D) 內政部"],"answer":3,"image":""},{"id":"ph6-106-2-9","subject":"ph6","topic":"藥事法規-藥師法與執業管理","meta":"106年第2次第9題","year":106,"session":2,"number":9,"question":"依藥師法之規定，下列何者非屬藥事照護業務內容？","options":["(A) 評估病人給藥流程","(B) 評估病人藥物治療流程","(C) 提供病人正確用藥諮詢","(D) 治療病人並開給藥物處方"],"answer":3,"image":""},{"id":"ph6-106-2-10","subject":"ph6","topic":"調劑學-處方判讀與調劑作業","meta":"106年第2次第10題","year":106,"session":2,"number":10,"question":"依藥師法之規定，有關藥師調劑藥品，下列何者錯誤？","options":["(A) 應按照處方調劑，不得錯誤","(B) 藥品未備或缺乏時，得通知原處方醫師，請其更換","(C) 調劑藥品不得任意省略","(D) 調劑藥品不得代以他藥"],"answer":1,"image":""},{"id":"ph6-106-2-11","subject":"ph6","topic":"調劑學-處方判讀與調劑作業","meta":"106年第2次第11題","year":106,"session":2,"number":11,"question":"藥品調劑非依一定作業程序不得為之，該作業程序經衛生福利部訂定發布為：","options":["(A) 藥師法","(B) 藥品優良製造標準","(C) 藥品優良調劑作業準則","(D) 醫事人員執業登記及繼續教育辦法"],"answer":2,"image":""},{"id":"ph6-106-2-12","subject":"ph6","topic":"調劑學-處方判讀與調劑作業","meta":"106年第2次第12題","year":106,"session":2,"number":12,"question":"有關藥師調劑，下列何者正確？","options":["(A) 警語或副作用於發藥時必須口頭告知病人，藥袋上不硬性規定列印","(B) 藥師調劑後應於藥袋上簽名蓋章","(C) 藥品不足時可代以較低劑量相同成分藥品","(D) 醫師所開處方箋，藥師調劑後應於醫師所開處方箋上簽名蓋章"],"answer":3,"image":""},{"id":"ph6-106-2-13","subject":"ph6","topic":"調劑學-處方判讀與調劑作業","meta":"106年第2次第13題","year":106,"session":2,"number":13,"question":"藥事人員受理處方箋後，應確認處方箋之合法性、完整性與處方期限有效性。其確認項目包括下列何項？","options":["(A) 藥品價格","(B) 藥品儲藏方法","(C) 醫療機構名稱、地址、電話","(D) 藥品是否過期"],"answer":2,"image":""},{"id":"ph6-106-2-14","subject":"ph6","topic":"藥事法規-藥師法與執業管理","meta":"106年第2次第14題","year":106,"session":2,"number":14,"question":"有關藥師懲戒委員會之決議，下列何者正確？","options":["(A) 廢止藥師證書","(B) 廢止考試及格證書","(C) 廢止畢業證書","(D) 廢止藥局開業執照"],"answer":0,"image":""},{"id":"ph6-106-2-15","subject":"ph6","topic":"調劑學-處方判讀與調劑作業","meta":"106年第2次第15題","year":106,"session":2,"number":15,"question":"下列敘述何者錯誤？","options":["(A) 藥師執行調劑業務，非有正當理由不得拒絕調劑","(B) 藥師應在作業處所標示受理調劑作業時間，不在時應有暫停受理調劑之標示","(C) 標示為日夜調劑之藥局，其藥師不得拒絕夜間調劑","(D) 經營藥局之藥師因出國探親而歇業超過30天，不必報請原發照機關備查"],"answer":3,"image":""},{"id":"ph6-106-2-16","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"106年第2次第16題","year":106,"session":2,"number":16,"question":"已核准藥品具有新醫療效能，屬藥事法第7條所稱之何種新藥？","options":["(A) 新劑型","(B) 新成分","(C) 新療效複方","(D) 新使用途徑"],"answer":2,"image":""},{"id":"ph6-106-2-17","subject":"ph6","topic":"藥事法規-新藥臨床試驗與安全監視","meta":"106年第2次第17題","year":106,"session":2,"number":17,"question":"依據嚴重藥物不良反應通報辦法之規定，持有藥物許可證之藥商於得知嚴重藥物不良反應之日起幾日內，應辦理通報？","options":["(A) 3","(B) 7","(C) 10","(D) 15"],"answer":3,"image":""},{"id":"ph6-106-2-18","subject":"ph6","topic":"藥事法規-藥物廣告與稽查","meta":"106年第2次第18題","year":106,"session":2,"number":18,"question":"依藥事法之規定，下列有關藥物廣告之敘述何者錯誤？","options":["(A) 藥物廣告以登載於學術性醫療刊物為限","(B) 非藥商不得為藥物廣告","(C) 非藥事法所稱之藥物，不得為醫療效能之標示或宣傳","(D) 藥物廣告，經中央或直轄市衛生主管機關核准者，其有效期間為1年，自核發證明文件之日起算"],"answer":0,"image":""},{"id":"ph6-106-2-19","subject":"ph6","topic":"藥事法規-醫療器材管理法","meta":"106年第2次第19題","year":106,"session":2,"number":19,"question":"下列何者不適用藥物優良製造準則第三編醫療器材優良製造規範？","options":["(A) 預防靜脈曲張之彈性襪","(B) 醫用氣體","(C) X光機","(D) 血管支架"],"answer":1,"image":""},{"id":"ph6-106-2-20","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"106年第2次第20題","year":106,"session":2,"number":20,"question":"下列何者為藥事法之不良醫療器材？","options":["(A) 未經核准擅自輸入者","(B) 許可證不准展延者","(C) 超過有效期間或保存期限者","(D) 未經核准擅自製造者"],"answer":2,"image":""},{"id":"ph6-106-2-21","subject":"ph6","topic":"藥事法規-新藥臨床試驗與安全監視","meta":"106年第2次第21題","year":106,"session":2,"number":21,"question":"依藥品優良臨床試驗準則之規定，試驗主持人及試驗機構應妥善保管所有臨床試驗相關重要文件，至試驗藥品於我國獲准上市後至少幾年？","options":["(A) 1","(B) 2","(C) 3","(D) 5"],"answer":1,"image":""},{"id":"ph6-106-2-22","subject":"ph6","topic":"調劑學-藥品包裝標示與儲存","meta":"106年第2次第22題","year":106,"session":2,"number":22,"question":"依藥事法第75條之規定，藥物之標籤、仿單或包裝，應依核准刊載相關事項，不包括下列何者？","options":["(A) 批號","(B) 英文說明","(C) 主治效能、性能或適應症","(D) 品名及許可證字號"],"answer":1,"image":""},{"id":"ph6-106-2-23","subject":"ph6","topic":"藥事法規-醫療器材管理法","meta":"106年第2次第23題","year":106,"session":2,"number":23,"question":"我國醫療器材分級管理規定為何？","options":["(A) 分成三個等級，風險最高者為第三等級","(B) 分成三個等級，風險最高者為第一等級","(C) 分成四個等級，風險最高者為第四等級","(D) 分成四個等級，風險最高者為第一等級"],"answer":0,"image":""},{"id":"ph6-106-2-24","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"106年第2次第24題","year":106,"session":2,"number":24,"question":"下列何者非屬新藥查驗登記申請應檢附之資料？","options":["(A) 品質管制資料","(B) 動物實驗資料","(C) 臨床試驗資料","(D) 藥價資料"],"answer":3,"image":""},{"id":"ph6-106-2-25","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"106年第2次第25題","year":106,"session":2,"number":25,"question":"藥品經稽查或檢驗發現有顯明變色、混濁、沉澱、潮解或已腐化分解者，係屬藥事法所稱之：","options":["(A) 禁藥","(B) 偽藥","(C) 劣藥","(D) 假藥"],"answer":2,"image":""},{"id":"ph6-106-2-26","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"106年第2次第26題","year":106,"session":2,"number":26,"question":"依藥事法之規定，下列何者錯誤？","options":["(A) 所稱固有成方製劑，係指依中央衛生主管機關選定公告具有醫療效能之傳統中藥處方調製（劑）之方劑","(B) 所稱成藥，係指作用緩和，無積蓄性，耐久儲存，使用簡便，並明示其效能、用量、用法，標明成藥許可證字號，經醫師指示後，即供治療疾病之用者","(C) 所稱新藥，係指經中央衛生主管機關審查認定屬新成分、新療效複方或新使用途徑製劑之藥品","(D) 所稱試驗用藥物，係指醫療效能及安全尚未經證實，專供動物毒性藥理評估或臨床試驗用之藥物"],"answer":1,"image":""},{"id":"ph6-106-2-27","subject":"ph6","topic":"藥事法規-醫療器材管理法","meta":"106年第2次第27題","year":106,"session":2,"number":27,"question":"下列何者未明訂於醫療器材查驗登記審查準則應檢附資料之規定？","options":["(A) 醫療器材查驗登記","(B) 醫療器材許可證變更","(C) 醫療器材許可證安全監視","(D) 醫療器材許可證有效期限之展延"],"answer":2,"image":""},{"id":"ph6-106-2-28","subject":"ph6","topic":"藥事法規-醫療器材管理法","meta":"106年第2次第28題","year":106,"session":2,"number":28,"question":"下列何者應向中央衛生主管機關申請查驗登記，獲得核准後，始得製造輸入？","options":["(A) 蠻牛","(B) 耳溫槍","(C) 洗面乳","(D) 真空包裝豆乾"],"answer":1,"image":""},{"id":"ph6-106-2-29","subject":"ph6","topic":"藥事法規-管制藥品與毒品危害防制","meta":"106年第2次第29題","year":106,"session":2,"number":29,"question":"依藥事法之規定，西藥販賣業者及西藥製造業者，購存或售賣管制藥品及毒劇藥品，應將藥品名稱、數量，詳列簿冊，以備檢查。此簿冊並應保存幾年？","options":["(A) 1","(B) 3","(C) 5","(D) 7"],"answer":2,"image":""},{"id":"ph6-106-2-30","subject":"ph6","topic":"藥事法規-藥物廣告與稽查","meta":"106年第2次第30題","year":106,"session":2,"number":30,"question":"下列何者無須依規定限期收回市售品，連同庫存品一併依法處理：","options":["(A) 經依法認定為偽藥、劣藥或禁藥者","(B) 藥物廣告違規經處罰鍰者","(C) 製造、輸入藥物許可證未申請展延或不准展延者","(D) 包裝、標籤、仿單經核准變更登記者"],"answer":1,"image":""},{"id":"ph6-106-2-31","subject":"ph6","topic":"藥事法規-醫療器材管理法","meta":"106年第2次第31題","year":106,"session":2,"number":31,"question":"下列何種醫療器材之製造，不須聘請藥師駐廠監製？","options":["(A) 隱形眼鏡鏡片消毒藥水","(B) 隱形眼鏡鏡片消毒藥錠","(C) 隱形眼鏡鏡片","(D) 衛生材料"],"answer":2,"image":""},{"id":"ph6-106-2-32","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"106年第2次第32題","year":106,"session":2,"number":32,"question":"某外國生產靜脈注射劑廠，擬申請輸入許可，依規定須檢附熱原試驗成績書，然該國並未有此規定。則下列有關之敘述，何者正確？","options":["(A) 若該國屬衛生福利部核列之歐美先進國，可免檢附熱原試驗成績書","(B) 若有3國以上採用證明，衛生福利部可逕予核發輸入許可證","(C) 若該廠在他國完成第三期臨床試驗，證明本產品對人體安全，可先核發2年有效期之許可證","(D) 仍需補完成熱原試驗，若檢附不實證件而涉及刑責者，移送司法機關辦理"],"answer":3,"image":""},{"id":"ph6-106-2-33","subject":"ph6","topic":"藥事法規-藥師法與執業管理","meta":"106年第2次第33題","year":106,"session":2,"number":33,"question":"某藥師藥局領有管制藥品登記證，其遷址未於期限內辦理變更，則下列處置方式何者錯誤？","options":["(A) 依藥事法之規定處罰藥局執照未辦理變更登記","(B) 依藥師法之規定處罰藥師證書未辦理變更登記","(C) 依藥師法之規定處罰藥師執業執照未辦理變更登記","(D) 依管制藥品管理條例之規定處罰管制藥品登記證未辦理變更登記"],"answer":1,"image":""},{"id":"ph6-106-2-34","subject":"ph6","topic":"藥事法規-藥物廣告與稽查","meta":"106年第2次第34題","year":106,"session":2,"number":34,"question":"下列敘述何者錯誤？","options":["(A) 電話號碼簿刊登藥商名稱，無須提出廣告申請","(B) 電話號碼簿刊登廣告內容涉及藥物廠牌、名稱、效能時視為藥物廣告","(C) 電話號碼簿刊登藥物廣告，須由藥商事先申請核准","(D) 未領有藥商許可執照者可自行於電話號碼簿刊登藥物廣告"],"answer":3,"image":""},{"id":"ph6-106-2-35","subject":"ph6","topic":"調劑學-藥品包裝標示與儲存","meta":"106年第2次第35題","year":106,"session":2,"number":35,"question":"依藥品優良調劑作業準則之規定，藥品應如何存放？","options":["(A) 依貯存條件","(B) 依不同劑型分類","(C) 依不同藥效分類","(D) 依不同廠牌分類"],"answer":0,"image":""},{"id":"ph6-106-2-36","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"106年第2次第36題","year":106,"session":2,"number":36,"question":"中藥藥膠布經檢驗出含未經核准擅自添加之西藥，應屬藥事法所稱之：","options":["(A) 毒劇藥品","(B) 劣藥","(C) 禁藥","(D) 偽藥"],"answer":3,"image":""},{"id":"ph6-106-2-37","subject":"ph6","topic":"藥事法規-新藥臨床試驗與安全監視","meta":"106年第2次第37題","year":106,"session":2,"number":37,"question":"同成分、同劑型、同劑量及同單位含量藥品，得於取得資料專屬權之新成分新藥許可證核發多久之後，提出查驗登記申請？","options":["(A) 立刻","(B) 1年","(C) 3年","(D) 5年"],"answer":2,"image":""},{"id":"ph6-106-2-38","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"106年第2次第38題","year":106,"session":2,"number":38,"question":"有關偽劣禁藥之處分，下列敘述何者錯誤？","options":["(A) 查獲之偽藥或禁藥，由直轄市或縣（市）衛生主管機關沒收銷燬之","(B) 查獲之本國製造劣藥，得由直轄市或縣（市）衛生主管機關派員監督原製造廠商限期改製","(C) 查獲之本國製造劣藥不能改製或屆期未改製者，由直轄市或縣（市）衛生主管機關沒入銷燬之","(D) 查獲之劣藥如係核准輸入者，應即封存，並由直轄市或縣（市）衛生主管機關責令原進口商限期退運出口，屆期未能退貨者，沒入銷燬之"],"answer":0,"image":""},{"id":"ph6-106-2-39","subject":"ph6","topic":"藥事法規-管制藥品與毒品危害防制","meta":"106年第2次第39題","year":106,"session":2,"number":39,"question":"依健保藥品給付規定，有關札來普隆（Zaleplon）成分藥品，下列敘述何者正確？","options":["(A) 該藥品為第四級管制藥品，屬於苯二氮平類（Benzodiazepines）藥物","(B) 使用該藥品，病歷應詳載病人發生睡眠障礙情形，惟不需作適當評估及探討可能原因","(C) 非精神科醫師若開立該藥品，每日不宜超過1顆，連續治療期間不宜超過6個月","(D) 該藥品用於治療難以入睡之失眠病人，因副作用少，對於65歲以上病患亦無劑量限制"],"answer":2,"image":""},{"id":"ph6-106-2-40","subject":"ph6","topic":"藥事法規-管制藥品與毒品危害防制","meta":"106年第2次第40題","year":106,"session":2,"number":40,"question":"社區藥局購買硝甲西泮（Nimetazepam）錠劑調劑時，依法應辦理那些事項？①申請管制藥品登記證 ②申請管制藥品使用執照 ③依醫師開立之管制藥品專用處方箋調劑 ④應設置簿冊詳實登載收支結存情形","options":["(A) ①②③","(B) ②③④","(C) ①③④","(D) ①②④"],"answer":2,"image":""},{"id":"ph6-106-2-41","subject":"ph6","topic":"藥事法規-管制藥品與毒品危害防制","meta":"106年第2次第41題","year":106,"session":2,"number":41,"question":"下列何者並非我國「毒品危害防制條例」分級列管的特性？","options":["(A) 毒性","(B) 成癮性","(C) 濫用性","(D) 社會危害性"],"answer":0,"image":""},{"id":"ph6-106-2-42","subject":"ph6","topic":"藥事法規-管制藥品與毒品危害防制","meta":"106年第2次第42題","year":106,"session":2,"number":42,"question":"醫師開立嗎啡專用處方箋給癌症病人，可調劑幾次？","options":["(A) 1次","(B) 2次","(C) 視病人需要決定調劑次數","(D) 癌症病人因安寧療護需要，可連續處方一個月"],"answer":0,"image":""},{"id":"ph6-106-2-43","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"106年第2次第43題","year":106,"session":2,"number":43,"question":"有關藥物、化粧品許可證有效期間及期滿展延規定，下列何者正確？","options":["(A) 有效期間為5年；每次展延不得超過5年","(B) 有效期間為4年；每次展延不得超過4年","(C) 有效期間為4年；每次展延不得超過5年","(D) 有效期間為5年；藥物每次展延不得超過5年，化粧品每次展延不得超過4年"],"answer":3,"image":""},{"id":"ph6-106-2-44","subject":"ph6","topic":"藥事法規-化粧品衛生安全管理法","meta":"106年第2次第44題","year":106,"session":2,"number":44,"question":"有關化粧品廣告之管理，下列敘述何者正確？","options":["(A) 應事前申請中央或直轄市衛生主管機關核准","(B) 業者須向傳播機構繳驗核准之證明文件","(C) 登載宣播內容虛偽誇大，情節重大，得由原發證照機關廢止其有關營業或設廠之許可證照","(D) 原核准廣告機關得令業者修正內容"],"answer":2,"image":""},{"id":"ph6-106-2-45","subject":"ph6","topic":"藥事法規-化粧品衛生安全管理法","meta":"106年第2次第45題","year":106,"session":2,"number":45,"question":"依衛生福利部公告，下列何種成分禁止使用於化粧品中？","options":["(A) Quaternium-15","(B) Hexachlorophene","(C) Chlorohexidine","(D) Chlorobutanol"],"answer":1,"image":""},{"id":"ph6-106-2-46","subject":"ph6","topic":"藥事法規-藥害救濟與罕見疾病","meta":"106年第2次第46題","year":106,"session":2,"number":46,"question":"依罕ྏ疾病防治及藥物法之規定，負有報告義務之醫事人員發現罕見疾病患者，應自發現之日起多少時間內，向中央主管機關陳報？","options":["(A) 24小時","(B) 3日","(C) 15日","(D) 1個月"],"answer":3,"image":""},{"id":"ph6-106-2-47","subject":"ph6","topic":"藥事法規-藥害救濟與罕見疾病","meta":"106年第2次第47題","year":106,"session":2,"number":47,"question":"某人因正當使用合法藥物而生藥害，倘經事實認定藥害之產生應由藥物輸入業者負其責任，則藥害救濟法之規定為何？","options":["(A) 仍得申請藥害救濟","(B) 不得申請藥害救濟","(C) 經提起訴訟後亦得申請藥害救濟","(D) 藥害救濟法並無規定"],"answer":1,"image":""},{"id":"ph6-106-2-48","subject":"ph6","topic":"藥事法規-藥害救濟與罕見疾病","meta":"106年第2次第48題","year":106,"session":2,"number":48,"question":"臺北市某藥商如何引進國內屬罕見疾病之藥物？","options":["(A) 向臺北市政府衛生局辦理藥品查驗登記","(B) 向衛生福利部辦理查驗登記","(C) 向國民健康署申請藥品查驗登記","(D) 直接向海關報關即可進口"],"answer":1,"image":""},{"id":"ph6-106-2-49","subject":"ph6","topic":"藥事法規-藥害救濟與罕見疾病","meta":"106年第2次第49題","year":106,"session":2,"number":49,"question":"下列何者並非藥害救濟法所稱之「合法藥物」？","options":["(A) 領有主管機關核發含藥化粧品許可證，依法製造者","(B) 領有主管機關核發藥品許可證，依法輸入者","(C) 領有主管機關核發藥品許可證，依法製造者","(D) 領有主管機關核發醫療器材許可證，依法製造、輸入者"],"answer":0,"image":""},{"id":"ph6-106-2-50","subject":"ph6","topic":"藥事法規-全民健康保險與藥事作業","meta":"106年第2次第50題","year":106,"session":2,"number":50,"question":"依全民健康保險法之規定，下列那些項目不給付？①成藥 ②指示用藥 ③藥癮治療 ④預防接種","options":["(A) 僅①","(B) 僅②③","(C) 僅②③④","(D) ①②③④"],"answer":3,"image":""},{"id":"ph6-107-1-1","subject":"ph6","topic":"藥事法規-化粧品衛生安全管理法","meta":"107年第1次第1題","year":107,"session":1,"number":1,"question":"含有醫療或毒劇藥品之化粧品，其應標示事項不包括下列何者？","options":["(A) 藥品名稱","(B) 藥品含量","(C) 藥品顏色","(D) 使用時注意事項"],"answer":2,"image":""},{"id":"ph6-107-1-2","subject":"ph6","topic":"藥事法規-化粧品衛生安全管理法","meta":"107年第1次第2題","year":107,"session":1,"number":2,"question":"依化粧品衛生管理條例之規定，化粧品（燙髮劑除外）含鉛之限量為何？","options":["(A) 不得含鉛","(B) 5ppm","(C) 10ppm","(D) 20ppm"],"answer":2,"image":"","answer_note":"更正:第2題答Ｃ給分 (原公告答案 D)"},{"id":"ph6-107-1-3","subject":"ph6","topic":"藥事法規-化粧品衛生安全管理法","meta":"107年第1次第3題","year":107,"session":1,"number":3,"question":"下列敘述何者錯誤？","options":["(A) 輸入化粧品色素，須申請衛生福利部查驗登記","(B) 輸入睫毛膏，無須申請衛生福利部查驗登記","(C) 輸入含藥化粧品，須申請衛生福利部查驗登記","(D) 製造含藥化粧品，須申請所在地衛生單位查驗登記"],"answer":3,"image":""},{"id":"ph6-107-1-4","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"107年第1次第4題","year":107,"session":1,"number":4,"question":"有關醫療機構及醫事人員管理之規定，下列敘述何者錯誤？","options":["(A) 醫事人員係指領有醫事專門職業證書之人員","(B) 醫療法人包括醫療財團法人及醫療社團法人","(C) 醫師係指醫師法所稱之醫師、牙醫師及中醫師","(D) 醫學新知之發表，未涉及招徠醫療業務者，仍視為醫療廣告"],"answer":3,"image":""},{"id":"ph6-107-1-5","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"107年第1次第5題","year":107,"session":1,"number":5,"question":"下列何者錯誤？","options":["(A) 藥商得以郵購買賣通路，販賣中風險之第二等級醫療器材","(B) 管制藥品第一級至第三級之每年申報期限與第四級一致","(C) 製造、輸入之中藥材，需符合臺灣中藥典第二版之規定","(D) 申請新成分新藥查驗登記，得免附出產國許可製售證明及採用證明"],"answer":[0,1,2,3],"image":"","answer_note":"送分:第5題一律給分。 (原公告答案 A)"},{"id":"ph6-107-1-6","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"107年第1次第6題","year":107,"session":1,"number":6,"question":"下列何項非屬法規命令之名稱？","options":["(A) 規程","(B) 要點","(C) 準則","(D) 辦法"],"answer":1,"image":""},{"id":"ph6-107-1-7","subject":"ph6","topic":"藥事法規-藥政管理組織與衛生行政","meta":"107年第1次第7題","year":107,"session":1,"number":7,"question":"衛生福利部食品藥物管理署係由下列何者於民國98年整合而成？","options":["(A) 行政院衛生署食品衛生處、藥政處、中醫藥委員會、管制藥品管理局","(B) 行政院衛生署食品衛生處、藥政處、藥物食品檢驗局、管制藥品管理局","(C) 行政院衛生署藥政處、藥物食品檢驗局、中醫藥管理局、管制藥品管理局","(D) 行政院衛生署食品衛生處、藥政處、藥物食品檢驗局、中醫藥委員會"],"answer":1,"image":""},{"id":"ph6-107-1-8","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"107年第1次第8題","year":107,"session":1,"number":8,"question":"藥事法所稱「藥事」，係指下列何者？","options":["(A) 藥物、藥商、藥局及其有關事項","(B) 藥師、藥商、藥局及其有關事項","(C) 藥廠、藥師、藥局及其有關事項","(D) 藥品、管制藥品、醫療器材及其有關事項"],"answer":0,"image":""},{"id":"ph6-107-1-9","subject":"ph6","topic":"藥事法規-藥師法與執業管理","meta":"107年第1次第9題","year":107,"session":1,"number":9,"question":"下列敘述，何者錯誤？","options":["(A) 藥師懲戒委員會由直轄市、縣（市）主管機關設置之。但藥師執業人數合計未滿一百人之縣（市），得免設藥師懲戒委員會，其藥師懲戒事項，由中央主管機關設置之藥師懲戒委員會辦理之","(B) 藥師應向執業所在地直轄市、縣（市）主管機關申請執業登記，領有執業執照，始得執業","(C) 藥師懲戒覆審委員會，由中央主管機關設置之","(D) 請領藥師證書，應具申請書及資格證明文件，送請執業所在地直轄市、縣（市）主管機關申請核發之"],"answer":3,"image":""},{"id":"ph6-107-1-10","subject":"ph6","topic":"藥事法規-藥政管理組織與衛生行政","meta":"107年第1次第10題","year":107,"session":1,"number":10,"question":"民國101年第二類急性法定傳染病之確定病例，下列何種疾病最多？","options":["(A) 阿米巴性痢疾","(B) 桿菌性痢疾","(C) 急性病毒性A型肝炎","(D) 登革熱"],"answer":3,"image":""},{"id":"ph6-107-1-11","subject":"ph6","topic":"藥事法規-藥政管理組織與衛生行政","meta":"107年第1次第11題","year":107,"session":1,"number":11,"question":"有關輸入食品邊境查驗工作，下列何者錯誤？","options":["(A) 進口食品均須於港埠邊境辦理輸入食品查驗，符合規定始能輸入","(B) 推動食品安全管制系統（HACCP），預防食品危害的發生","(C) 針對日本輸入之各類食品，加強輻射監控","(D) 對於曾檢出乙型受體素（俗稱瘦肉精）產地之牛肉產品，實施逐批查驗"],"answer":1,"image":""},{"id":"ph6-107-1-12","subject":"ph6","topic":"臨床藥學-藥事照護與用藥評估","meta":"107年第1次第12題","year":107,"session":1,"number":12,"question":"依藥師法之規定，下列何者屬於藥事照護之業務範圍？","options":["(A) 受理醫師處方調劑藥品","(B) 為病人進行藥品檢驗分析","(C) 為病人評估給藥流程","(D) 提供病人量測血壓器材"],"answer":2,"image":""},{"id":"ph6-107-1-13","subject":"ph6","topic":"臨床藥學-藥事照護與用藥評估","meta":"107年第1次第13題","year":107,"session":1,"number":13,"question":"依藥師法之規定，下列何者非屬執行藥事照護業務之機構？","options":["(A) 醫療機構","(B) 社會福利機構","(C) 護理機構","(D) 藥局"],"answer":1,"image":""},{"id":"ph6-107-1-14","subject":"ph6","topic":"藥事法規-管制藥品與毒品危害防制","meta":"107年第1次第14題","year":107,"session":1,"number":14,"question":"調劑含有麻醉或毒劇藥品之處方，其處方箋應保存幾年？","options":["(A) 1","(B) 3","(C) 5","(D) 永久"],"answer":2,"image":""},{"id":"ph6-107-1-15","subject":"ph6","topic":"調劑學-處方判讀與調劑作業","meta":"107年第1次第15題","year":107,"session":1,"number":15,"question":"有關藥品優良調劑作業準則所稱之「調製」，下列何者正確？","options":["(A) 選取正確藥品","(B) 計數正確數量","(C) 改變原劑型","(D) 包裝"],"answer":2,"image":""},{"id":"ph6-107-1-16","subject":"ph6","topic":"藥事法規-管制藥品與毒品危害防制","meta":"107年第1次第16題","year":107,"session":1,"number":16,"question":"下列何者不得調劑主成分為Buprenorphine之藥品？","options":["(A) 藥師","(B) 藥劑生","(C) 執業於無藥事人員執業偏遠地區之醫師","(D) 具護理師資格之執業藥師"],"answer":1,"image":""},{"id":"ph6-107-1-17","subject":"ph6","topic":"藥事法規-藥師法與執業管理","meta":"107年第1次第17題","year":107,"session":1,"number":17,"question":"有關藥師執業義務之敘述，下列何者錯誤？","options":["(A) 藥師停業期間以1年為限，逾1年者，應向執業所在地衛生主管機關申請核准，方可停業","(B) 藥師變更執業如停業，應自事實發生之日起30天內，報請原發執業執照之主管機關備查","(C) 藥師經登記領照執業者，其執業處所以一處為限，但於醫療機構、藥局執業者，經事先報准，得於執業處所外執行業務","(D) 藥師應親自主持所經營之藥局"],"answer":0,"image":""},{"id":"ph6-107-1-18","subject":"ph6","topic":"藥事法規-藥師法與執業管理","meta":"107年第1次第18題","year":107,"session":1,"number":18,"question":"依藥師法之規定，藥師得販賣或管理一定等級之醫療器材其範圍及種類為何？","options":["(A) 醫療器材管理辦法所定之第一、二等級醫療器材","(B) 醫療器材管理辦法所定之第一等級醫療器材","(C) 醫療器材管理辦法所定之非植入性第二等級醫療器材","(D) 醫療器材管理辦法所定之第一等級醫療器材，以及非植入性之第二等級及第三等級醫療器材"],"answer":3,"image":""},{"id":"ph6-107-1-19","subject":"ph6","topic":"藥事法規-藥師法與執業管理","meta":"107年第1次第19題","year":107,"session":1,"number":19,"question":"經考試院藥師考試及格後，如何請領藥師證書？","options":["(A) 向衛生福利部申請","(B) 向衛生福利部食品藥物管理署申請","(C) 向執業所在地衛生主管機關申請","(D) 由考試院直接核發"],"answer":0,"image":""},{"id":"ph6-107-1-20","subject":"ph6","topic":"藥事法規-藥師法與執業管理","meta":"107年第1次第20題","year":107,"session":1,"number":20,"question":"依藥師法之規定，各級藥師公會決議有違反法令者，下列處理方式何者錯誤？","options":["(A) 得由主管機關警告","(B) 得由主管機關撤銷","(C) 得由會員大會另組理、監事會","(D) 得由人民團體主管機關限期整理"],"answer":2,"image":""},{"id":"ph6-107-1-21","subject":"ph6","topic":"藥事法規-藥師法與執業管理","meta":"107年第1次第21題","year":107,"session":1,"number":21,"question":"某藥師執業登記於臺中市甲藥局，應友人之邀於臺南市為產品代言，經臺南市政府衛生局查獲代言虛偽不真實，則下列處置何者正確？","options":["(A) 臺中市藥師公會得將該藥師移付懲戒","(B) 臺南市藥師公會得廢止該藥師公會會員證明","(C) 臺南市政府得廢止該藥師執業執照","(D) 衛生福利部得處該藥師罰鍰處分"],"answer":0,"image":""},{"id":"ph6-107-1-22","subject":"ph6","topic":"藥事法規-新藥臨床試驗與安全監視","meta":"107年第1次第22題","year":107,"session":1,"number":22,"question":"臨床試驗中，受試者發生嚴重不良事件或嚴重藥品不良反應時，下列何者正確？","options":["(A) 發生嚴重不良事件時，試驗委託者應立即通知試驗主持人，並儘快提供詳細書面報告","(B) 發生未預期嚴重藥品不良反應時，試驗主持人應立即通知人體試驗委員會","(C) 發生未預期嚴重藥品不良反應，但若試驗計畫書或其他文件明確排除者，試驗主持人應立即通知執行試驗之機構","(D) 試驗委託者獲知未預期之危及生命之嚴重藥品不良反應，應於獲知日起15日內通報主管機關或其委託機構，並提供詳細書面資料"],"answer":1,"image":""},{"id":"ph6-107-1-23","subject":"ph6","topic":"藥事法規-醫療器材管理法","meta":"107年第1次第23題","year":107,"session":1,"number":23,"question":"臺南市政府衛生局查獲超過有效期間之不良醫療器材，下列敘述何者正確？","options":["(A) 製造或輸入者，移送法辦","(B) 產品直接沒入銷燬","(C) 製造或輸入者，由臺南市政府處行政罰鍰","(D) 製造或輸入者，由衛生福利部處行政罰鍰"],"answer":2,"image":""},{"id":"ph6-107-1-24","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"107年第1次第24題","year":107,"session":1,"number":24,"question":"藥事法對於不法藥物之處置，下列敘述何者錯誤？","options":["(A) 查獲之偽藥，如可改製，應經許可，限期改製","(B) 製造偽藥，應由原核准機關廢止其全部藥品許可證、藥商許可執照及藥物製造許可","(C) 製造劣藥，由直轄市或縣（市）衛生主管機關公告其公司或商號名稱、地址、負責人姓名、藥品名稱及違反情節","(D) 查獲之劣藥，如不能改製，沒入銷燬之"],"answer":0,"image":""},{"id":"ph6-107-1-25","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"107年第1次第25題","year":107,"session":1,"number":25,"question":"有關藥品安定性試驗之規定，下列敘述何者錯誤？","options":["(A) 安定性試驗報告之原始數據紀錄得免送審而留廠商備查","(B) 分段委託之藥品安定性試驗的執行，需由分段委託製造製程之受託製造廠執行","(C) 申請新成分新藥查驗登記，若送審資料已包含達有效期間之長期試驗，可免除加速試驗","(D) 申請學名藥查驗登記使用先導性規模一批，申請時應檢附6個月加速及12個月長期試驗的前6個月資料，據此可獲得最多2年之暫定有效期間的核准"],"answer":1,"image":""},{"id":"ph6-107-1-26","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"107年第1次第26題","year":107,"session":1,"number":26,"question":"下列敘述何者正確？","options":["(A) 藥商買賣來源不明之藥品，應處罰其負責人，併罰其管理人","(B) 從事人用生物藥品製造業者，未聘用具有微生物學、免疫學藥品製造專門知識5ࠕ以上製造經驗之技術人員駐廠負責製造，應處罰其負責人，併罰其監製人","(C) 藥商未依規定申請變更藥商名稱，應處罰其負責人，併罰其管理人","(D) 未有醫師處方調劑或供應管制藥品及毒劇藥品，應處罰其負責人，併罰其藥品管理人"],"answer":3,"image":""},{"id":"ph6-107-1-27","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"107年第1次第27題","year":107,"session":1,"number":27,"question":"有關藥品查驗登記之規定，下列敘述何者錯誤？","options":["(A) 送驗藥品與申請資料不符，自檢驗結果確定日起6個月內，不予受理其製造廠其他藥物之新申請案","(B) 申復期間申請重新檢驗仍未通過，中央衛生主管機關自重新檢驗結果確定日起6個月內，不予受理其製造廠其他藥物之變更案及展延案","(C) 對於查驗登記案未獲核准，申請人得自處分書送達之日起4個月內提出申復","(D) 申復人不服決定，得依法提起訴願及行政訴訟"],"answer":1,"image":""},{"id":"ph6-107-1-28","subject":"ph6","topic":"藥事法規-醫療器材管理法","meta":"107年第1次第28題","year":107,"session":1,"number":28,"question":"申請輸入第二等級或第三等級醫療器材查驗登記，下列何者非屬必須檢附之資料？","options":["(A) 醫療器材販賣業藥商許可執照影本","(B) 輸入醫療器材製造廠符合醫療器材優良製造規範之證明文件","(C) 出產國許可製售證明正本","(D) 臨床試驗報告"],"answer":3,"image":""},{"id":"ph6-107-1-29","subject":"ph6","topic":"藥事法規-藥物廣告與稽查","meta":"107年第1次第29題","year":107,"session":1,"number":29,"question":"某公司設於桃園市，輸入醫療器材及化粧品販售，下列有關廣告申請何者正確？","options":["(A) 醫療器材及化妝品均向桃園市政府申請","(B) 化粧品向桃園市政府申請；醫療器材向衛生福利部申請","(C) 醫療器材及化妝品均向衛生福利部申請","(D) 化粧品無須申請；醫療器材向桃園巿政府申請"],"answer":3,"image":""},{"id":"ph6-107-1-30","subject":"ph6","topic":"藥事法規-新藥臨床試驗與安全監視","meta":"107年第1次第30題","year":107,"session":1,"number":30,"question":"有關藥物安全監視及不良反應通報之規定，下列敘述何者正確？","options":["(A) 新藥監視廠商應每6個月提供該藥品國內外的最新安全性資料予直轄市或縣（市）衛生主管機關","(B) 醫療機構及藥局應於得知患者因嚴重藥物不良反應所造成的死亡時，應於7日內向中央衛生主管機關通報","(C) 經查驗登記發證之醫療器材，其安全監視期為5年","(D) 持有藥物許可證之藥商，應於得知患者因嚴重藥物不良反應造成死亡之日起7日內，向中央衛生主管機關通報"],"answer":1,"image":""},{"id":"ph6-107-1-31","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"107年第1次第31題","year":107,"session":1,"number":31,"question":"有關藥物查驗登記之規定，下列敘述何者錯誤？","options":["(A) 許可證有效期間為5年","(B) 國內製造之醫療器材，其標籤、仿單、包裝應以中文為主，所附外文文字應小於中文","(C) 輸入之藥物，品名及許可證字號得以外文為主，但應附上中文仿單","(D) 藥商名稱之變更，涉及權利之移轉者，應由雙方共同提出申請"],"answer":2,"image":""},{"id":"ph6-107-1-32","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"107年第1次第32題","year":107,"session":1,"number":32,"question":"有關藥廠之設廠條件，下列敘述何者錯誤？","options":["(A) 無菌產品製造工廠之設備應為能保持正壓之高效能空氣過濾系統","(B) 注射劑藥品製造工廠之藥液調製室應設置能嚴密關閉之雙重門戶","(C) 熱原試驗應以活體動物優先執行","(D) 有害氣體或粉塵，應設置密閉設備與局部排氣裝置及負壓操作予以收集"],"answer":2,"image":""},{"id":"ph6-107-1-33","subject":"ph6","topic":"藥事法規-醫療器材管理法","meta":"107年第1次第33題","year":107,"session":1,"number":33,"question":"下列有關隱形眼鏡之廣告及管理何者正確？","options":["(A) 限於學術醫療刊物廣告","(B) 應於廣告中以一般大眾皆能通曉清楚辨識之原則，加註警語","(C) 為醫師指示醫療器材","(D) 日拋棄式，為醫師指示醫療器材；雙週拋棄式，為醫師處方醫療器材"],"answer":1,"image":""},{"id":"ph6-107-1-34","subject":"ph6","topic":"藥事法規-醫療器材管理法","meta":"107年第1次第34題","year":107,"session":1,"number":34,"question":"藥物優良製造準則中有關醫療器材之規定，下列敘述何者錯誤？","options":["(A) 有關醫療器材之設計、開發、生產、安裝與服務之規範，係依據國際標準組織醫療器材品質管理系統（ISO13485）之內容訂定","(B) 製造業者應建立與維持品質手冊","(C) 品質管理系統應管制所需之文件，僅限於書面紀錄","(D) 製造業者應建立與維持紀錄，以提供符合品質管理系統要求與有效運作之證據"],"answer":2,"image":""},{"id":"ph6-107-1-35","subject":"ph6","topic":"藥事法規-藥物廣告與稽查","meta":"107年第1次第35題","year":107,"session":1,"number":35,"question":"下列含0.5% w/v酒精濃度以上之藥品製劑，其廣告應標示使用警語之規定何者正確？","options":["(A) 僅中藥酒劑應標示使用警語","(B) 內服液劑均須標示使用警語","(C) 胺基酸類不必標示使用警語","(D) 多種維他命營養劑類不必標示使用警語"],"answer":1,"image":""},{"id":"ph6-107-1-36","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"107年第1次第36題","year":107,"session":1,"number":36,"question":"下列敘述何者錯誤？","options":["(A) 西藥製造業者，應由專任藥師駐廠監製","(B) 製造衛生材料、衛生棉條業者，應聘專任藥師駐廠監製","(C) 製造化粧品含有醫療或毒劇藥品者，應聘請藥師駐廠監製","(D) 製造一般醫療設備、臨床檢驗設備及生物材料設備者，均應聘專任藥師駐廠監製"],"answer":3,"image":""},{"id":"ph6-107-1-37","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"107年第1次第37題","year":107,"session":1,"number":37,"question":"有關藥商之規定，下列何者正確？","options":["(A) 醫療器材販賣業者，應由藥師駐店管理","(B) 西藥販賣業者，應由藥師或藥劑生專任駐店管理","(C) 中藥製造業者，一定要由專任藥師駐廠監製","(D) 藥商分設營業處所或分廠，由總公司辦理藥商登記即可"],"answer":1,"image":""},{"id":"ph6-107-1-38","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"107年第1次第38題","year":107,"session":1,"number":38,"question":"下列何者錯誤？","options":["(A) 非藥商不得為藥物廣告","(B) 輸入藥品可由藥品許可證所有人授權其他藥商輸入","(C) 西藥販賣業者之藥品及其買賣，不售賣麻醉藥品者，得由藥劑生為之","(D) 藥局兼營一定等級之醫療器材，應另外請領藥商許可執照"],"answer":3,"image":""},{"id":"ph6-107-1-39","subject":"ph6","topic":"藥事法規-管制藥品與毒品危害防制","meta":"107年第1次第39題","year":107,"session":1,"number":39,"question":"有關硫美妥（Thiamylal Sodium）藥品，下列敘述何者正確？","options":["(A) 該藥品成癮性低未列為管制藥品，可用於成癮治療","(B) 該藥品為第四級管制藥品","(C) 該藥品屬於靜脈注射之麻醉劑（anesthetic），非依管制藥品管理","(D) 無醫師處方擅自調劑供應處方藥品，涉及違反管制藥品管理條例之規定"],"answer":1,"image":""},{"id":"ph6-107-1-40","subject":"ph6","topic":"藥事法規-管制藥品與毒品危害防制","meta":"107年第1次第40題","year":107,"session":1,"number":40,"question":"某高血壓病人服用全民健保特約診所醫師開立之慢性病處方藥Irbesarten，不意某日因半夜流連於保齡球館遇火警而嚴重灼傷，原診所醫師擬加開Fentanyl貼片劑連續使用14天。下列敘述何者最正確？","options":["(A) 該醫師須領有管制藥使用執照，方可開立Fentanyl貼片於同一慢性病處方箋","(B) 該診所應將病人轉介醫學中心治療，必要時仍可開立降壓藥Irbesarten連續處方","(C) Fentanyl屬外用貼片劑，可免由領受人憑身分證明簽名領受","(D) Fentanyl管制等級與Cocaine相同，故仍須貯於專櫃中保管"],"answer":1,"image":""},{"id":"ph6-107-1-41","subject":"ph6","topic":"藥事法規-管制藥品與毒品危害防制","meta":"107年第1次第41題","year":107,"session":1,"number":41,"question":"有關管制藥品之管理，下列敘述何者正確？","options":["(A) 係指具成癮性麻醉藥品、影響精神藥品及其他有加強管理必要之藥品","(B) 依其成癮性、濫用性及對社會危害性之程度，分為四級管理","(C) 不限於提供醫藥及科學上之需要","(D) 醫師、牙醫師及獸醫師外，其他人員不得使用"],"answer":0,"image":""},{"id":"ph6-107-1-42","subject":"ph6","topic":"藥事法規-化粧品衛生安全管理法","meta":"107年第1次第42題","year":107,"session":1,"number":42,"question":"下列何種違反化粧品衛生管理條例之情事，需處以刑責？","options":["(A) 販賣化粧品色素，未經直轄市或縣（市）衛生主管機關許可","(B) 廠商無故拒絕工業主管機關之檢查","(C) 製造化粧品，未領有工廠登記證","(D) 未依地方衛生主管機關限期改善，其所產製不合規定或品質管制不良化粧品者"],"answer":2,"image":""},{"id":"ph6-107-1-43","subject":"ph6","topic":"藥事法規-藥害救濟與罕見疾病","meta":"107年第1次第43題","year":107,"session":1,"number":43,"question":"下列何者並非罕見疾病及藥物審議會辦理項目？","options":["(A) 協助罕見疾病國際醫療合作","(B) 審議罕見疾病藥物臨床試驗及查驗登記","(C) 審議維持生命食品補助及研究發展","(D) 審議罕見疾病之認定"],"answer":1,"image":""},{"id":"ph6-107-1-44","subject":"ph6","topic":"藥事法規-藥害救濟與罕見疾病","meta":"107年第1次第44題","year":107,"session":1,"number":44,"question":"經由專案申請許可進口之未經查驗登記罕見疾病藥物，下列敘述何者最正確？","options":["(A) 必要時可依法申請藥害救濟","(B) 若該藥有剩餘，可比照藥物樣品，轉賣其他醫院使用","(C) 若屬管制藥品，仍須開立管制藥品專用處方箋","(D) 專案許可為衛生福利部之權責"],"answer":3,"image":""},{"id":"ph6-107-1-45","subject":"ph6","topic":"藥事法規-藥害救濟與罕見疾病","meta":"107年第1次第45題","year":107,"session":1,"number":45,"question":"藥害救濟法之藥害救濟審議委員會與人體研究法之倫理審查委員會，對於非醫療專業成員中，均規定需有具備下列何種背景者參與？","options":["(A) 法學","(B) 社會工作","(C) 統計學","(D) 心理衡鑑"],"answer":0,"image":""},{"id":"ph6-107-1-46","subject":"ph6","topic":"藥事法規-全民健康保險與藥事作業","meta":"107年第1次第46題","year":107,"session":1,"number":46,"question":"依全民健康保險法相關規定，可建議納入全民健康保險給付之藥品為：","options":["(A) 醫師處方藥品","(B) 醫師、藥師、藥劑生指示藥品","(C) 甲類成藥","(D) 乙類成藥"],"answer":0,"image":""},{"id":"ph6-107-1-47","subject":"ph6","topic":"藥事法規-全民健康保險與藥事作業","meta":"107年第1次第47題","year":107,"session":1,"number":47,"question":"下列何者非屬全民健康保險給付之藥品？","options":["(A) Amlodipine","(B) Clopidogrel","(C) Diazepam","(D) Mifepristone"],"answer":3,"image":""},{"id":"ph6-107-1-48","subject":"ph6","topic":"藥事法規-全民健康保險與藥事作業","meta":"107年第1次第48題","year":107,"session":1,"number":48,"question":"依全民健康保險醫療辦法之規定，病人於健保特約醫院取得醫師開具含管制藥品Tramadol之門診處方箋，其得選擇之下列調劑處所何者錯誤？","options":["(A) 該健保特約醫院","(B) 健保特約診所","(C) 健保特約藥師藥局","(D) 健保特約藥劑生藥局"],"answer":1,"image":""},{"id":"ph6-107-1-49","subject":"ph6","topic":"藥事法規-全民健康保險與藥事作業","meta":"107年第1次第49題","year":107,"session":1,"number":49,"question":"依照全民健康保險醫療辦法之規定，保險對象如有重複就醫或不當利用醫療資源之情形，應由下列何者予以輔導？","options":["(A) 最後就醫之健保特約醫療機構","(B) 受理處方箋之健保特約藥局","(C) 衛生福利部委託保險對象居住地之衛生局","(D) 衛生福利部中央健康保險署"],"answer":3,"image":""},{"id":"ph6-107-1-50","subject":"ph6","topic":"藥事法規-全民健康保險與藥事作業","meta":"107年第1次第50題","year":107,"session":1,"number":50,"question":"某保險特約藥局無正當理由拒絕為保險對象提供管制藥品處方箋之調劑，下列敘述何者正確？","options":["(A) 依全民健康保險法之規定，處新臺幣2萬元以上10萬元以下罰鍰","(B) 依藥師法之規定，處停業1個月以上1年以下懲戒處分","(C) 依全民健康保險醫事服務機構特約及管理辦法之規定，終止特約","(D) 依管制藥品管理條例之規定，處停止調劑6個月"],"answer":0,"image":""},{"id":"ph6-107-2-1","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"107年第2次第1題","year":107,"session":2,"number":1,"question":"依藥事法之規定，下列敘述何者錯誤？","options":["(A) 中央衛生主管機關於核發新藥許可證時，應公開申請人檢附之已揭露專利字號或案號","(B) 新成分新藥許可證自核發之日起4年內，其他藥商非經許可證所有人同意，不得引據其申請資料申請查驗登記","(C) 新成分新藥許可證核發之日起3年後，其他藥商得依藥事法及相關法規有關藥品查驗登記審查之規定提出學名藥之查驗登記申請","(D) 新成分新藥許可證核發屆滿5年之次日起，中央衛生主管機關得發給學名藥品許可證"],"answer":1,"image":""},{"id":"ph6-107-2-2","subject":"ph6","topic":"藥事法規-化粧品衛生安全管理法","meta":"107年第2次第2題","year":107,"session":2,"number":2,"question":"依化粧品衛生安全管理法（107年5月修正）之規定，有關化粧品之廣告，下列何者錯誤？","options":["(A) 不得於報紙等傳播工具登載虛偽誇大之廣告","(B) 廣告虛偽誇大情節重大得廢止商業登記事項","(C) 應事先向中央或直轄巿衛生主管機關申請核准","(D) 廣告一再有傷風化，情節重大，得令其歇業"],"answer":2,"image":""},{"id":"ph6-107-2-3","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"107年第2次第3題","year":107,"session":2,"number":3,"question":"依健康食品管理法之規定，下列敘述何者錯誤？","options":["(A) 健康食品具有增進民眾健康，減少疾病危害風險之保健功效","(B) 保健食品得經當地衛生主管機關核准而標示為健康食品","(C) 經科學化之安全及保健功效評估試驗，證明無害人體健康，且成分具有明確保健功效，得申請健康食品查驗登記","(D) 健康食品之標示或廣告，不得涉及醫療效能之內容"],"answer":1,"image":""},{"id":"ph6-107-2-4","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"107年第2次第4題","year":107,"session":2,"number":4,"question":"下列敘述何者錯誤？","options":["(A) 新成分新藥，係指新發明之成分可供藥用者","(B) 學名藥係指其國內已核准之藥品具同成分、同劑型、同劑量、同療效之製劑","(C) 新成分新藥許可證核發之日起5年後，其他藥商方得申請同成分、同劑型、同劑量及同單位含量藥品之查驗登記","(D) 中央主管機關核發新藥許可證時，應公開申請人檢附之已揭露專利字號或案號"],"answer":2,"image":""},{"id":"ph6-107-2-5","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"107年第2次第5題","year":107,"session":2,"number":5,"question":"藥物有下列何種情形，無須收回市售品？","options":["(A) 該藥物之廣告在核准登載、刊播期間變更原核准事項","(B) 製造藥物之許可證未申請展延","(C) 該藥物之仿單經核准變更登記","(D) 藥物製造工廠經檢查發現其藥物確有損害使用者健康之事實"],"answer":0,"image":""},{"id":"ph6-107-2-6","subject":"ph6","topic":"藥事法規-藥政管理組織與衛生行政","meta":"107年第2次第6題","year":107,"session":2,"number":6,"question":"下列何者非屬衛生福利部食品藥物管理署之掌理事項？","options":["(A) 第一級、第二級管制藥品之輸入、輸出、製造及販賣","(B) 中藥、植物性藥材之管理","(C) 食品之境外管理作業","(D) 防疫藥物、生物製劑之供應"],"answer":[1,3],"image":"","answer_note":"更正:第6題答Ｂ、Ｄ給分"},{"id":"ph6-107-2-7","subject":"ph6","topic":"藥事法規-藥政管理組織與衛生行政","meta":"107年第2次第7題","year":107,"session":2,"number":7,"question":"下列何者為衛生福利部中醫藥司之業務職掌？","options":["(A) 中藥材基源鑑定、種源保存及培育之研究","(B) 中藥（材）、植物性藥材之管理與品質促進政策之規劃、推動及相關法規之研擬","(C) 中藥藥理成分之分離、純化、鑑定及其他藥物化學有關之研究","(D) 中醫藥典籍之收集、保存、研究及發展應用"],"answer":1,"image":""},{"id":"ph6-107-2-8","subject":"ph6","topic":"藥事法規-藥物廣告與稽查","meta":"107年第2次第8題","year":107,"session":2,"number":8,"question":"設址於新北市之藥商，如欲申請藥品廣告，應向下列何者提出廣告申請？","options":["(A) 衛生福利部食品藥物管理署","(B) 新北市政府","(C) 新北市政府新聞局","(D) 國家通訊傳播委員會"],"answer":1,"image":""},{"id":"ph6-107-2-9","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"107年第2次第9題","year":107,"session":2,"number":9,"question":"為落實藥物製造源頭管理，下列敘述何者正確？","options":["(A) 我國自民國99年起正式成為國際醫藥品稽查協約組織（PIC/S）會員國","(B) 依據海峽兩岸醫藥衛生合作協議，自民國101年起已實施所有品項之中藥材邊境管理","(C) 製藥廠建立原料藥主檔案（DMF）制度，可加強原料藥品質管理","(D) 西藥藥品之製造應符合中央衛生主管機關參照PIC/S其規範所訂之西藥藥品優良製造規範"],"answer":3,"image":""},{"id":"ph6-107-2-10","subject":"ph6","topic":"藥事法規-藥政管理組織與衛生行政","meta":"107年第2次第10題","year":107,"session":2,"number":10,"question":"有關中央衛生經費編列，下列何者所佔比率最高？","options":["(A) 醫療保健支出","(B) 社會保險支出","(C) 教育及社會救助支出","(D) 科學支出"],"answer":1,"image":""},{"id":"ph6-107-2-11","subject":"ph6","topic":"臨床藥學-藥事照護與用藥評估","meta":"107年第2次第11題","year":107,"session":2,"number":11,"question":"藥師執行藥事照護有關藥物治療流程評估業務之處所，下列何者正確？","options":["(A) 學校","(B) 老人福利機構","(C) 里辦公室","(D) 大賣場與百貨公司"],"answer":1,"image":""},{"id":"ph6-107-2-12","subject":"ph6","topic":"臨床藥學-藥事照護與用藥評估","meta":"107年第2次第12題","year":107,"session":2,"number":12,"question":"下列敘述何者錯誤？","options":["(A) 藥師對病人進行用藥評估後，若有不適當，應填寫用藥評估表，並調整病人用藥劑量","(B) 藥師對老人福利機構之住民，得執行用藥諮詢","(C) 藥師若發現病人發生嚴重不良反應時，應向中央衛生主管機關或其委託機構通報","(D) 藥師為增進藥物療程之效益，得評估療效"],"answer":0,"image":""},{"id":"ph6-107-2-13","subject":"ph6","topic":"臨床藥學-藥事照護與用藥評估","meta":"107年第2次第13題","year":107,"session":2,"number":13,"question":"依藥師法之規定，下列何者屬於藥事照護業務範圍？","options":["(A) 評估病人是否有任何藥品引起之不良反應","(B) 幫病人量血壓，觀察血壓變化","(C) 幫病人抽血檢驗，了解病人生化檢驗值","(D) 提供病人病房設備介紹服務諮詢"],"answer":0,"image":""},{"id":"ph6-107-2-14","subject":"ph6","topic":"調劑學-處方判讀與調劑作業","meta":"107年第2次第14題","year":107,"session":2,"number":14,"question":"依藥品優良調劑作業準則之規定，藥事人員受理處方後，應確認處方之內容，下列何者正確？","options":["(A) 病患的身高","(B) 病患的體重","(C) 病患的血型","(D) 病患的性別"],"answer":3,"image":""},{"id":"ph6-107-2-15","subject":"ph6","topic":"調劑學-處方判讀與調劑作業","meta":"107年第2次第15題","year":107,"session":2,"number":15,"question":"藥品優良調劑作業準則所稱之「調劑處所」，下列何者錯誤？","options":["(A) 從事處方調劑之場所","(B) 存放調劑器具之場所","(C) 存放處方藥品之場所","(D) 存放指示藥品之場所"],"answer":3,"image":""},{"id":"ph6-107-2-16","subject":"ph6","topic":"藥事法規-藥師法與執業管理","meta":"107年第2次第16題","year":107,"session":2,"number":16,"question":"有關藥品調劑之敘述，下列何者錯誤？","options":["(A) 醫療急迫情形下，得由醫師親自為藥品之調劑","(B) 修習中藥課程達適當標準之藥師，得執行中藥調劑業務","(C) 護理人員不得調劑藥品","(D) 藥劑生不得調劑管制藥品"],"answer":3,"image":""},{"id":"ph6-107-2-17","subject":"ph6","topic":"調劑學-藥品包裝標示與儲存","meta":"107年第2次第17題","year":107,"session":2,"number":17,"question":"有關調劑交付藥品之包裝或容器，下列敘述何者錯誤？","options":["(A) 應載明藥品名稱","(B) 為防止兒童取得藥品，必要時，應使用有安全瓶蓋之容器","(C) 響應環保，得回收藥品之包裝或容器，重複使用","(D) 不得裝入有害物質所製成之容器"],"answer":2,"image":""},{"id":"ph6-107-2-18","subject":"ph6","topic":"藥事法規-藥師法與執業管理","meta":"107年第2次第18題","year":107,"session":2,"number":18,"question":"依藥師法之規定，下列何者非屬藥師執業範圍？","options":["(A) 藥品鑑定","(B) 藥品調劑","(C) 藥事照護","(D) 申報健保藥事服務費及藥品費用"],"answer":3,"image":""},{"id":"ph6-107-2-19","subject":"ph6","topic":"藥事法規-藥師法與執業管理","meta":"107年第2次第19題","year":107,"session":2,"number":19,"question":"依藥師法之規定，下列何者錯誤？","options":["(A) 藥師執業應接受繼續教育，並每6年提出完成繼續教育證明文件，辦理執業執照更新","(B) 藥師執行藥事照護業務時，應進行用藥適當性評估","(C) 藥師因業務而知悉他人之秘密，不得無故洩漏","(D) 藥師得販賣一定等級醫療器材"],"answer":1,"image":""},{"id":"ph6-107-2-20","subject":"ph6","topic":"藥事法規-藥師法與執業管理","meta":"107年第2次第20題","year":107,"session":2,"number":20,"question":"某藥師開設藥局，於民國102年因販賣管制藥品Zolpidem，經法院判決有期徒刑2年定讞，入監服刑，下列敘述何者正確？","options":["(A) 因入監服刑，應申請藥局停業2年","(B) 應廢止其藥師證書","(C) 藥師2年內不得申請執業執照","(D) 應處罰鍰處分"],"answer":1,"image":""},{"id":"ph6-107-2-21","subject":"ph6","topic":"藥事法規-醫療器材管理法","meta":"107年第2次第21題","year":107,"session":2,"number":21,"question":"有關醫療器材之回收，下列敘述何者正確？","options":["(A) 製造或輸入醫療器材許可證未申請展延者，其製造或輸入之業者，應自許可證到期之日起最長2個月內回收市售品","(B) 經依法認定為不良醫療器材者，其製造或輸入之業者，應於回收期限內回收市售品，回收期限最長不超過2個月","(C) 未經核准而製造或輸入之醫療器材，其製造或輸入之業者，應自許可證到期之日起6個月內回收市售品","(D) 包裝、標籤、仿單經核准變更登記者，藥商應自依法認定之日起，立即停止製造或輸入"],"answer":1,"image":""},{"id":"ph6-107-2-22","subject":"ph6","topic":"藥事法規-醫療器材管理法","meta":"107年第2次第22題","year":107,"session":2,"number":22,"question":"有關醫療器材之敘述，下列何者正確？","options":["(A) 直轄市或縣（市）衛生主管機關查獲未經核准擅自製造之醫療器材者，移送檢察機關偵辦","(B) 標示與原核准不符，屬藥事法第23條之不良醫療器材","(C) 直轄市或縣（市）衛生主管機關查獲標示項目與原來核准不符者，移送檢察機關偵辦","(D) 直轄市或縣（市）衛生主管機關查獲未經核准擅自製造之醫療器材，直接沒入銷燬"],"answer":0,"image":""},{"id":"ph6-107-2-23","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"107年第2次第23題","year":107,"session":2,"number":23,"question":"藥商A公司已取得某藥品之輸入許可證，藥商B公司未經許可擅自輸入完全相同產品，應如何處辦？","options":["(A) 以禁藥罪移送檢察機關偵辦","(B) 以未辦理查驗登記處以罰鍰","(C) 以劣藥處以罰鍰","(D) 以偽藥罪處3年以下有期徒刑"],"answer":[0,1],"image":"","answer_note":"更正:第23題答Ａ、Ｂ給分。"},{"id":"ph6-107-2-24","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"107年第2次第24題","year":107,"session":2,"number":24,"question":"下列敘述何者錯誤？","options":["(A) 藥事專業服務包括產品及服務，適用消費者保護法","(B) 企業經營者違反藥品未明顯警告標示具有危害消費者之副作用，致生損害於消費者或第三人，應負連帶賠償責任","(C) 媒體經營者明知廣告內容與事實不符而刊登，就消費者因信賴該廣告所受之損害，與企業經營者負連帶賠償責任","(D) 無處方箋販售處方藥，致使消費者產生危險，不適用消費者保護法"],"answer":3,"image":""},{"id":"ph6-107-2-25","subject":"ph6","topic":"藥事法規-新藥臨床試驗與安全監視","meta":"107年第2次第25題","year":107,"session":2,"number":25,"question":"某生技公司從中藥發現新抗癌有效成分，擬申請該成分之全球多國多中心新藥臨床試驗。下列敘述何者最正確？","options":["(A) 中藥在我國已使用多年，本案可免除「非臨床試驗研究」","(B) 該新抗癌成分應先經查驗登記後，方能執行臨床試驗","(C) 使用含本成分藥品進行臨床試驗，其製造應符合藥品優良製造規範","(D) 本成分療效及安全尚未證實，故臨床試驗限於在醫學中心執行"],"answer":2,"image":""},{"id":"ph6-107-2-26","subject":"ph6","topic":"藥事法規-新藥臨床試驗與安全監視","meta":"107年第2次第26題","year":107,"session":2,"number":26,"question":"下列何者非屬臨床試驗之嚴重不良事件範圍？","options":["(A) 延長住院","(B) 先天畸形","(C) 暫時失能","(D) 危及生命"],"answer":2,"image":""},{"id":"ph6-107-2-27","subject":"ph6","topic":"藥事法規-醫療器材管理法","meta":"107年第2次第27題","year":107,"session":2,"number":27,"question":"依藥事法相關規定，下列何者非屬應事前向衛生福利部辦理查驗登記始得變更之項目？","options":["(A) 變更醫療器材製造廠之製造廠廠址","(B) 醫療器材許可證增加效能","(C) 將原核定之標籤仿單更改原核准圖文之位置","(D) 醫療器材許可證之藥商名稱變更"],"answer":2,"image":""},{"id":"ph6-107-2-28","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"107年第2次第28題","year":107,"session":2,"number":28,"question":"下列敘述何者正確？","options":["(A) 藥局零售一定等級醫療器材，應另行請領藥商許可執照","(B) 藥局販賣衛生棉，不須另行請領藥商許可執照","(C) 藥局販賣衛生套，應另行請領藥商許可執照","(D) 藥局販賣藥品，應另行請領藥商許可執照"],"answer":1,"image":""},{"id":"ph6-107-2-29","subject":"ph6","topic":"藥事法規-化粧品衛生安全管理法","meta":"107年第2次第29題","year":107,"session":2,"number":29,"question":"有關「醫美」一詞，下列敘述何者正確？","options":["(A) 化粧品可作宣稱醫美保養品之廣告","(B) 僅含藥化粧品可宣稱醫美效能","(C) 含有特定成分之化粧品才能宣稱醫美級化粧品","(D) 化粧品宣稱「醫美」一詞，違反藥事法第69條「非本法所稱之藥物，不得為醫療效能之標示或宣傳」之規定"],"answer":3,"image":""},{"id":"ph6-107-2-30","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"107年第2次第30題","year":107,"session":2,"number":30,"question":"藥物製造工廠之廠房設施，經中央衛生主管機關檢查未能符合藥物優良製造準則規定，且屆期未改善者，下列處分何者錯誤？","options":["(A) 處以行政罰鍰且中央衛生主管機關得公布藥廠或藥商名稱","(B) 藥物許可證不准展延或不予受理其製造廠其他藥物之新申請案件","(C) 衛生主管機關得註銷其藥商許可執照","(D) 情節重大者，衛生主管機關得廢止藥物製造許可"],"answer":2,"image":""},{"id":"ph6-107-2-31","subject":"ph6","topic":"藥事法規-藥物廣告與稽查","meta":"107年第2次第31題","year":107,"session":2,"number":31,"question":"下列何者屬藥事法所稱「學術性醫療刊物」？","options":["(A) 健康世界","(B) 康健雜誌","(C) 藥師週刊","(D) 醫藥新聞"],"answer":2,"image":""},{"id":"ph6-107-2-32","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"107年第2次第32題","year":107,"session":2,"number":32,"question":"有關藥物優良製造規範，下列敘述何者錯誤？","options":["(A) 頭孢子菌素類藥品之製造應有專用之獨立廠房","(B) 製造過程如有粉塵或有害氣體，應設置局部排氣裝置及正壓操作","(C) 供應時已完成滅菌之醫療器材應以書面訂定產品曝露環境之要求","(D) 有關醫療器材製造有關品質紀錄之管制，應至少保存到與有效期間相同且不得少於自產品出廠後2年"],"answer":1,"image":""},{"id":"ph6-107-2-33","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"107年第2次第33題","year":107,"session":2,"number":33,"question":"有關藥品品名之規定，下列何者錯誤？","options":["(A) 品名不得涉有虛偽或誇大或使人對品名與效能產生不當聯想或混淆","(B) 以藥典記載之名稱、學名、通俗名稱或固有成方名稱為品名者，應加冠商標廠商名稱或可資辨別之名稱","(C) 品名不得使用他人藥物商標或廠商名稱。但取得所用廠商名稱之商標權者，不在此限","(D) 依藥事法撤銷許可證之藥品，2年內其品名不得再使用"],"answer":3,"image":""},{"id":"ph6-107-2-34","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"107年第2次第34題","year":107,"session":2,"number":34,"question":"下列何種產品之製造，不必聘藥師駐廠監製？","options":["(A) 衛生材料","(B) 衛生棉","(C) 衛生棉條","(D) 隱形眼鏡鏡片消毒藥錠"],"answer":1,"image":""},{"id":"ph6-107-2-35","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"107年第2次第35題","year":107,"session":2,"number":35,"question":"有關領有藥物許可證之藥商，下列敘述何者正確？","options":["(A) 申請停業，僅需將藥商許可執照隨繳當地衛生主管機關","(B) 申請停業，每次不超過1年","(C) 停業後復業，應於停業期滿前10天內申請","(D) 申請歇業時，僅需將藥物許可證繳銷"],"answer":1,"image":""},{"id":"ph6-107-2-36","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"107年第2次第36題","year":107,"session":2,"number":36,"question":"依藥物製造業者檢查辦法之規定，有關新設廠之國產藥物製造業者，下列敘述何者錯誤？","options":["(A) 其硬體設備及衛生條件，應由工業主管機關及直轄市或縣（市）衛生主管機關檢查之","(B) 其軟體設備及衛生條件，應由中央衛生主管機關檢查之","(C) 後續追蹤管理的檢查，每2年檢查一次，並得視其生產產品之劑型、作業內容及歷次檢查紀錄，延長1年至2年","(D) 申請評鑑藥品優良製造（GMP），由直轄市或縣（市）衛生主管機關得會同工業主管機關赴廠檢查之"],"answer":3,"image":""},{"id":"ph6-107-2-37","subject":"ph6","topic":"藥事法規-醫療器材管理法","meta":"107年第2次第37題","year":107,"session":2,"number":37,"question":"下列何項醫療器材應依藥事法之規定實施邊境管理，於輸入時進行抽驗？","options":["(A) 血壓計","(B) 耳溫槍","(C) 隱形眼鏡","(D) 衛生套"],"answer":3,"image":""},{"id":"ph6-107-2-38","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"107年第2次第38題","year":107,"session":2,"number":38,"question":"依藥事法之規定，下列行為何者應負刑事責任？","options":["(A) 無處方箋販賣處方藥","(B) 非藥師執行藥品之調劑","(C) 擅自添加非法定著色劑於藥品","(D) 性能與核准不符之醫療器材"],"answer":2,"image":""},{"id":"ph6-107-2-39","subject":"ph6","topic":"藥事法規-管制藥品與毒品危害防制","meta":"107年第2次第39題","year":107,"session":2,"number":39,"question":"有關愷他命（Ketamine）藥品，下列敘述何者正確？","options":["(A) 藥師調劑該藥品，不需要管制藥品專用處方箋","(B) 民眾購買該藥品，不需要領受人簽名領受","(C) 無正當理由持有或施用愷他命者，涉嫌違反毒品危害防制條例","(D) 藥劑生不得調劑含愷他命成分之藥品"],"answer":2,"image":""},{"id":"ph6-107-2-40","subject":"ph6","topic":"藥事法規-管制藥品與毒品危害防制","meta":"107年第2次第40題","year":107,"session":2,"number":40,"question":"首次用於伊拉克戰爭，供戰鬥人員保持警醒之莫待芬寧（Modafinil），在我國是與下列何藥屬同一管制等級？","options":["(A) 丁基原啡因（Buprenorphine）","(B) 二氮平（Diazepam）","(C) 咖啡因（Caffeine）","(D) 美沙冬（Methadone）"],"answer":1,"image":""},{"id":"ph6-107-2-41","subject":"ph6","topic":"藥事法規-管制藥品與毒品危害防制","meta":"107年第2次第41題","year":107,"session":2,"number":41,"question":"病人隨身攜帶自用之第一級至第三級管制藥品入出境時，下列敘述何者錯誤？","options":["(A) 應檢附必須施用管制藥品理由之醫師診斷證明書","(B) 所攜帶管制藥品不限於該醫師證明之處方量","(C) 聲明書應載明出國或入國口岸","(D) 報請備查之機關為衛生福利部食品藥物管理署"],"answer":1,"image":""},{"id":"ph6-107-2-42","subject":"ph6","topic":"藥事法規-化粧品衛生安全管理法","meta":"107年第2次第42題","year":107,"session":2,"number":42,"question":"依現行（105年11月修正）化粧品衛生管理條例之規定，下列化粧品何者不需加刊注意事項？","options":["(A) 防曬化粧品","(B) 染髮劑","(C) 牙齒美白劑","(D) 燙髮劑"],"answer":0,"image":""},{"id":"ph6-107-2-43","subject":"ph6","topic":"藥事法規-化粧品衛生安全管理法","meta":"107年第2次第43題","year":107,"session":2,"number":43,"question":"依現行（105年11月修正）化粧品衛生管理條例之規定，下列有關防曬化粧品之管理，何者正確？","options":["(A) 含防曬成分之化粧品，均以含藥化粧品管理","(B) 化粧品防曬效能之測試，國際間都以人體測試為主","(C) 防曬係數（SPF）之最高標示值，國際間均規定為50","(D) 防曬化粧品無法完全防止紫外線曬傷"],"answer":3,"image":""},{"id":"ph6-107-2-44","subject":"ph6","topic":"藥事法規-新藥臨床試驗與安全監視","meta":"107年第2次第44題","year":107,"session":2,"number":44,"question":"下列何種核准上市藥物，應由衛生福利部編列年報，載明其用量、人數、不良反應及其他相關報告資料？","options":["(A) 第一級、第二級管制藥品","(B) 新興藥物及生物製劑","(C) 罕見疾病藥物","(D) 血漿製劑與活菌疫苗"],"answer":2,"image":""},{"id":"ph6-107-2-45","subject":"ph6","topic":"藥事法規-藥政管理組織與衛生行政","meta":"107年第2次第45題","year":107,"session":2,"number":45,"question":"下列何法規之主管機關排除地方主管機關？","options":["(A) 全民健康保險法與藥害救濟法","(B) 藥品優良臨床試驗準則與管制藥品管理條例","(C) 化粧品衛生管理條例與藥師法","(D) 藥物製造工廠設廠標準與藥物優良製造準則"],"answer":0,"image":""},{"id":"ph6-107-2-46","subject":"ph6","topic":"藥事法規-全民健康保險與藥事作業","meta":"107年第2次第46題","year":107,"session":2,"number":46,"question":"依全民健康保險醫療辦法之規定，保險對象於健保特約醫院取得醫師所開具交付之一般藥品處方箋及第二級麻醉藥品專用處方箋，下列敘述何者正確？","options":["(A) 第二級麻醉藥品專用處方箋應在健保特約醫院調劑，一般藥品處方箋可以在健保特約藥師藥局調劑","(B) 一般藥品處方箋及第二級麻醉藥品專用處方箋可以選擇在健保特約診所調劑","(C) 一般藥品處方箋可以在健保特約藥劑生藥局調劑，第二級麻醉藥品專用處方箋應在健保特約藥師藥局調劑","(D) 一般藥品處方箋及第二級麻醉藥品專用處方箋應同時在健保特約藥師藥局調劑"],"answer":3,"image":""},{"id":"ph6-107-2-47","subject":"ph6","topic":"藥事法規-全民健康保險與藥事作業","meta":"107年第2次第47題","year":107,"session":2,"number":47,"question":"依全民健康保險醫療辦法之規定，非屬慢性病之一般處方箋，每次以不超過幾日份用藥量為原則？","options":["(A) 3","(B) 7","(C) 28","(D) 30"],"answer":1,"image":""},{"id":"ph6-107-2-48","subject":"ph6","topic":"藥事法規-全民健康保險與藥事作業","meta":"107年第2次第48題","year":107,"session":2,"number":48,"question":"保險特約藥局以送贈品方式招徠保險對象調劑慢性病連續處方箋之行為，依法應如何處理？","options":["(A) 依全民健康保險醫事服務機構特約及管理辦法之規定予以違約記點1點","(B) 依全民健康保險醫療辦法之規定不予支付藥費及藥事服務費","(C) 依藥事法之規定處分罰鍰","(D) 依全民健康保險法之規定處分停業"],"answer":0,"image":""},{"id":"ph6-107-2-49","subject":"ph6","topic":"藥事法規-全民健康保險與藥事作業","meta":"107年第2次第49題","year":107,"session":2,"number":49,"question":"依全民健康保險醫事服務機構特約及管理辦法之規定，保險特約藥局有下列情事者，應予終止特約？","options":["(A) 受衛生主管機關停業處分","(B) 以虛偽之證明申報藥費及藥事服務費用，情節重大","(C) 受罰鍰處分未繳清者","(D) 受違約記點未完成改善者"],"answer":1,"image":""},{"id":"ph6-107-2-50","subject":"ph6","topic":"藥事法規-全民健康保險與藥事作業","meta":"107年第2次第50題","year":107,"session":2,"number":50,"question":"某保險特約藥局於停約期間，受理保險對象之處方調劑服務，交由另一保險特約藥局申報藥費及藥事服務費，依全民健康保險醫事服務機構特約及管理辦法之規定，應如何處辦？","options":["(A) 終止特約","(B) 停止特約1年","(C) 受申報費用10倍罰鍰處分","(D) 違約記點"],"answer":0,"image":""},{"id":"ph6-108-1-1","subject":"ph6","topic":"藥事法規-藥政管理組織與衛生行政","meta":"108年第1次第1題","year":108,"session":1,"number":1,"question":"下列敘述何者錯誤？","options":["(A) 衛⽣福利部為辦理中醫藥之研究，特設國家中醫藥研究所","(B) 衛⽣福利部之次級機關包括有「疾病管制署」、「食品藥物管理署」、「中央健康保險署」、「國⺠健康署」及「國⺠年⾦署」","(C) ⾏政院為辦理全國衛⽣及福利業務，特設衛⽣福利部","(D) 勞保相關業務非屬衛⽣福利部職掌"],"answer":1,"image":""},{"id":"ph6-108-1-2","subject":"ph6","topic":"藥事法規-化粧品衛生安全管理法","meta":"108年第1次第2題","year":108,"session":1,"number":2,"question":"依現⾏（105年11⽉修正）化粧品衛⽣管理條例之規定，下列何種⾏為應負刑事責任？","options":["(A) 化粧品⾊素未經中央衛⽣主管機關核准擅⾃變更已核准事項","(B) 製造化粧品使⽤非經中央衛⽣主管機關核准之⾊素","(C) 販賣來源不明之化粧品","(D) 輸入化粧品未經中央衛⽣主管機關核准⽽在國內分裝出售"],"answer":1,"image":""},{"id":"ph6-108-1-3","subject":"ph6","topic":"藥事法規-管制藥品與毒品危害防制","meta":"108年第1次第3題","year":108,"session":1,"number":3,"question":"下列敘述何者正確？","options":["(A) 管制藥品關於安全監視及嚴重不良反應通報業務之法定主管機關為衛⽣福利部","(B) 衛⽣福利部食品藥物管理署；直轄市及縣（市）政府；直轄市及縣（市）政府衛⽣局；三者均為藥事法所定之衛⽣主管機關","(C) 衛⽣福利部食品藥物管理署為法定衛⽣主管機關；直轄市及縣（市）政府衛⽣局為法定藥政管理機關","(D) ⿇醉藥品製劑之查驗登記，由衛⽣福利部食品藥物管理署管制藥品組負責辦理"],"answer":0,"image":""},{"id":"ph6-108-1-4","subject":"ph6","topic":"藥事法規-藥政管理組織與衛生行政","meta":"108年第1次第4題","year":108,"session":1,"number":4,"question":"衛⽣福利部之附屬機關，不包括下列何者？","options":["(A) 中央健康保險署","(B) 社會及家庭署","(C) 護理及健康照護署","(D) 食品藥物管理署"],"answer":2,"image":""},{"id":"ph6-108-1-5","subject":"ph6","topic":"藥事法規-新藥臨床試驗與安全監視","meta":"108年第1次第5題","year":108,"session":1,"number":5,"question":"有關新藥上市後之安全監視，下列何者錯誤？","options":["(A) 為許可證持有者之義務","(B) 應積極收集國內、外藥品使⽤之安全資料","(C) 醫療機構應將處⽅全⾯釋出","(D) 安全性報告應依衛⽣福利部指定時間通報"],"answer":2,"image":""},{"id":"ph6-108-1-6","subject":"ph6","topic":"藥事法規-藥政管理組織與衛生行政","meta":"108年第1次第6題","year":108,"session":1,"number":6,"question":"下列有關醫事⼈⼒及執業環境之敘述，何者錯誤？","options":["(A) 為因應未來⼈⼝老化及五⼤科醫師⼈⼒需求，⾃105學年度辦理培育重點科別公費醫學⽣","(B) 為建立中醫師臨床訓練制度，依師資培訓認證要點培訓指導醫師及指導藥師","(C) 為保障醫師勞動權益，受僱醫師已全⾯納入勞基法適⽤對象","(D) 施⾏⽣產事故救濟條例，以承擔女性的⽣產風險"],"answer":2,"image":""},{"id":"ph6-108-1-7","subject":"ph6","topic":"藥事法規-藥政管理組織與衛生行政","meta":"108年第1次第7題","year":108,"session":1,"number":7,"question":"下列何者非屬全⾯推動癌症篩檢之項⽬？","options":["(A) ⼦宮頸癌","(B) 肝癌","(C) 乳癌","(D) ⼤腸癌"],"answer":1,"image":""},{"id":"ph6-108-1-8","subject":"ph6","topic":"藥事法規-藥師法與執業管理","meta":"108年第1次第8題","year":108,"session":1,"number":8,"question":"依藥師法之規定，下列敘述何者錯誤？","options":["(A) 對處⽅之內容如有可疑之點，應詢明原處⽅醫師確認後⽅得調劑","(B) 處⽅箋上所載500mg acetaminophen錠劑缺乏時，可改以同廠牌、同成分、同劑量之膠囊劑替代","(C) 應注意處⽅上年、⽉、⽇、病⼈姓名、性別、年齡、藥名、劑量、⽤法、醫師署名或蓋章等項","(D) 對於醫師所開處⽅，祇許調劑⼀次"],"answer":1,"image":""},{"id":"ph6-108-1-9","subject":"ph6","topic":"藥事法規-藥師法與執業管理","meta":"108年第1次第9題","year":108,"session":1,"number":9,"question":"依藥師法之規定，藥師調劑應按照下列何者，不得錯誤？","options":["(A) 藥品仿單（說明書）","(B) 常⽤藥品⼿冊","(C) 藥理及治療學教科書","(D) 醫師處⽅"],"answer":3,"image":""},{"id":"ph6-108-1-10","subject":"ph6","topic":"藥事法規-全民健康保險與藥事作業","meta":"108年第1次第10題","year":108,"session":1,"number":10,"question":"依藥事法第102條之規定，全⺠健康保險實施2年後，醫師得依⾃開處⽅，親⾃為藥品之調劑情形為何？","options":["(A) 具有藥事法規定之調劑設備者","(B) 醫療急迫情形","(C) 附近藥局未備有所處⽅之藥品","(D) 1公⾥內無藥事⼈員執業"],"answer":1,"image":""},{"id":"ph6-108-1-11","subject":"ph6","topic":"臨床藥學-藥事照護與用藥評估","meta":"108年第1次第11題","year":108,"session":1,"number":11,"question":"依藥師法之規定，下列何者屬藥事照護業務範圍？","options":["(A) 藥品調劑","(B) 藥品檢驗","(C) 病⼈給藥流程評估","(D) 藥品鑑定"],"answer":2,"image":""},{"id":"ph6-108-1-12","subject":"ph6","topic":"藥事法規-藥師法與執業管理","meta":"108年第1次第12題","year":108,"session":1,"number":12,"question":"依藥師法之規定，下列有關藥師業務之敘述，何者錯誤？","options":["(A) 藥師得執⾏藥品儲備、供應及分裝之監督","(B) 藥師均得執⾏中藥製劑之製造、供應及調劑","(C) 藥師得執⾏含藥化粧品製造之監製","(D) 藥師得販賣或管理⼀定等級之醫療器材"],"answer":1,"image":""},{"id":"ph6-108-1-13","subject":"ph6","topic":"藥事法規-藥師法與執業管理","meta":"108年第1次第13題","year":108,"session":1,"number":13,"question":"下列有關藥師懲戒之敘述，何者錯誤？","options":["(A) 藥師懲戒委員會由直轄市、縣（市）主管機關設置之，但藥師執業⼈數合計未滿⼀百⼈之縣（市），得免設藥師懲戒委員會","(B) 藥師藉其專業⾝分為產品代⾔誇⼤不實，致有誤導消費者誤信廣告內容⽽購買之虞者，應以停業為懲戒⽅ 式","(C) 法定懲戒⽅式共有5項，其性質不相牴觸者，得合併為⼀懲戒處分","(D) 由藥師公會或主管機關移付之懲戒事件，應由藥師懲戒委員會處理"],"answer":1,"image":""},{"id":"ph6-108-1-14","subject":"ph6","topic":"藥事法規-藥師法與執業管理","meta":"108年第1次第14題","year":108,"session":1,"number":14,"question":"依藥師法之規定，下列何者正確？","options":["(A) 領得藥師證書後第六年，⾸次申請執業登記，得免檢具繼續教育之證明文件","(B) 藥師申請停歇業時，應⾃事實發⽣之⽇起⼀週內，報請原發執業執照之主管機關備查","(C) 藥師歇業後重新申請執業登記，執業登記⽇期未逾原發執業執照所載應更新⽇期者，以該⽇期為新發執業執照應更新⽇期","(D) 藥師因執業異動，中斷執業達⼀個⽉以上者，於再⾏申請執業時，應檢附申請⽇前⼀年內接受繼續教育25點以上證明文件"],"answer":2,"image":""},{"id":"ph6-108-1-15","subject":"ph6","topic":"藥事法規-藥師法與執業管理","meta":"108年第1次第15題","year":108,"session":1,"number":15,"question":"某藥師取得執業執照第⼆年，出國進修歇業兩年半，返國後再申請回原醫院執業，下列有關繼續教育之敘述，何者正確？","options":["(A) 出國進修歇業兩年半，繼續教育積分數仍有效，可免提交繼續教育積分數","(B) 應檢具120積分數繼續教育證明文件，始得繼續執業","(C) 進修內容如與藥學相關，得免具繼續教育積分數證明文件，即可繼續執業","(D) 得以前⼀年內接受繼續教育20積分數以上之證明文件，重新申請執業登記"],"answer":3,"image":""},{"id":"ph6-108-1-16","subject":"ph6","topic":"臨床藥學-藥事照護與用藥評估","meta":"108年第1次第16題","year":108,"session":1,"number":16,"question":"病⼈「⽣病在家」、「住院治療」，應分別由下列何種醫事⼈員提供其藥事照護？","options":["(A) 藥師、醫師","(B) 醫師、護理師","(C) 藥師、藥師","(D) 藥師、護理師"],"answer":2,"image":""},{"id":"ph6-108-1-17","subject":"ph6","topic":"藥事法規-藥師法與執業管理","meta":"108年第1次第17題","year":108,"session":1,"number":17,"question":"下列有關藥師於執業處所外執⾏業務之敘述，何者錯誤？","options":["(A) 藥師於執業處所外執⾏業務者，應事先報請中央主管機關核准","(B) 藥師於醫療機構、藥局執業者，⽅得事先報准於執業處所外執⾏業務","(C) 藥師於藥商執業者，不得於執業處所外執⾏業務","(D) 藥師於執業處所外執⾏業務，應考量⼯作時數分配之適當性"],"answer":0,"image":""},{"id":"ph6-108-1-18","subject":"ph6","topic":"臨床藥學-藥物不良反應與交互作用","meta":"108年第1次第18題","year":108,"session":1,"number":18,"question":"下列何者非屬嚴重藥物不良反應通報辦法所稱之嚴重藥物不良反應？","options":["(A) 全⾝出疹⼦","(B) 造成永久性殘疾","(C) 胎嬰兒先天性畸形","(D) 導致病⼈住院或延⻑病⼈住院時間"],"answer":0,"image":""},{"id":"ph6-108-1-19","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"108年第1次第19題","year":108,"session":1,"number":19,"question":"106年發⽣之降⾎脂藥物「冠脂妥」事件，經檢驗發現其所含有效成分之名稱與核准不符，屬藥事法所稱之：","options":["(A) 偽藥","(B) 劣藥","(C) 禁藥","(D) 不良藥品"],"answer":0,"image":""},{"id":"ph6-108-1-20","subject":"ph6","topic":"藥事法規-醫療器材管理法","meta":"108年第1次第20題","year":108,"session":1,"number":20,"question":"病⼈使⽤⼼臟節律器，不幸發⽣危及⽣命事件，醫療機構及藥局應如何處置？","options":["(A) 以健保醫療資訊雲端查詢系統之「疑似藥品療效不相等」管道通報","(B) 收集詳細圖片及事件紀錄，送衛⽣福利部食品藥物管理署供判定是否為劣藥","(C) 醫院應於15⽇內，依規定辦理通報，並副知持有⼼臟節律器許可證之藥商","(D) 緊急時得先⾏以⼝頭⽅式通報，並於期限內完成書⾯通報"],"answer":3,"image":""},{"id":"ph6-108-1-21","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"108年第1次第21題","year":108,"session":1,"number":21,"question":"依藥事法之規定，下列敘述何者正確？","options":["(A) 除藥局外，醫療機構及藥商，對於嚴重藥物不良反應，應⾏通報","(B) 醫療機構因嚴重藥物不良反應致⽣死亡或危及⽣命情形時，應立即向所在地衛⽣主管機關通報","(C) 新藥，須依規定進⾏安全監視","(D) 所有第⼆等級及第三等級醫療器材均應監視其安全性"],"answer":2,"image":""},{"id":"ph6-108-1-22","subject":"ph6","topic":"調劑學-處方判讀與調劑作業","meta":"108年第1次第22題","year":108,"session":1,"number":22,"question":"依藥品優良調劑作業準則之規定，下列敘述何者錯誤？","options":["(A) 依處⽅箋內容選取正確藥品、計數正確數量、書寫藥袋或貼標籤、包裝等過程之⾏為，為調配","(B) 依醫師所開具之處⽅箋，配製新製品之⾏為，為調配","(C) 藥師⾃受理處⽅⾄交付藥品⽤藥指導等相關之⾏為，為調劑","(D) 依醫師所開具之處⽅箋，改變原劑型之⾏為，為調製"],"answer":1,"image":""},{"id":"ph6-108-1-23","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"108年第1次第23題","year":108,"session":1,"number":23,"question":"下列有關衛⽣主管機關檢查事項之敘述，何者錯誤？","options":["(A) 派員檢查時，應出⽰有關執⾏職務之證明文件","(B) 抽驗藥物屬執⾏公權⼒，得不出具單據","(C) 得檢查藥物製造業者、販賣業者之處所設施及有關業務","(D) 得檢查醫療機構或藥局之有關業務"],"answer":1,"image":""},{"id":"ph6-108-1-24","subject":"ph6","topic":"藥事法規-醫療器材管理法","meta":"108年第1次第24題","year":108,"session":1,"number":24,"question":"下列有關醫療器材品名之規定，何者錯誤？","options":["(A) 不得與其他廠商醫療器材品名相同，或涉及仿冒或影射情事","(B) 中文品名不得夾雜外文或數字，但具直接意義或英文商標具特殊意義經中央衛⽣主管機關核定者，不在此限","(C) 品名不得使⽤他⼈藥物商標或廠商名稱，但已取得商標或授權使⽤者，不在此限","(D) 外銷專⽤醫療器材之中英文品名為因應國際市場需求，無特別限制"],"answer":3,"image":""},{"id":"ph6-108-1-25","subject":"ph6","topic":"藥事法規-藥師法與執業管理","meta":"108年第1次第25題","year":108,"session":1,"number":25,"question":"下列敘述何者正確？","options":["(A) 義診或巡迴醫療服務時，藥師即可逕⾏於執業處所外執⾏業務","(B) 醫師治療癌末病⼈，得視需要，開立海洛因處⽅，交由藥師調劑","(C) 病⼈可持健保特約醫院釋出之處⽅箋，⾄該醫院轄區之健保特約藥局調劑","(D) 修習中藥課程達適當標準之醫師，得兼營中藥之調劑"],"answer":2,"image":""},{"id":"ph6-108-1-26","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"108年第1次第26題","year":108,"session":1,"number":26,"question":"有關擔任藥廠監製藥師之應⾏注意事項，下列敘述何者正確？","options":["(A) 倉儲採完全電腦化儲存系統者，原料標籤須以資料易讀⽅式標出","(B) 電腦化系統安定性試驗資料，僅能由原始操作者修改數據","(C) 藥廠均應有品質管制部⾨，該部⾨⽬前暫未列為管制區","(D) 應視需要，核對產率及進⾏重量/數量調和，以確保無超出允收範圍的差異"],"answer":3,"image":""},{"id":"ph6-108-1-27","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"108年第1次第27題","year":108,"session":1,"number":27,"question":"依⻄藥藥品優良製造規範之規定，為使因交叉污染所引起之嚴重醫療傷害的風險降到最低，那些藥品應有專 ⽤且⾃⾜圍堵的⽣產設施？①青黴素②疫苗③可待因④免疫球蛋⽩","options":["(A) ①②③","(B) ①③④","(C) ①②④","(D) ②③④"],"answer":2,"image":""},{"id":"ph6-108-1-28","subject":"ph6","topic":"藥事法規-藥物廣告與稽查","meta":"108年第1次第28題","year":108,"session":1,"number":28,"question":"下列有關藥物廣告之敘述，何者正確？","options":["(A) 採訪醫療成功案例推廣藥物療效","(B) 使⽤者⾒證記錄成⼿冊發給⺠眾","(C) 持藥物空盒5件回郵可參加抽獎","(D) 非經藥物許可證持有者之委託，主管機關不受理申請藥物廣告"],"answer":3,"image":""},{"id":"ph6-108-1-29","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"108年第1次第29題","year":108,"session":1,"number":29,"question":"下列有關衛⽣主管機關檢查藥物製造業及販賣業之敘述，何者錯誤？","options":["(A) 得出具單據抽驗藥物，業者不得無故拒絕","(B) 抽驗藥物之數量以⾜供檢驗之⽤者為限","(C) 依藥物製造業者檢查辦法之規定檢查藥廠","(D) 檢查藥物販賣業有關業務之內容，包括使⽤塑膠袋數量、銷售全部產品之營業⾦額"],"answer":3,"image":""},{"id":"ph6-108-1-30","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"108年第1次第30題","year":108,"session":1,"number":30,"question":"依藥事法之規定，有關國內製造藥品，下列敘述何者錯誤？","options":["(A) 製造藥物，應由藥物製造⼯廠為之","(B) 藥物製造，應符合藥物優良調製準則之規定","(C) 應取得藥物製造許可後，始得製造","(D) 從事藥物研發之機構或公司，其研發⽤藥物，應於符合中央衛⽣主管機關規定之⼯廠或場所製造"],"answer":1,"image":""},{"id":"ph6-108-1-31","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"108年第1次第31題","year":108,"session":1,"number":31,"question":"依藥事法之規定，下列何者非屬藥商？","options":["(A) 中藥製造業","(B) 醫療器材製造業","(C) ⻄藥販賣業","(D) 含藥化粧品製造業"],"answer":3,"image":""},{"id":"ph6-108-1-32","subject":"ph6","topic":"藥事法規-新藥臨床試驗與安全監視","meta":"108年第1次第32題","year":108,"session":1,"number":32,"question":"依藥事法之規定，中央衛⽣主管機關於核發新藥許可證時，應公開申請⼈檢附之下列何項資料？","options":["(A) 臨床試驗報告書","(B) 成分含量規格","(C) 檢驗規格","(D) 已揭露專利字號或案號"],"answer":3,"image":""},{"id":"ph6-108-1-33","subject":"ph6","topic":"藥事法規-藥物廣告與稽查","meta":"108年第1次第33題","year":108,"session":1,"number":33,"question":"依藥事法之規定，藥物廣告應事先向下列何機關申請核准？","options":["(A) 中央衛⽣主管機關或直轄市衛⽣主管機關","(B) 文化部","(C) 國家通訊傳播委員會","(D) ⾏政院消費者保護會"],"answer":0,"image":""},{"id":"ph6-108-1-34","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"108年第1次第34題","year":108,"session":1,"number":34,"question":"下列有關藥物標⽰之敘述，何者錯誤？","options":["(A) 輸入之藥物，中文品名之文字不得⼩於外文","(B) 應依核准刊載產品之批號","(C) 輸入之藥物，品名及許可證字號得以外文為主，但應附上中文仿單","(D) 應依核准刊載品名及許可證字號"],"answer":2,"image":""},{"id":"ph6-108-1-35","subject":"ph6","topic":"藥事法規-醫療器材管理法","meta":"108年第1次第35題","year":108,"session":1,"number":35,"question":"有關醫療器材查驗登記之規定，下列敘述何者錯誤？","options":["(A) 若為已有類似品之第⼆等級醫療器材，可以檢附美國官⽅及歐盟會員國官⽅或權責單位出具之核准上市證明文件，取代臨床前測試及原廠品質管制資料","(B) 對於第⼆等級無類似品且不符合簡化規定者，以及第三等級醫療器材申請查驗登記時，同時需檢附相關臨床評估或臨床試驗資料","(C) 未滅菌及不具量測功能之第⼀等級醫療器材，可無須符合醫療器材優良製造準則","(D) 醫療器材中文仿單之字體⼤⼩規格不得⼩於電腦字體7號字"],"answer":2,"image":""},{"id":"ph6-108-1-36","subject":"ph6","topic":"藥事法規-醫療器材管理法","meta":"108年第1次第36題","year":108,"session":1,"number":36,"question":"下列有關藥物查驗登記之敘述，何者錯誤？","options":["(A) 許可證有效期間為5年","(B) 國內製造之醫療器材，其標籤、仿單、包裝應以中文為主，所附外文文字應⼩於中文","(C) 輸入醫療器材，應向衛⽣福利部申請查驗登記，經核發許可證後，始得為之","(D) 中央衛⽣主管機關為維護公益⽬的，公開所持有及保管藥商申請製造或輸入藥物所檢附之藥物成分、仿單等相關資料，須事前經業者同意，始得為之"],"answer":3,"image":""},{"id":"ph6-108-1-37","subject":"ph6","topic":"藥事法規-醫療器材管理法","meta":"108年第1次第37題","year":108,"session":1,"number":37,"question":"下列何者不在藥局兼營零售之醫療器材之列？","options":["(A) 靜脈點滴套","(B) 含殺精劑衛⽣套","(C) 玻尿酸⽪下植入物","(D) ⾎糖機"],"answer":2,"image":""},{"id":"ph6-108-1-38","subject":"ph6","topic":"藥事法規-管制藥品與毒品危害防制","meta":"108年第1次第38題","year":108,"session":1,"number":38,"question":"下列有關管制藥品之證照制度，何者正確？","options":["(A) 醫藥教育研究試驗機構申請管制藥品登記證之負責⼈，僅能由機關⾸⻑擔任","(B) 醫師、牙醫師使⽤管制藥品，必須領有管制藥品使⽤執照","(C) 藥局執照之負責⼈，可為管制藥品登記證之負責⼈","(D) 國內運輸第⼀級⾄第三級管制藥品，應向衛⽣主管機關申請核發運輸憑照"],"answer":2,"image":""},{"id":"ph6-108-1-39","subject":"ph6","topic":"藥事法規-管制藥品與毒品危害防制","meta":"108年第1次第39題","year":108,"session":1,"number":39,"question":"下列有關管制藥品管理之敘述，何者正確？","options":["(A) 各級管制藥品均應置於業務處所，並應專櫃儲藏","(B) 藥局依規定設簿冊登載管制藥品，應依各藥品批號分別登載收⽀情形","(C) 第⼀級⾄第三級管制藥品，除歇業或停業外，不得借貸、轉讓","(D) 調劑或使⽤後之殘餘管制藥品，應由管制藥品管理⼈會同有關⼈員銷燬"],"answer":3,"image":""},{"id":"ph6-108-1-40","subject":"ph6","topic":"藥事法規-管制藥品與毒品危害防制","meta":"108年第1次第40題","year":108,"session":1,"number":40,"question":"下列何種成分可從鴉片中分離出來，但因不具成癮性，已被排除在管制藥品之外？","options":["(A) 可待因（codeine）","(B) 諾司卡賓（noscapine）","(C) 美托邦（metopon）","(D) 狄芬諾⻄萊（diphenoxylate）"],"answer":1,"image":""},{"id":"ph6-108-1-41","subject":"ph6","topic":"藥事法規-化粧品衛生安全管理法","meta":"108年第1次第41題","year":108,"session":1,"number":41,"question":"依現⾏化粧品衛⽣管理條例之規定，下列何者不屬於含藥化粧品？","options":["(A) 髮表著⾊劑","(B) 染髮劑","(C) 燙髮劑","(D) ⽌汗制臭劑"],"answer":0,"image":""},{"id":"ph6-108-1-42","subject":"ph6","topic":"藥事法規-化粧品衛生安全管理法","meta":"108年第1次第42題","year":108,"session":1,"number":42,"question":"某衛⽣局查獲⼀批來源不明之洗髮精，依化粧品衛⽣安全管理法規定，對該違規產品之處置，下列何者錯誤？","options":["(A) 得命化粧品業者下架該違規產品","(B) 應訂定期限命化粧品製造或輸入業者，通知販賣業者回收市售違規產品","(C) 得命化粧品業者重新包裝後，⽅可上架販售","(D) 沒入銷毀"],"answer":2,"image":""},{"id":"ph6-108-1-43","subject":"ph6","topic":"藥事法規-藥害救濟與罕見疾病","meta":"108年第1次第43題","year":108,"session":1,"number":43,"question":"與國際先進國家比較，我國罕⾒疾病防治及藥物法的特⾊為何？","options":["(A) 立法內容結合罕⾒疾病防治與罕⾒疾病藥物管理","(B) 罕⾒疾病藥物許可證保障達五年，不受理同類藥物查驗登記申請","(C) 罕⾒疾病藥物包含維持⽣命所需特殊營養食品","(D) 政府全額補助國外代⾏檢驗費⽤"],"answer":0,"image":""},{"id":"ph6-108-1-44","subject":"ph6","topic":"藥事法規-藥害救濟與罕見疾病","meta":"108年第1次第44題","year":108,"session":1,"number":44,"question":"下列有關政府成立「藥害救濟基⾦會」業務之敘述，何者錯誤？","options":["(A) 受理藥害救濟案件申請","(B) 藥害救濟徵收⾦管理","(C) 核定藥害救濟審議結果","(D) 藥害救濟⾦給付"],"answer":2,"image":""},{"id":"ph6-108-1-45","subject":"ph6","topic":"藥事法規-藥害救濟與罕見疾病","meta":"108年第1次第45題","year":108,"session":1,"number":45,"question":"某診所醫師為氣喘病患開立改善⼼悸藥之處⽅，藥師依處⽅給藥列印藥袋時，仿單中呈現「氣喘禁⽤」之警 ⽰，但未詢問開立處⽅醫師即調劑給藥，造成病患服藥後死亡，下列敘述何者正確？","options":["(A) 該藥因為經過醫師處⽅，藥師依處⽅給藥，符合藥害救濟法所稱之正當使⽤","(B) 病患因此服藥後死亡，符合藥害救濟法之死亡給付","(C) 藥師得替該死亡病患申請藥害救濟，以符合及時救濟宗旨","(D) 該醫師與藥師均應負其責任"],"answer":3,"image":""},{"id":"ph6-108-1-46","subject":"ph6","topic":"藥事法規-全民健康保險與藥事作業","meta":"108年第1次第46題","year":108,"session":1,"number":46,"question":"下列何者為全⺠健康保險不予給付之藥品？","options":["(A) 沙立邁（thalidomide）膠囊","(B) 冠脂妥（rosuvastatin）膜衣錠","(C) 丙泊酚（propofol）製劑","(D) 美服培酮（mifepristone）錠"],"answer":3,"image":""},{"id":"ph6-108-1-47","subject":"ph6","topic":"藥事法規-全民健康保險與藥事作業","meta":"108年第1次第47題","year":108,"session":1,"number":47,"question":"依全⺠健康保險法之規定，下列何者可列入給付範圍？","options":["(A) 精神疾病之⽇間住院費⽤","(B) 住院之膳食費⽤","(C) 掛號及診斷書費⽤","(D) 指定醫師費⽤"],"answer":0,"image":""},{"id":"ph6-108-1-48","subject":"ph6","topic":"藥事法規-全民健康保險與藥事作業","meta":"108年第1次第48題","year":108,"session":1,"number":48,"question":"某健保特約藥局調劑由甲醫師開立之處⽅箋，經衛⽣福利部中央健康保險署核定藥品費⽤不予給付，且可歸責於甲醫師時，該藥品費⽤應如何處理？","options":["(A) 應⾃甲醫師之⾨診診療服務費⽤核減⼀半以上","(B) 應⾃特約藥局之藥事⼈員藥事服務費中核減","(C) 應處甲醫師罰鍰","(D) 應⾃甲醫師所屬之醫療機構申報之醫療費⽤核減"],"answer":3,"image":""},{"id":"ph6-108-1-49","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"108年第1次第49題","year":108,"session":1,"number":49,"question":"有關醫師處⽅應記明事項及藥劑交付應註明事項等規定，係訂定於下列何項法律中？","options":["(A) 醫療法","(B) 醫師法","(C) 藥事法","(D) 全⺠健康保險法"],"answer":1,"image":""},{"id":"ph6-108-1-50","subject":"ph6","topic":"藥事法規-全民健康保險與藥事作業","meta":"108年第1次第50題","year":108,"session":1,"number":50,"question":"依全⺠健康保險醫事服務機構特約及管理辦法之規定，下列有關特約及管理原則，何者錯誤？","options":["(A) 公平","(B) 互信","(C) 互利","(D) 對等"],"answer":2,"image":""},{"id":"ph6-108-2-1","subject":"ph6","topic":"藥事法規-管制藥品與毒品危害防制","meta":"108年第2次第1題","year":108,"session":2,"number":1,"question":"第一級、第二級管制藥品之輸入、輸出、製造、販賣，應由下列何者為之？","options":["(A) 國防部軍需局","(B) 財團法人醫藥品查驗中心","(C) 衛生福利部食品藥物管理署製藥工廠","(D) 財團法人國家衛生研究院製藥工廠"],"answer":2,"image":""},{"id":"ph6-108-2-2","subject":"ph6","topic":"藥事法規-新藥臨床試驗與安全監視","meta":"108年第2次第2題","year":108,"session":2,"number":2,"question":"有關醫療機構依醫學理論於人體施行新醫療技術、新藥品、新醫療器材及學名藥生體可用率、生體相等性之試驗研究，係規定於下列何項法規？","options":["(A) 藥事法","(B) 醫療法","(C) 人體研究法","(D) 人體生物資料庫管理條例"],"answer":1,"image":""},{"id":"ph6-108-2-3","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"108年第2次第3題","year":108,"session":2,"number":3,"question":"下列何種藥物可於網路販售？","options":["(A) 清心蓮子飲濃縮製劑","(B) 有度數運動防護眼鏡","(C) 維士比、保力達B","(D) 斯斯感冒膠囊"],"answer":1,"image":""},{"id":"ph6-108-2-4","subject":"ph6","topic":"藥事法規-藥物廣告與稽查","meta":"108年第2次第4題","year":108,"session":2,"number":4,"question":"下列何者之廣告無須事先向中央或直轄市衛生主管機關申請核准？","options":["(A) 化粧品","(B) 中藥","(C) 西藥","(D) 醫療器材"],"answer":0,"image":""},{"id":"ph6-108-2-5","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"108年第2次第5題","year":108,"session":2,"number":5,"question":"下列何者非屬藥事法管理之範圍？","options":["(A) 隱形眼鏡","(B) 六味地黃丸","(C) 染髮劑","(D) 感冒藥水"],"answer":2,"image":""},{"id":"ph6-108-2-6","subject":"ph6","topic":"藥事法規-藥政管理組織與衛生行政","meta":"108年第2次第6題","year":108,"session":2,"number":6,"question":"當食品安全疑慮事件發生時，下列何者可提供消費者即時查詢食品安全警訊？","options":["(A) 國民飲食指標","(B) 每日飲食指南","(C) 食品消費紅綠燈","(D) 食品藥物分析期刊"],"answer":2,"image":""},{"id":"ph6-108-2-7","subject":"ph6","topic":"藥事法規-藥師法與執業管理","meta":"108年第2次第7題","year":108,"session":2,"number":7,"question":"藥師對醫師所開處方有疑義時，依藥師法之規定，下列敘述何者錯誤？","options":["(A) 未向原處方醫師確認，藥師應負責任","(B) 向原處方醫師提出處方疑義，醫師堅決不改，藥師如確認悖於用藥專業，得作為拒絕調劑之理由","(C) 藥師如自行更改處方品項，藥師應負責任","(D) 處方錯誤，藥師及醫師雙方皆未發現，民事責任僅由藥師負責"],"answer":3,"image":""},{"id":"ph6-108-2-8","subject":"ph6","topic":"藥事法規-藥師法與執業管理","meta":"108年第2次第8題","year":108,"session":2,"number":8,"question":"依藥師法之規定，藥師調劑交付藥劑時，應於容器或包裝記明之事項，下列何者錯誤？","options":["(A) 藥品名稱、劑量、數量、用法","(B) 警語或副作用","(C) 作用或適應症","(D) 病人姓名、性別及年齡"],"answer":3,"image":""},{"id":"ph6-108-2-9","subject":"ph6","topic":"藥事法規-藥師法與執業管理","meta":"108年第2次第9題","year":108,"session":2,"number":9,"question":"下列何者屬藥師法所稱之藥事照護相關業務？","options":["(A) 參加巡迴醫療義診之藥品調劑","(B) 天然災害醫療救護之藥品管理","(C) 藥師參與醫院藥品聯合採購","(D) 藥師於衛生福利部部立醫院執行藥品安全監視"],"answer":3,"image":""},{"id":"ph6-108-2-10","subject":"ph6","topic":"調劑學-處方判讀與調劑作業","meta":"108年第2次第10題","year":108,"session":2,"number":10,"question":"依藥品優良調劑作業準則之規定，所謂調劑係指藥事人員自受理處方箋至病患取得藥品間所為之行為，不包括下列何者？","options":["(A) 處方登錄","(B) 病情確認","(C) 用藥適當性評估","(D) 確認取藥者交付藥品"],"answer":1,"image":""},{"id":"ph6-108-2-11","subject":"ph6","topic":"調劑學-處方判讀與調劑作業","meta":"108年第2次第11題","year":108,"session":2,"number":11,"question":"依藥品優良調劑作業準則之規定，下列有關藥品調劑時應注意之事項，何者錯誤？","options":["(A) 醫師於醫療急迫情形下親自為藥品調劑時，無須符合藥品優良調劑作業準則之規定","(B) 處方藥不得以開架式陳列","(C) 為防止兒童取得藥品，必要時，應使用有安全瓶蓋之容器","(D) 藥事作業處所應具備洗滌設備"],"answer":0,"image":""},{"id":"ph6-108-2-12","subject":"ph6","topic":"藥事法規-藥師法與執業管理","meta":"108年第2次第12題","year":108,"session":2,"number":12,"question":"下列有關藥師執業之敘述，何者錯誤？","options":["(A) 藥師非加入所在地藥師公會，不得執業","(B) 藥師應向執業所在地直轄市、縣（市）主管機關申請執業登記，領有執業執照，始得執業","(C) 藥師停業或歇業時，應自事實發生之日起三十日內，報請原發執業執照之主管機關備查","(D) 藥師執業，應接受繼續教育，並每三年提出完成繼續教育證明文件，辦理執業執照更新"],"answer":3,"image":""},{"id":"ph6-108-2-13","subject":"ph6","topic":"藥事法規-藥師法與執業管理","meta":"108年第2次第13題","year":108,"session":2,"number":13,"question":"藥師法第11條有關藥癮治療或傳染病防治服務，所稱服務，係指下列何者？","options":["(A) 藥品販賣或管理","(B) 藥品調劑","(C) 藥品鑑定","(D) 藥品製造之監製"],"answer":1,"image":""},{"id":"ph6-108-2-14","subject":"ph6","topic":"藥事法規-藥師法與執業管理","meta":"108年第2次第14題","year":108,"session":2,"number":14,"question":"經藥師考試及格後，欲執行藥師業務，應檢具申請書及資格證明文件，向下列何者請領藥師證書？","options":["(A) 衛生福利部食品藥物管理署","(B) 所欲執業之所在地衛生主管機關","(C) 衛生福利部","(D) 考試院"],"answer":2,"image":""},{"id":"ph6-108-2-15","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"108年第2次第15題","year":108,"session":2,"number":15,"question":"有關藥局之設置，下列何者錯誤？","options":["(A) 由藥師或藥劑生親自主持","(B) 總面積需有12平方公尺以上","(C) 不得在醫療機構內，以隔間方式設置","(D) 藥局執照應懸掛於營業處所之明顯位置"],"answer":1,"image":""},{"id":"ph6-108-2-16","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"108年第2次第16題","year":108,"session":2,"number":16,"question":"某健保特約診所聘藥師甲執行調劑，某日該藥師甲不在，負責醫師命護士乙調劑，當場經衛生主管機關查獲，其下列處置，何者錯誤？","options":["(A) 負責醫師應依違反醫療法之規定處辦","(B) 負責醫師應依違反全民健康保險法之規定處辦","(C) 護士乙應依藥師法之規定處辦","(D) 藥師甲應依藥事法之規定移付懲戒"],"answer":3,"image":""},{"id":"ph6-108-2-17","subject":"ph6","topic":"藥事法規-藥害救濟與罕見疾病","meta":"108年第2次第17題","year":108,"session":2,"number":17,"question":"依嚴重藥物不良反應通報辦法之規定，下列何者非屬應通報嚴重藥物不良反應之對象？","options":["(A) 醫療機構","(B) 藥局","(C) 藥商","(D) 財團法人藥害救濟基金會"],"answer":3,"image":""},{"id":"ph6-108-2-18","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"108年第2次第18題","year":108,"session":2,"number":18,"question":"依藥事法之規定，直轄市或縣（市）衛生主管機關對於涉嫌不法藥物之處置，下列何者正確？","options":["(A) 已逾保存期限之隱形眼鏡鏡片消毒藥錠，得就地封存，抽樣檢驗後，再行處理","(B) 已呈明顯混濁之移植器官保存液，應就地封存，抽樣檢驗後，再行處理","(C) 已逾保存期限之衛生棉條，應就地封存，抽樣檢驗後，再行處理","(D) 已呈明顯混濁之注射用生理食鹽水，應就地封存，抽樣檢驗後，再行處理"],"answer":0,"image":""},{"id":"ph6-108-2-19","subject":"ph6","topic":"藥事法規-新藥臨床試驗與安全監視","meta":"108年第2次第19題","year":108,"session":2,"number":19,"question":"下列有關藥物安全監視之敘述，何者正確？","options":["(A) 藥品及醫療器材，於申請查驗登記時，即須進行安全監視","(B) 僅輸入藥品應進行安全監視","(C) 藥物之安全監視期間一律5年","(D) 經中央衛生福利主管機關核定應執行上市後臨床試驗之藥品，應進行安全監視"],"answer":3,"image":""},{"id":"ph6-108-2-20","subject":"ph6","topic":"藥事法規-新藥臨床試驗與安全監視","meta":"108年第2次第20題","year":108,"session":2,"number":20,"question":"下列何者取得許可證後，自許可證核發之日起三年內，其他藥商非經許可證所有人同意，不得引據其申請資料申請查驗登記？①第三等級新醫療器材②新成分新藥③新適應症新藥④新使用途徑新藥","options":["(A) 僅①","(B) 僅②","(C) ②③④","(D) ①②③④"],"answer":1,"image":""},{"id":"ph6-108-2-21","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"108年第2次第21題","year":108,"session":2,"number":21,"question":"下列有關新藥及學名藥之敘述，何者錯誤？","options":["(A) Inderal之學名藥皆含propranolol","(B) 學名藥，係指與國內已核准之藥品具同成分、同劑量、同劑型、同療效之製劑","(C) 新藥之專利權一經過期，即轉類成為學名藥","(D) 新藥，係指經中央衛生主管機關審查認定屬新成分、新療效複方或新使用途徑製劑之藥品"],"answer":2,"image":""},{"id":"ph6-108-2-22","subject":"ph6","topic":"藥事法規-新藥臨床試驗與安全監視","meta":"108年第2次第22題","year":108,"session":2,"number":22,"question":"下列何者係為瞭解藥品是否有人種差異所進行之臨床試驗？","options":["(A) 田野試驗（Field Trial）","(B) 進藥試驗（Listing Trial）","(C) 銜接性試驗（Bridging Study）","(D) 生體相等性試驗（Bioequivalence Study）"],"answer":2,"image":""},{"id":"ph6-108-2-23","subject":"ph6","topic":"藥事法規-醫療器材管理法","meta":"108年第2次第23題","year":108,"session":2,"number":23,"question":"輸入之隱形眼鏡清潔液，經主管機關抽查檢驗結果，其有效成分含量與核准不符，下列敘述何者錯誤？","options":["(A) 該品為不良醫療器材","(B) 該品經檢驗後仍可改製使用者，應由直轄市或縣（市）衛生主管機關，派員監督廠商限期改製","(C) 輸入該品之業者，應即通知醫療機構、藥局及藥商，並依規定限期收回市售品，連同庫存品一併依藥事法有關規定處理","(D) 輸入該品業者所轄之主管機關應公告該業者之名稱、地址、負責人姓名、該品名稱及違反情節"],"answer":1,"image":""},{"id":"ph6-108-2-24","subject":"ph6","topic":"藥事法規-醫療器材管理法","meta":"108年第2次第24題","year":108,"session":2,"number":24,"question":"下列有關醫療器材製造之敘述，何者錯誤？","options":["(A) 製造工廠，應依藥物製造工廠設廠標準設立，並依工廠管理輔導法規定，辦理工廠登記","(B) 製造業者，應視其類別，聘用技術人員","(C) 輸入之國外製造廠，由中央衛生主管機關定期或依實際需要赴廠檢查之","(D) 製造工廠，不得委託他廠製造或接受委託製造"],"answer":3,"image":""},{"id":"ph6-108-2-25","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"108年第2次第25題","year":108,"session":2,"number":25,"question":"西醫診所在多少公里範圍內無藥局的情況下，視為藥事法所稱無藥事人員執業之醫療偏遠地區？","options":["(A) 1.5","(B) 1.8","(C) 2.0","(D) 2.1"],"answer":1,"image":""},{"id":"ph6-108-2-26","subject":"ph6","topic":"藥事法規-新藥臨床試驗與安全監視","meta":"108年第2次第26題","year":108,"session":2,"number":26,"question":"依藥物安全監視管理辦法之規定，下列何者經衛生福利部公告，即應納入適用範圍？","options":["(A) 應執行風險管理計畫之藥品","(B) 未取得藥物製造許可之藥品","(C) 人畜共用藥品","(D) 可批發予食品製造廠商作為食品原料之藥品"],"answer":0,"image":""},{"id":"ph6-108-2-27","subject":"ph6","topic":"藥事法規-藥物廣告與稽查","meta":"108年第2次第27題","year":108,"session":2,"number":27,"question":"下列有關藥物廣告之敘述，何者錯誤？","options":["(A) 促銷藥品之單張，為「傳播方法」","(B) 內容暗示或影射醫療效能者，視為藥物廣告","(C) 食品不得為醫療效能之標示或宣傳","(D) 中藥材之效能敘述以《中華本草》所載為限"],"answer":3,"image":""},{"id":"ph6-108-2-28","subject":"ph6","topic":"藥事法規-藥物廣告與稽查","meta":"108年第2次第28題","year":108,"session":2,"number":28,"question":"降血脂藥rosuvastatin之廣告，可登載於下列何處？","options":["(A) 合法電視台","(B) 藥師週刊","(C) 政府公報","(D) 人體試驗招募"],"answer":1,"image":""},{"id":"ph6-108-2-29","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"108年第2次第29題","year":108,"session":2,"number":29,"question":"依西藥藥品優良製造規範之規定，製造藥品品質目標之達成，係下列何者之責任？","options":["(A) 監製藥師要負完全責任","(B) 高層管理者","(C) 品質管制主管及品管部門所有人員共同負責","(D) 品質管制主管之責任"],"answer":1,"image":""},{"id":"ph6-108-2-30","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"108年第2次第30題","year":108,"session":2,"number":30,"question":"藥品製造過程，會產生粉塵的情況（例如：抽樣、秤重、混合、製程操作及乾燥產品的分／包裝等期間中）應採取下列那些特別的措施？①集塵設備②操作人員防護③負壓環境④C級區環境","options":["(A) ①②④","(B) ①②③","(C) ①③④","(D) ②③④"],"answer":1,"image":""},{"id":"ph6-108-2-31","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"108年第2次第31題","year":108,"session":2,"number":31,"question":"某藥商從事單株抗體藥品製造業，下列敘述何者正確？","options":["(A) 可聘具微生物學藥品製造專門知識與5年以上製造經驗之生物學系畢業技術人員，駐廠負責製造","(B) 若該製造廠兼售其他藥品，依法不須另聘專任管理藥師","(C) 若該製造廠又製造西藥劑型之中藥，應另聘專任中醫師監製","(D) 該製造廠工作細胞資料庫的建立，為實驗室職責，無須符合藥品優良製造規範"],"answer":0,"image":""},{"id":"ph6-108-2-32","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"108年第2次第32題","year":108,"session":2,"number":32,"question":"下列何者非屬藥事法所稱藥商之範疇？","options":["(A) 醫療器材製造業","(B) 醫療器材租賃業","(C) 醫療器材販賣業","(D) 醫療器材維修業"],"answer":3,"image":""},{"id":"ph6-108-2-33","subject":"ph6","topic":"藥事法規-藥物廣告與稽查","meta":"108年第2次第33題","year":108,"session":2,"number":33,"question":"藥事法所稱「稽查」，下列敘述何者正確？","options":["(A) 關於藥物有無經核准查驗登記之事項","(B) 關於藥局有無經核准營業登記之事項","(C) 關於藥師是否領有藥師執業執照之事項","(D) 關於藥商有無經營非法藥物之事項"],"answer":0,"image":""},{"id":"ph6-108-2-34","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"108年第2次第34題","year":108,"session":2,"number":34,"question":"社區藥局藥師發現某藥品致病人危及生命之處置，下列何者正確？","options":["(A) 得以郵寄、傳真或網路方式通報當地衛生主管機關轉報中央衛生主管機關","(B) 得知該不良反應之日起7日內，告知持有藥物許可證之藥商，並副知醫院臨床試驗中心","(C) 得知該不良反應之日起15日內，備齊臨床試驗及動物毒性資料，送至中央衛生主管機關","(D) 緊急時得先行以口頭方式通報中央衛生主管機關，並應於期限內完成書面通報"],"answer":3,"image":""},{"id":"ph6-108-2-35","subject":"ph6","topic":"藥事法規-藥物廣告與稽查","meta":"108年第2次第35題","year":108,"session":2,"number":35,"question":"電視藥物廣告誇大不實，應依下列何法規處罰？","options":["(A) 藥事法","(B) 公平交易法","(C) 消費者保護法","(D) 廣播電視法"],"answer":0,"image":""},{"id":"ph6-108-2-36","subject":"ph6","topic":"藥事法規-醫療器材管理法","meta":"108年第2次第36題","year":108,"session":2,"number":36,"question":"依藥事法之規定，下列有關不良醫療器材之處理，何者正確？","options":["(A) 有效成分之質、量或強度與核准不符者，其製造或輸入者，移送檢察機關偵辦","(B) 超過有效期間者，其製造或輸入者，處行政罰鍰","(C) 使用時有損傷人體者，其製造或輸入者，處行政罰鍰","(D) 查獲之不良醫療器材，如係輸入者，直接沒入銷燬之"],"answer":1,"image":""},{"id":"ph6-108-2-37","subject":"ph6","topic":"藥事法規-管制藥品與毒品危害防制","meta":"108年第2次第37題","year":108,"session":2,"number":37,"question":"下列有關管制藥品與毒品之管理，何者正確？","options":["(A) 違反管制藥品管理條例之罰則以罰鍰為原則，違反毒品危害防制條例以判刑或併科罰金為原則","(B) 毒品依其依賴性、濫用性及對社會危害性之程度，分為四級管理","(C) 毒品之分級及品項，由行政院組成審議委員會，每三個月定期檢討","(D) 管制藥品與毒品之分級及品項完全相同，其差別僅在於管制藥品限供醫藥及科學上使用"],"answer":0,"image":""},{"id":"ph6-108-2-38","subject":"ph6","topic":"藥事法規-管制藥品與毒品危害防制","meta":"108年第2次第38題","year":108,"session":2,"number":38,"question":"依管制藥品濫用通報及獎勵辦法之規定，下列敘述何者錯誤？","options":["(A) 非經醫囑不當或過度使用管制藥品而需要就診、戒毒者，均為適用之通報對象","(B) 通報單位，應向當地衛生主管機關申請通報系統之帳號及密碼","(C) 未經行政院核定公告分級管理之新興濫用藥品，經主管機關審議認定者，準用本辦法規定通報","(D) 依本辦法通報之人員，經主管機關認定後，得依標準發給通報獎金"],"answer":1,"image":""},{"id":"ph6-108-2-39","subject":"ph6","topic":"藥事法規-管制藥品與毒品危害防制","meta":"108年第2次第39題","year":108,"session":2,"number":39,"question":"某醫療機構購用之管制藥品含有配西汀（pethidine）針劑，下列何者不得擔任管制藥品管理人？","options":["(A) 醫師","(B) 牙醫師","(C) 藥師","(D) 藥劑生"],"answer":3,"image":""},{"id":"ph6-108-2-40","subject":"ph6","topic":"藥事法規-管制藥品與毒品危害防制","meta":"108年第2次第40題","year":108,"session":2,"number":40,"question":"下列有關氟硝西泮（flunitrazepam）錠劑之登載列報，何者正確？","options":["(A) 每年1月、4月、7月及10月辦理申報前3個月之簿冊登載情形","(B) 每年1月及7月辦理申報前6個月之簿冊登載情形","(C) 每年1月辦理申報前1年之簿冊登載情形","(D) 若申報期間無收支結存者，則不須辦理申報"],"answer":2,"image":""},{"id":"ph6-108-2-41","subject":"ph6","topic":"藥事法規-化粧品衛生安全管理法","meta":"108年第2次第41題","year":108,"session":2,"number":41,"question":"依化粧品衛生安全管理法之規定，下列何者非屬新興化粧品之管理制度及措施？","options":["(A) 產品登錄","(B) 良好衛生規範","(C) 產品資訊檔案","(D) 優良製造準則"],"answer":1,"image":""},{"id":"ph6-108-2-42","subject":"ph6","topic":"藥事法規-化粧品衛生安全管理法","meta":"108年第2次第42題","year":108,"session":2,"number":42,"question":"某衛生局稽查夾娃娃機，發現陳列於機台內之化粧品未依規定標示，依現行化粧品衛生管理條例之規定，下列敘述何者正確？","options":["(A) 可處機台負責業者行政罰鍰","(B) 可處化粧品負責廠商行政罰鍰","(C) 娃娃機內之化粧品為娛樂商品，不適用化粧品衛生管理條例之規定","(D) 夾娃娃機內之化粧品應標示機臺負責業者姓名"],"answer":1,"image":""},{"id":"ph6-108-2-43","subject":"ph6","topic":"藥事法規-藥害救濟與罕見疾病","meta":"108年第2次第43題","year":108,"session":2,"number":43,"question":"下列有關罕見疾病之業務，何者非屬衛生福利部食品藥物管理署之權責？","options":["(A) 特殊營養食品供應、製造與研發獎勵","(B) 核發罕見疾病重大傷病證明","(C) 罕見疾病藥物認定","(D) 罕見疾病特殊營養食品專案申請"],"answer":1,"image":""},{"id":"ph6-108-2-44","subject":"ph6","topic":"藥事法規-藥害救濟與罕見疾病","meta":"108年第2次第44題","year":108,"session":2,"number":44,"question":"某孕婦隨團赴日旅遊，在日本藥粧店購買含ibuprofen之鎮痛藥EVE，不幸導致胎兒發生早發性動脈導管閉鎖。下列敘述何者正確？","options":["(A) 該孕婦可憑健保卡、購買單據及藥粧店證明，申請健保補助","(B) 該藥產生之藥害不得申請藥害救濟","(C) 若該日本藥粧店在國內亦有核准設立之分店，該藥品即屬藥害救濟法所稱之合法藥品","(D) 該孕婦可依罕見疾病防治及藥物法申請罕見疾病救濟"],"answer":1,"image":""},{"id":"ph6-108-2-45","subject":"ph6","topic":"藥事法規-藥害救濟與罕見疾病","meta":"108年第2次第45題","year":108,"session":2,"number":45,"question":"依藥害救濟法之規定，藥害救濟之申請人對主管機關藥害救濟給付之審定，如有不服，得提起下列何種救濟程序？","options":["(A) 民事訴訟","(B) 刑事訴訟","(C) 訴願及行政訴訟","(D) 請願或請求國家賠償"],"answer":2,"image":""},{"id":"ph6-108-2-46","subject":"ph6","topic":"藥事法規-全民健康保險與藥事作業","meta":"108年第2次第46題","year":108,"session":2,"number":46,"question":"下列何者非屬全民健康保險法所定醫療給付費用總額之項目？","options":["(A) 醫師門診診療服務費用","(B) 藥師藥事服務費用","(C) 醫學美容外科手術費用","(D) 藥品費用"],"answer":2,"image":""},{"id":"ph6-108-2-47","subject":"ph6","topic":"藥事法規-全民健康保險與藥事作業","meta":"108年第2次第47題","year":108,"session":2,"number":47,"question":"依全民健康保險法之規定，全民健康保險為下列何者？","options":["(A) 福利性之公益保險","(B) 商業性之醫療保險","(C) 強制性之社會保險","(D) 公益性之醫療契約"],"answer":2,"image":""},{"id":"ph6-108-2-48","subject":"ph6","topic":"藥事法規-全民健康保險與藥事作業","meta":"108年第2次第48題","year":108,"session":2,"number":48,"question":"依全民健康保險醫事服務機構特約及管理辦法之規定，特約保險藥局之藥師因故不能執行業務逾三十日，應自逾三十日之日起幾日內，報請保險人備查？","options":["(A) 三","(B) 五","(C) 七","(D) 十"],"answer":3,"image":""},{"id":"ph6-108-2-49","subject":"ph6","topic":"藥事法規-全民健康保險與藥事作業","meta":"108年第2次第49題","year":108,"session":2,"number":49,"question":"健保特約醫院以虛偽之報告申報醫療費用，依全民健康保險法之規定，下列何種處罰方式錯誤？","options":["(A) 得處以該醫院申報之醫療費用一倍之罰鍰","(B) 該醫院如涉及刑責者，移送司法機關辦理","(C) 其情節重大者，應公告醫院名稱、負責醫事人員姓名及違法事實","(D) 得視情節輕重，限定醫院於一定期間不予特約或永不特約"],"answer":0,"image":""},{"id":"ph6-108-2-50","subject":"ph6","topic":"藥事法規-全民健康保險與藥事作業","meta":"108年第2次第50題","year":108,"session":2,"number":50,"question":"下列何者得為全民健康保險給付之藥品？","options":["(A) 預防接種所用之疫苗","(B) 吩坦尼貼片","(C) 黑斑漂白劑","(D) 戒菸貼片"],"answer":1,"image":""},{"id":"ph6-109-1-1","subject":"ph6","topic":"藥事法規-藥政管理組織與衛生行政","meta":"109年第1次第1題","year":109,"session":1,"number":1,"question":"下列何者不屬衛生福利部之重大政策或施政目標？","options":["(A) 健全福利服務體系，優先照顧弱勢族群","(B) 精進健保及國保制度，強化自助互助社會保險機制","(C) 建立完善勞工保險年金保障體系，提供被保險人長期生活照顧","(D) 拓展全方位醫療照護體系，保障民眾就醫權益"],"answer":2,"image":""},{"id":"ph6-109-1-2","subject":"ph6","topic":"藥事法規-藥政管理組織與衛生行政","meta":"109年第1次第2題","year":109,"session":1,"number":2,"question":"依食品安全衛生管理法之規定，為加強全國食品安全事務之協調、監督及查緝，行政院應設：","options":["(A) 食品安全諮議會","(B) 食品安全審議委員會","(C) 食品安全會報","(D) 食品安全辦公室"],"answer":2,"image":""},{"id":"ph6-109-1-3","subject":"ph6","topic":"藥事法規-藥害救濟與罕見疾病","meta":"109年第1次第3題","year":109,"session":1,"number":3,"question":"依罕見疾病防治及藥物法之規定，查驗登記發給之藥物許可證，其有效期間為幾年？","options":["(A) 3","(B) 5","(C) 10","(D) 12"],"answer":2,"image":""},{"id":"ph6-109-1-4","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"109年第1次第4題","year":109,"session":1,"number":4,"question":"某君欲經營藥品買賣，應依藥事法之規定，向下列何者申請為藥商？","options":["(A) 衛生福利部","(B) 直轄市或縣（市）政府衛生局","(C) 衛生福利部食品藥物管理署","(D) 直轄市或縣（市）政府"],"answer":3,"image":""},{"id":"ph6-109-1-5","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"109年第1次第5題","year":109,"session":1,"number":5,"question":"下列有關網路販售之敘述，何者正確？","options":["(A) 醫療器材不得於網路販售","(B) 乙類成藥得於網路販售","(C) 處方藥得於網路販售","(D) 僅藥商、藥局，得於網路經營乙類成藥零售業務"],"answer":1,"image":""},{"id":"ph6-109-1-6","subject":"ph6","topic":"藥事法規-藥政管理組織與衛生行政","meta":"109年第1次第6題","year":109,"session":1,"number":6,"question":"下列有關衛生福利重要指標，何者錯誤？","options":["(A) 我國之主要死因已由急性、傳染性疾病，轉變成慢性疾病與事故傷害","(B) 依民國105年癌症死因順位與95年比較，上升者有口腔癌，下降者有胃癌","(C) 依據105年資料顯示，世界主要國家扶養比，我國為36%，屬較低者","(D) 依各國104年資料，世界主要國家中我國之新生兒死亡率每千活產2.5人最低"],"answer":3,"image":""},{"id":"ph6-109-1-7","subject":"ph6","topic":"藥事法規-管制藥品與毒品危害防制","meta":"109年第1次第7題","year":109,"session":1,"number":7,"question":"下列有關含可待因製劑之敘述，何者正確？","options":["(A) 含可待因製劑皆為管制藥品","(B) 藥品每錠500 mg，含可待因52 mg，應開具管制藥品專用處方箋","(C) 糖漿劑每50 mL，含可待因48 mg，應開具管制藥品專用處方箋","(D) 含可待因成分之製劑，均應開具管制藥品專用處方箋"],"answer":1,"image":""},{"id":"ph6-109-1-8","subject":"ph6","topic":"調劑學-處方判讀與調劑作業","meta":"109年第1次第8題","year":109,"session":1,"number":8,"question":"下列有關藥師調劑作業之敘述，何者錯誤？","options":["(A) 調劑時發現藥品未備或缺乏時，應通知原處方醫師，請其更換","(B) 藥師對於醫師所開處方，祇許調劑一次","(C) 某藥師開設藥局，其藥局之調劑作業，應日夜為之","(D) 含毒劇藥品之處方箋，調劑後應保存五年"],"answer":2,"image":""},{"id":"ph6-109-1-9","subject":"ph6","topic":"臨床藥學-藥事照護與用藥評估","meta":"109年第1次第9題","year":109,"session":1,"number":9,"question":"依藥師法之規定，下列何者非屬藥事照護相關業務？","options":["(A) 藥物治療流程評估","(B) 用藥諮詢","(C) 評估病患病情穩定狀況，直接機動調整醫師處方藥品之服用劑量及次數","(D) 執行藥品安全監視"],"answer":2,"image":""},{"id":"ph6-109-1-10","subject":"ph6","topic":"調劑學-處方判讀與調劑作業","meta":"109年第1次第10題","year":109,"session":1,"number":10,"question":"依藥品優良調劑作業準則之規定，下列有關調製之敘述，何者正確？","options":["(A) 依醫師處方箋計數正確數量、書寫藥袋或貼標籤、包裝","(B) 依醫師處方箋進行用藥適當性評估、交付藥品及用藥指導","(C) 依醫師處方箋替小兒病患將錠劑磨成粉末","(D) 購買原料藥製備藥品，分裝成小瓶裝販賣"],"answer":2,"image":""},{"id":"ph6-109-1-11","subject":"ph6","topic":"藥事法規-藥師法與執業管理","meta":"109年第1次第11題","year":109,"session":1,"number":11,"question":"甲藥師剛取得藥師證書，欲於藥局執業，下列敘述何者錯誤？","options":["(A) 甲藥師不得負責主持經營藥局","(B) 如果有一位在醫院執行調劑業務10年之乙藥師申請開設藥局，甲藥師即可申請在該藥局執業","(C) 甲藥師得在藥局受理醫師處方或依中華藥典、國民處方選輯之處方調劑","(D) 即使藥局領有管制藥品登記證，甲藥師仍不得調劑第一級至第三級管制藥品專用處方箋"],"answer":3,"image":""},{"id":"ph6-109-1-12","subject":"ph6","topic":"藥事法規-藥師法與執業管理","meta":"109年第1次第12題","year":109,"session":1,"number":12,"question":"依藥師法之規定，下列何者非屬藥師業務範圍？","options":["(A) 藥品鑑定","(B) 藥品調劑","(C) 藥事照護","(D) 施打疫苗"],"answer":3,"image":""},{"id":"ph6-109-1-13","subject":"ph6","topic":"藥事法規-藥師法與執業管理","meta":"109年第1次第13題","year":109,"session":1,"number":13,"question":"臺北市某藥師未親自執業且將證照租給他人使用，被移付懲戒後應由下列何者審理？","options":["(A) 臺北市衛生局","(B) 衛生福利部藥師懲戒委員會","(C) 臺北市藥師公會","(D) 臺北市藥師懲戒委員會"],"answer":3,"image":""},{"id":"ph6-109-1-14","subject":"ph6","topic":"調劑學-處方判讀與調劑作業","meta":"109年第1次第14題","year":109,"session":1,"number":14,"question":"下列敘述，何者錯誤？","options":["(A) 藥師對於醫師所開處方，祇許調劑一次","(B) 藥師調劑醫師所開之管制藥品處方箋應保存五年","(C) 藥師調劑醫師所開之毒劇藥品處方箋應保存三年","(D) 藥師調劑麻醉藥品之處方箋應保存五年"],"answer":2,"image":""},{"id":"ph6-109-1-15","subject":"ph6","topic":"調劑學-處方判讀與調劑作業","meta":"109年第1次第15題","year":109,"session":1,"number":15,"question":"依藥品優良調劑作業準則之規定，下列敘述何者正確？","options":["(A) 販賣業藥商執行調劑業務時準用之","(B) 不適用於依藥事法第102條規定調劑之醫師","(C) 調劑處所應有十八平方公尺以上之作業面積","(D) 處方藥不得以開架式陳列"],"answer":3,"image":""},{"id":"ph6-109-1-16","subject":"ph6","topic":"藥事法規-藥師法與執業管理","meta":"109年第1次第16題","year":109,"session":1,"number":16,"question":"藥師執業，應接受繼續教育，並應每幾年提出完成繼續教育證明文件，辦理執業執照更新？","options":["(A) 1","(B) 3","(C) 5","(D) 6"],"answer":3,"image":""},{"id":"ph6-109-1-17","subject":"ph6","topic":"藥事法規-新藥臨床試驗與安全監視","meta":"109年第1次第17題","year":109,"session":1,"number":17,"question":"持有藥物許可證之藥商於得知嚴重藥物不良反應之日起，多少時間內，應依規定通報？","options":["(A) 24小時","(B) 3日","(C) 7日","(D) 15日"],"answer":3,"image":""},{"id":"ph6-109-1-18","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"109年第1次第18題","year":109,"session":1,"number":18,"question":"A藥未取得我國核准之藥品許可證，小黃出國購買A藥帶回國內，在自家商店賣給來店客人，小黃這樣的行為，屬於下列何者？","options":["(A) 輸入偽藥","(B) 輸入劣藥","(C) 輸入禁藥","(D) 旅客自用未違法令"],"answer":2,"image":""},{"id":"ph6-109-1-19","subject":"ph6","topic":"藥事法規-新藥臨床試驗與安全監視","meta":"109年第1次第19題","year":109,"session":1,"number":19,"question":"藥事法所稱之新藥，其安全監視期間為自發證日起多少年？","options":["(A) 3","(B) 5","(C) 6","(D) 7"],"answer":1,"image":""},{"id":"ph6-109-1-20","subject":"ph6","topic":"調劑學-處方判讀與調劑作業","meta":"109年第1次第20題","year":109,"session":1,"number":20,"question":"某眼科診所將眼藥水稀釋分裝給病患使用，下列敘述何者錯誤？","options":["(A) 眼藥水稀釋後即非核准之標示濃度","(B) 調劑，必須依據醫師處方為之","(C) 診所分裝眼藥水不符合藥品優良製造規範","(D) 依劣藥罪進行起訴"],"answer":3,"image":""},{"id":"ph6-109-1-21","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"109年第1次第21題","year":109,"session":1,"number":21,"question":"下列有關衛生主管機關檢查作業，何者錯誤？","options":["(A) 得派員檢查醫療機構或藥局之有關業務","(B) 得派員檢查藥物製造業者及販賣業者之處所設施及有關業務","(C) 中央衛生主管機關得公告輸入時應抽查、檢驗之藥物，以加強邊境管理","(D) 衛生主管機關應每年不定期辦理藥商及藥局普查"],"answer":3,"image":""},{"id":"ph6-109-1-22","subject":"ph6","topic":"藥事法規-醫療器材管理法","meta":"109年第1次第22題","year":109,"session":1,"number":22,"question":"申請醫療器材查驗登記之案件未獲核准者，申請人得自處分書送達之日起幾個月內，敘明理由提出申復？","options":["(A) 1","(B) 2","(C) 3","(D) 4"],"answer":3,"image":""},{"id":"ph6-109-1-23","subject":"ph6","topic":"藥事法規-醫療器材管理法","meta":"109年第1次第23題","year":109,"session":1,"number":23,"question":"醫療器材之標籤、仿單或包裝，應依核准刊載之事項中，下列何者經中央衛生主管機關明令公告免予刊載者，不在此限？","options":["(A) 批號","(B) 製造日期及有效期間或保存期限","(C) 主要成分含量、用量及用法","(D) 主治效能、性能或適應症"],"answer":1,"image":""},{"id":"ph6-109-1-24","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"109年第1次第24題","year":109,"session":1,"number":24,"question":"下列敘述何者非屬於醫藥分業之目的？","options":["(A) 強化藥品流通管理體系，確保民眾用藥安全","(B) 健全社區藥局功能，增加民眾利用的可近性","(C) 建立醫療分工合理執業形態，提升臨床試驗品質","(D) 保障民眾知藥及選擇調劑處所之權利"],"answer":2,"image":""},{"id":"ph6-109-1-25","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"109年第1次第25題","year":109,"session":1,"number":25,"question":"依西藥藥品優良製造規範之規定，下列敘述何者正確？","options":["(A) 品質保證是品質管制的一部分，其精髓即是藥品生命週期","(B) 如發現產品已有污染，即應列為偏差品且不得回收","(C) 庫存應依先到期先出貨原則，例外情形應記錄備查","(D) 生產部門主管在生產紀錄送到品質管制部門前，應審核抽樣指令"],"answer":2,"image":""},{"id":"ph6-109-1-26","subject":"ph6","topic":"藥事法規-藥物廣告與稽查","meta":"109年第1次第26題","year":109,"session":1,"number":26,"question":"下列有關藥物廣告之規定，何者正確？","options":["(A) 血糖機廣告，應刊載於學術性醫療刊物","(B) 抗生素注射藥品廣告，應刊載於健康世界雜誌","(C) 血管支架可做電視廣告","(D) 日戴型每週拋棄式隱形眼鏡廣告，應刊載於藥師週刊"],"answer":3,"image":""},{"id":"ph6-109-1-27","subject":"ph6","topic":"藥事法規-新藥臨床試驗與安全監視","meta":"109年第1次第27題","year":109,"session":1,"number":27,"question":"藥品優良臨床試驗準則對於臨床試驗所使用之試驗藥品，下列敘述何者錯誤？","options":["(A) 係指臨床試驗中用來試驗之藥品，或當做參考之活性成分製劑，但不包括無活性成分之安慰劑","(B) 試驗主持人或試驗機構應負責試驗藥品之點收及保存","(C) 試驗藥品僅得使用於經核准之臨床試驗計畫","(D) 試驗主持人或試驗機構得指派專責藥師或適當人員負責部分或全部試驗藥品之點收及保存"],"answer":0,"image":""},{"id":"ph6-109-1-28","subject":"ph6","topic":"藥事法規-全民健康保險與藥事作業","meta":"109年第1次第28題","year":109,"session":1,"number":28,"question":"依全民健康保險藥物給付項目及支付標準之規定，下列何者錯誤？","options":["(A) 限由醫師使用或需由醫師處方使用之藥品得納入全民健康保險給付","(B) 全民健康保險給付醫師指示用藥，現正擴大給付範圍","(C) 中藥以「調劑專用」及「需由醫師（中醫師）處方使用」之濃縮中藥為限","(D) 全民健康保險不給付成藥"],"answer":1,"image":""},{"id":"ph6-109-1-29","subject":"ph6","topic":"藥事法規-新藥臨床試驗與安全監視","meta":"109年第1次第29題","year":109,"session":1,"number":29,"question":"下列敘述何者正確？","options":["(A) 新藥查驗登記須提交符合優良臨床試驗規範之完整臨床試驗計畫書供審查","(B) 用於人體試驗階段之藥品製造，無須符合藥品優良製造規範","(C) 輸入藥品，應由藥品許可證所有人及其授權者輸入","(D) 申請藥品查驗登記如原料藥屬低風險成分，可省略提交原料藥來源資料"],"answer":2,"image":""},{"id":"ph6-109-1-30","subject":"ph6","topic":"藥事法規-藥師法與執業管理","meta":"109年第1次第30題","year":109,"session":1,"number":30,"question":"下列敘述何者正確？","options":["(A) 藥局執照應懸掛於營業處所之明顯位置，藥商許可執照應建檔收存","(B) 西藥販賣業者之藥品及其買賣，應由專任藥師駐店管理","(C) 中醫師修習西藥課程達適當標準，得專任駐店管理西藥販賣業之藥品及其買賣","(D) 藥局零售隱形眼鏡，應另外申請醫療器材販賣業藥商許可執照"],"answer":1,"image":""},{"id":"ph6-109-1-31","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"109年第1次第31題","year":109,"session":1,"number":31,"question":"依成藥及固有成方製劑管理辦法之規定，下列敘述何者錯誤？","options":["(A) 成藥中摻用麻醉藥品，嗎啡含量應在千分之一以下","(B) 成藥中摻用毒劇藥品，如為中華藥典所載者，不得超過常用量三分之一","(C) 固有成方製劑應標明名稱及固有成方字樣","(D) 乙類成藥得由百貨店、雜貨店及餐飲服務商兼營零售之"],"answer":0,"image":""},{"id":"ph6-109-1-32","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"109年第1次第32題","year":109,"session":1,"number":32,"question":"下列有關百貨店兼營零售乙類成藥之敘述，何者正確？","options":["(A) 商號或招牌得使用「XX藥房」","(B) 得設置藥品推銷員","(C) 得將乙類成藥拆除包裝零售","(D) 對內服及外用乙類成藥，應各別專設櫥櫃陳列"],"answer":3,"image":""},{"id":"ph6-109-1-33","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"109年第1次第33題","year":109,"session":1,"number":33,"question":"依藥事法之規定，下列有關研發用藥物之敘述，何者錯誤？","options":["(A) 應於符合中央衛生主管機關規定之工廠或場所製造","(B) 非經中央衛生主管機關核准，不得使用於人體","(C) 製造應依藥物製造工廠設立之規定辦理工廠登記","(D) 製造工廠操作芽孢、細菌及病毒場所，應與其他場所完全隔離"],"answer":2,"image":""},{"id":"ph6-109-1-34","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"109年第1次第34題","year":109,"session":1,"number":34,"question":"某新成分新藥於104年3月1日於日本首度上市，由藥廠甲於107年2月1日申請查驗登記，於108年10月1日核准取得新成分新藥許可證。藥廠乙欲提出該新藥成分之學名藥申請時，可於何時提出申請？何時可領到衛生福利部核發之學名藥許可證？","options":["(A) 107年3月1日後；109年3月1日後","(B) 110年2月1日後；112年10月1日後","(C) 111年10月1日後；113年10月1日後","(D) 108年10月1日後；無時間限制"],"answer":2,"image":""},{"id":"ph6-109-1-35","subject":"ph6","topic":"藥事法規-新藥臨床試驗與安全監視","meta":"109年第1次第35題","year":109,"session":1,"number":35,"question":"為落實執行新藥臨床試驗，下列何者為受試者「自主」之最重要的方法？","options":["(A) 臨床試驗知情同意","(B) 執行臨床試驗稽核","(C) 數據安全監測計畫","(D) 嚴重不良反應通報"],"answer":0,"image":""},{"id":"ph6-109-1-36","subject":"ph6","topic":"藥事法規-新藥臨床試驗與安全監視","meta":"109年第1次第36題","year":109,"session":1,"number":36,"question":"臨床試驗之目的，係為確認藥物之安全性與有效性，其法源依據為：","options":["(A) 藥物安全監視管理辦法","(B) 醫療法","(C) 藥事法","(D) 藥物科技研究發展獎勵辦法"],"answer":2,"image":""},{"id":"ph6-109-1-37","subject":"ph6","topic":"藥事法規-管制藥品與毒品危害防制","meta":"109年第1次第37題","year":109,"session":1,"number":37,"question":"施用鴉片、大麻者，於犯罪未被發覺前，自動向衛生主管機關指定之醫療機構請求治療，依法該醫療機構應如何處置？","options":["(A) 將請求治療者，送觀察、勒戒處所","(B) 將請求治療者，送強制戒治處所","(C) 接受治療期滿後，送就業輔導機構輔導就業","(D) 免將請求治療者送法院或檢察機關"],"answer":3,"image":""},{"id":"ph6-109-1-38","subject":"ph6","topic":"藥事法規-管制藥品與毒品危害防制","meta":"109年第1次第38題","year":109,"session":1,"number":38,"question":"下列有關管制藥品之敘述，何者錯誤？","options":["(A) 管制藥品係指成癮性麻醉藥品、影響精神藥品、其他認為有加強管理必要之藥品","(B) 依其習慣性、依賴性、濫用性及社會危害性之程度，分第一級至第三級管理","(C) 醫師、牙醫師、獸醫師及獸醫佐非為正當醫療之目的，不得使用管制藥品","(D) 醫師、牙醫師、藥師或藥劑生調劑第一級至第三級管制藥品，非依醫師、牙醫師開立之管制藥品專用處方箋，不得為之"],"answer":1,"image":""},{"id":"ph6-109-1-39","subject":"ph6","topic":"藥事法規-管制藥品與毒品危害防制","meta":"109年第1次第39題","year":109,"session":1,"number":39,"question":"依管制藥品管理條例之規定，醫療機構及藥局，應於每年何月申報前一年管制藥品之簿冊登載情形？","options":["(A) 一月","(B) 十二月","(C) 四月","(D) 七月"],"answer":0,"image":""},{"id":"ph6-109-1-40","subject":"ph6","topic":"藥事法規-管制藥品與毒品危害防制","meta":"109年第1次第40題","year":109,"session":1,"number":40,"question":"下列有關管制藥品標籤之敘述，何者正確？","options":["(A) 管制藥品中文標籤之版面，應加貼或印刷圓形外框，框內註明級別","(B) 屬麻醉藥品者，中文標籤之版面，應加貼或印刷六角形外框，框內註明麻字","(C) 管制藥品均應於中文標籤加刊「調劑本藥應依管制藥品專用處方箋為之」","(D) 應以中文載明管制級別、警語及足以警惕之圖案或顏色"],"answer":3,"image":""},{"id":"ph6-109-1-41","subject":"ph6","topic":"藥事法規-化粧品衛生安全管理法","meta":"109年第1次第41題","year":109,"session":1,"number":41,"question":"依化粧品衛生安全管理法之規定，下列對於化粧品供應、販賣、贈送、公開陳列或提供消費者試用（簡稱上市）之產品登錄制度，何者正確？","options":["(A) 僅衛生福利部公告之化粧品種類及一定規模之化粧品製造或輸入業者，須於上市前完成產品登錄","(B) 輸入業者須於化粧品上市後完成登錄","(C) 製造及販賣業者須於上市前，完成產品登錄","(D) 產品登錄資料如有變更，僅需將變更資料留在業者備查即可"],"answer":0,"image":""},{"id":"ph6-109-1-42","subject":"ph6","topic":"藥事法規-化粧品衛生安全管理法","meta":"109年第1次第42題","year":109,"session":1,"number":42,"question":"依特定用途化粧品許可證核發辦法之規定，下列何者非屬中央主管機關公告具有特定用途之化粧品類別？","options":["(A) 止汗制臭","(B) 牙齒美白","(C) 防曬","(D) 殺菌"],"answer":3,"image":""},{"id":"ph6-109-1-43","subject":"ph6","topic":"藥事法規-藥害救濟與罕見疾病","meta":"109年第1次第43題","year":109,"session":1,"number":43,"question":"下列有關我國對「罕見疾病」定義的敘述，何者錯誤？","options":["(A) 總罹病人數一萬人以下","(B) 遺傳性","(C) 診治困難性","(D) 經罕見疾病及藥物審議委員會認定者"],"answer":0,"image":""},{"id":"ph6-109-1-44","subject":"ph6","topic":"藥事法規-藥害救濟與罕見疾病","meta":"109年第1次第44題","year":109,"session":1,"number":44,"question":"某血友病患者住院時，使用遭污染之血液製劑而感染愛滋病毒，下列敘述何者正確？","options":["(A) 血液製劑非屬全民健康保險給付範圍","(B) 患者可經訴願管道，請衛生福利部代位請求賠償","(C) 該血液製劑係遭病毒污染，不得申請藥害救濟","(D) 該患者知有藥害時起七年內，皆可請求藥害救濟"],"answer":2,"image":""},{"id":"ph6-109-1-45","subject":"ph6","topic":"藥事法規-藥害救濟與罕見疾病","meta":"109年第1次第45題","year":109,"session":1,"number":45,"question":"某辦理藥害救濟相關業務人員，無故洩漏受害人罹患愛滋病資訊，致該受害人罹患憂鬱症，下列敘述何者正確？","options":["(A) 受害人得以憂鬱症病因，申請藥害救濟","(B) 該承辦人員因業務而洩密，應受廢照廢證處分","(C) 受害人得對該洩密人員提出訴願之行政救濟","(D) 該承辦人員不得為自己利益而使用愛滋病之資訊"],"answer":3,"image":""},{"id":"ph6-109-1-46","subject":"ph6","topic":"藥事法規-全民健康保險與藥事作業","meta":"109年第1次第46題","year":109,"session":1,"number":46,"question":"我國實施醫藥分業制度，依全民健康保險法之規定，甲特約醫院A醫師開立之處方，由乙特約藥局B藥師調劑，經保險人核定不予給付，且可歸責於A醫師時，其調劑費及藥品費之處置，下列何者正確？","options":["(A) 應自乙特約藥局申報之費用核減","(B) 應自所支付給B藥師之費用核減","(C) 應自甲特約醫院申報之醫療費用核減","(D) 應自所支付給A醫師之費用核減"],"answer":2,"image":""},{"id":"ph6-109-1-47","subject":"ph6","topic":"藥事法規-全民健康保險與藥事作業","meta":"109年第1次第47題","year":109,"session":1,"number":47,"question":"依全民健康保險醫療辦法之規定，下列敘述何者正確？","options":["(A) 保險對象就醫未能及時繳驗健保卡，仍應先行提供醫療服務","(B) 特約醫院、診所應將門診處方交由保險對象，並限於該醫院、診所調劑","(C) 因長期慢性頑固性疼痛所需使用之第二級管制藥品得開立慢性病連續處方箋","(D) 領藥後藥品遺失，可再向原開方醫院就醫，由醫院申請健保醫療費用"],"answer":0,"image":""},{"id":"ph6-109-1-48","subject":"ph6","topic":"藥事法規-全民健康保險與藥事作業","meta":"109年第1次第48題","year":109,"session":1,"number":48,"question":"依全民健康保險醫療辦法之規定，保險對象持慢性病連續處方箋並出具切結文件，得一次領取該處方箋總用藥量之情形，不包括下列何者？","options":["(A) 預定出國或返回離島地區","(B) 遠洋漁船船員出海作業或國際航線船舶船員出海服務","(C) 罕見疾病病人","(D) 經醫師出具診斷書認定確有一次領取該處方箋總用藥量必要之特殊病人"],"answer":3,"image":""},{"id":"ph6-109-1-49","subject":"ph6","topic":"藥事法規-全民健康保險與藥事作業","meta":"109年第1次第49題","year":109,"session":1,"number":49,"question":"下列何國非屬全民健康保險給付藥品十國藥價參考國？","options":["(A) 美國","(B) 日本","(C) 韓國","(D) 加拿大"],"answer":2,"image":""},{"id":"ph6-109-1-50","subject":"ph6","topic":"藥事法規-全民健康保險與藥事作業","meta":"109年第1次第50題","year":109,"session":1,"number":50,"question":"依照全民健康保險醫療辦法之規定，保險對象如有重複就醫或不當利用醫療資源之情形，下列何者非屬法定之輔導方式？","options":["(A) 瞭解其就醫原因","(B) 依其病情指定其至特定之保險醫事服務機構接受診療服務","(C) 提供適當醫療衛教","(D) 修正處方用藥品項"],"answer":3,"image":""},{"id":"ph6-109-2-1","subject":"ph6","topic":"藥事法規-藥師法與執業管理","meta":"109年第2次第1題","year":109,"session":2,"number":1,"question":"藥師證書由下列何機關核發？","options":["(A) 衛生福利部食品藥物管理署","(B) 考試院","(C) 直轄市或縣（市）政府衛生局","(D) 衛生福利部"],"answer":3,"image":""},{"id":"ph6-109-2-2","subject":"ph6","topic":"藥事法規-藥政管理組織與衛生行政","meta":"109年第2次第2題","year":109,"session":2,"number":2,"question":"下列何者不屬衛生福利部之次級機關？","options":["(A) 社會及家庭署","(B) 食品藥物管理署","(C) 疾病管制署","(D) 醫藥品查驗中心"],"answer":3,"image":""},{"id":"ph6-109-2-3","subject":"ph6","topic":"藥事法規-醫療器材管理法","meta":"109年第2次第3題","year":109,"session":2,"number":3,"question":"設址於苗栗市之醫療器材商，如欲申請醫療器材廣告，應向下列何者提出廣告申請？","options":["(A) 衛生福利部","(B) 苗栗市政府衛生局","(C) 苗栗市政府","(D) 國家通訊傳播委員會"],"answer":0,"image":""},{"id":"ph6-109-2-4","subject":"ph6","topic":"藥事法規-藥政管理組織與衛生行政","meta":"109年第2次第4題","year":109,"session":2,"number":4,"question":"「緊急應變檢驗能量之規劃及建置」係屬衛生福利部食品藥物管理署轄下何單位之掌理事項？","options":["(A) 研究檢驗組","(B) 企劃及科技管理組","(C) 品質監督管理組","(D) 消費者保護中心"],"answer":0,"image":""},{"id":"ph6-109-2-5","subject":"ph6","topic":"藥事法規-新藥臨床試驗與安全監視","meta":"109年第2次第5題","year":109,"session":2,"number":5,"question":"目前我國公告新藥上市後之安全監視期間，為自發證日起幾年？","options":["(A) 1","(B) 3","(C) 5","(D) 7"],"answer":2,"image":""},{"id":"ph6-109-2-6","subject":"ph6","topic":"藥事法規-藥政管理組織與衛生行政","meta":"109年第2次第6題","year":109,"session":2,"number":6,"question":"下列何者非屬法定傳染病？","options":["(A) 蕁麻疹","(B) 日本腦炎","(C) 登革熱","(D) 後天免疫缺乏症候群（AIDS）"],"answer":0,"image":""},{"id":"ph6-109-2-7","subject":"ph6","topic":"藥事法規-藥政管理組織與衛生行政","meta":"109年第2次第7題","year":109,"session":2,"number":7,"question":"依據衛生福利部民國105年施政目標，下列何者之經費編列最多？","options":["(A) 健全福利服務體系，優先照顧弱勢族群","(B) 精進醫療照護體系，保障民眾就醫權益","(C) 完善高齡照護體系，建構高齡友善環境","(D) 健全社會保險制度，強化自助互助機制"],"answer":3,"image":""},{"id":"ph6-109-2-8","subject":"ph6","topic":"藥事法規-藥師法與執業管理","meta":"109年第2次第8題","year":109,"session":2,"number":8,"question":"健保特約藥局受理健保處方箋，下列何者非屬藥師法所定處方應注意事項？","options":["(A) 開立處方日期","(B) 核對病人姓名、性別、年齡、藥名、劑量、用法","(C) 健保藥價","(D) 處方是否有可疑之處"],"answer":2,"image":""},{"id":"ph6-109-2-9","subject":"ph6","topic":"藥事法規-藥師法與執業管理","meta":"109年第2次第9題","year":109,"session":2,"number":9,"question":"下列有關藥師法第11條藥師執業以一處為限之敘述，何者錯誤？","options":["(A) 大法官會議第711號解釋宣告藥師執業僅得限於一處違憲","(B) 於醫療機構、藥局及藥商執業者，經中央主管機關認定之公益或緊急需要，並經事先報准，得於執業處所外執行業務","(C) 醫院進行偏鄉義診，隨行藥師需事先報准才可執業","(D) 於執業處所外執行藥事照護相關業務，應向執業所在地主管機關提出申請"],"answer":1,"image":""},{"id":"ph6-109-2-10","subject":"ph6","topic":"藥事法規-藥師法與執業管理","meta":"109年第2次第10題","year":109,"session":2,"number":10,"question":"依藥師法之規定，下列有關「他藥」之敘述，何者正確？","options":["(A) 係指同成分、同劑量之藥品","(B) 係指同成分、同療效之藥品","(C) 係指同劑量、療效或劑型之藥品","(D) 係指不同成分、含量、劑量或劑型之藥品"],"answer":3,"image":""},{"id":"ph6-109-2-11","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"109年第2次第11題","year":109,"session":2,"number":11,"question":"下列何項產品不得以開架式陳列？","options":["(A) 含藥酒類","(B) 醫師藥師藥劑生指示藥品","(C) 治療高血壓藥品","(D) 耳溫槍"],"answer":2,"image":""},{"id":"ph6-109-2-12","subject":"ph6","topic":"藥事法規-藥師法與執業管理","meta":"109年第2次第12題","year":109,"session":2,"number":12,"question":"下列何者為藥師法所稱之藥事照護相關業務？","options":["(A) 藥師為管制藥品專用處方箋調劑","(B) 藥師為癌症病人調劑止痛用麻醉藥品","(C) 臨床藥師為病患自控式麻醉止痛（PCA）使用嗎啡治療流程評估","(D) 醫院管制藥品之管理"],"answer":2,"image":""},{"id":"ph6-109-2-13","subject":"ph6","topic":"調劑學-處方判讀與調劑作業","meta":"109年第2次第13題","year":109,"session":2,"number":13,"question":"依藥品優良調劑作業準則之規定，調劑處所應有多少平方公尺以上之作業面積，並應與其他作業處所明顯區隔？","options":["(A) 6","(B) 8","(C) 10","(D) 5"],"answer":0,"image":""},{"id":"ph6-109-2-14","subject":"ph6","topic":"藥事法規-藥師法與執業管理","meta":"109年第2次第14題","year":109,"session":2,"number":14,"question":"某藥師於106年11月1日首次領得執業執照，進入醫學中心擔任藥師，在職期間出國進修9個月，於108年12月1日離職，下列敘述何者錯誤？","options":["(A) 該藥師離職應自離職之日起30日內報請原發執業執照之主管機關申請歇業","(B) 出國進修應向原發執業執照主管機關申請停業","(C) 該藥師112年6月1日，再申請執業無須提具繼續教育證明文件","(D) 該藥師已具備2年調劑經驗"],"answer":3,"image":""},{"id":"ph6-109-2-15","subject":"ph6","topic":"藥事法規-藥師法與執業管理","meta":"109年第2次第15題","year":109,"session":2,"number":15,"question":"依藥師法之規定，下列有關藥師懲戒之敘述，何者錯誤？","options":["(A) 某甲兼領有藥師證書及藥劑生證書，當受懲戒廢止藥師證書時，其藥劑生證書一併廢止","(B) 執業執照之廢止，由中央主管機關為之","(C) 藥師懲戒委員會、藥師懲戒覆審委員之懲戒決議，應送由該管主管機關執行之","(D) 藥師移付懲戒事件，由藥師懲戒委員會處理之"],"answer":1,"image":""},{"id":"ph6-109-2-16","subject":"ph6","topic":"調劑學-處方判讀與調劑作業","meta":"109年第2次第16題","year":109,"session":2,"number":16,"question":"下列何者非屬藥品優良調劑作業準則所稱之「藥事作業處所」？","options":["(A) 醫院藥劑部門","(B) 健保特約藥局","(C) 連鎖體系藥商","(D) 未加入健保之藥局"],"answer":2,"image":""},{"id":"ph6-109-2-17","subject":"ph6","topic":"藥事法規-藥師法與執業管理","meta":"109年第2次第17題","year":109,"session":2,"number":17,"question":"負責主持經營藥局之藥師，應具備多久以上實際調劑執業經驗，始得提供藥品調劑服務？","options":["(A) 6個月","(B) 1年","(C) 2年","(D) 3年"],"answer":2,"image":""},{"id":"ph6-109-2-18","subject":"ph6","topic":"藥事法規-新藥臨床試驗與安全監視","meta":"109年第2次第18題","year":109,"session":2,"number":18,"question":"醫療法所稱之人體試驗，係指醫療機構依醫學理論於人體施行之下列那些試驗研究？①新醫療技術 ②新藥品 ③新醫療器材 ④學名藥生體可用率／生體相等性","options":["(A) ①②③④","(B) 僅①②③","(C) 僅①②④","(D) 僅③④"],"answer":0,"image":""},{"id":"ph6-109-2-19","subject":"ph6","topic":"藥事法規-新藥臨床試驗與安全監視","meta":"109年第2次第19題","year":109,"session":2,"number":19,"question":"醫療機構及藥局應於得知導致病人死亡或危及生命之藥品嚴重不良反應之日起幾日內依法通報，並應副知何者？","options":["(A) 7日；藥害救濟基金會","(B) 3日；醫院負責醫師","(C) 7日；許可證持有藥商","(D) 5日；醫藥品查驗中心"],"answer":2,"image":""},{"id":"ph6-109-2-20","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"109年第2次第20題","year":109,"session":2,"number":20,"question":"阿娟將已超過有效期間沒賣完的藥品，更換有效期間標示繼續販售，該藥品屬於藥事法所定之下列何者？","options":["(A) 劣藥","(B) 禁藥","(C) 偽藥","(D) 不良藥品"],"answer":2,"image":""},{"id":"ph6-109-2-21","subject":"ph6","topic":"藥事法規-新藥臨床試驗與安全監視","meta":"109年第2次第21題","year":109,"session":2,"number":21,"question":"依藥事法之規定，下列敘述何者正確？","options":["(A) 已核准藥品，改變使用劑量而具有新醫療效能，不符合新藥之定義","(B) 新成分新藥於國外執行臨床試驗，可視同為國內之臨床試驗","(C) 新藥應進行安全監視","(D) 中藥新藥應經財團法人醫藥品查驗中心審查認定"],"answer":2,"image":""},{"id":"ph6-109-2-22","subject":"ph6","topic":"調劑學-藥品包裝標示與儲存","meta":"109年第2次第22題","year":109,"session":2,"number":22,"question":"下列有關藥廠藥師進行栓劑產品安定性試驗之敘述，何者正確？","options":["(A) 由質量平衡之兩極端值，可檢出安定性試驗之結果","(B) 涵括設計（bracketing）假設每一受測部分組合安定性，可代表所有樣本在一既定時間點之安定性","(C) 加速試驗中，目視栓劑軟化可判為安定性不及格指標，毋須再執行虐待試驗","(D) 安定性試驗分析方法確效，須涵蓋系統適用性"],"answer":3,"image":""},{"id":"ph6-109-2-23","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"109年第2次第23題","year":109,"session":2,"number":23,"question":"下列有關新藥及學名藥之敘述，何者錯誤？","options":["(A) Propanolol為Inderal學名藥之一","(B) 學名藥係與國內已核准之藥品具同成分、同劑量、同劑型、同療效之製劑","(C) 全民健康保險不給付學名藥","(D) 申請新成分新藥查驗登記，得免附出產國許可製售證明及採用證明"],"answer":2,"image":""},{"id":"ph6-109-2-24","subject":"ph6","topic":"藥事法規-化粧品衛生安全管理法","meta":"109年第2次第24題","year":109,"session":2,"number":24,"question":"某面膜廣告出現「促進膠原蛋白再生」字句，下列敘述何者正確？","options":["(A) 膠原蛋白為人體天然物質，該面膜不符合化粧品定義","(B) 該面膜應先通過查驗登記，始得上市","(C) 該面膜廣告標示涉及誇大不當","(D) 該面膜製造應先通過GMP符合性查廠"],"answer":2,"image":""},{"id":"ph6-109-2-25","subject":"ph6","topic":"藥事法規-新藥臨床試驗與安全監視","meta":"109年第2次第25題","year":109,"session":2,"number":25,"question":"依藥品優良臨床試驗準則之規定，下列敘述何者錯誤？","options":["(A) 受試者無需任何理由即可退出試驗","(B) 只有受試者發生死亡或危及生命的嚴重藥物不良反應，試驗主持人才須通知試驗委託者","(C) 受試者皆須清楚知道試驗內容及簽署同意書","(D) 試驗機構為審查藥品臨床試驗，應設人體試驗委員會"],"answer":1,"image":""},{"id":"ph6-109-2-26","subject":"ph6","topic":"藥事法規-醫療器材管理法","meta":"109年第2次第26題","year":109,"session":2,"number":26,"question":"下列有關醫療器材販賣業者之敘述，何者錯誤？","options":["(A) 係指經營醫療器材之批發、零售、輸入及輸出之業者","(B) 應申請中央衛生主管機關核准登記，繳納執照費，領得許可執照後，方准營業","(C) 登記事項如有變更，包括自行停業、復業或歇業，應自事實發生之日起十五日內，向原核准登記之衛生主管機關申請辦理變更登記","(D) 僱用之推銷員，應由該業者向當地之直轄市、縣（市）衛生主管機關登記後，方准執行推銷工作"],"answer":1,"image":""},{"id":"ph6-109-2-27","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"109年第2次第27題","year":109,"session":2,"number":27,"question":"依藥事法第102條之規定，澎湖地區無藥事人員執業之醫療偏遠地區由下列何者公告？","options":["(A) 中央健康保險署","(B) 澎湖縣政府","(C) 內政部","(D) 衛生福利部"],"answer":3,"image":""},{"id":"ph6-109-2-28","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"109年第2次第28題","year":109,"session":2,"number":28,"question":"依藥事法之規定，下列敘述何者錯誤？","options":["(A) 藥物製造工廠，應依藥物製造工廠設廠標準設立，並依工廠管理輔導法規定，辦理工廠登記","(B) 從事藥物研發之機構或公司，其研發用藥物，應於符合中央衛生主管機關規定之工廠或場所製造","(C) 藥物製造工廠之廠房設施、設備、組織與人事、生產、品質管制、儲存、運銷、客戶申訴及其他事項，應符合藥物優良製造準則之規定","(D) 藥物工廠，經中央衛生主管機關檢查，符合藥物優良製造準則之規定，取得藥物製造許可後，無須再經中央衛生主管機關核准，即可接受他廠委託製造藥物"],"answer":3,"image":""},{"id":"ph6-109-2-29","subject":"ph6","topic":"藥事法規-藥物廣告與稽查","meta":"109年第2次第29題","year":109,"session":2,"number":29,"question":"下列何類產品不得於電視上刊播廣告？","options":["(A) 醫師處方藥","(B) 醫師藥師藥劑生指示藥品","(C) 乙類成藥","(D) 健康食品"],"answer":0,"image":""},{"id":"ph6-109-2-30","subject":"ph6","topic":"藥事法規-醫療器材管理法","meta":"109年第2次第30題","year":109,"session":2,"number":30,"question":"下列有關隱形眼鏡之敘述，何者錯誤？","options":["(A) 日拋隱形眼鏡，得不限刊登於學術性醫療刊物","(B) 隱形眼鏡屬第二等級醫療器材，藥局不可販售","(C) 隱形眼鏡廣告須經事前審查，且要加註警語","(D) 隱形眼鏡網路販售，藥商須事前提出申請"],"answer":1,"image":""},{"id":"ph6-109-2-31","subject":"ph6","topic":"藥事法規-藥物廣告與稽查","meta":"109年第2次第31題","year":109,"session":2,"number":31,"question":"藥商於網路上登載藥物資訊或廣告，下列敘述何者正確？","options":["(A) 許可證持有藥商於自家公司網頁提供符合規定之產品資訊，無須申請廣告許可","(B) 非處方藥於一般網站上刊播產品廣告，無須申請許可","(C) 處方藥於列管之醫療網站刊播廣告資訊，無須申請許可","(D) 處方藥可於一般網站上刊播產品廣告"],"answer":0,"image":""},{"id":"ph6-109-2-32","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"109年第2次第32題","year":109,"session":2,"number":32,"question":"下列何者非屬製造藥品時應確保之事項？","options":["(A) 該藥品符合其預定用途","(B) 符合上市許可的要求","(C) 不會由於其安全性、品質或有效性的不足而使病人陷於危險","(D) 藥品通過世界衛生組織資格預審（WHO prequalification）要求"],"answer":3,"image":""},{"id":"ph6-109-2-33","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"109年第2次第33題","year":109,"session":2,"number":33,"question":"提供西藥藥品優良製造規範所需之資源，包括下列那些？①經適當資格檢定與訓練的人員 ②足夠的廠房與作業空間 ③適當的設備及支援服務 ④依製藥品質系統所核定之程序及指令 ⑤正確的原物料、容器及標籤 ⑥適當之儲存及運送","options":["(A) ①②③④⑤⑥","(B) 僅①③⑤⑥","(C) 僅①②③④","(D) 僅②④⑤⑥"],"answer":0,"image":""},{"id":"ph6-109-2-34","subject":"ph6","topic":"藥事法規-化粧品衛生安全管理法","meta":"109年第2次第34題","year":109,"session":2,"number":34,"question":"下列有關眼藥水、角膜變色片之敘述，何者正確？","options":["(A) 眼藥水業經主管機關公告核准網路販賣","(B) 網路販賣角膜變色片，依違反化粧品衛生安全管理法之規定處罰","(C) 販賣眼藥水，應請領藥商許可執照後方准營業","(D) 眼藥水販賣業在臺北市與新北市分設營業處所，得向衛生福利部統一辦理登記"],"answer":2,"image":""},{"id":"ph6-109-2-35","subject":"ph6","topic":"藥事法規-醫療器材管理法","meta":"109年第2次第35題","year":109,"session":2,"number":35,"question":"中醫師常用之針灸針係屬藥事法中所稱之：","options":["(A) 一般商品","(B) 醫療器材","(C) 成藥","(D) 試驗用藥"],"answer":1,"image":""},{"id":"ph6-109-2-36","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"109年第2次第36題","year":109,"session":2,"number":36,"question":"有關藥品販賣業者之敘述，下列何者錯誤？","options":["(A) 西藥販賣業者，不得兼售中藥，但成藥不在此限","(B) 中藥販賣業者，不得兼售西藥，但成藥不在此限","(C) 中藥販賣業者，不得兼售農藥、動物用藥品或其他毒性化學物質","(D) 西藥販賣業者，得兼售農藥、動物用藥品或其他毒性化學物質"],"answer":3,"image":""},{"id":"ph6-109-2-37","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"109年第2次第37題","year":109,"session":2,"number":37,"question":"依藥事法之規定，有關藥品查驗登記資料保護5年之對象包括下列何者？①新成分新藥 ②新劑型新藥 ③同成分、同劑型、同劑量及同單位含量之藥品","options":["(A) 僅①","(B) 僅②③","(C) 僅①③","(D) ①②③"],"answer":0,"image":""},{"id":"ph6-109-2-38","subject":"ph6","topic":"藥事法規-管制藥品與毒品危害防制","meta":"109年第2次第38題","year":109,"session":2,"number":38,"question":"毒品危害防制條例所稱毒品，指具有成癮性、濫用性及對社會危害性之麻醉藥品與其製品及影響精神物質與其製品，依其成癮性、濫用性及對社會危害性分為幾級？","options":["(A) 2","(B) 3","(C) 4","(D) 5"],"answer":2,"image":""},{"id":"ph6-109-2-39","subject":"ph6","topic":"藥事法規-管制藥品與毒品危害防制","meta":"109年第2次第39題","year":109,"session":2,"number":39,"question":"出國旅遊攜帶第一級至第三級管制藥品出入境時，下列敘述何者正確？","options":["(A) 為治療本人之疾病，可攜帶不限量之管制藥品","(B) 得檢附聲明書與必須施用管制藥品理由之醫師診斷證明書","(C) 得檢附地方衛生主管機關備查之證明文件","(D) 國人攜帶管制藥品出境，不需瞭解入境國之特殊規定"],"answer":1,"image":""},{"id":"ph6-109-2-40","subject":"ph6","topic":"藥事法規-管制藥品與毒品危害防制","meta":"109年第2次第40題","year":109,"session":2,"number":40,"question":"管制藥品管理條例所稱衛生主管機關為：","options":["(A) 中央為衛生福利部食品藥物管理署，地方為直轄市政府或縣（市）政府之衛生局","(B) 中央為衛生福利部，地方為直轄市政府或縣（市）政府之衛生局","(C) 中央為衛生福利部食品藥物管理署，地方為直轄市政府或縣（市）政府","(D) 中央為衛生福利部，地方為直轄市政府或縣（市）政府"],"answer":3,"image":""},{"id":"ph6-109-2-41","subject":"ph6","topic":"藥事法規-化粧品衛生安全管理法","meta":"109年第2次第41題","year":109,"session":2,"number":41,"question":"依化粧品衛生安全管理法之規定，有關化粧品外包裝應明顯標示之規定，下列敘述何者錯誤？","options":["(A) 外包裝須標示品名","(B) 輸入產品之原產地（國）","(C) 全成分名稱皆應以中文標示","(D) 特定用途化粧品應標示所含特定用途成分名稱、含量及使用注意事項"],"answer":2,"image":""},{"id":"ph6-109-2-42","subject":"ph6","topic":"藥事法規-化粧品衛生安全管理法","meta":"109年第2次第42題","year":109,"session":2,"number":42,"question":"臺北市衛生局稽查某化粧品進口商，發現有未經核准擅自輸入之染髮劑，依化粧品衛生安全管理法之規定，對該業者之處置方式，下列何者錯誤？","options":["(A) 不得提供消費用試用","(B) 將產品予以封存","(C) 得命其產品下架","(D) 移請檢察機關偵查起訴"],"answer":3,"image":""},{"id":"ph6-109-2-43","subject":"ph6","topic":"藥事法規-藥害救濟與罕見疾病","meta":"109年第2次第43題","year":109,"session":2,"number":43,"question":"有關未依藥物許可證所載之適應症或效能而為藥物之使用，下列敘述何者正確？","options":["(A) 須經全民健康保險會認定用藥適當性，方屬適法","(B) 藥害救濟法可申請給付之宗旨為鼓勵非適應症外使用，以保障用藥基本權益","(C) 依用藥當時具公信力醫學文獻給藥，是合法使用之基本要件","(D) 藥商對許可證所載適應症外使用之藥品得進行行銷"],"answer":2,"image":""},{"id":"ph6-109-2-44","subject":"ph6","topic":"藥事法規-藥害救濟與罕見疾病","meta":"109年第2次第44題","year":109,"session":2,"number":44,"question":"依藥害救濟法之規定，下列何者非屬「嚴重疾病」定義之範圍？","options":["(A) 胎嬰兒先天性畸形","(B) 導致病人住院","(C) 躁鬱症","(D) 延長病人住院時間"],"answer":2,"image":""},{"id":"ph6-109-2-45","subject":"ph6","topic":"藥事法規-藥害救濟與罕見疾病","meta":"109年第2次第45題","year":109,"session":2,"number":45,"question":"擅自製造、輸入未經許可之罕見疾病藥物，下列處置何者正確？","options":["(A) 供製造之器具沒收，藥物銷燬","(B) 若藥物經檢驗合格，可開放醫院診所申請使用","(C) 視同一般之製造或輸入偽藥或禁藥","(D) 該藥物僅得供研究、教學或教育宣導使用"],"answer":2,"image":""},{"id":"ph6-109-2-46","subject":"ph6","topic":"藥事法規-全民健康保險與藥事作業","meta":"109年第2次第46題","year":109,"session":2,"number":46,"question":"某健保特約醫院對於健保醫療給付，自立名目向保險對象收取費用，依全民健康保險法之規定，除應退還已收取之費用，並應按所收取之費用處以幾倍之罰鍰？","options":["(A) 1","(B) 2","(C) 5","(D) 10"],"answer":2,"image":""},{"id":"ph6-109-2-47","subject":"ph6","topic":"藥事法規-全民健康保險與藥事作業","meta":"109年第2次第47題","year":109,"session":2,"number":47,"question":"下列何者屬於全民健康保險法中給付的項目？","options":["(A) 人體試驗藥品","(B) 預防接種之公費疫苗","(C) 治療藥癮之美沙冬","(D) 緊急傷病經醫師診斷認為必要之輸血"],"answer":3,"image":""},{"id":"ph6-109-2-48","subject":"ph6","topic":"藥事法規-全民健康保險與藥事作業","meta":"109年第2次第48題","year":109,"session":2,"number":48,"question":"依全民健康保險法之規定，藥品費用超出預先設定之藥品費用分配比率目標時，下列何者錯誤？","options":["(A) 超出部分，應自當季之醫療給付費用總額中扣除","(B) 超出目標之額度，保險人應於次一年度修正藥物給付項目及支付標準","(C) 超出部分，依支出目標調整核付各保險醫事服務機構之費用","(D) 超出部分，應加權平均核減該年度各醫療機構申報之醫療費用"],"answer":3,"image":""},{"id":"ph6-109-2-49","subject":"ph6","topic":"藥事法規-全民健康保險與藥事作業","meta":"109年第2次第49題","year":109,"session":2,"number":49,"question":"依據全民健康保險法之規定，健保特約藥局調劑藥品之替代，下列敘述何者錯誤？","options":["(A) 若醫師未註明不可替代，得以相同價格或低於原處方藥品價格之同成分、同劑型、同含量其他廠牌藥品替代","(B) 若醫師註明不可替代，不得以同成分、同劑型、同劑量之其他廠牌藥品替代","(C) 若醫師未註明不可替代，得以使用同藥理作用、同劑型、同劑量之其他廠牌藥品替代","(D) 若醫師未註明不可替代，而以其他同成分、同劑型、同含量之其他廠牌藥品替代時，應告知保險對象"],"answer":2,"image":""},{"id":"ph6-109-2-50","subject":"ph6","topic":"藥事法規-全民健康保險與藥事作業","meta":"109年第2次第50題","year":109,"session":2,"number":50,"question":"依全民健康保險法相關規定，可建議納入全民健康保險給付之藥品不包括下列何者？","options":["(A) 限由醫師使用之藥品","(B) 由醫師或檢驗師使用之藥品","(C) 醫師指示藥品","(D) 限由麻醉醫師使用之藥品"],"answer":2,"image":""},{"id":"ph6-110-1-1","subject":"ph6","topic":"藥事法規-藥政管理組織與衛生行政","meta":"110年第1次第1題","year":110,"session":1,"number":1,"question":"下列有關衛生福利部食品藥物管理署的敘述，何者錯誤？","options":["(A) 前身為行政院衛生署食品藥物管理局","(B) 是整併行政院衛生署食品衛生處、藥政處、藥物食品檢驗局、中醫藥委員會而成","(C) 為中央三級行政機關","(D) 辦理食品、藥物、化粧品之管理等業務"],"answer":1,"image":""},{"id":"ph6-110-1-2","subject":"ph6","topic":"藥事法規-新藥臨床試驗與安全監視","meta":"110年第1次第2題","year":110,"session":1,"number":2,"question":"A公司為一研發新藥之公司，下列有關申請事項之受理機關何者錯誤？","options":["(A) 藥物人體試驗須向衛生福利部醫事司申請","(B) 新藥查驗登記須向衛生福利部申請","(C) 適用生技新藥產業發展條例之生技新藥公司應向經濟部申請","(D) 藥品專案諮詢輔導應向衛生福利部食品藥物管理署申請"],"answer":0,"image":""},{"id":"ph6-110-1-3","subject":"ph6","topic":"藥事法規-藥政管理組織與衛生行政","meta":"110年第1次第3題","year":110,"session":1,"number":3,"question":"人用中藥、西藥及動物用藥品之法定主管機關，下列何者正確？","options":["(A) 皆由衛生福利部食品藥物管理署主管","(B) 中藥由衛生福利部中醫藥司主管；西藥及動物用藥品由衛生福利部食品藥物管理署主管","(C) 人用中藥、西藥由衛生福利部主管；動物用藥品由行政院農業委員會主管","(D) 人用中藥、西藥由衛生福利部食品藥物管理署主管；動物用藥品由農業委員會動植物防疫檢疫局主管"],"answer":2,"image":""},{"id":"ph6-110-1-4","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"110年第1次第4題","year":110,"session":1,"number":4,"question":"下列何者得於網路販售？","options":["(A) 綠油精","(B) 龍膽瀉肝湯濃縮製劑","(C) 普拿疼500 mg錠","(D) 綜合感冒糖漿劑"],"answer":0,"image":""},{"id":"ph6-110-1-5","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"110年第1次第5題","year":110,"session":1,"number":5,"question":"藥事法所稱藥物，係指藥品及下列何者？","options":["(A) 疫苗","(B) 生物製劑","(C) 醫療器材","(D) 含藥化粧品"],"answer":2,"image":""},{"id":"ph6-110-1-6","subject":"ph6","topic":"藥事法規-藥政管理組織與衛生行政","meta":"110年第1次第6題","year":110,"session":1,"number":6,"question":"下列有關國家執行藥物食品檢驗之業務，何者錯誤？","options":["(A) 增購精密分析儀器設備","(B) 辦理標準品製備及供應","(C) 開發精確檢驗方法","(D) 配合行政管理檢驗，但不含突發事件之檢驗"],"answer":3,"image":""},{"id":"ph6-110-1-7","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"110年第1次第7題","year":110,"session":1,"number":7,"question":"依藥事法之規定，下列何者為藥師或藥劑生親自主持，依法執行藥品調劑、供應業務之處所？","options":["(A) 藥局","(B) 西藥房","(C) 健康廣場","(D) 藥妝店"],"answer":0,"image":""},{"id":"ph6-110-1-8","subject":"ph6","topic":"藥事法規-藥師法與執業管理","meta":"110年第1次第8題","year":110,"session":1,"number":8,"question":"依藥師法之規定，下列敘述何者正確？","options":["(A) 藥師不得於執業處所外執行藥事照護相關業務","(B) 藥局之藥師應日夜執行調劑業務","(C) 藥局執業藥師經事先報准，可參與義診","(D) 藥師執行調劑業務，因藥品未備或缺乏時，得代以他藥"],"answer":2,"image":""},{"id":"ph6-110-1-9","subject":"ph6","topic":"藥事法規-藥師法與執業管理","meta":"110年第1次第9題","year":110,"session":1,"number":9,"question":"依藥師法之規定，下列敘述何者錯誤？","options":["(A) 經藥師考試及格，檢具申請書及資格證明文件，送請衛生福利部核發藥師證書","(B) 藥師執業應加入執業所在地之藥師公會","(C) 藥師執業應向執業所在地之直轄市、縣（市）主管機關申請執業登記，請領藥師執業執照","(D) 藥師在主管機關核准登記之醫療機構、依法規定之執業處所或其他經主管機關認可之機構，均得同時登記執業"],"answer":3,"image":""},{"id":"ph6-110-1-10","subject":"ph6","topic":"藥事法規-醫療器材管理法","meta":"110年第1次第10題","year":110,"session":1,"number":10,"question":"某女士生理期延誤，到社區藥局購買驗孕棒，驗後呈現未懷孕，藥師售以高劑量避孕藥催經，下列敘述何者錯誤？","options":["(A) 驗孕棒屬第二等級醫療器材，藥局可販售","(B) 依照驗孕棒的原理，有可能在使用驗孕棒時激素尚不足所以驗不出","(C) 驗孕棒可在網路上購買","(D) 藥師未經醫師處方給予處方藥，違反藥事法"],"answer":2,"image":""},{"id":"ph6-110-1-11","subject":"ph6","topic":"藥事法規-藥師法與執業管理","meta":"110年第1次第11題","year":110,"session":1,"number":11,"question":"依藥師法之規定，有關藥師懲戒之執行機關，下列何者正確？","options":["(A) 警告、罰鍰、廢止執業執照，由中央主管機關為之","(B) 廢止藥師證書，由直轄市及縣（市）政府為之","(C) 停業處分，中央主管機關、直轄市及縣（市）主管機關皆得為之","(D) 警告，由直轄市及縣（市）主管機關為之"],"answer":3,"image":""},{"id":"ph6-110-1-12","subject":"ph6","topic":"藥事法規-藥師法與執業管理","meta":"110年第1次第12題","year":110,"session":1,"number":12,"question":"藥師考試及格證書、藥師執業執照、管制藥品登記證，應分別向下列何機關申請核發？","options":["(A) 衛生福利部；衛生福利部；直轄市或縣（市）衛生主管機關","(B) 考試院；衛生福利部食品藥物管理署；直轄市或縣（市）衛生主管機關","(C) 衛生福利部；直轄市或縣（市）主管機關；直轄市或縣（市）衛生主管機關","(D) 考試院；直轄市或縣（市）衛生主管機關；衛生福利部食品藥物管理署"],"answer":3,"image":""},{"id":"ph6-110-1-13","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"110年第1次第13題","year":110,"session":1,"number":13,"question":"下列何者於藥局內不得以開架式陳列？","options":["(A) 保力達B","(B) 威而鋼","(C) 普拿疼加強錠","(D) 善存"],"answer":1,"image":""},{"id":"ph6-110-1-14","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"110年第1次第14題","year":110,"session":1,"number":14,"question":"有關藥師執行藥品之調劑，下列敘述何者錯誤？","options":["(A) 藥師調劑時，對於處方可疑之點詢明原處方醫師確認之情事，應予註明","(B) 非慢性病之連續處方箋，最多可調劑三次","(C) 藥師調劑後應在其處方箋簽名蓋章","(D) 處方箋保存3年，含有麻醉藥品者保存5年"],"answer":1,"image":""},{"id":"ph6-110-1-15","subject":"ph6","topic":"藥事法規-藥師法與執業管理","meta":"110年第1次第15題","year":110,"session":1,"number":15,"question":"依藥師法之規定，藥事照護相關業務不包括下列何者？","options":["(A) 為增進藥物療程之效益及生活品質，考量藥物使用情形及評估療效之藥事服務事項","(B) 於醫療機構、護理機構，執行藥品安全監視、給藥流程評估、用藥諮詢及藥物治療流程評估等相關藥事服務事項","(C) 於依老人福利法所定之老人福利機構，執行藥品安全監視、給藥流程評估、用藥諮詢及藥物治療流程評估等相關藥事服務事項","(D) 於嬰幼托育機構，執行藥品安全監視、給藥流程評估、用藥諮詢及藥物治療流程評估等相關藥事服務事項"],"answer":3,"image":""},{"id":"ph6-110-1-16","subject":"ph6","topic":"藥事法規-藥師法與執業管理","meta":"110年第1次第16題","year":110,"session":1,"number":16,"question":"藥師辦理執業執照更新，應於其執業執照應更新日期屆滿前六個月內，檢具最近六年內接受繼續教育達幾點之證明文件，且專業品質、專業倫理及專業相關法規課程積分數合計至少十二點？","options":["(A) 120","(B) 150","(C) 180","(D) 200"],"answer":0,"image":""},{"id":"ph6-110-1-17","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"110年第1次第17題","year":110,"session":1,"number":17,"question":"小明藥師的朋友自國外跑單幫帶回未經核准之「必敗」藥品，請小明藥師幫忙販售，小明知道違法，但不敵人情壓力，於店中陳列販售。小明係違反藥事法何種規定？","options":["(A) 輸入劣藥","(B) 未經核准擅自輸入禁藥","(C) 明知為禁藥，而販賣、供應或意圖販賣而陳列","(D) 所賣之藥品為旅客攜帶自用藥品進口，未違反規定"],"answer":2,"image":""},{"id":"ph6-110-1-18","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"110年第1次第18題","year":110,"session":1,"number":18,"question":"依藥事法之規定，下列敘述何者錯誤？","options":["(A) 藥品製造業者輸入自用原料，無須每次進口前向中央衛生主管機關申請核准","(B) 查驗登記審查準則所稱採用證明，指十大醫藥先進國家中之一國出具之採用證明","(C) 藥品製造可直接購買有許可證之原料藥","(D) 成藥係原料藥加工調製而成"],"answer":0,"image":""},{"id":"ph6-110-1-19","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"110年第1次第19題","year":110,"session":1,"number":19,"question":"下列何者非屬病人使用藥品有關「知的權利」？","options":["(A) 釋出處方箋","(B) 藥師學經歷","(C) 藥師用藥諮詢","(D) 藥品標示賦形劑成分"],"answer":1,"image":""},{"id":"ph6-110-1-20","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"110年第1次第20題","year":110,"session":1,"number":20,"question":"下列有關偽藥之敘述，何者錯誤？","options":["(A) 舉發偽藥經緝獲者應予獎勵，相關獎金由衛生福利部食品藥物管理署統一核發","(B) 製造偽藥，因而致人於死者，處無期徒刑或十年以上有期徒刑","(C) 明知為偽藥而調劑者，處七年以下有期徒刑","(D) 明知為偽藥而販賣之藥師，應由藥師公會或主管機關移付懲戒"],"answer":0,"image":""},{"id":"ph6-110-1-21","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"110年第1次第21題","year":110,"session":1,"number":21,"question":"下列何者非屬藥事法所定西藥專利連結所規範之藥品專利權？","options":["(A) 物質","(B) 組合物或配方","(C) 醫藥用途","(D) 新製程"],"answer":3,"image":""},{"id":"ph6-110-1-22","subject":"ph6","topic":"藥事法規-管制藥品與毒品危害防制","meta":"110年第1次第22題","year":110,"session":1,"number":22,"question":"下列有關管制藥品之敘述，何者錯誤？","options":["(A) 管制藥品依其習慣性、依賴性、濫用性及社會危害性之程度，分四級管理","(B) Stilnox及Methadone需依管制藥品專用處方箋調劑","(C) 獸醫師應領有衛生福利部食品藥物管理署核發之管制藥品使用執照，方得使用第一級至第三級管制藥品","(D) 管制藥品處方箋應保存五年"],"answer":1,"image":""},{"id":"ph6-110-1-23","subject":"ph6","topic":"藥事法規-新藥臨床試驗與安全監視","meta":"110年第1次第23題","year":110,"session":1,"number":23,"question":"依藥品優良臨床試驗準則之規定，執行臨床試驗應符合下列何者之倫理原則？","options":["(A) 赫爾辛基宣言","(B) 史特拉斯堡宣言","(C) 牛津宣言","(D) 匹茲堡宣言"],"answer":0,"image":""},{"id":"ph6-110-1-24","subject":"ph6","topic":"藥事法規-醫療器材管理法","meta":"110年第1次第24題","year":110,"session":1,"number":24,"question":"下列有關醫療器材管理之規定，何者錯誤？","options":["(A) 製造、輸入醫療器材，應向中央衛生主管機關申請查驗登記，經核准發給醫療器材許可證後，始得製造或輸入","(B) 辦理醫療器材查驗登記，應檢附申請者之藥商許可執照影本","(C) 經核准製造或輸入之醫療器材，中央衛生主管機關得指定期間，監視其安全性","(D) 對於因醫療器材所引起之任何不良反應，醫療機構、藥局或藥商皆應行通報"],"answer":3,"image":""},{"id":"ph6-110-1-25","subject":"ph6","topic":"藥事法規-醫療器材管理法","meta":"110年第1次第25題","year":110,"session":1,"number":25,"question":"依藥物製造業者檢查辦法之規定，下列何者錯誤？","options":["(A) 國產醫療器材製造業者，每三年檢查一次","(B) 輸入醫療器材國外製造業者，每三年檢查一次","(C) 輸入醫療器材國外製造業者，應由我國代理商（藥商）於其國外製造業者之醫療器材製造許可有效期間屆滿三個月前，主動提出檢查申請","(D) 中央衛生主管機關於發現醫療器材有重大危害之情事者，得另實施不定期檢查"],"answer":2,"image":""},{"id":"ph6-110-1-26","subject":"ph6","topic":"藥事法規-醫療器材管理法","meta":"110年第1次第26題","year":110,"session":1,"number":26,"question":"依據藥事法之規定，下列何種醫療器材輸入時，應抽查、檢驗合格後，始得輸入？","options":["(A) 骨內植體","(B) 衛生套","(C) 衛生棉條","(D) 隱形眼鏡"],"answer":1,"image":""},{"id":"ph6-110-1-27","subject":"ph6","topic":"藥事法規-藥師法與執業管理","meta":"110年第1次第27題","year":110,"session":1,"number":27,"question":"小明打算開一家藥局，他必須具備多少時間之實際調劑執業經驗才能擔任藥局負責人？","options":["(A) 6個月","(B) 1年","(C) 18個月","(D) 2年"],"answer":3,"image":""},{"id":"ph6-110-1-28","subject":"ph6","topic":"藥事法規-藥害救濟與罕見疾病","meta":"110年第1次第28題","year":110,"session":1,"number":28,"question":"嚴重藥物不良反應通報辦法所稱之嚴重藥物不良反應，不包括下列何者？","options":["(A) 死亡","(B) 危及生命","(C) 造成永久性殘疾","(D) 導致病人住院費用增加"],"answer":3,"image":""},{"id":"ph6-110-1-29","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"110年第1次第29題","year":110,"session":1,"number":29,"question":"美國曾發生多起血液透析病人，使用遭over sulfated chondroitin sulfate（OSCS）污染之肝素鈉致死。身為藥師，您認為下列何種做法正確？","options":["(A) 應憑原廠合格檢驗報告，方可用於製造藥物產品","(B) 經拉曼光譜分析法之邊境檢查通過後，才能確認不含OSCS","(C) 製藥廠應每年執行產品虐待試驗，確認產品不受OSCS污染","(D) 藥物製造前，應檢測並確認每批進廠粗肝素物種來源"],"answer":3,"image":""},{"id":"ph6-110-1-30","subject":"ph6","topic":"藥事法規-新藥臨床試驗與安全監視","meta":"110年第1次第30題","year":110,"session":1,"number":30,"question":"依藥事法之規定，有關從事後天免疫缺乏症候群（AIDS）疫苗研發及製造供臨床試驗使用，下列敘述何者錯誤？","options":["(A) 研發用疫苗應於符合中央衛生主管機關規定之場所製造","(B) 該公司申請AIDS病歷研究計畫時，人體試驗審議會得以簡易審查方式審核","(C) 該研發用疫苗非經中央衛生主管機關許可，不得委託他廠製造","(D) 該疫苗製造場所非經中央衛生主管機關許可，不得兼製其他產品"],"answer":1,"image":""},{"id":"ph6-110-1-31","subject":"ph6","topic":"藥事法規-藥物廣告與稽查","meta":"110年第1次第31題","year":110,"session":1,"number":31,"question":"某食品之宣傳單，載有「有清熱退火、祛傷解鬱、涼血固肺、開中氣之效果，有藥王之喻，能防止細胞老化、預防癌症、糖尿病、心臟病，特價80元」等文字，下列敘述何者錯誤？","options":["(A) 清熱退火、祛傷解鬱、涼血固肺、開中氣，為療效之宣稱","(B) 預防癌症、糖尿病及心臟病，為療效之宣稱","(C) 食品宣稱特價80元，非屬藥物廣告管理範疇","(D) 本案宣傳單應事前向主管機關申請藥品廣告"],"answer":3,"image":""},{"id":"ph6-110-1-32","subject":"ph6","topic":"藥事法規-藥物廣告與稽查","meta":"110年第1次第32題","year":110,"session":1,"number":32,"question":"某化粧品宣稱可治療褥瘡，係違反藥事法之下列何規定？","options":["(A) 未申請藥物廣告","(B) 非藥物不得宣稱療效","(C) 未向傳播業者送驗核准文件","(D) 未取得藥物製造許可"],"answer":1,"image":""},{"id":"ph6-110-1-33","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"110年第1次第33題","year":110,"session":1,"number":33,"question":"藥品應於下列何處製造？","options":["(A) 通過藥品優良調劑作業規範之藥品調製中心","(B) 領有藥品製造許可之藥品製造工廠","(C) 具有符合藥品優良實驗室操作規範之藥商","(D) 通過藥品優良臨床試驗準則之醫院"],"answer":1,"image":""},{"id":"ph6-110-1-34","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"110年第1次第34題","year":110,"session":1,"number":34,"question":"依藥事法之規定，下列事項那些正確？①西藥販賣業者之藥品及其買賣，應由專任藥師駐店管理 ②藥商僱用之推銷員，應向當地之直轄市、縣（市）衛生主管機關登記後，方准執行推銷工作 ③藥局兼營藥品零售業務，應適用關於藥商之規定請領藥商許可執照 ④以西藥劑型製造中藥之中藥製造業者，應由專任中醫師駐廠監製","options":["(A) ①③","(B) ②③","(C) ①②","(D) ②④"],"answer":2,"image":""},{"id":"ph6-110-1-35","subject":"ph6","topic":"藥事法規-藥師法與執業管理","meta":"110年第1次第35題","year":110,"session":1,"number":35,"question":"下列何者不屬於藥事法之管理範疇？","options":["(A) 藥物製造及販賣","(B) 藥物查驗登記","(C) 藥師執業登記","(D) 藥商管理"],"answer":2,"image":""},{"id":"ph6-110-1-36","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"110年第1次第36題","year":110,"session":1,"number":36,"question":"主管機關於109年6月10日稽查發現某藥品之有效期間由109年6月15日塗改為109年9月15日，依藥事法之規定，該藥品係屬下列何者？","options":["(A) 偽藥","(B) 劣藥","(C) 禁藥","(D) 不良藥品"],"answer":0,"image":""},{"id":"ph6-110-1-37","subject":"ph6","topic":"藥事法規-管制藥品與毒品危害防制","meta":"110年第1次第37題","year":110,"session":1,"number":37,"question":"依管制藥品管理條例之規定，下列敘述何者錯誤？","options":["(A) 藥劑生得調劑不含麻醉藥品之管制藥品","(B) 藥師交付第一級至第三級管制藥品時，應由領受人憑身分證明簽名領受","(C) 藥師調劑第一級、第二級管制藥品專用處方箋，以調劑一次為限","(D) 醫師、牙醫師如需使用管制藥品時，即應開立管制藥品專用處方箋"],"answer":3,"image":""},{"id":"ph6-110-1-38","subject":"ph6","topic":"藥事法規-管制藥品與毒品危害防制","meta":"110年第1次第38題","year":110,"session":1,"number":38,"question":"管制藥品管理條例所規定之簿冊、單據及管制藥品專用處方箋，均應保存幾年？","options":["(A) 3","(B) 5","(C) 7","(D) 永久保存"],"answer":1,"image":""},{"id":"ph6-110-1-39","subject":"ph6","topic":"藥事法規-管制藥品與毒品危害防制","meta":"110年第1次第39題","year":110,"session":1,"number":39,"question":"每毫升含安非他命1.0毫克以下，包裝1.0毫升以下，且經放射物質、抗原、抗體標幟，並以有機溶劑配製非用於人體之檢驗試劑，係屬下列何者？","options":["(A) 非管制藥品或毒品","(B) 第一級管制藥品","(C) 第二級毒品及管制藥品","(D) 藥事法所稱之禁藥"],"answer":0,"image":""},{"id":"ph6-110-1-40","subject":"ph6","topic":"藥事法規-管制藥品與毒品危害防制","meta":"110年第1次第40題","year":110,"session":1,"number":40,"question":"某注射海洛因之毒犯，接受替代療法戒毒，發現已染有愛滋病。下列敘述何者正確？","options":["(A) 因愛滋病接受替代療法所需醫療費用，全數由衛生福利部負擔","(B) 目前核准替代療法之藥品有methadone、buprenorphine、fentanyl三種，其中fentanyl為貼片劑型","(C) 若採用buprenorphine HCl/naloxone複方，則使用注射法給藥，其優點係naloxone可迅速發揮戒癮效果","(D) 替代療法屬高風險特殊臨床醫療，應先簽署受試者同意書後方可執行"],"answer":0,"image":""},{"id":"ph6-110-1-41","subject":"ph6","topic":"藥事法規-化粧品衛生安全管理法","meta":"110年第1次第41題","year":110,"session":1,"number":41,"question":"依化粧品衛生安全管理法之規定，某廠商在國內申請設立化粧品製造工廠，下列敘述何者錯誤？","options":["(A) 經中央機關公告者，應完成工廠登記","(B) 應符合化粧品製造工廠設廠標準","(C) 所有化粧種類之製造場所，皆須符合化粧品優良製造準則","(D) 應聘請藥師或具化粧品專業技術人員駐廠監督調配製造"],"answer":2,"image":""},{"id":"ph6-110-1-42","subject":"ph6","topic":"藥事法規-化粧品衛生安全管理法","meta":"110年第1次第42題","year":110,"session":1,"number":42,"question":"依化粧品衛生安全管理法之規定，下列有關化粧品廣告之敘述，何者正確？","options":["(A) 不論是刊載產品資訊或實質廣告，均應事前申請核准，始得廣告","(B) 化粧品廣告不得有虛偽或誇大之情事","(C) 特定化粧品須辦理廣告申請","(D) 化粧品廣告內容暗示或影射醫療效能者，應視為藥物廣告"],"answer":1,"image":""},{"id":"ph6-110-1-43","subject":"ph6","topic":"藥事法規-藥害救濟與罕見疾病","meta":"110年第1次第43題","year":110,"session":1,"number":43,"question":"下列何者為我國提供罕見疾病病人特殊營養品補助之具體作法？","options":["(A) 建立通報平台，納入所有特殊營養品為緊急健康食品","(B) 罕見疾病病人特殊營養品全額編列為健保給付","(C) 成立特殊營養食品暨藥品物流中心","(D) 訂定罕見疾病個案檢體檢查快速審查原則"],"answer":2,"image":""},{"id":"ph6-110-1-44","subject":"ph6","topic":"藥事法規-藥害救濟與罕見疾病","meta":"110年第1次第44題","year":110,"session":1,"number":44,"question":"下列何者係政府捐助成立財團法人藥害救濟基金會之宗旨？","options":["(A) 落實醫藥分業與專業分工","(B) 建立藥品來源及流向追溯追蹤系統","(C) 提升市售藥品品質監測效率","(D) 使正當使用合法藥物而受害者，獲得及時救濟"],"answer":3,"image":""},{"id":"ph6-110-1-45","subject":"ph6","topic":"藥事法規-藥害救濟與罕見疾病","meta":"110年第1次第45題","year":110,"session":1,"number":45,"question":"罕見疾病防治及藥物法制定之目的不包括下列何者？","options":["(A) 防治罕見疾病之發生","(B) 協助病人取得罕見疾病適用藥物","(C) 協助病人取得所食用之健康食品","(D) 保障罕見疾病藥物之供應"],"answer":2,"image":""},{"id":"ph6-110-1-46","subject":"ph6","topic":"藥事法規-全民健康保險與藥事作業","meta":"110年第1次第46題","year":110,"session":1,"number":46,"question":"下列有關全民健保處方箋調劑之敘述，何者錯誤？","options":["(A) 持慢性病連續處方箋，且所在地無特約藥局，無法至原處方醫院、診所調劑，得至其他特約醫院或衛生所調劑","(B) 接受全民健康保險居家照護服務，經醫師開立第一級或第二級管制藥品處方箋，無法至原處方醫院、診所調劑，得至其他特約醫院或衛生所調劑","(C) 醫師交付慢性病連續處方箋及管制藥品專用處方箋，保險對象應同時併持於同一調劑處所調劑","(D) 矯正機關之收容對象，得由家屬持健保卡及處方箋至全民健康保險特約藥局或任何特約醫院、診所調劑領藥"],"answer":3,"image":""},{"id":"ph6-110-1-47","subject":"ph6","topic":"藥事法規-全民健康保險與藥事作業","meta":"110年第1次第47題","year":110,"session":1,"number":47,"question":"全民健康保險法之主管機關為：","options":["(A) 衛生福利部","(B) 全民健康保險會","(C) 衛生福利部中央健康保險署","(D) 衛生福利部國民健康署"],"answer":0,"image":""},{"id":"ph6-110-1-48","subject":"ph6","topic":"藥事法規-全民健康保險與藥事作業","meta":"110年第1次第48題","year":110,"session":1,"number":48,"question":"依全民健康保險藥物給付項目及支付標準之規定，新藥列入價量協議之條件，係廠商財務預估於給付後五年間有任何一年之藥費支出高於新臺幣多少金額？","options":["(A) 1億元","(B) 2億元","(C) 5億元","(D) 10億元"],"answer":1,"image":""},{"id":"ph6-110-1-49","subject":"ph6","topic":"藥事法規-全民健康保險與藥事作業","meta":"110年第1次第49題","year":110,"session":1,"number":49,"question":"下列有關全民健康保險調整藥品支付價格之處理原則，何者錯誤？","options":["(A) 逾專利期五年內之藥品，每年檢討一次","(B) 進行藥價調整時，不得對藥品訂定基本價及下限價","(C) 專利期內之藥品，每二年調整一次","(D) 罕見疾病用藥每二年檢討調整"],"answer":1,"image":""},{"id":"ph6-110-1-50","subject":"ph6","topic":"藥事法規-全民健康保險與藥事作業","meta":"110年第1次第50題","year":110,"session":1,"number":50,"question":"依全民健康保險醫事服務機構特約及管理辦法之規定，保險特約藥局有下列何項情事者，應予終止特約？","options":["(A) 受衛生主管機關停業處分","(B) 超過合理調劑量不予支付藥費及藥事服務費者","(C) 遷址至他縣市者","(D) 對衛生福利部中央健康保險署負有債務未結清，且不同意於應支付之醫療費用中扣抵者"],"answer":2,"image":""},{"id":"ph6-110-2-1","subject":"ph6","topic":"藥事法規-藥政管理組織與衛生行政","meta":"110年第2次第1題","year":110,"session":2,"number":1,"question":"依據食品藥物管理署組織法之規定，下列何者不屬食品藥物管理署之掌理事項？","options":["(A) 食品藥物化粧品消費者保護措施之推動","(B) 管制藥品之稽核、通報、預警、教育宣導","(C) 第一級、第二級管制藥品之輸入、輸出、製造及販賣","(D) 中醫藥管理政策之規劃與執行及相關法規之研擬"],"answer":3,"image":""},{"id":"ph6-110-2-2","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"110年第2次第2題","year":110,"session":2,"number":2,"question":"藥廠製造之藥品，經稽查已超過有效期間，下列敘述何者錯誤？","options":["(A) 業者應即通知醫療機構、藥局及藥商，依規定回收市售品","(B) 藥廠回收藥品時，醫療機構、藥局及藥商應予配合","(C) 業者依規定期限收回市售品，庫存品應一併處理","(D) 藥廠之回收作業應依地方衛生主管機關訂定之辦法處理"],"answer":3,"image":""},{"id":"ph6-110-2-3","subject":"ph6","topic":"藥事法規-藥政管理組織與衛生行政","meta":"110年第2次第3題","year":110,"session":2,"number":3,"question":"下列藥物、化粧品查驗登記業務之受理單位，何者錯誤？","options":["(A) 化粧品查驗登記申請案，由衛生福利部食品藥物管理署醫療器材及化粧品組受理","(B) 醫療器材查驗登記申請案，由衛生福利部食品藥物管理署醫療器材及化粧品組受理","(C) 西藥製劑查驗登記申請案，由衛生福利部食品藥物管理署藥品組受理","(D) 中藥製劑查驗登記申請案，由衛生福利部中醫藥司受理，屬西藥劑型之中藥產品，則由食品藥物管理署藥品組受理"],"answer":3,"image":""},{"id":"ph6-110-2-4","subject":"ph6","topic":"藥事法規-藥害救濟與罕見疾病","meta":"110年第2次第4題","year":110,"session":2,"number":4,"question":"依主管機關之公告，目前下列何項產品發生藥害事件，得申請藥害救濟？","options":["(A) 含藥化粧品","(B) 驗孕棒","(C) 感冒糖漿","(D) 加味逍遙散"],"answer":2,"image":""},{"id":"ph6-110-2-5","subject":"ph6","topic":"藥事法規-藥政管理組織與衛生行政","meta":"110年第2次第5題","year":110,"session":2,"number":5,"question":"中藥（材）、植物性藥材之管理，係由下列何者掌理？","options":["(A) 衛生福利部食品藥物管理署","(B) 衛生福利部國家中醫藥研究所","(C) 衛生福利部中醫藥司","(D) 製造廠所在地衛生局"],"answer":2,"image":""},{"id":"ph6-110-2-6","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"110年第2次第6題","year":110,"session":2,"number":6,"question":"下列有關藥政管理之敘述，何者正確？","options":["(A) 西藥藥品製造工廠目前尚未全面實施西藥優良運銷準則（GDP）","(B) 製劑使用之原料藥應符合藥品GMP，但無須登錄來源","(C) 經中央衛生主管機關公告類別之藥品，其販賣業者或製造業者，應依其產業模式建立藥品來源及流向之追溯或追蹤系統","(D) 國內醫療器材及化粧品製造廠，已全面納入GMP管理"],"answer":2,"image":""},{"id":"ph6-110-2-7","subject":"ph6","topic":"藥事法規-藥師法與執業管理","meta":"110年第2次第7題","year":110,"session":2,"number":7,"question":"藥師執行調劑業務時，下列敘述何者錯誤？","options":["(A) 因調劑業務而知悉他人之秘密，不得無故洩漏","(B) 藥品未備或缺乏時，得代以他藥","(C) 藥局標示為日夜調劑者，其藥師應日夜為之","(D) 藥師應按處方內容調劑，不得錯誤"],"answer":1,"image":""},{"id":"ph6-110-2-8","subject":"ph6","topic":"藥事法規-藥師法與執業管理","meta":"110年第2次第8題","year":110,"session":2,"number":8,"question":"依藥師法之規定，藥師交付藥劑時，應於容器或包裝上記明之事項，下列何者正確？","options":["(A) 調劑藥師及處方醫師姓名","(B) 藥品外觀、標記","(C) 藥品名稱、劑量、數量、用法","(D) 藥品廠牌名稱"],"answer":2,"image":""},{"id":"ph6-110-2-9","subject":"ph6","topic":"藥事法規-藥師法與執業管理","meta":"110年第2次第9題","year":110,"session":2,"number":9,"question":"下列有關藥師法所稱藥事照護，何者正確？","options":["(A) 於全國反毒種子營，講授濫用藥物作用機轉，並接受藥物諮詢工作","(B) 參與衛生福利部長照計畫之用藥諮詢及藥物治療流程評估","(C) 擔任藥學院用藥諮詢及藥物治療流程評估教學服務","(D) 擔任藥師公會用藥諮詢及給藥流程評估教學服務"],"answer":1,"image":""},{"id":"ph6-110-2-10","subject":"ph6","topic":"藥事法規-藥師法與執業管理","meta":"110年第2次第10題","year":110,"session":2,"number":10,"question":"依藥師法之規定，下列敘述何者錯誤？","options":["(A) 藥師對於醫師所開處方，祇許調劑一次，其處方箋應於調劑後簽名蓋章，添記調劑年、月、日，保存三年，含有麻醉或毒劇藥品者保存五年","(B) 藥師受理處方，應注意處方上年、月、日、病人姓名、性別、年齡、藥名、劑量、用法、醫師署名或蓋章等項","(C) 負責主持經營藥局之藥師，應具備一年以上實際調劑執業經驗，始得提供藥品調劑服務","(D) 藥師受理處方，如有可疑之點，應詢明原處方醫師確認後方得調劑"],"answer":2,"image":""},{"id":"ph6-110-2-11","subject":"ph6","topic":"藥事法規-藥師法與執業管理","meta":"110年第2次第11題","year":110,"session":2,"number":11,"question":"下列何者非屬藥師法所定事先報准，方得於執業處所外執行之業務？","options":["(A) 至護理機構執行藥事照護相關業務","(B) 至矯正機關執行調劑業務","(C) 藥癮治療","(D) 至藥品販賣業管理藥品"],"answer":3,"image":""},{"id":"ph6-110-2-12","subject":"ph6","topic":"藥事法規-藥師法與執業管理","meta":"110年第2次第12題","year":110,"session":2,"number":12,"question":"下列有關藥師繼續教育之規定，何者錯誤？","options":["(A) 藥師執業，每六年應完成繼續教育120點之積分數","(B) 在醫學院及藥學專科未修習滿中藥17學分，可利用每年繼續教育補足中藥課程標準所需學分，從事中藥調劑業務","(C) 應接受之課程內容包括專業課程、專業品質、專業倫理、專業相關法規等","(D) 應依醫事人員執業登記及繼續教育辦法之規定辦理"],"answer":1,"image":""},{"id":"ph6-110-2-13","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"110年第2次第13題","year":110,"session":2,"number":13,"question":"下列有關藥局及藥粧店之敘述，何者錯誤？","options":["(A) 藥粧店屬藥商，為藥品或醫療器材零售販賣業者，並無調劑業務","(B) 藥局依法執行調劑業務，得兼營藥品及一定等級醫療器材之零售業務","(C) 藥局及取得藥商許可執照之藥粧店皆可販賣西藥成藥、中藥成藥及一定等級醫療器材","(D) 藥局負責人須由藥師親自主持；藥粧店負責人不必為藥師，藥師不必親自駐店"],"answer":3,"image":""},{"id":"ph6-110-2-14","subject":"ph6","topic":"藥事法規-藥師法與執業管理","meta":"110年第2次第14題","year":110,"session":2,"number":14,"question":"某藥局登記有3名藥事人員執業，但主持藥師登記後即長年居住香港執業，依藥師法之規定，該主持藥師違反下列何項規定？","options":["(A) 藥師執業以一處為限","(B) 藥師執行調劑業務，非有正當理由，不得拒絕為調劑","(C) 藥師應親自主持其所經營之藥局業務","(D) 負責主持經營藥局之藥師，應具備2年以上實際調劑執業經驗"],"answer":2,"image":""},{"id":"ph6-110-2-15","subject":"ph6","topic":"調劑學-處方判讀與調劑作業","meta":"110年第2次第15題","year":110,"session":2,"number":15,"question":"依藥品優良調劑作業準則之規定，藥事人員受理處方後，應確認之處方內容，包括下列那些？①病患姓名 ②病患年齡 ③病患性別 ④病患體重 ⑤處方醫師姓名 ⑥處方醫師執照號碼 ⑦處方醫師科別 ⑧藥品劑型","options":["(A) ②③④⑤⑥","(B) ①③④⑦⑧","(C) ①②③⑤⑧","(D) ①②④⑥⑦"],"answer":2,"image":""},{"id":"ph6-110-2-16","subject":"ph6","topic":"藥事法規-藥師法與執業管理","meta":"110年第2次第16題","year":110,"session":2,"number":16,"question":"有關藥劑生之業務，下列敘述何者正確？","options":["(A) 執行麻醉藥品販賣業務，須事先向主管機關申請許可","(B) 在醫院執行所有藥品之調劑業務","(C) 執行得由藥劑生執行之給藥流程評估","(D) 需在藥師監督下執行麻醉藥品之調劑"],"answer":2,"image":""},{"id":"ph6-110-2-17","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"110年第2次第17題","year":110,"session":2,"number":17,"question":"依藥事法之規定，下列何者為不良醫療器材？","options":["(A) 使用時易生危險，或可損傷人體，或使診斷發生錯誤者","(B) 經中央衛生主管機關公告列入安全監視者","(C) 未經核准，擅自製造、輸入者","(D) 許可證到期未申請展延者"],"answer":0,"image":""},{"id":"ph6-110-2-18","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"110年第2次第18題","year":110,"session":2,"number":18,"question":"依藥事法之規定，製造或輸入偽禁藥之處罰，下列何者正確？","options":["(A) 處十年以下有期徒刑，得併科新臺幣一億元以下罰金","(B) 致重傷者，處無期徒刑或十年以上有期徒刑，得併科新臺幣二億元以下罰金","(C) 處七年以下有期徒刑，得併科新臺幣五千萬元以下罰金","(D) 處一年以上七年以下有期徒刑，得併科新臺幣四百五十萬元以下罰金"],"answer":0,"image":""},{"id":"ph6-110-2-19","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"110年第2次第19題","year":110,"session":2,"number":19,"question":"依藥事法之規定，下列有關藥品分裝定義之敘述，何者正確？","options":["(A) 係指依處方箋內容選取正確藥品及數量，依種類分別裝入藥袋","(B) 係指受理處方，將藥品調配後作成餐包頓服，裝入藥袋，交付給病人","(C) 係指藥品販賣業者輸入藥品製劑，申請中央衛生主管機關核准後，由符合藥品優良製造規範之藥品製造業者所作之分裝","(D) 係指依醫師所開處方箋內容，改變劑型或配製新製品後之重新包裝"],"answer":2,"image":""},{"id":"ph6-110-2-20","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"110年第2次第20題","year":110,"session":2,"number":20,"question":"106年3月發生冠脂妥Crestor偽藥事件，下列敘述何者錯誤？","options":["(A) 醫院可以將冠脂妥Crestor正品出售給藥局","(B) 藥師明知冠脂妥Crestor偽藥而為調劑，可處七年以下有期徒刑","(C) 藥局應向有藥商許可執照者購買冠脂妥Crestor藥品，並取得進貨憑證以證明進貨來源管道","(D) 若病患發現冠脂妥Crestor不足使用，持其外盒到藥局證明醫師開過，藥局也不可以出售"],"answer":0,"image":""},{"id":"ph6-110-2-21","subject":"ph6","topic":"藥事法規-新藥臨床試驗與安全監視","meta":"110年第2次第21題","year":110,"session":2,"number":21,"question":"下列有關藥品臨床試驗之敘述，何者正確？","options":["(A) 第一期臨床試驗性質屬療效確認的樞紐試驗","(B) 軍人受試者屬易受傷害族群，但可不須額外保護措施","(C) 主要療效指標若發現無統計學意義，則以次要療效指標取代","(D) 在臨床試驗階段仍可進行製程最適化研究"],"answer":3,"image":""},{"id":"ph6-110-2-22","subject":"ph6","topic":"藥事法規-新藥臨床試驗與安全監視","meta":"110年第2次第22題","year":110,"session":2,"number":22,"question":"某醫學院學生擬參與學名藥之生體相等性試驗，下列敘述何者正確？","options":["(A) 學名藥已非新藥，其生體相等性試驗不屬於人體試驗範圍","(B) 若該學生未成年，則參與試驗前僅須由本人簽署受試者同意書","(C) 生體相等性試驗設計，可為平行設計或交叉設計","(D) 若試驗中發生危及生命之嚴重不良反應，計畫主持人須立即通報衛生福利部"],"answer":2,"image":""},{"id":"ph6-110-2-23","subject":"ph6","topic":"藥事法規-醫療器材管理法","meta":"110年第2次第23題","year":110,"session":2,"number":23,"question":"下列何者非屬申請輸入第二等級或第三等級醫療器材查驗登記應檢附之資料？","options":["(A) 產品之結構、材料、規格、性能、用途、圖樣等有關資料","(B) 仿單目錄、使用說明書及其詳細中文譯稿、包裝、標籤及產品實際外觀彩色圖片","(C) 醫療器材製造業藥商許可執照影本","(D) 出產國許可製售證明正本"],"answer":2,"image":""},{"id":"ph6-110-2-24","subject":"ph6","topic":"藥事法規-醫療器材管理法","meta":"110年第2次第24題","year":110,"session":2,"number":24,"question":"製造業者對於臨床試驗用醫療器材之批次製造紀錄，應於臨床試驗完成後或於產品完成後保存至少幾年，二者以期間較長者為準？","options":["(A) 1","(B) 2","(C) 3","(D) 5"],"answer":1,"image":""},{"id":"ph6-110-2-25","subject":"ph6","topic":"藥事法規-醫療器材管理法","meta":"110年第2次第25題","year":110,"session":2,"number":25,"question":"下列有關醫療器材臨床試驗之敘述，何者正確？","options":["(A) 申請查驗登記之醫療器材如係為第一等級者，應檢附臨床試驗報告","(B) 申請查驗登記之醫療器材如係為第二等級且無類似品經中央衛生主管機關核准上市者，均免附臨床試驗報告","(C) 申請第二等級或第三等級醫療器材查驗登記，應否在國內進行臨床試驗，另由中央衛生主管機關視申請之醫療器材品項、個案及申請人檢送之資料核辦或公告","(D) 試驗用醫療器材，應經中央衛生主管機關核准始得供經核可之區域醫院臨床試驗，以確認其安全與醫療效能"],"answer":2,"image":""},{"id":"ph6-110-2-26","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"110年第2次第26題","year":110,"session":2,"number":26,"question":"依藥事法之規定，只有在下列何種情況下，醫師得親自為藥品之調劑？","options":["(A) 經病人簽署同意書","(B) 1.5公里內有健保特約藥局之診所","(C) 藥師請假時","(D) 醫療急迫情形"],"answer":3,"image":""},{"id":"ph6-110-2-27","subject":"ph6","topic":"藥事法規-新藥臨床試驗與安全監視","meta":"110年第2次第27題","year":110,"session":2,"number":27,"question":"下列有關藥物安全監視及嚴重藥物不良反應系統之敘述，何者錯誤？","options":["(A) 監視期間應蒐集國內、外藥物使用之安全資料","(B) 衛生福利部公告指定之醫療器材安全監視期間自發證日起5年","(C) 嚴重藥物不良反應通報系統是藥物安全監視主要的資訊來源","(D) 健全嚴重藥物不良反應通報系統，可保障民眾用藥安全"],"answer":1,"image":""},{"id":"ph6-110-2-28","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"110年第2次第28題","year":110,"session":2,"number":28,"question":"下列有關藥廠製造廠房設施之敘述，何者錯誤？","options":["(A) 青黴素應有專用且自足圍堵設施","(B) 休息室與餐廳應與其他區域隔離","(C) 動物室若與其他區共用出入口，須管制動物出入時間","(D) 廁所與儲存區不得直接相通"],"answer":2,"image":""},{"id":"ph6-110-2-29","subject":"ph6","topic":"藥事法規-藥物廣告與稽查","meta":"110年第2次第29題","year":110,"session":2,"number":29,"question":"下列有關藥物廣告之規定，何者正確？","options":["(A) 藥品廣告之申請限由藥品製造廠或輸入業者提出","(B) 醫療器材廣告限由醫療器材製造廠或輸入業者提出申請","(C) 藥物廣告應將廠商名稱、藥物許可證及廣告核准字號一併登載或宣播","(D) 中藥製劑之廣告所用文字，其效能應以本草綱目所載者為限"],"answer":2,"image":""},{"id":"ph6-110-2-30","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"110年第2次第30題","year":110,"session":2,"number":30,"question":"依藥事法之規定，下列何者必須聘藥師駐廠監製？","options":["(A) 濃縮中藥製造業者","(B) 血壓計製造業者","(C) 隱形眼鏡鏡片消毒藥水製造業者","(D) 化粧品製造業者"],"answer":2,"image":""},{"id":"ph6-110-2-31","subject":"ph6","topic":"藥事法規-藥師法與執業管理","meta":"110年第2次第31題","year":110,"session":2,"number":31,"question":"下列有關藥師懲戒之敘述，何者錯誤？","options":["(A) 藥師業務上重大過失行為，得由藥師公會移付懲戒","(B) 藥師懲戒委員會之停業決議，應有委員二分之一以上親自出席，出席委員二分之一以上同意","(C) 藥師明知為偽藥而販賣者，得由主管機關移付懲戒","(D) 新北市衛生局應設藥師懲戒委員會，新北市政府應設藥師懲戒覆審委員會"],"answer":3,"image":""},{"id":"ph6-110-2-32","subject":"ph6","topic":"藥事法規-新藥臨床試驗與安全監視","meta":"110年第2次第32題","year":110,"session":2,"number":32,"question":"藥局之藥師發現所調劑之藥品於病人發生嚴重藥物不良反應，下列敘述何者錯誤？","options":["(A) 於緊急時，得先行以口頭方式通報，並應於期限內完成書面通報","(B) 發現危及病人生命，應在七日內通報中央衛生主管機關","(C) 發現病人可能導致永久性傷害需做處置，應在十五日內通報中央衛生主管機關","(D) 藥局得知病人死亡，除依法通報外，並應副知持有該藥品許可證之藥商"],"answer":2,"image":""},{"id":"ph6-110-2-33","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"110年第2次第33題","year":110,"session":2,"number":33,"question":"藥物之包裝、標籤、仿單經核准變更登記時，其製造或輸入之業者，應於核准變更之日起多少個月內，收回市售品，連同庫存品送經直轄市或縣（市）衛生主管機關驗章後，始得販賣？","options":["(A) 1","(B) 3","(C) 5","(D) 6"],"answer":3,"image":""},{"id":"ph6-110-2-34","subject":"ph6","topic":"藥事法規-新藥臨床試驗與安全監視","meta":"110年第2次第34題","year":110,"session":2,"number":34,"question":"藥事法第40條之2有關藥商申請查驗登記時引據資料之規定，係規範下列那一項新藥？","options":["(A) 所有新藥","(B) 新成分新藥","(C) 新劑型新藥","(D) 中藥以外之新藥"],"answer":1,"image":""},{"id":"ph6-110-2-35","subject":"ph6","topic":"藥事法規-藥物廣告與稽查","meta":"110年第2次第35題","year":110,"session":2,"number":35,"question":"下列有關藥事管理之敘述，何者錯誤？","options":["(A) 衛生主管機關派員檢查販售業者之處所設施，抽驗其藥物，需以原價抽取樣品","(B) 衛生主管機關派員檢查販售業者之處所設施及有關業務，業者不得無故拒絕","(C) 直轄市或縣（市）衛生主管機關應每年辦理藥商普查","(D) 醫療器材之效能變更，應先向中央衛生主管機關申請，經核准後始得變更"],"answer":0,"image":""},{"id":"ph6-110-2-36","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"110年第2次第36題","year":110,"session":2,"number":36,"question":"依藥事法之規定，藥廠經司法機關判決製造偽藥定讞，應為下列何處分？①廢止藥商許可執照 ②廢止全部藥物製造許可 ③廢止全部藥物許可證","options":["(A) 僅②","(B) 僅③","(C) 僅②③","(D) ①②③"],"answer":3,"image":""},{"id":"ph6-110-2-37","subject":"ph6","topic":"藥事法規-管制藥品與毒品危害防制","meta":"110年第2次第37題","year":110,"session":2,"number":37,"question":"領有管制藥品登記證之藥局申請歇業，其結存管制藥品之處理，下列何者正確？","options":["(A) 向當地衛生主管機關申請核准自行保管","(B) 由其管制藥品管理人會同有關人員銷燬","(C) 報請衛生福利部食品藥物管理署會同銷燬","(D) 轉讓予其他領有管制藥品登記證者"],"answer":3,"image":""},{"id":"ph6-110-2-38","subject":"ph6","topic":"藥事法規-管制藥品與毒品危害防制","meta":"110年第2次第38題","year":110,"session":2,"number":38,"question":"某藝人被查獲無正當理由施用硝甲西泮（nimetazepam），下列敘述何者正確？","options":["(A) 查獲之硝甲西泮，不問屬於藝人與否，均沒收銷燬之","(B) 檢察官應聲請法院裁定，令藝人先入勒戒處所觀察、勒戒","(C) 無正當理由持有或施用硝甲西泮者，應依違反管制藥品管理條例處分","(D) 除處以罰鍰外，並應限期令藝人接受四小時以上八小時以下之毒品危害講習"],"answer":3,"image":""},{"id":"ph6-110-2-39","subject":"ph6","topic":"藥事法規-管制藥品與毒品危害防制","meta":"110年第2次第39題","year":110,"session":2,"number":39,"question":"下列有關藥物濫用之敘述，何者正確？","options":["(A) 依非尿液檢體統計，新興濫用物質多為具中樞神經抑制作用之卡西酮類物質","(B) 合成卡西酮類物質檢體中，常檢出多種不同藥物混合濫用","(C) 新興濫用物質是由行政院依管制藥品及毒品之不同分級及品項進行審議，同時增修列管","(D) 施用mephedrone（俗稱喵喵）及MDPV（俗稱浴鹽）之人數逐年增加，皆已列第二級管制藥品管理"],"answer":1,"image":""},{"id":"ph6-110-2-40","subject":"ph6","topic":"藥事法規-管制藥品與毒品危害防制","meta":"110年第2次第40題","year":110,"session":2,"number":40,"question":"醫療機構擬使用第一級、第二級管制藥品，從事管制藥品成癮治療業務，應檢附治療計畫，向下列何者提出申請？","options":["(A) 衛生福利部心理及口腔健康司","(B) 衛生福利部食品藥物管理署","(C) 衛生福利部中央健康保險署","(D) 衛生福利部國民健康署"],"answer":1,"image":""},{"id":"ph6-110-2-41","subject":"ph6","topic":"藥事法規-化粧品衛生安全管理法","meta":"110年第2次第41題","year":110,"session":2,"number":41,"question":"依化粧品衛生安全管理法之規定，有關藥粧店販賣化粧品之規定，下列敘述何者正確？","options":["(A) 藥粧店不得擅自將化粧品之標籤、仿單、外包裝或容器等改變出售","(B) 藥粧店應領有特定用途化粧品許可證，始得販賣特定用途化粧品","(C) 藥粧店應聘專任藥師管理特定用途化粧品","(D) 藥粧店應領有化粧品販賣業許可執照"],"answer":0,"image":""},{"id":"ph6-110-2-42","subject":"ph6","topic":"藥事法規-化粧品衛生安全管理法","meta":"110年第2次第42題","year":110,"session":2,"number":42,"question":"依化粧品衛生安全管理法之規定，化粧品含有汞、鉛或其他經中央主管機關公告禁止使用之成分，下列對業者之處置何者錯誤？","options":["(A) 命其產品下架","(B) 產品予以封存","(C) 命限期回收市售產品","(D) 命其進行成分安全性評估"],"answer":3,"image":""},{"id":"ph6-110-2-43","subject":"ph6","topic":"藥事法規-藥害救濟與罕見疾病","meta":"110年第2次第43題","year":110,"session":2,"number":43,"question":"下列何者非為衛生福利部每年應編列年報或公告之法定業務？","options":["(A) 第一級管制藥品收支情形","(B) 罕見疾病藥物輸入廠GMP查核結果","(C) 第二級管制藥品現存品量","(D) 核准上市之罕見疾病藥物使用量"],"answer":1,"image":""},{"id":"ph6-110-2-44","subject":"ph6","topic":"藥事法規-藥害救濟與罕見疾病","meta":"110年第2次第44題","year":110,"session":2,"number":44,"question":"下列何者為衛生福利部補助罕見疾病居家醫療照護器材租賃費用所編列預算之來源？","options":["(A) 菸品健康福利捐分配收入","(B) 全民健康保險前一年度結餘款","(C) 醫療器材查驗登記收繳之規費","(D) 食品藥物管理署專案補助"],"answer":0,"image":""},{"id":"ph6-110-2-45","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"110年第2次第45題","year":110,"session":2,"number":45,"question":"下列何者非屬藥事法授權所制定之子法規？","options":["(A) 罕見疾病防治及藥物法施行細則","(B) 藥品優良臨床試驗作業準則","(C) 藥品生體可用率及生體相等性試驗準則","(D) 藥事法施行細則"],"answer":0,"image":""},{"id":"ph6-110-2-46","subject":"ph6","topic":"藥事法規-全民健康保險與藥事作業","meta":"110年第2次第46題","year":110,"session":2,"number":46,"question":"衛生福利部中央健康保險署自104年起擴大發展下列何種平台，增建過敏藥物紀錄等查詢系統，供醫師查詢？","options":["(A) 健保雲端藥歷系統","(B) 健保醫療資訊雲端查詢系統","(C) 健康存摺","(D) 全民健保行動快易通APP"],"answer":1,"image":""},{"id":"ph6-110-2-47","subject":"ph6","topic":"藥事法規-全民健康保險與藥事作業","meta":"110年第2次第47題","year":110,"session":2,"number":47,"question":"依全民健康保險法之規定，下列有關支付特約藥局處方調劑，何者錯誤？","options":["(A) 應依藥物給付項目及支付標準向保險人申報","(B) 相關費用之申報應自調劑之次月一日起六個月內為之","(C) 應向保險人申報藥品費用","(D) 應向保險人申報調劑之金額"],"answer":3,"image":""},{"id":"ph6-110-2-48","subject":"ph6","topic":"藥事法規-全民健康保險與藥事作業","meta":"110年第2次第48題","year":110,"session":2,"number":48,"question":"下列有關全民健康保險之敘述，何者錯誤？","options":["(A) 屬於全民納保之強制性社會保險制度","(B) 衛生福利部中央健康保險署為保險人","(C) 全民健康保險會審議健保相關爭議事項","(D) 全民健康保險以衛生福利部為主管機關"],"answer":2,"image":""},{"id":"ph6-110-2-49","subject":"ph6","topic":"藥事法規-全民健康保險與藥事作業","meta":"110年第2次第49題","year":110,"session":2,"number":49,"question":"甲藥師受聘於B健保特約藥局負責藥品調劑，於109年8月至12月赴美進修，此期間B藥局仍以甲藥師為調劑藥師向衛生福利部中央健康保險署申報藥事服務及藥品費用，依全民健康保險法之規定，下列處置何者錯誤？","options":["(A) 由衛生福利部處其領取醫療費用二倍至二十倍罰鍰","(B) 情節重大者，由衛生福利部中央健康保險署公告B藥局名稱","(C) 情節重大者，由衛生福利部中央健康保險署公告負責人姓名","(D) 得視其情節輕重，由衛生福利部中央健康保險署限定於一定期間不予特約或永不特約"],"answer":0,"image":""},{"id":"ph6-110-2-50","subject":"ph6","topic":"藥事法規-全民健康保險與藥事作業","meta":"110年第2次第50題","year":110,"session":2,"number":50,"question":"全民健康保險給付範圍之審議業務，係由下列何者辦理？","options":["(A) 行政院","(B) 衛生福利部","(C) 全民健康保險會","(D) 衛生福利部中央健康保險署"],"answer":2,"image":""},{"id":"ph6-111-1-1","subject":"ph6","topic":"藥事法規-藥政管理組織與衛生行政","meta":"111年第1次第1題","year":111,"session":1,"number":1,"question":"人用藥品、動物用藥品及環境用藥之法定主管機關分別為何？","options":["(A) 衛生福利部食品藥物管理署、衛生福利部疾病管制署、行政院環境保護署","(B) 衛生福利部食品藥物管理署、行政院農業委員會動植物防疫檢疫局、行政院環境保護署","(C) 衛生福利部食品藥物管理署、行政院農業委員會動植物防疫檢疫局、行政院農業委員會動植物防疫檢疫局","(D) 衛生福利部、行政院農業委員會、行政院環境保護署"],"answer":3,"image":""},{"id":"ph6-111-1-2","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"111年第1次第2題","year":111,"session":1,"number":2,"question":"依藥事法之規定，下列敘述何者正確？","options":["(A) 衛生主管機關得派員檢查藥局之有關業務，並得出具單據抽驗其藥物","(B) 地方衛生主管機關應每二年定期辦理藥商及藥局之普查","(C) 經許可製造之藥品，如發現有重大危害時，地方衛生主管機關應隨時公告禁止其製造","(D) 查獲核准輸入之不良醫療器材，由中央衛生主管機關責令進口商限期退運"],"answer":0,"image":""},{"id":"ph6-111-1-3","subject":"ph6","topic":"藥事法規-藥政管理組織與衛生行政","meta":"111年第1次第3題","year":111,"session":1,"number":3,"question":"下列有關我國藥政管理體系之敘述，何者正確？","options":["(A) 衛生福利部中醫藥司，負責中醫師及其政策之管理，衛生福利部食品藥物管理署藥品組負責中藥製劑及其法規管理","(B) 衛生福利部食品藥物管理署為直轄市、縣（市）政府藥政管理科（課）之上級機關","(C) 衛生福利部食品藥物管理署管制藥品管理組，負責管制藥品法規及其產品查驗登記之業務","(D) 財團法人藥害救濟基金會，為衛生福利部捐助成立，受委託辦理藥害救濟相關業務"],"answer":3,"image":""},{"id":"ph6-111-1-4","subject":"ph6","topic":"藥事法規-藥害救濟與罕見疾病","meta":"111年第1次第4題","year":111,"session":1,"number":4,"question":"依藥害救濟法之規定，下列敘述何者正確？","options":["(A) 在國外購買國內有許可證之藥品，發生藥害得申請藥害救濟","(B) 藥害救濟給付包括死亡給付、疾病給付及健保給付","(C) 藥害救濟之請求權，自請求權人知有藥害時起，因二年間不行使而消滅","(D) 常見且可預期之藥品不良反應不得申請藥害救濟"],"answer":3,"image":""},{"id":"ph6-111-1-5","subject":"ph6","topic":"藥事法規-藥政管理組織與衛生行政","meta":"111年第1次第5題","year":111,"session":1,"number":5,"question":"下列有關衛生福利部食品藥物管理署之組織職掌，何者錯誤？","options":["(A) 食品藥物化粧品之查驗登記、審核、給證、備查與藥物人體試驗之審查及監督","(B) 食品藥物化粧品之安全監視、危害事件調查及處理","(C) 毒品及其他物質成癮防治政策之規劃、推動及相關法規之研訂","(D) 食品藥物化粧品之檢驗、研究、實驗室認證、風險評估與風險管理及中藥、植物性藥材之檢驗"],"answer":2,"image":""},{"id":"ph6-111-1-6","subject":"ph6","topic":"臨床藥學-藥事照護與用藥評估","meta":"111年第1次第6題","year":111,"session":1,"number":6,"question":"為加強醫院醫療品質，達到提升用藥安全之工作目標，下列何者錯誤？","options":["(A) 推行病人用藥整合","(B) 落實用藥過敏及不良反應的傳遞","(C) 加強高警訊藥品及輸液幫浦的使用安全","(D) 落實採購法採購高品質藥品"],"answer":3,"image":""},{"id":"ph6-111-1-7","subject":"ph6","topic":"藥事法規-藥政管理組織與衛生行政","meta":"111年第1次第7題","year":111,"session":1,"number":7,"question":"下列何者為全國食安專線？","options":["(A) 113專線","(B) 1919專線","(C) 1922專線","(D) 1957專線"],"answer":1,"image":""},{"id":"ph6-111-1-8","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"111年第1次第8題","year":111,"session":1,"number":8,"question":"下列有關藥局經營之敘述，何者正確？","options":["(A) 為提升處方箋量，來店調劑處方即送贈品一份","(B) 為使不良於行之病人方便領藥，藥師可以親自送藥到轄區病人家中","(C) 依據病人到藥局所留下的電話資料，可以通知病人該藥局之藥品有包裝換獎活動","(D) 該藥局所聘之藥劑生，可協助藥品及麻醉藥品之處方調劑"],"answer":1,"image":""},{"id":"ph6-111-1-9","subject":"ph6","topic":"臨床藥學-藥事照護與用藥評估","meta":"111年第1次第9題","year":111,"session":1,"number":9,"question":"下列何者屬藥師法所定藥事照護相關業務？","options":["(A) 醫師處方藥品之調劑","(B) 第一級麻醉藥品之調劑","(C) 提供病患手術後，自控式麻醉藥品劑量諮詢之服務","(D) 醫院麻醉藥品流向管理業務"],"answer":2,"image":""},{"id":"ph6-111-1-10","subject":"ph6","topic":"藥事法規-藥師法與執業管理","meta":"111年第1次第10題","year":111,"session":1,"number":10,"question":"下列各項有關藥師之行為，何者錯誤？①依醫師處方進行調劑 ②零售指示用藥 ③藥局內藥品儲存及供應 ④發現處方藥品有交互作用建議醫師更改 ⑤建議病患購買Pulmicort turbuhaler，並指導正確用法 ⑥發現Inderal沒庫存，自行將處方更換為Tenormin","options":["(A) ①②④","(B) ①③⑥","(C) ⑤⑥","(D) ②⑥"],"answer":2,"image":""},{"id":"ph6-111-1-11","subject":"ph6","topic":"藥事法規-藥師法與執業管理","meta":"111年第1次第11題","year":111,"session":1,"number":11,"question":"某藥師同時具有中醫師資格，於醫院登記執行藥師業務1年，離職後晚上在診所登記執行藥師業務，白天自行在社區藥局執業達7個月，再離職後到藥妝店執業1年，下列敘述何者錯誤？","options":["(A) 白天在社區藥局晚上在診所執行藥師業務，已違反執業以一處為限之規定，可處3～15萬元以下罰鍰","(B) 執行藥師業務已超過2年，故有2年調劑資格","(C) 依規定辦理中醫師及藥師執業登記，得在同一執業處所執行各該業務","(D) 該藥師為西藥販賣業藥妝店之負責人，可以經營中藥成藥之販賣"],"answer":1,"image":""},{"id":"ph6-111-1-12","subject":"ph6","topic":"藥事法規-藥師法與執業管理","meta":"111年第1次第12題","year":111,"session":1,"number":12,"question":"依藥師法之規定，下列敘述何者錯誤？","options":["(A) 藥師執業，應接受繼續教育，每六年辦理執業執照更新","(B) 藥師非加入藥師公會全國聯合會，不得執業","(C) 藥師停業期間以一年為限；逾一年者，應辦理歇業","(D) 藥師應領有執業執照，始得執業"],"answer":1,"image":""},{"id":"ph6-111-1-13","subject":"ph6","topic":"藥事法規-藥師法與執業管理","meta":"111年第1次第13題","year":111,"session":1,"number":13,"question":"依藥師法之規定，下列敘述何者正確？","options":["(A) 藥師得販賣侵入式及植入式醫療器材","(B) 化粧品工廠產品製造之督導工作，應由藥師負責","(C) 運送藥品所需處理技術之指導事項，為藥師執行藥品供應之監督職責","(D) 藥師受理有關機關詢問或委託鑑定時，不得為虛偽之陳述或報告。其中「有關機關」係指衛生、教育、司法或司法警察機關"],"answer":2,"image":""},{"id":"ph6-111-1-14","subject":"ph6","topic":"藥事法規-藥師法與執業管理","meta":"111年第1次第14題","year":111,"session":1,"number":14,"question":"依藥師法之規定，下列何者非屬應移付懲戒之情事？","options":["(A) 藉其藥師身分為產品代言，誇大不實致消費者誤信廣告而購買者","(B) 明知為偽藥而販賣者","(C) 未親自執業而將證照租借他人使用者","(D) 藥師執業未申請執業登記者"],"answer":3,"image":""},{"id":"ph6-111-1-15","subject":"ph6","topic":"藥事法規-藥師法與執業管理","meta":"111年第1次第15題","year":111,"session":1,"number":15,"question":"藥師法對於醫療機構聘藥師提供藥品調劑服務之規定，下列敘述何者正確？","options":["(A) 醫療機構所聘藥師，至少二人應具備二年以上實際調劑執業經驗，始得提供藥品調劑服務","(B) 醫療機構所聘藥師，均需具備一年以上實際調劑執業經驗，始得提供藥品調劑服務","(C) 社區藥局之執業年資不得採計為實際調劑執業經驗","(D) 中醫診所、西醫診所之執業年資均得採計為實際調劑執業經驗"],"answer":3,"image":""},{"id":"ph6-111-1-16","subject":"ph6","topic":"藥事法規-管制藥品與毒品危害防制","meta":"111年第1次第16題","year":111,"session":1,"number":16,"question":"藥師調劑管制藥品未依規定於藥袋標示藥品名稱，將受下列何種處分？","options":["(A) 依違反藥事法之規定處停業","(B) 依違反藥師法之規定處停業","(C) 依違反藥師法之規定處罰鍰","(D) 依違反管制藥品管理條例之規定處罰鍰"],"answer":2,"image":""},{"id":"ph6-111-1-17","subject":"ph6","topic":"臨床藥學-藥物不良反應與交互作用","meta":"111年第1次第17題","year":111,"session":1,"number":17,"question":"依嚴重藥物不良反應通報辦法之規定，因藥物引起嚴重藥物不良反應時，應依該辦法進行通報者，不包括下列何者？","options":["(A) 醫療機構","(B) 藥局","(C) 藥商","(D) 病人"],"answer":3,"image":""},{"id":"ph6-111-1-18","subject":"ph6","topic":"藥事法規-管制藥品與毒品危害防制","meta":"111年第1次第18題","year":111,"session":1,"number":18,"question":"某藥商持有必要藥品清單品項diazepam肛門劑型之製造許可證，因颱風致廠房淹水而半年無法製造該藥且無庫存，下列敘述何者正確？","options":["(A) 本案屬不應歸責於藥商事由，不必通報","(B) diazepam屬第三級管制藥品，藥商應於颱風解除後儘速復原，並經衛生福利部實地查廠核准後，方能繼續生產本藥","(C) 本案應於事件發生後3個月內，向衛生福利部提交合格之diazepam安定性試驗報告","(D) 若本藥有供應不足情況，衛生福利部得登錄於公開網站，專案核准該藥品輸入或製造，不受藥品查驗登記規定限制"],"answer":3,"image":""},{"id":"ph6-111-1-19","subject":"ph6","topic":"藥事法規-新藥臨床試驗與安全監視","meta":"111年第1次第19題","year":111,"session":1,"number":19,"question":"下列有關新藥之敘述，何者正確？","options":["(A) 未經中央衛生福利主管機關公告，不得執行藥物安全監視管理","(B) 新藥安全監視期間，各醫療機構進藥使用，得抽樣個別試用，以保障用藥安全","(C) 申請查驗登記應檢附原料藥藥品主檔案","(D) 將原料藥批次產量提高十倍，即歸類為主要變更管理"],"answer":2,"image":""},{"id":"ph6-111-1-20","subject":"ph6","topic":"調劑學-處方判讀與調劑作業","meta":"111年第1次第20題","year":111,"session":1,"number":20,"question":"醫師開立如下之處方箋，下列敘述何者錯誤？","options":["(A) 本處方欠缺處方日期及醫師署名等項","(B) Stilnox如果缺藥，不得任意以Valium替代","(C) 處方有疑義，應詢明原處方醫師確認","(D) Stilnox屬管制藥品應有管制藥品專用處方箋"],"answer":3,"image":"ph6-111-1-20.jpeg"},{"id":"ph6-111-1-21","subject":"ph6","topic":"調劑學-藥品包裝標示與儲存","meta":"111年第1次第21題","year":111,"session":1,"number":21,"question":"下列有關藥師調劑作業之敘述，何者錯誤？","options":["(A) 為防止兒童取得藥品，應使用安全瓶蓋之容器","(B) 為怕藥物潮解變質應將藥品一律放置冰箱","(C) 交付藥品之包裝或容器不得重複使用","(D) 應在藥品包裝上載明藥品名稱、單位含量、數量、用法及用量"],"answer":1,"image":""},{"id":"ph6-111-1-22","subject":"ph6","topic":"藥事法規-醫療器材管理法","meta":"111年第1次第22題","year":111,"session":1,"number":22,"question":"下列有關醫療器材之敘述，何者正確？","options":["(A) 以藥理、免疫或代謝方法作用於人體，以達成其主要功能","(B) 用於診斷、治療、減輕、預防動物或人類疾病、調節生育或足以影響人類身體結構及機能","(C) 包含儀器、器械、用具、物質、軟體及其相關物品，不包括體外診斷試劑","(D) 醫療器材製造應符合藥物優良製造準則第三編醫療器材優良製造規範之規定"],"answer":3,"image":""},{"id":"ph6-111-1-23","subject":"ph6","topic":"藥事法規-醫療器材管理法","meta":"111年第1次第23題","year":111,"session":1,"number":23,"question":"依據醫療器材查驗登記審查準則之規定，進行臨床前測試檢測之受託實驗室，執行下列何項試驗，不須符合ISO/IEC 17025或藥物非臨床試驗優良操作規範（GLP）之規定？","options":["(A) 機械力學","(B) 電性安全性","(C) 生物相容性","(D) 無菌性試驗"],"answer":0,"image":""},{"id":"ph6-111-1-24","subject":"ph6","topic":"藥事法規-醫療器材管理法","meta":"111年第1次第24題","year":111,"session":1,"number":24,"question":"依藥物優良製造準則之規定，下列何項醫療器材之製造，應符合醫療器材優良製造規範之精要模式？","options":["(A) 隱形眼鏡","(B) 紅外線耳溫槍","(C) 機械式輪椅","(D) 衛生棉條"],"answer":2,"image":""},{"id":"ph6-111-1-25","subject":"ph6","topic":"藥事法規-醫療器材管理法","meta":"111年第1次第25題","year":111,"session":1,"number":25,"question":"依醫療器材管理法及其相關規定，下列有關醫療器材之輸入，何者錯誤？","options":["(A) 輸入醫療器材，應向中央衛生主管機關申請查驗登記並繳納費用，經核准發給醫療器材許可證後，始得由醫療器材許可證所有人或其授權者輸入","(B) 為預防、診治危及生命或嚴重失能之疾病，且國內尚無合適替代療法，得經中央衛生主管機關專案核准輸入","(C) 醫療器材輸入時，均應抽查、檢驗合格後，始得輸入","(D) 因應緊急公共衛生情事之需要，得經中央衛生主管機關專案核准輸入"],"answer":2,"image":""},{"id":"ph6-111-1-26","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"111年第1次第26題","year":111,"session":1,"number":26,"question":"下列有關醫師調劑之規定，何者正確？","options":["(A) 所聘藥師離開調劑處所時，醫師得親自調劑","(B) 醫師於調劑後，須在病歷上簽名，並加註日期","(C) 限調劑自開含麻醉藥或毒劇藥之處方","(D) 曾犯毒品危害防制條例之罪，經判刑確定之醫師，不具調劑權"],"answer":3,"image":""},{"id":"ph6-111-1-27","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"111年第1次第27題","year":111,"session":1,"number":27,"question":"依西藥藥品優良製造規範有關運送之規定，所稱「環境溫度」，意指：","options":["(A) 非冷藏藥品所需的儲存溫度","(B) 在我國，與「室溫」同義，可互換使用","(C) 係用於藥品冷鏈運送之風險管理專業術語","(D) 此溫度的標示值，通常由加速試驗結果計算判定之"],"answer":0,"image":""},{"id":"ph6-111-1-28","subject":"ph6","topic":"藥事法規-藥物廣告與稽查","meta":"111年第1次第28題","year":111,"session":1,"number":28,"question":"下列有關藥品廣告之敘述，何者錯誤？","options":["(A) 刊播內容須事前申請","(B) 核准期間不得變更原核准事項","(C) 應刊載廠商名稱、藥品許可證及廣告核准文件字號","(D) 有效期自刊登時起算"],"answer":3,"image":""},{"id":"ph6-111-1-29","subject":"ph6","topic":"藥事法規-藥物廣告與稽查","meta":"111年第1次第29題","year":111,"session":1,"number":29,"question":"下列敘述何者錯誤？","options":["(A) 登載宣播藥品、醫療器材或化粧品廣告，應事前申請核准","(B) 縣市主管機關得對藥品、醫療器材及化粧品產品執行抽樣檢驗","(C) 化粧品與保健食品不得為醫療效能之標示或宣傳","(D) 藥品、醫療器材及化粧品廣告不得於人體試驗招募廣告中刊載"],"answer":0,"image":""},{"id":"ph6-111-1-30","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"111年第1次第30題","year":111,"session":1,"number":30,"question":"依西藥藥品優良製造規範之規定，下列何者為藥品製造之關鍵人員？","options":["(A) 營運主管","(B) 廠長","(C) 生產主管及品質主管","(D) 工廠裡每一個員工"],"answer":2,"image":""},{"id":"ph6-111-1-31","subject":"ph6","topic":"臨床藥學-藥物不良反應與交互作用","meta":"111年第1次第31題","year":111,"session":1,"number":31,"question":"某甲到藥妝店向藥師購買acetaminophen錠，順手買罐咖啡飲料回家，一起服用後發生心悸現象，30分鐘後才逐漸恢復正常。下列敘述何者正確？","options":["(A) acetaminophen係合法藥物，某甲依法可申請藥害救濟","(B) 藥師應依嚴重藥物不良反應通報辦法之規定通報","(C) 該藥妝店之藥商許可執照應予註銷","(D) 該藥師販售之acetaminophen，無法申請健保給付"],"answer":3,"image":""},{"id":"ph6-111-1-32","subject":"ph6","topic":"藥事法規-醫療器材管理法","meta":"111年第1次第32題","year":111,"session":1,"number":32,"question":"下列有關醫療器材之販賣，何者正確？","options":["(A) 應向中央主管機關申請核准登記，繳納執照費，領得許可執照後，方准營業","(B) 分設營業處所或分廠，無須各別辦理醫療器材商登記","(C) 應將醫療器材商許可執照，懸掛於營業處所之明顯位置","(D) 一般民眾網路拍賣醫用口（面）罩，無須申請醫療器材商許可執照"],"answer":2,"image":""},{"id":"ph6-111-1-33","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"111年第1次第33題","year":111,"session":1,"number":33,"question":"下列何者無須聘專任藥師駐廠監製？","options":["(A) 西藥製造業者","(B) 西藥製造業之分廠","(C) 一般醫療設備之醫療器材製造業者","(D) 中藥製造業者摻入西藥製造中藥"],"answer":2,"image":""},{"id":"ph6-111-1-34","subject":"ph6","topic":"藥事法規-醫療器材管理法","meta":"111年第1次第34題","year":111,"session":1,"number":34,"question":"下列有關第一等級醫療器材之敘述，何者正確？","options":["(A) 因第一等級醫療器材之風險較低（如紗布，OK繃等），輸入、製造時，無須向衛生福利部申請查驗登記，惟標示仍需符合醫療器材管理法第33條規定","(B) 未滅菌及不具量測功能之第一等級醫療器材，應符合醫療器材優良製造規範標準模式之規定","(C) 第一等級醫療器材之風險較低，已開放得在網路販售","(D) 藥局須另請領藥商許可執照，始得販售第一等級醫療器材"],"answer":2,"image":""},{"id":"ph6-111-1-35","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"111年第1次第35題","year":111,"session":1,"number":35,"question":"某藥品之某批次出廠時間為108年8月，有效期限為111年5月，則該批次產品之製造管制與運銷紀錄均應保存至何時？","options":["(A) 112年8月","(B) 110年8月","(C) 112年5月","(D) 110年5月"],"answer":2,"image":""},{"id":"ph6-111-1-36","subject":"ph6","topic":"藥事法規-藥師法與執業管理","meta":"111年第1次第36題","year":111,"session":1,"number":36,"question":"某化學系畢業生完成藥廠品管實習，再修畢藥學研究所課程，並獲碩士學位。下列有關該員之敘述，何者正確？","options":["(A) 該碩士可參加藥師考試","(B) 西藥製造業者可聘該碩士駐廠負責監製","(C) 藥商可僱用該碩士為推銷員","(D) 該碩士得執行藥事照護業務"],"answer":2,"image":""},{"id":"ph6-111-1-37","subject":"ph6","topic":"藥事法規-管制藥品與毒品危害防制","meta":"111年第1次第37題","year":111,"session":1,"number":37,"question":"管制藥品減損時，管制藥品管理人應立即報請當地衛生主管機關查核，並自減損之日起幾日內，將減損藥品品量，檢同當地衛生主管機關證明文件，向食品藥物管理署申報？","options":["(A) 3","(B) 5","(C) 7","(D) 10"],"answer":2,"image":""},{"id":"ph6-111-1-38","subject":"ph6","topic":"藥事法規-管制藥品與毒品危害防制","meta":"111年第1次第38題","year":111,"session":1,"number":38,"question":"墮胎藥美服培酮（Mifepristone）在法國列為高中保健室必備藥品，在我國則為管制藥品，其原因為：","options":["(A) 有加強管理必要","(B) 防治毒品危害","(C) 屬成癮性麻醉藥","(D) 影響精神藥品"],"answer":0,"image":""},{"id":"ph6-111-1-39","subject":"ph6","topic":"藥事法規-管制藥品與毒品危害防制","meta":"111年第1次第39題","year":111,"session":1,"number":39,"question":"依管制藥品管理條例之規定，下列敘述何者錯誤？","options":["(A) 非領有管制藥品使用執照，不得開立管制藥品專用處方箋","(B) 醫師、牙醫師使用第一級至第三級管制藥品，應開立管制藥品專用處方箋","(C) 管制藥品之簿冊、單據及專用處方箋均應保存五年","(D) 獸醫師使用第一級至第三級管制藥品，應開立管制藥品專用處方箋"],"answer":3,"image":""},{"id":"ph6-111-1-40","subject":"ph6","topic":"藥事法規-化粧品衛生安全管理法","meta":"111年第1次第40題","year":111,"session":1,"number":40,"question":"依化粧品或化粧品成分安全性評估申請動物試驗辦法之規定，下列何者非必須檢附之文件？","options":["(A) 申請者之公司或商業登記證明文件影本","(B) 實驗動物照護及使用委員會或小組審議核可之審查同意書影本及動物試驗計畫","(C) 須進行動物試驗之必要性說明及相關佐證資料","(D) 特定用途化粧品許可證"],"answer":3,"image":""},{"id":"ph6-111-1-41","subject":"ph6","topic":"藥事法規-化粧品衛生安全管理法","meta":"111年第1次第41題","year":111,"session":1,"number":41,"question":"依化粧品衛生安全管理法所定之處罰，下列何者非由直轄市、縣（市）主管機關為之？","options":["(A) 行政罰鍰","(B) 撤銷或廢止化粧品之登錄或許可證","(C) 沒入銷毀違規產品","(D) 違反廣告規定情節重大者，應於原刊播之同一篇幅、時段刊播一定次數之更正廣告"],"answer":1,"image":""},{"id":"ph6-111-1-42","subject":"ph6","topic":"藥事法規-藥害救濟與罕見疾病","meta":"111年第1次第42題","year":111,"session":1,"number":42,"question":"有關leflunomide核准適應症為類風濕關節炎，其代謝物teriflunomide為治療多發性硬化症的罕見疾病藥物，下列敘述何者正確？","options":["(A) 以leflunomide治療多發性硬化症致肝功能受損，可申請藥害救濟","(B) leflunomide可作為teriflunomide缺藥時之替代藥","(C) leflunomide與teriflunomide許可證有效期五年，不受理同類藥查驗登記申請","(D) 以teriflunomide申請查驗登記時，衛生福利部必要時得要求進行國內臨床試驗"],"answer":3,"image":""},{"id":"ph6-111-1-43","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"111年第1次第43題","year":111,"session":1,"number":43,"question":"下列何者不屬於法定獎勵範圍？","options":["(A) 新興藥物科技發展","(B) 管制藥品濫用通報","(C) 藥物回收案件","(D) 罕見疾病藥物供應"],"answer":2,"image":""},{"id":"ph6-111-1-44","subject":"ph6","topic":"藥事法規-藥害救濟與罕見疾病","meta":"111年第1次第44題","year":111,"session":1,"number":44,"question":"貿易公司老闆吳先生某次應酬完，隔天覺得身體不適，到附近藥局拿藥。藥師聽完症狀描述後給他allopurinol服用，未料發生「史蒂文生強生症候群」之藥害，下列敘述何者正確？","options":["(A) 吳先生之家屬可申請藥害救濟","(B) 藥師應先檢驗吳先生血中尿酸濃度","(C) 吳先生應補檢測證明帶有特定致病基因，方可申請藥害救濟","(D) 本案非屬正當使用，不符合藥害救濟法規定"],"answer":3,"image":""},{"id":"ph6-111-1-45","subject":"ph6","topic":"藥事法規-全民健康保險與藥事作業","meta":"111年第1次第45題","year":111,"session":1,"number":45,"question":"依全民健康保險醫療辦法之規定，處方用藥每次不得超過多久用量為原則；慢性病人，如有病情需要，得給予一次多久時間內之用藥量？","options":["(A) 3天；28天","(B) 7天；28天","(C) 3天；30天","(D) 7天；30天"],"answer":3,"image":""},{"id":"ph6-111-1-46","subject":"ph6","topic":"藥事法規-全民健康保險與藥事作業","meta":"111年第1次第46題","year":111,"session":1,"number":46,"question":"依全民健康保險藥物給付項目及支付標準之規定，下列何者非屬於新建議收載之新藥分類項目？","options":["(A) 新成分","(B) 新劑型","(C) 新療效複方","(D) 新劑量"],"answer":3,"image":""},{"id":"ph6-111-1-47","subject":"ph6","topic":"藥事法規-全民健康保險與藥事作業","meta":"111年第1次第47題","year":111,"session":1,"number":47,"question":"依全民健康保險藥物給付項目及支付標準之規定，對於在我國為國際間第一個上市，且具臨床價值之新藥，得擇一方法訂定支付價格。所稱臨床價值之範圍不包括下列何者？","options":["(A) 增進療效","(B) 減少不良反應","(C) 降低抗藥性","(D) 增加安定性"],"answer":3,"image":""},{"id":"ph6-111-1-48","subject":"ph6","topic":"藥事法規-全民健康保險與藥事作業","meta":"111年第1次第48題","year":111,"session":1,"number":48,"question":"健保擴大費基，對於以獎金、股利、利息所得作為挹注財源所納一定比率費用者為何？","options":["(A) 補充保險費","(B) 眷屬保險費","(C) 自行負擔部分費用","(D) 特殊材料自付差額費用"],"answer":0,"image":""},{"id":"ph6-111-1-49","subject":"ph6","topic":"藥事法規-全民健康保險與藥事作業","meta":"111年第1次第49題","year":111,"session":1,"number":49,"question":"依全民健康保險法之規定，有關全民健康保險特約醫療院所開立之慢性病連續處方箋之敘述，下列何者正確？","options":["(A) 只限該開立處方箋之醫療院所調劑","(B) 住家所在地無特約藥局，可至一般藥局調劑","(C) 可無條件至任何健保特約醫療院所調劑","(D) 可至住家附近之健保特約藥局調劑"],"answer":3,"image":""},{"id":"ph6-111-1-50","subject":"ph6","topic":"藥事法規-全民健康保險與藥事作業","meta":"111年第1次第50題","year":111,"session":1,"number":50,"question":"依全民健康保險藥品價格調整作業辦法之規定，下列何者非屬同成分、同含量、同規格且同劑型藥品以分組分類（Grouping）方式逐步縮小支付價格差異？","options":["(A) 逾專利期","(B) 年代久遠","(C) 執行BA/BE","(D) 品質較無爭議"],"answer":2,"image":""},{"id":"ph6-111-2-1","subject":"ph6","topic":"藥事法規-藥政管理組織與衛生行政","meta":"111年第2次第1題","year":111,"session":2,"number":1,"question":"依衛生福利部食品藥物管理署組織法之規定，下列何者不屬於掌理事項？","options":["(A) 食品藥物化粧品之安全監視、危害事件調查及處理","(B) 物質成癮防治之政策規劃、管理及監督","(C) 管制藥品之稽核、通報、預警、教育宣導","(D) 食品藥物化粧品消費者保護措施之推動"],"answer":1,"image":""},{"id":"ph6-111-2-2","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"111年第2次第2題","year":111,"session":2,"number":2,"question":"某藥商欲自美國輸入acetaminophen 250 mg膠囊藥品，依藥事法之規定，應向下列何者申請查驗登記？","options":["(A) 衛生福利部","(B) 衛生福利部中央健康保險署","(C) 衛生福利部食品藥物管理署","(D) 財團法人醫藥品查驗中心"],"answer":0,"image":""},{"id":"ph6-111-2-3","subject":"ph6","topic":"藥事法規-醫療器材管理法","meta":"111年第2次第3題","year":111,"session":2,"number":3,"question":"下列有關網路零售藥品或醫療器材之規定，何者正確？","options":["(A) 一般民眾可於網路拍賣酒精棉片","(B) 逍風散濃縮中藥製劑，藥商可於網路零售","(C) 僅第一等級醫療器材，醫療器材商可於網路零售","(D) 手術用口罩，醫療器材商可於網路零售"],"answer":3,"image":""},{"id":"ph6-111-2-4","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"111年第2次第4題","year":111,"session":2,"number":4,"question":"下列敘述何者正確？","options":["(A) 我國西藥製劑GMP已推展至PIC/S GMP階段，國產西藥可與國際接軌","(B) 第一等級醫療器材風險較低，尚未要求實施GMP，第二及第三等級醫療器材已實施GMP","(C) 中藥製劑僅新廠應實施GMP，舊廠輔導進行中","(D) 化粧品已推動強制性GMP"],"answer":0,"image":""},{"id":"ph6-111-2-5","subject":"ph6","topic":"藥事法規-藥政管理組織與衛生行政","meta":"111年第2次第5題","year":111,"session":2,"number":5,"question":"衛生福利部食品藥物管理署已成為國際醫藥法規協和會（ICH）會員，其所代表之意義與下列何者無關？","options":["(A) 說明我國符合國際法規標準之藥品，受到國際認可","(B) 顯示我國致力於建構國際化藥品管理法規之成果","(C) 證明我國藥品價格已與國際接軌","(D) 對於輔導我國藥品產業，創造良好法規環境頗有助益"],"answer":2,"image":""},{"id":"ph6-111-2-6","subject":"ph6","topic":"藥事法規-藥政管理組織與衛生行政","meta":"111年第2次第6題","year":111,"session":2,"number":6,"question":"政府推動長期照顧服務，下列敘述何者正確？","options":["(A) 為因應失能、失智人口增加所衍生之長照需求，政府正推動長照十年計畫（長照1.0）","(B) 為擴大長照財源，修法增加遺產稅、贈與稅及菸酒稅等為長照指定財源","(C) 長照整體服務資源以居家護理成長最為顯著","(D) 長照2.0修法前已設立之住宿式長照機構，一律不受法人化之限制"],"answer":1,"image":""},{"id":"ph6-111-2-7","subject":"ph6","topic":"調劑學-處方判讀與調劑作業","meta":"111年第2次第7題","year":111,"session":2,"number":7,"question":"下列有關處方箋調劑作業之敘述，何者錯誤？","options":["(A) 交付藥品時，應再核對藥品標籤內容、藥品種類、數量與處方指示是否正確","(B) 應確保所有藥品在病患治療期間內，均未超過藥品標示之保存期限","(C) 藥品交付對象應為病人本人","(D) 藥師得親自送藥到轄區病人住處交付"],"answer":2,"image":""},{"id":"ph6-111-2-8","subject":"ph6","topic":"藥事法規-藥師法與執業管理","meta":"111年第2次第8題","year":111,"session":2,"number":8,"question":"下列有關藥師於執業處所外執行業務之敘述，何者錯誤？","options":["(A) 被支援之藥局應已聘有至少1名專任藥師或藥劑生","(B) 主管機關審理時，應考量原執業處所之人力配置、支援藥師工作時數分配之適當性、支援期間是否過長及支援之必要性","(C) 執行藥事照護業務無須事先報准","(D) 無藥事人員執業之偏遠地區或醫療急迫情形也可申請"],"answer":2,"image":""},{"id":"ph6-111-2-9","subject":"ph6","topic":"調劑學-處方判讀與調劑作業","meta":"111年第2次第9題","year":111,"session":2,"number":9,"question":"依藥品優良調劑作業準則之規定，下列敘述何者正確？","options":["(A) 所稱調配，係指調劑作業過程中，依醫師所開具之處方箋，改變原劑型或配製新製品之行為","(B) 調劑處所應有八平方公尺以上之作業面積，並應與其他作業處所明顯區隔","(C) 處方藥不得以開架式陳列","(D) 交付藥品之包裝或容器必要時得重複使用"],"answer":2,"image":""},{"id":"ph6-111-2-10","subject":"ph6","topic":"藥事法規-藥師法與執業管理","meta":"111年第2次第10題","year":111,"session":2,"number":10,"question":"某生於民國107年畢業，當年度參加藥師專技高考及格，下列敘述何者錯誤？","options":["(A) 得請領藥師證書","(B) 欲在臺北市執業，應先加入臺北市藥師公會，即可同時在不同的醫療機構執業","(C) 若想執行中藥調劑、零售業務必先修習中藥課程達適當標準","(D) 如在醫院執業一段時間想出國遊歷2年，須先辦理歇業"],"answer":1,"image":""},{"id":"ph6-111-2-11","subject":"ph6","topic":"藥事法規-藥師法與執業管理","meta":"111年第2次第11題","year":111,"session":2,"number":11,"question":"下列有關藥師執業及繼續教育之敘述，何者錯誤？","options":["(A) 藥師執業，應接受繼續教育，每六年達120積分數","(B) 執業執照更新，應於屆期前六個月內提出申請","(C) 辦理執業執照更新，應檢具執業所在地藥師公會會員證明文件","(D) 領得藥師證書未逾五年，首次申請執業登記，應提具申請執業登記前一年內繼續教育20積分數之證明文件"],"answer":3,"image":""},{"id":"ph6-111-2-12","subject":"ph6","topic":"藥事法規-藥師法與執業管理","meta":"111年第2次第12題","year":111,"session":2,"number":12,"question":"負責主持經營藥局之藥師，應具備多少年以上實際調劑執業經驗，始得提供藥品調劑服務？","options":["(A) 1","(B) 2","(C) 3","(D) 6"],"answer":1,"image":""},{"id":"ph6-111-2-13","subject":"ph6","topic":"調劑學-處方判讀與調劑作業","meta":"111年第2次第13題","year":111,"session":2,"number":13,"question":"藥師受理處方箋調劑，如藥品未備或缺乏時，應如何處理？","options":["(A) 應通知原處方醫師，請其更換","(B) 可考量病情需要予以省略","(C) 可代以同成分不同劑型之他藥","(D) 可代以同成分不同劑量之他藥"],"answer":0,"image":""},{"id":"ph6-111-2-14","subject":"ph6","topic":"調劑學-藥品包裝標示與儲存","meta":"111年第2次第14題","year":111,"session":2,"number":14,"question":"依藥師法之規定，藥師交付藥劑時，下列何者非屬容器或包裝上應記明事項？","options":["(A) 藥品名稱、劑量、數量、用法","(B) 作用或適應症","(C) 警語或副作用","(D) 藥品之有效年、月、日"],"answer":3,"image":""},{"id":"ph6-111-2-15","subject":"ph6","topic":"藥事法規-藥師法與執業管理","meta":"111年第2次第15題","year":111,"session":2,"number":15,"question":"藥師執行藥事照護相關業務係明定於下列何法規？","options":["(A) 醫療法及醫療法施行細則","(B) 藥師法及藥師法施行細則","(C) 藥事法及藥事法施行細則","(D) 藥事法及藥品優良調劑作業準則"],"answer":1,"image":""},{"id":"ph6-111-2-16","subject":"ph6","topic":"藥事法規-藥師法與執業管理","meta":"111年第2次第16題","year":111,"session":2,"number":16,"question":"某診所聘任甲藥師負責藥局業務，甲藥師休假由乙護士代理，錯給藥物引起病人死亡。下列敘述何者錯誤？","options":["(A) 該診所負責醫師負有醫療法之責任","(B) 乙護士執行藥師業務，違反藥師法第24條規定","(C) 甲藥師因休假不在場，得屬藥師法第12條拒絕為調劑之正當理由規定，可以減免責任","(D) 甲藥師違反藥學倫理規範，可由藥師公會或主管機關移付懲戒"],"answer":2,"image":""},{"id":"ph6-111-2-17","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"111年第2次第17題","year":111,"session":2,"number":17,"question":"西藥販賣業所販賣之藥品包括錠劑、注射劑、麻醉藥品等，應聘請下列何種人員駐店管理？","options":["(A) 藥師","(B) 藥劑生","(C) 醫師","(D) 護理師"],"answer":0,"image":""},{"id":"ph6-111-2-18","subject":"ph6","topic":"藥事法規-新藥臨床試驗與安全監視","meta":"111年第2次第18題","year":111,"session":2,"number":18,"question":"某藥師研發成功自acetophenone（）經五步驟製得中間體amphetamine（），再經三步驟製得強效抗鬱藥bupropion（）新製程。今擬申請藥品主檔案審核，下列敘述何者正確？","options":["(A) 該藥品得以主檔案申請，提交「通用技術文件」","(B) 若bupropion在白種人體內證明會代謝成amphetamine，則須提交黃種人之銜接性試驗結果","(C) 該新製程已違反毒品危害防制條例","(D) 該新製程仍須遵循藥事法有關專利連結之規定"],"answer":2,"image":"ph6-111-2-18.jpeg"},{"id":"ph6-111-2-19","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"111年第2次第19題","year":111,"session":2,"number":19,"question":"A販賣業藥商向製藥廠購買了有藥品許可證的大瓶裝藥水，為了容易銷售，在自己公司地下室將大瓶裝藥水分裝成每瓶100毫升的小瓶裝，並自行印製原製藥廠之標籤貼於小瓶瓶身，A藥商之行為係屬違反藥事法之何種規定？","options":["(A) 未經核准擅自變更成分標示","(B) 製造偽藥","(C) 無處方箋調劑","(D) 因為A公司是藥商，購買有許可證藥品分裝，未違反規定"],"answer":1,"image":""},{"id":"ph6-111-2-20","subject":"ph6","topic":"藥事法規-新藥臨床試驗與安全監視","meta":"111年第2次第20題","year":111,"session":2,"number":20,"question":"下列有關新藥之敘述，何者錯誤？","options":["(A) 臨床試驗資料為新成分新藥查驗登記應檢具資料之一","(B) 新藥核准上市後應依藥物安全監視管理辦法進行藥品安全監視","(C) 須通報之嚴重藥物不良反應僅限死亡及危及生命","(D) 新藥上市前到上市後如發生嚴重不良反應均應進行通報"],"answer":2,"image":""},{"id":"ph6-111-2-21","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"111年第2次第21題","year":111,"session":2,"number":21,"question":"下列何者可以在網路販售？","options":["(A) 經核准於網路販售之處方藥","(B) 醫師藥師藥劑生指示藥品","(C) 乙類成藥","(D) 不可以在網路上販賣藥品，只能販賣醫療器材"],"answer":2,"image":""},{"id":"ph6-111-2-22","subject":"ph6","topic":"藥事法規-新藥臨床試驗與安全監視","meta":"111年第2次第22題","year":111,"session":2,"number":22,"question":"臨床試驗用藥依試驗委託者指示，刻意偽裝藥品的識別性，即為：","options":["(A) 盲性（blinding）","(B) 隨機化（randomization）","(C) 同步對照（concurrent control）","(D) 探索（exploratory）試驗"],"answer":0,"image":""},{"id":"ph6-111-2-23","subject":"ph6","topic":"藥事法規-醫療器材管理法","meta":"111年第2次第23題","year":111,"session":2,"number":23,"question":"醫療器材製造業者保存品質紀錄之期限，應至少相當於產品有效期間，且不得少於產品放行之日起幾年？","options":["(A) 1","(B) 2","(C) 3","(D) 4"],"answer":2,"image":""},{"id":"ph6-111-2-24","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"111年第2次第24題","year":111,"session":2,"number":24,"question":"醫師於下列何種情況，得依自開處方親自為藥品之調劑？","options":["(A) 教學醫院領有管制藥品使用執照之醫師，診治癌症病人所開麻醉藥品處方","(B) 醫院醫師為診療目的，具備藥事法規定之調劑設備","(C) 非主管機關公告之偏遠地區，診所醫師依病人需求","(D) 診所醫師於醫療急迫情形須立即使用藥品之情事"],"answer":3,"image":""},{"id":"ph6-111-2-25","subject":"ph6","topic":"藥事法規-新藥臨床試驗與安全監視","meta":"111年第2次第25題","year":111,"session":2,"number":25,"question":"下列何者屬於藥品上市後之安全監視？","options":["(A) 查驗登記","(B) 藥品優良製造規範","(C) 不良反應通報","(D) 藥品主檔案"],"answer":2,"image":""},{"id":"ph6-111-2-26","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"111年第2次第26題","year":111,"session":2,"number":26,"question":"下列有關藥品製造及管理之敘述，何者正確？","options":["(A) 物流中心對輸入藥品重貼標籤之作業，應符合藥品優良製造規範","(B) 經核准製造之臨床試驗用藥，可依法申請全民健保給付","(C) 中央研究院若依中華藥典所定方法，即得接受委託檢驗藥物","(D) 原料藥中間體之製造，目前尚無須符合藥品優良製造規範"],"answer":0,"image":""},{"id":"ph6-111-2-27","subject":"ph6","topic":"藥事法規-藥物廣告與稽查","meta":"111年第2次第27題","year":111,"session":2,"number":27,"question":"某藥局在臉書Facebook設立藥局專頁，分析所售A藥品所適用之醫療案例，並直播某病人對A藥品之使用經驗，下列敘述何者錯誤？","options":["(A) 該藥局之臉書Facebook專頁可使多數人知悉A藥品之內容，屬廣告管理範疇","(B) 以招徠銷售為目的，於該藥局之臉書Facebook專頁舉醫療案例分析A藥品之特色，屬藥物廣告","(C) 該藥局藉由該藥局臉書Facebook專頁直播某病人對A藥品之使用經驗分享，非屬藥物廣告","(D) 持有A藥品許可證之藥商，方得為藥物廣告"],"answer":2,"image":""},{"id":"ph6-111-2-28","subject":"ph6","topic":"藥事法規-藥物廣告與稽查","meta":"111年第2次第28題","year":111,"session":2,"number":28,"question":"下列有關藥品廣告之敘述，何者錯誤？","options":["(A) 藥商刊播藥品廣告時，應於刊播前將所有文字、圖畫或言詞，申請該直轄巿或縣（市）衛生主管機關核准，並向傳播業者送驗核准文件","(B) 藥品廣告，經核准者，其有效期間為一年","(C) 藥品廣告有效期間屆滿後，仍需繼續廣告者，得申請原核准之衛生主管機關核定展延之；每次展延之期間，不得超過一年","(D) 須由醫師處方之藥品，其廣告以登載於學術性醫療刊物為限"],"answer":0,"image":""},{"id":"ph6-111-2-29","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"111年第2次第29題","year":111,"session":2,"number":29,"question":"藥品製造應符合下列何項規範？","options":["(A) GMP","(B) GCP","(C) GTP","(D) GLP"],"answer":0,"image":""},{"id":"ph6-111-2-30","subject":"ph6","topic":"藥事法規-藥政管理組織與衛生行政","meta":"111年第2次第30題","year":111,"session":2,"number":30,"question":"依藥事法之規定，藥商藥局普查應由下列何者多久辦理一次？","options":["(A) 衛生福利部食品藥物管理署；一年","(B) 衛生福利部中央健康保險署；二年","(C) 衛生福利部；二年","(D) 直轄市、縣（市）衛生主管機關；一年"],"answer":3,"image":""},{"id":"ph6-111-2-31","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"111年第2次第31題","year":111,"session":2,"number":31,"question":"下列有關藥商之敘述，何者錯誤？","options":["(A) 藥品販賣業者，為藥商；醫療器材製造業者，為醫療器材商","(B) 藥品販賣業者所聘藥師修習中藥課程達適當標準，可同時經營西藥及中藥批發、零售、調劑","(C) 西藥販賣業者可兼售中藥成藥","(D) 未領得藥商許可執照，不得販賣藥品"],"answer":1,"image":""},{"id":"ph6-111-2-32","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"111年第2次第32題","year":111,"session":2,"number":32,"question":"下列何種藥品或醫療器材之製造，應聘專任藥師駐廠監製？","options":["(A) 中藥製造業者以西藥劑型製造中藥","(B) 隱形眼鏡鏡片","(C) 中藥材之炮製","(D) 依固有成方調配而成的傳統丸、散、膏、丹"],"answer":0,"image":""},{"id":"ph6-111-2-33","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"111年第2次第33題","year":111,"session":2,"number":33,"question":"藥品製造、輸入許可證之有效期間為幾年？","options":["(A) 10","(B) 6","(C) 5","(D) 3"],"answer":2,"image":""},{"id":"ph6-111-2-34","subject":"ph6","topic":"藥事法規-藥政管理組織與衛生行政","meta":"111年第2次第34題","year":111,"session":2,"number":34,"question":"依藥事法之規定，臺北市之衛生主管機關為：","options":["(A) 衛生福利部食品藥物管理署","(B) 臺北市政府","(C) 臺北市政府衛生局食品藥物管理處","(D) 臺北市藥師公會"],"answer":1,"image":""},{"id":"ph6-111-2-35","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"111年第2次第35題","year":111,"session":2,"number":35,"question":"廠商使用不實資料申請藥品查驗登記，下列之處置方式何者錯誤？","options":["(A) 撤銷該藥品許可證","(B) 二年內不得再行申請該藥品許可證","(C) 涉及刑事責任者移送司法機關","(D) 登報公告該廠商名稱、地址、負責人姓名、藥物名稱及違反情節"],"answer":3,"image":""},{"id":"ph6-111-2-36","subject":"ph6","topic":"藥事法規-新藥臨床試驗與安全監視","meta":"111年第2次第36題","year":111,"session":2,"number":36,"question":"下列何者於必要時，經中央衛生福利主管機關核定後，即納入藥品安全監視管理辦法管理？","options":["(A) 非臨床試驗之藥品","(B) 第一期臨床試驗之藥品","(C) 第三期臨床試驗之藥品","(D) 上市後臨床試驗之藥品"],"answer":3,"image":""},{"id":"ph6-111-2-37","subject":"ph6","topic":"藥事法規-藥物廣告與稽查","meta":"111年第2次第37題","year":111,"session":2,"number":37,"question":"下列有關藥品或醫療器材廣告刊播之規定，何者正確？","options":["(A) sildenafil錠劑廣告可在電視刊播","(B) 肉毒桿菌素製劑廣告海報可張貼在捷運車廂","(C) 可請裝設心血管支架人士代言，宣傳產品之效能及安全性","(D) 綜合感冒液劑廣告可於電視刊播"],"answer":3,"image":""},{"id":"ph6-111-2-38","subject":"ph6","topic":"藥事法規-管制藥品與毒品危害防制","meta":"111年第2次第38題","year":111,"session":2,"number":38,"question":"依管制藥品管理條例之規定，下列敘述何者正確？","options":["(A) 醫藥教育研究試驗機構購買管制藥品，不須申請管制藥品登記證","(B) 藥局使用或購買管制藥品，不須設置管制藥品管理人","(C) 診所於同縣市遷址，仍應依規定辦理管制藥品登記證變更登記","(D) 藥局不須申請管制藥品登記證，亦能購買管制藥品調劑處方箋"],"answer":2,"image":""},{"id":"ph6-111-2-39","subject":"ph6","topic":"藥事法規-管制藥品與毒品危害防制","meta":"111年第2次第39題","year":111,"session":2,"number":39,"question":"機構或業者要購買管制藥品，應向下列何者申請取得管制藥品登記證？","options":["(A) 衛生福利部","(B) 衛生福利部食品藥物管理署","(C) 直轄巿及縣（巿）衛生主管機關","(D) 法務部"],"answer":1,"image":""},{"id":"ph6-111-2-40","subject":"ph6","topic":"藥事法規-管制藥品與毒品危害防制","meta":"111年第2次第40題","year":111,"session":2,"number":40,"question":"下列有關管制藥品管理之敘述，何者正確？","options":["(A) 常見安眠藥品札來普隆（zaleplon），不具成癮性未列入管制藥品管理","(B) 管制藥品依其成癮性、濫用性及對社會危害性之程度，分為四級管理","(C) 俗稱牛奶針之丙泊酚（propofol）製劑，易遭濫用已列入管制藥品管理","(D) 民眾將取自診所已列管之安眠藥，上網販售圖利，並未涉及毒品販賣行為"],"answer":2,"image":""},{"id":"ph6-111-2-41","subject":"ph6","topic":"藥事法規-化粧品衛生安全管理法","meta":"111年第2次第41題","year":111,"session":2,"number":41,"question":"依化粧品衛生安全管理法之規定，下列何者非屬化粧品外包裝或容器應標示事項？","options":["(A) 品名","(B) 全成分名稱","(C) 輸入產品之原產地（國）","(D) 如屬特定用途化粧品，應標示所有成分之含量"],"answer":3,"image":""},{"id":"ph6-111-2-42","subject":"ph6","topic":"藥事法規-化粧品衛生安全管理法","meta":"111年第2次第42題","year":111,"session":2,"number":42,"question":"依現行化粧品衛生管理條例之規定，含有下列防曬成分及含量之乳劑化粧品，何者無須辦理查驗登記？","options":["(A) 1％ benzophenone-8","(B) 2％ titanium dioxide","(C) 3％ p-aminobenzoic acid","(D) 4％ octyl salicylate"],"answer":1,"image":""},{"id":"ph6-111-2-43","subject":"ph6","topic":"藥事法規-藥害救濟與罕見疾病","meta":"111年第2次第43題","year":111,"session":2,"number":43,"question":"下列何者不符合「罕見疾病藥物專案申請要件」？","options":["(A) 罕見疾病藥物售價經衛生福利部認定顯不合理","(B) 罕見疾病藥物許可證期滿仍須輸入，並事先申請展延獲准者","(C) 持有罕見疾病藥物許可證者，無法供應該藥需求","(D) 未經查驗登記之罕見疾病藥物"],"answer":1,"image":""},{"id":"ph6-111-2-44","subject":"ph6","topic":"藥事法規-藥害救濟與罕見疾病","meta":"111年第2次第44題","year":111,"session":2,"number":44,"question":"政府積極推廣「藥物過敏早期症狀自我檢視」，目的即為配合推動下列何種政策？","options":["(A) 醫藥分業","(B) 藥物流向追蹤","(C) 疑似藥品療效不等通報","(D) 藥害救濟"],"answer":3,"image":""},{"id":"ph6-111-2-45","subject":"ph6","topic":"藥事法規-藥害救濟與罕見疾病","meta":"111年第2次第45題","year":111,"session":2,"number":45,"question":"一名父親帶其小兒接受流感預防接種，發生注射部位之手臂永久失能，下列敘述何者正確？","options":["(A) 若該父親已為其小兒投保意外保險並獲得給付，則應排除藥害救濟","(B) 若該手臂永久失能係可預期且發生率 ≥ 1%，即符合申請藥害救濟資格","(C) 本案若已依其他法令獲得救濟，不應再申請藥害救濟","(D) 須有國內銜接性試驗證明，方能申請藥害救濟"],"answer":2,"image":""},{"id":"ph6-111-2-46","subject":"ph6","topic":"藥事法規-全民健康保險與藥事作業","meta":"111年第2次第46題","year":111,"session":2,"number":46,"question":"依健保藥品支付價格訂定原則，下列何者非屬新建議收載全民健康保險藥品之分類？","options":["(A) 經主管機關核准認定之生物相似性藥品","(B) 臨床價值相近於已收載核價參考品之新藥","(C) 顯示臨床療效有明顯改善之突破創新新藥","(D) 已收載品項中，新增之醫師指示類藥品品項"],"answer":3,"image":""},{"id":"ph6-111-2-47","subject":"ph6","topic":"藥事法規-全民健康保險與藥事作業","meta":"111年第2次第47題","year":111,"session":2,"number":47,"question":"依全民健康保險藥物給付項目及支付標準之規定，下列取得藥品許可證之藥品，何者可建議予以納入？","options":["(A) 須由醫師處方使用","(B) 預防接種所用之疫苗","(C) 避孕用藥","(D) 戒菸用貼片"],"answer":0,"image":""},{"id":"ph6-111-2-48","subject":"ph6","topic":"藥事法規-全民健康保險與藥事作業","meta":"111年第2次第48題","year":111,"session":2,"number":48,"question":"下列何者非屬全民健康保險慢性病之範圍？","options":["(A) 癌症","(B) 流行性感冒","(C) 結核病","(D) 脂漏性皮膚炎"],"answer":1,"image":""},{"id":"ph6-111-2-49","subject":"ph6","topic":"藥事法規-全民健康保險與藥事作業","meta":"111年第2次第49題","year":111,"session":2,"number":49,"question":"全民健康保險會應於各年度開始幾個月前，協議訂定醫療給付費用總額及其分配方式？","options":["(A) 1","(B) 2","(C) 3","(D) 6"],"answer":2,"image":""},{"id":"ph6-111-2-50","subject":"ph6","topic":"藥事法規-全民健康保險與藥事作業","meta":"111年第2次第50題","year":111,"session":2,"number":50,"question":"全民健康保險之保險對象罹患慢性疾病，經醫師診斷須長期使用同一處方藥品，下列敘述何者錯誤？","options":["(A) 醫師得開立慢性病連續處方箋","(B) 慢性病連續處方箋，得併列印可供辨識之二維條碼","(C) 慢性病連續處方箋如與管制藥品專用處方箋併用時，可分別持兩種處方箋分別至不同處所調劑","(D) 同一慢性病，以開立一張慢性病連續處方箋為限"],"answer":2,"image":""},{"id":"ph6-112-1-1","subject":"ph6","topic":"藥事法規-藥政管理組織與衛生行政","meta":"112年第1次第1題","year":112,"session":1,"number":1,"question":"下列有關業務職掌之敘述，何者錯誤？","options":["(A) 毒品及其他物質成癮防治政策之規劃、推動及相關法規之研訂，為衛生福利部心理及口腔衛生司之法定職掌","(B) 家庭暴力、性侵害、性騷擾防治與老人、身心障礙者、兒少保護及兒少性剝削防制政策規劃、法規研訂與被害人保護服務方案、教育宣導及研究發展之規劃、推動及督導事項為衛生福利部保護服務司之法定職掌","(C) 藥師懲戒及爭議處理為食品藥物管理署之法定職掌","(D) 中醫醫事人員管理與人力發展政策之規劃、推動及相關法規之研擬，為衛生福利部中醫藥司之法定職掌"],"answer":[0,2],"image":"","answer_note":"更正:第1題答Ａ或Ｃ或AC者均給分"},{"id":"ph6-112-1-2","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"112年第1次第2題","year":112,"session":1,"number":2,"question":"下列何者非屬申請輸入試製藥品原料藥業者應檢附之資料？","options":["(A) 藥商許可執照","(B) 藥品許可證","(C) 經濟部工廠登記證明文件（研發單位免附）","(D) 試製計畫書"],"answer":1,"image":""},{"id":"ph6-112-1-3","subject":"ph6","topic":"藥事法規-藥政管理組織與衛生行政","meta":"112年第1次第3題","year":112,"session":1,"number":3,"question":"下列有關藥政管理體系之敘述，何者正確？","options":["(A) 依藥事法，中央衛生主管機關，得專設藥物管理機關，直轄市及縣（市）衛生主管機關，亦應設立藥物管理機關","(B) 中央藥物管理機關為食品藥物管理署藥品組","(C) 醫藥工業技術發展中心為食品藥物管理署附屬單位","(D) 食品藥物管理署醫療器材及化粧品組負責醫療器材及化粧品之法規管理"],"answer":3,"image":""},{"id":"ph6-112-1-4","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"112年第1次第4題","year":112,"session":1,"number":4,"question":"下列敘述何者錯誤？","options":["(A) 藥商歇業，應向當地衛生主管機關申請，並將其所領藥商許可執照及藥品許可證一併繳銷","(B) 新設之國產藥品製造業者，其硬體設備及衛生條件，應符合藥物製造工廠設廠標準及工廠管理輔導法之規定，並由工業主管機關及直轄市或縣（市）衛生主管機關檢查之；其軟體設備及衛生條件，應符合藥品優良製造準則之規定，並由中央衛生主管機關檢查之","(C) 藥商刊播藥物廣告時，應於刊播前將所有文字、圖畫或言詞，申請中央衛生主管機關核准，並向傳播業者送驗核准文件。其有效期間為一年，期滿仍需繼續廣告者，得向地方衛生主管機關申請展延之；每次展延之期間，不得超過一年","(D) 凡申請為藥商者，應申請直轄市或縣（市）衛生主管機關核准登記，繳納執照費，領得許可執照後，方准營業；其登記事項如有變更時，應辦理變更登記"],"answer":2,"image":""},{"id":"ph6-112-1-5","subject":"ph6","topic":"藥事法規-藥政管理組織與衛生行政","meta":"112年第1次第5題","year":112,"session":1,"number":5,"question":"下列何者非屬衛生福利部食品藥物管理署之業務？","options":["(A) 醫療器材管理、政策及相關法規之研擬","(B) 化粧品管理、政策及相關法規之研擬","(C) 藥品臨床試驗之審查及監督","(D) 藥師懲戒相關事項"],"answer":3,"image":""},{"id":"ph6-112-1-6","subject":"ph6","topic":"藥事法規-全民健康保險與藥事作業","meta":"112年第1次第6題","year":112,"session":1,"number":6,"question":"下列有關全民健康保險之敘述，何者錯誤？","options":["(A) 全民健保之財源主要來自保險對象、雇主及政府共同分擔之保險費","(B) 推動分級醫療及轉診制度，鼓勵民眾至基層院所就醫，如有醫療上需要協助轉診","(C) 實施醫療費用總額預算支付制度，透過支付制度策略，提升醫療服務品質","(D) 建置健保雲端藥歷系統，僅提供醫院醫師線上查詢病人用藥紀錄"],"answer":3,"image":""},{"id":"ph6-112-1-7","subject":"ph6","topic":"藥事法規-藥政管理組織與衛生行政","meta":"112年第1次第7題","year":112,"session":1,"number":7,"question":"民國105年食品藥物管理署協同地方衛生局執行食品後市場監測計畫，下列何者不合格率最高？","options":["(A) 市售與包裝場農產品殘留農藥監測","(B) 市售食品動物用藥殘留監測","(C) 市售食品真菌毒素含量監測","(D) 市售食品重金屬含量監測"],"answer":0,"image":""},{"id":"ph6-112-1-8","subject":"ph6","topic":"調劑學-處方判讀與調劑作業","meta":"112年第1次第8題","year":112,"session":1,"number":8,"question":"下列有關藥師執行調劑作業之敘述，何者錯誤？","options":["(A) 藥師受理處方，應注意處方內容，如有可疑之點，應詢明原處方醫師始得調劑，並應於調劑後之處方箋上註明前述詢明事項","(B) 調劑後之處方箋應簽名蓋章，並添記調劑年、月、日，處方箋均應保存五年","(C) 藥師對於醫師所開處方，只許調劑一次","(D) 藥師交付藥劑時，應於容器或包裝上記明法定事項"],"answer":1,"image":""},{"id":"ph6-112-1-9","subject":"ph6","topic":"藥事法規-全民健康保險與藥事作業","meta":"112年第1次第9題","year":112,"session":1,"number":9,"question":"下列何種藥品，不得開具慢性病連續處方箋？","options":["(A) 含可待因複方製劑","(B) 含麻黃素製劑","(C) 長效嗎啡製劑","(D) 胰島素製劑"],"answer":2,"image":""},{"id":"ph6-112-1-10","subject":"ph6","topic":"藥事法規-藥師法與執業管理","meta":"112年第1次第10題","year":112,"session":1,"number":10,"question":"依藥師法之規定，下列何者非屬藥師執行藥事照護之處所？","options":["(A) 醫院","(B) 護理機構","(C) 社區藥局","(D) 衛生局"],"answer":3,"image":""},{"id":"ph6-112-1-11","subject":"ph6","topic":"藥事法規-藥師法與執業管理","meta":"112年第1次第11題","year":112,"session":1,"number":11,"question":"下列何者不屬藥師法所規定之藥師業務？","options":["(A) 藥品分裝之監督職責，包括分裝藥品之封緘事項","(B) 植入性第二等級或第三等級醫療器材之販賣","(C) 藥品之調劑","(D) 藥品之鑑定"],"answer":1,"image":""},{"id":"ph6-112-1-12","subject":"ph6","topic":"藥事法規-藥師法與執業管理","meta":"112年第1次第12題","year":112,"session":1,"number":12,"question":"依藥師法之規定，下列有關藥師懲戒之方式，何者正確？","options":["(A) 撤銷藥師證書","(B) 撤銷藥師執業執照","(C) 限制執業範圍或停業一年以上","(D) 警告"],"answer":3,"image":""},{"id":"ph6-112-1-13","subject":"ph6","topic":"藥事法規-藥師法與執業管理","meta":"112年第1次第13題","year":112,"session":1,"number":13,"question":"依藥師法之規定，下列敘述何者正確？","options":["(A) 藥師執業應向其執業所在地衛生局，申請開業執照","(B) 藥師執業應每六年辦理執業執照更新","(C) 藥師繼續教育之課程及積分，得依各地藥師服務對象不同，由衛生局審查認定","(D) 藥師繼續教育課程及內容，應由各縣市衛生主管機關辦理"],"answer":1,"image":""},{"id":"ph6-112-1-14","subject":"ph6","topic":"藥事法規-藥師法與執業管理","meta":"112年第1次第14題","year":112,"session":1,"number":14,"question":"依藥師法之規定，藥師經撤銷執業執照後，再申請發給執業執照，下列何者正確？","options":["(A) 經撤銷藥師執業執照未滿二年者，不得發給執業執照","(B) 經撤銷藥師執業執照未滿五年者，不得發給執業執照","(C) 無特別限制，隨時可再申請發給執業執照","(D) 經撤銷藥師執業執照未滿一年者，不得發給執業執照"],"answer":3,"image":""},{"id":"ph6-112-1-15","subject":"ph6","topic":"藥事法規-藥師法與執業管理","meta":"112年第1次第15題","year":112,"session":1,"number":15,"question":"下列何者不是法定藥師執業之必要條件？","options":["(A) 藥師考試及格","(B) 領有藥師證書","(C) 領有藥師執業執照","(D) 修習臨床藥學課程達適當標準"],"answer":3,"image":""},{"id":"ph6-112-1-16","subject":"ph6","topic":"藥事法規-藥師法與執業管理","meta":"112年第1次第16題","year":112,"session":1,"number":16,"question":"藥師執行藥品販賣或管理業務之職責，下列何者錯誤？","options":["(A) 藥品鑑定方法及結果之確認事項","(B) 對購用藥品者應注意事項之說明","(C) 藥品拆封販賣之指導事項","(D) 藥品貯藏、陳列管理及衛生安全之指導、檢查事項"],"answer":0,"image":""},{"id":"ph6-112-1-17","subject":"ph6","topic":"臨床藥學-藥事照護與用藥評估","meta":"112年第1次第17題","year":112,"session":1,"number":17,"question":"下列何者屬於法定藥事照護之業務範圍？","options":["(A) 醫院護理師拿藥給臥床病人，告訴他胃藥應嚼碎服下","(B) 藥師依處方箋將錠劑磨成粉提供病人服用","(C) 藥師幫病人分裝藥品","(D) 藥師幫病人評估給藥流程"],"answer":3,"image":""},{"id":"ph6-112-1-18","subject":"ph6","topic":"藥事法規-新藥臨床試驗與安全監視","meta":"112年第1次第18題","year":112,"session":1,"number":18,"question":"下列有關人體試驗委員會之敘述，何者錯誤？","options":["(A) 人體試驗委員會得邀請非委員之專家給予特定專業上之協助","(B) 人體試驗委員會是由具醫學背景之專業人員與非醫學背景之社會公正人士所共同組成之委員會，其責任在確保試驗之正確性及科學之相關性","(C) 人體試驗委員會應根據受試者所承受之風險，每年至少應進行一次評估進行中之臨床試驗","(D) 試驗機構為審查藥品臨床試驗，應設人體試驗委員會，組成人員應具備審查及評估藥品臨床試驗之科學、醫學或倫理資格及經驗"],"answer":1,"image":""},{"id":"ph6-112-1-19","subject":"ph6","topic":"藥事法規-新藥臨床試驗與安全監視","meta":"112年第1次第19題","year":112,"session":1,"number":19,"question":"依嚴重藥物不良反應通報辦法之規定，下列敘述何者錯誤？","options":["(A) 因藥品引起之嚴重不良反應，由持有藥品許可證之藥商負責通報即可","(B) 導致病人住院為嚴重不良反應","(C) 持有藥品許可證之藥商於得知嚴重藥品不良反應之日起15日內，依規定辦理通報","(D) 得以郵寄、傳真或網路等方式為之"],"answer":0,"image":""},{"id":"ph6-112-1-20","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"112年第1次第20題","year":112,"session":1,"number":20,"question":"依藥事法施行細則之規定，舉發偽藥、劣藥經緝獲者，應由下列何者核發獎金？","options":["(A) 衛生福利部","(B) 衛生福利部食品藥物管理署","(C) 直轄市或縣（市）政府不法藥物查緝中心","(D) 直轄市或縣（市）衛生主管機關"],"answer":3,"image":""},{"id":"ph6-112-1-21","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"112年第1次第21題","year":112,"session":1,"number":21,"question":"衛生局稽查發現，小明在自家工廠製造仿真品的A藥品，此仿真品之A藥品係屬藥事法所規定之何種藥品？","options":["(A) 偽藥","(B) 劣藥","(C) 禁藥","(D) 毒劇藥"],"answer":0,"image":""},{"id":"ph6-112-1-22","subject":"ph6","topic":"藥事法規-新藥臨床試驗與安全監視","meta":"112年第1次第22題","year":112,"session":1,"number":22,"question":"依藥品安全監視管理辦法之規定，新藥之安全監視期間為何？","options":["(A) 5年","(B) 3年","(C) 2年","(D) 以藥品許可證有效期間為準"],"answer":3,"image":""},{"id":"ph6-112-1-23","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"112年第1次第23題","year":112,"session":1,"number":23,"question":"依藥事法及相關法規之規定，下列敘述何者錯誤？","options":["(A) 新藥係指經中央衛生主管機關審查認定屬新成分、新療效複方或新使用途徑製劑之藥品","(B) 已核准之藥品，經審查認定具新適應症者，屬新藥","(C) 新成分新藥在國外取得上市後五年內，向中央衛生主關機關申請查驗登記，得享新藥新成分專利權之優惠","(D) 已核准之藥品，其改變使用途徑者，應檢送臨床試驗報告"],"answer":2,"image":""},{"id":"ph6-112-1-24","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"112年第1次第24題","year":112,"session":1,"number":24,"question":"小新在藥品公司買了2瓶合法之指示藥品，沿街到處叫賣，依藥事法之規定，其行為應屬下列何者？","options":["(A) 未申請藥商許可執照販賣藥品","(B) 未依處方箋調劑藥品","(C) 未經查驗登記販賣藥品","(D) 藥商僱用之推銷員未經登記，執行推銷工作"],"answer":0,"image":""},{"id":"ph6-112-1-25","subject":"ph6","topic":"藥事法規-新藥臨床試驗與安全監視","meta":"112年第1次第25題","year":112,"session":1,"number":25,"question":"下列有關藥品臨床試驗之執行，何者正確？","options":["(A) 受試者不得不附理由隨時退出臨床試驗","(B) 試驗主持人應於臨床試驗進行前，取得受試者簽署之受試者同意書","(C) 藥品臨床試驗計畫書經人體試驗委員會或衛生福利部食品藥物管理署其中一個單位核准，即得進行藥品臨床試驗","(D) 試驗藥品、對照藥品及安慰劑之製造、處理及儲存，應符合藥品優良實驗室規範"],"answer":1,"image":""},{"id":"ph6-112-1-26","subject":"ph6","topic":"藥事法規-醫療器材管理法","meta":"112年第1次第26題","year":112,"session":1,"number":26,"question":"醫療器材製造、輸入許可證有效期間為幾年？有效期間之展延，應於期滿前幾個月內申請？","options":["(A) 5年，12個月","(B) 5年，6個月","(C) 3年，12個月","(D) 3年，6個月"],"answer":1,"image":""},{"id":"ph6-112-1-27","subject":"ph6","topic":"藥事法規-全民健康保險與藥事作業","meta":"112年第1次第27題","year":112,"session":1,"number":27,"question":"醫師將所開處方箋交予病人，病人持處方箋可至下列何處調劑？","options":["(A) 藥房","(B) 藥局","(C) 藥商","(D) 藥粧店"],"answer":1,"image":""},{"id":"ph6-112-1-28","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"112年第1次第28題","year":112,"session":1,"number":28,"question":"下列有關藥品製造業者之敘述，何者錯誤？","options":["(A) 須先取得核發藥品許可證後，始得製造","(B) 全廠皆委託他廠製造者仍須符合藥品優良製造準則","(C) 得兼營自製產品之零售業務","(D) 非經核准，不得委託他廠製造或接受委託"],"answer":1,"image":""},{"id":"ph6-112-1-29","subject":"ph6","topic":"藥事法規-藥物廣告與稽查","meta":"112年第1次第29題","year":112,"session":1,"number":29,"question":"依藥事法之規定，下列有關藥品廣告之敘述，何者錯誤？","options":["(A) 藥品廣告不得藉採訪或報導為宣傳","(B) 刊播藥品廣告應向傳播業者送驗核准文件","(C) 廣告屬言論自由範疇，依司法院釋字第744號解釋，藥品廣告採事前審查屬違憲","(D) 學術性醫療刊物可刊登醫師處方藥之廣告"],"answer":2,"image":""},{"id":"ph6-112-1-30","subject":"ph6","topic":"藥事法規-藥物廣告與稽查","meta":"112年第1次第30題","year":112,"session":1,"number":30,"question":"下列何項產品刊播廣告需事先申請核准？","options":["(A) 藥品","(B) 健康食品","(C) 化粧品","(D) 應施檢驗之商品"],"answer":0,"image":""},{"id":"ph6-112-1-31","subject":"ph6","topic":"藥事法規-藥物廣告與稽查","meta":"112年第1次第31題","year":112,"session":1,"number":31,"question":"對於違反藥事法之藥品廣告，下列罰則何者錯誤？","options":["(A) 除依規定處罰外，衛生主管機關得登報公告其負責人姓名、藥品名稱及所犯情節","(B) 違規情節重大者，衛生主管機關並得廢止該藥物許可證；其原品名二年內亦不得申請使用","(C) 藥品廣告在核准登載、刊播期間不得變更原核准事項，違反者處新臺幣二十萬元以上五百萬元以下罰鍰","(D) 傳播業者不得刊播未經核准之藥品廣告。經衛生主管機關通知限期停止而仍繼續刊播者，應廢止其傳播業者執照"],"answer":3,"image":""},{"id":"ph6-112-1-32","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"112年第1次第32題","year":112,"session":1,"number":32,"question":"下列有關藥品製造原料之敘述，何者錯誤？","options":["(A) 申請查驗登記所用之原料依據藥典者，以中華藥典、十大醫藥先進國家出版之藥典，或其他經中央衛生主管機關採用之藥典為限","(B) 藥廠得申請中央衛生主管機關核准，輸入許可證所准成分之原料藥","(C) 藥廠輸入之自用原料，非經核准，不得轉售或轉讓","(D) 原料藥分裝，應申請中央衛生主管機關核准後，由符合藥品優良製造規範之藥品製造業者分裝"],"answer":3,"image":""},{"id":"ph6-112-1-33","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"112年第1次第33題","year":112,"session":1,"number":33,"question":"西藥藥品優良製造規範第三部運銷中所謂之藥品批發運銷不包含下列何者？","options":["(A) 藥品採購","(B) 藥品儲存","(C) 藥品輸入或輸出","(D) 供應藥品給病患"],"answer":3,"image":""},{"id":"ph6-112-1-34","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"112年第1次第34題","year":112,"session":1,"number":34,"question":"於國內建廠生產學名藥藥品，其辦理之下列事項順序為何？①取得國產藥品製造許可證 ②取得製造業藥商許可執照 ③取得工廠登記證 ④通過PIC/S GMP符合性評鑑","options":["(A) ①→②→③→④","(B) ③→④→②→①","(C) ③→②→④→①","(D) ①→③→④→②"],"answer":2,"image":""},{"id":"ph6-112-1-35","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"112年第1次第35題","year":112,"session":1,"number":35,"question":"下列有關藥商管理，何者錯誤？","options":["(A) 申請為藥商者，應申請直轄市或縣（市）衛生主管機關核准登記","(B) 藥商分設營業處所，無須各別辦理藥商登記","(C) 藥商申請停業，每次停業期間不得超過1年，未經核准繼續停業者，應於停業期滿前30日內申請復業","(D) 藥商申請歇業，應自事實發生之日起15日內，向原核准登記之衛生主管機關申請辦理"],"answer":1,"image":""},{"id":"ph6-112-1-36","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"112年第1次第36題","year":112,"session":1,"number":36,"question":"藥品委託製造之產品責任者為下列何者？","options":["(A) 委託者","(B) 製造者","(C) 經銷商","(D) 品管部門"],"answer":0,"image":""},{"id":"ph6-112-1-37","subject":"ph6","topic":"藥事法規-醫療器材管理法","meta":"112年第1次第37題","year":112,"session":1,"number":37,"question":"經稽查或檢驗發現醫療器材有性能或規格與查驗登記、登錄之內容不符者，係屬醫療器材管理法中所稱之：","options":["(A) 未經核准之醫療器材","(B) 不良醫療器材","(C) 高風險醫療器材","(D) 安全監視醫療器材"],"answer":1,"image":""},{"id":"ph6-112-1-38","subject":"ph6","topic":"藥事法規-管制藥品與毒品危害防制","meta":"112年第1次第38題","year":112,"session":1,"number":38,"question":"下列何者非屬管制藥品管理條例之管理範疇？","options":["(A) 管制藥品簿冊登載不詳實","(B) 未依規定定期申報管制藥品收支結存情形","(C) 正當使用管制藥品產生藥害","(D) 非藥事人員調劑管制藥品"],"answer":2,"image":""},{"id":"ph6-112-1-39","subject":"ph6","topic":"藥事法規-管制藥品與毒品危害防制","meta":"112年第1次第39題","year":112,"session":1,"number":39,"question":"依濫用藥物尿液檢驗作業準則之規定，下列敘述何者錯誤？","options":["(A) 司法案件之尿液檢體，得採用最低可定量濃度為閾值","(B) 委驗機構得要求檢驗機構提供原始檢驗紀錄或檢驗結果數值","(C) 提供作為複驗之尿液檢體，應以低於攝氏6度之溫度冷藏保存之","(D) 初步檢驗結果在閾值以上或有疑義之檢體，應再進行確認檢驗"],"answer":2,"image":""},{"id":"ph6-112-1-40","subject":"ph6","topic":"藥事法規-管制藥品與毒品危害防制","meta":"112年第1次第40題","year":112,"session":1,"number":40,"question":"經認定為戒癮治療機構，其執行藥癮戒治之各類人員，每年應接受藥癮治療相關繼續教育至少幾小時？","options":["(A) 6","(B) 8","(C) 10","(D) 3"],"answer":1,"image":""},{"id":"ph6-112-1-41","subject":"ph6","topic":"藥事法規-化粧品衛生安全管理法","meta":"112年第1次第41題","year":112,"session":1,"number":41,"question":"依據化粧品衛生安全管理法之規定，下列有關化粧品之外包裝應明顯標示之事項，何者錯誤？","options":["(A) 淨重、容量或數量","(B) 全成分名稱","(C) 批號","(D) 貱賣業者名稱、地址及電話"],"answer":3,"image":""},{"id":"ph6-112-1-42","subject":"ph6","topic":"藥事法規-化粧品衛生安全管理法","meta":"112年第1次第42題","year":112,"session":1,"number":42,"question":"依化粧品衛生安全管理法之規定，下列有關染髮用途化粧品之敘述，何者錯誤？","options":["(A) 染髮劑為特定用途化粧品","(B) 染髮劑未經中央衛生主管機關查驗而製造，可處業者三年以下有期徒刑","(C) 染髮劑應向衛生福利部申請查驗登記；經核准並發給許可證後，始得輸入","(D) 美髮業者不得將染髮劑之標籤、仿單、外包裝或容器等改變出售"],"answer":1,"image":""},{"id":"ph6-112-1-43","subject":"ph6","topic":"藥事法規-藥害救濟與罕見疾病","meta":"112年第1次第43題","year":112,"session":1,"number":43,"question":"依罕見疾病防治及藥物法之規定，社區藥局藥師若發現有罹患罕見疾病而致死案例，應如何處置？","options":["(A) 經藥品不良反應通報管道通報","(B) 在24至48小時內，向地方主管機關通報","(C) 協助原製造或輸入藥商收集相關資訊","(D) 自發現之日起一個月內向衛生福利部報告"],"answer":3,"image":""},{"id":"ph6-112-1-44","subject":"ph6","topic":"藥事法規-藥害救濟與罕見疾病","meta":"112年第1次第44題","year":112,"session":1,"number":44,"question":"有關藥害救濟制度之保障範圍，下列何者係屬有條件開放？","options":["(A) 指依醫藥專業人員之指示使用藥物","(B) 持有許可證，依法輸入販賣之藥物","(C) 因藥物不良反應，導致死亡、障礙及嚴重疾病","(D) 未依藥物許可證所載之適應症或效能而為藥物之使用案件救濟"],"answer":3,"image":""},{"id":"ph6-112-1-45","subject":"ph6","topic":"藥事法規-藥害救濟與罕見疾病","meta":"112年第1次第45題","year":112,"session":1,"number":45,"question":"下列何者符合申請藥害救濟之要件？","options":["(A) 使用試驗用抗癌藥，致病人骨髓機能永久受損","(B) 椎間盤突出使用carbamazepine，致病人口腔潰爛","(C) 使用降血脂藥lovastatin，致病人發生橫紋肌溶解症","(D) 用藥致殘，法院判決醫師無過失，但已領保險公司殘障險賠償金"],"answer":3,"image":""},{"id":"ph6-112-1-46","subject":"ph6","topic":"藥事法規-全民健康保險與藥事作業","meta":"112年第1次第46題","year":112,"session":1,"number":46,"question":"下列項目何者為可建議納入全民健康保險給付之藥品？","options":["(A) 幼童常規疫苗","(B) 實施鴉片類物質成癮替代療法使用之藥品","(C) 由醫師處方使用之避孕用藥品","(D) 列屬「臨床常用中藥方劑基準方」之複方濃縮中藥"],"answer":3,"image":""},{"id":"ph6-112-1-47","subject":"ph6","topic":"藥事法規-全民健康保險與藥事作業","meta":"112年第1次第47題","year":112,"session":1,"number":47,"question":"下列何者非屬衛生福利部中央健康保險署對於健保特約醫事服務機構，扣減其申報相關醫療費用十倍金額之情事？","options":["(A) 容留未具藥事資格之人員執行藥品調劑工作","(B) 未依處方箋之記載提供醫事服務","(C) 申報明知病人以他人之保險憑證就醫之醫療費用","(D) 以虛偽證明申報醫療費用"],"answer":3,"image":""},{"id":"ph6-112-1-48","subject":"ph6","topic":"藥事法規-全民健康保險與藥事作業","meta":"112年第1次第48題","year":112,"session":1,"number":48,"question":"健保特約藥局受理慢性病連續處方調劑作業時，下列敘述何者錯誤？","options":["(A) 保險對象持慢性病連續處方箋調劑者，須俟上次給藥期間屆滿前十日內，始得憑原處方箋再次調劑","(B) 慢性病連續處方箋，總用藥量至多九十日","(C) 醫師處方之藥物未註明不可替代者，藥師得以相同價格或低於原處方藥物價格之同成分、同劑型、同含量其他廠牌藥品或同功能類別其他廠牌特殊材料替代，並應告知保險對象","(D) 保險對象領藥後，藥品遺失或毀損，得申請健保免費補發"],"answer":3,"image":""},{"id":"ph6-112-1-49","subject":"ph6","topic":"藥事法規-全民健康保險與藥事作業","meta":"112年第1次第49題","year":112,"session":1,"number":49,"question":"依全民健康保險法之規定，藥品逾專利期第幾年開始於幾年內，應由保險人依巿場交易情形逐步調整至合理價格？","options":["(A) 1年，1年","(B) 1年，5年","(C) 2年，5年","(D) 2年，10年"],"answer":1,"image":""},{"id":"ph6-112-1-50","subject":"ph6","topic":"藥事法規-全民健康保險與藥事作業","meta":"112年第1次第50題","year":112,"session":1,"number":50,"question":"某甲持慢性病連續處方箋調劑，依照全民健康保險醫療辦法之規定，下列何種情況某甲不得一次領取該慢性病連續處方箋之總用藥量？","options":["(A) 罕見疾病病人","(B) 返回離島地區","(C) 國內航線航空服務人員","(D) 預定出國"],"answer":2,"image":""},{"id":"ph6-112-2-1","subject":"ph6","topic":"藥事法規-藥政管理組織與衛生行政","meta":"112年第2次第1題","year":112,"session":2,"number":1,"question":"我國為推動衛生醫療工作建立各層級衛生行政體系，下列關於各層級之組織隸屬關係，何者正確？","options":["(A) 中醫藥研究所隸屬於衛生福利部食品藥物管理署","(B) 衛生局隸屬於縣市政府","(C) 鄉鎮市區衛生所隸屬於鄉鎮市區公所","(D) 國家衛生研究院隸屬於國家科學及技術委員會"],"answer":1,"image":""},{"id":"ph6-112-2-2","subject":"ph6","topic":"藥事法規-藥政管理組織與衛生行政","meta":"112年第2次第2題","year":112,"session":2,"number":2,"question":"某企業家捐贈20億元在臺北市北投區設立80床之醫療財團法人醫院，須向何機關申請設立許可？","options":["(A) 臺北市政府衛生局","(B) 衛生福利部","(C) 臺北市政府","(D) 衛生福利部中央健康保險署"],"answer":[1,2],"image":"","answer_note":"更正:第2題答Ｂ或Ｃ或BC者均給分"},{"id":"ph6-112-2-3","subject":"ph6","topic":"藥事法規-新藥臨床試驗與安全監視","meta":"112年第2次第3題","year":112,"session":2,"number":3,"question":"新冠肺炎疫苗經過下列何單位審查後緊急專案核准製造輸入？","options":["(A) 行政院","(B) 財團法人醫藥品查驗中心","(C) 衛生福利部疾病管制署","(D) 衛生福利部"],"answer":3,"image":""},{"id":"ph6-112-2-4","subject":"ph6","topic":"藥事法規-新藥臨床試驗與安全監視","meta":"112年第2次第4題","year":112,"session":2,"number":4,"question":"某新藥之臨床試驗計畫書依法應向下列何者申請審查核准？","options":["(A) 衛生福利部醫事司","(B) 衛生福利部","(C) 衛生福利部中央健康保險署","(D) 衛生福利部食品藥物管理署"],"answer":1,"image":""},{"id":"ph6-112-2-5","subject":"ph6","topic":"藥事法規-藥政管理組織與衛生行政","meta":"112年第2次第5題","year":112,"session":2,"number":5,"question":"有關我國藥政管理組織體系之敘述，下列何者正確？","options":["(A) 衛生福利部食品藥物管理署，係由原行政院衛生署食品衛生處、藥政處、藥物食品檢驗局、管制藥品管理局及中醫藥委員會，合併成立","(B) 衛生福利部食品藥物管理署負責藥品（西藥及中藥）查驗登記許可證之核發","(C) 財團法人醫藥品查驗中心，為衛生福利部食品藥物管理署所屬機構","(D) 管制藥品製藥工廠，為衛生福利部食品藥物管理署所屬"],"answer":3,"image":""},{"id":"ph6-112-2-6","subject":"ph6","topic":"臨床藥學-藥事照護與用藥評估","meta":"112年第2次第6題","year":112,"session":2,"number":6,"question":"下列何者非屬政府推動長期照顧十年計畫2.0之照顧服務對象？","options":["(A) 65歲以上失能老人","(B) 50歲以上的身心障礙者","(C) 55歲失能原住民","(D) 40歲失智個案"],"answer":3,"image":""},{"id":"ph6-112-2-7","subject":"ph6","topic":"藥事法規-藥師法與執業管理","meta":"112年第2次第7題","year":112,"session":2,"number":7,"question":"某診所藥師在執行業務時，因家人發生嚴重意外，須暫時離開藥局趕赴處理。下列敘述何者最適當？","options":["(A) 藥師不在營業場所執行業務時，應於門口懸掛明顯標示。若該標示被人取掉，藥師應負舉證之責，始可免責","(B) 經診所醫師同意後，可委請資深護理人員暫代業務，但不得包括麻醉藥品調劑","(C) 得請診所休假醫師，依藥事法第102條，經報備主管機關後，始可代為執行調劑業務","(D) 若由非護理人員代理調劑業務時，如該藥師確實知情，則此藥師處以罰款6～30萬元，該代理人員另以違反醫療法處罰"],"answer":0,"image":""},{"id":"ph6-112-2-8","subject":"ph6","topic":"藥事法規-藥師法與執業管理","meta":"112年第2次第8題","year":112,"session":2,"number":8,"question":"依據藥局設置作業注意事項，關於藥局之設置，下列何者正確？","options":["(A) 藥局總面積至少18平方公尺之作業區，包含調劑處所、候藥區、受理處方箋與非處方藥品供應區、藥事諮詢服務區、廁所及倉庫","(B) 藥局總面積至少18平方公尺之作業區，包含調劑處所、候藥區、受理處方箋與非處方藥品供應區及藥事諮詢服務區","(C) 藥局總面積至少16平方公尺之作業區，包含調劑處所、候藥區、受理處方箋與非處方藥品供應區、藥事諮詢服務區、廁所及倉庫","(D) 藥局總面積至少16平方公尺之作業區，包含調劑處所、候藥區、受理處方箋與非處方藥品供應區及藥事諮詢服務區"],"answer":1,"image":""},{"id":"ph6-112-2-9","subject":"ph6","topic":"藥事法規-全民健康保險與藥事作業","meta":"112年第2次第9題","year":112,"session":2,"number":9,"question":"依據全民健康保險醫療辦法之規定，非屬慢性病連續處方箋之藥品處方箋，如未遇有例假日，應於開立之日起算幾日內調劑該處方箋？","options":["(A) 一","(B) 三","(C) 五","(D) 七"],"answer":1,"image":""},{"id":"ph6-112-2-10","subject":"ph6","topic":"調劑學-處方判讀與調劑作業","meta":"112年第2次第10題","year":112,"session":2,"number":10,"question":"依據藥品優良調劑作業準則，涉及藥品安定性及有效性之調製作業，下列何者錯誤？","options":["(A) 使用之量測儀器，應定期維護及校正，並製作紀錄，紀錄至少保存2年","(B) 交叉污染的防範，如磨粉時要將前一份粉末殘留清乾淨、粉末型態中藥調劑可設置集塵設備","(C) 除依醫療法規定評鑑合格之醫院，其餘醫療機構或藥局申請執行無菌調製時，應備無菌作業場所及設備、訓練紀錄、無菌調製標準作業程序及環境監測紀錄等相關資料，向中央衛生主管機關申請核准","(D) 粉末型態中藥之調劑作業處所，應設置避免交叉污染之設備"],"answer":0,"image":""},{"id":"ph6-112-2-11","subject":"ph6","topic":"藥事法規-藥師法與執業管理","meta":"112年第2次第11題","year":112,"session":2,"number":11,"question":"依據藥師法施行細則，藥師證書應向何機關請領？","options":["(A) 戶籍所在地衛生局","(B) 衛生福利部食品藥物管理署","(C) 衛生福利部","(D) 考選部"],"answer":2,"image":""},{"id":"ph6-112-2-12","subject":"ph6","topic":"藥事法規-藥師法與執業管理","meta":"112年第2次第12題","year":112,"session":2,"number":12,"question":"依藥師法所訂藥師業務，下列何者錯誤？","options":["(A) 藥品販賣或管理","(B) 處方藥品製造","(C) 藥品儲備、供應及分裝之監督","(D) 藥事照護相關業務"],"answer":1,"image":""},{"id":"ph6-112-2-13","subject":"ph6","topic":"藥事法規-藥師法與執業管理","meta":"112年第2次第13題","year":112,"session":2,"number":13,"question":"依據藥師法，下列關於不得發給藥師執業執照之情形，何者錯誤？","options":["(A) 經撤銷或廢止藥師證書","(B) 經撤銷或廢止藥師執業執照滿一年","(C) 有客觀事實認不能執行業務，經直轄市、縣（市）主管機關邀請相關專科醫師、藥師及學者專家組成小組認定","(D) 受停業處分仍執行業務"],"answer":1,"image":""},{"id":"ph6-112-2-14","subject":"ph6","topic":"藥物治療-呼吸系統疾病","meta":"112年第2次第14題","year":112,"session":2,"number":14,"question":"含可待因（codeine）成分之非處方藥品，禁止供下列何者使用？","options":["(A) 65歲以上老人","(B) 停經婦女","(C) 未滿12歲兒童","(D) 懷孕婦女"],"answer":2,"image":""},{"id":"ph6-112-2-15","subject":"ph6","topic":"藥事法規-藥師法與執業管理","meta":"112年第2次第15題","year":112,"session":2,"number":15,"question":"下列何者屬藥師法所定之藥事照護相關業務？","options":["(A) 與藥事法所稱「藥事」之內容相同","(B) 為受理處方之調劑業務","(C) 於教學醫院執行用藥諮詢之服務事項","(D) 為有關機關委託藥品鑑定業務"],"answer":2,"image":""},{"id":"ph6-112-2-16","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"112年第2次第16題","year":112,"session":2,"number":16,"question":"依藥事法之規定，下列敘述何者正確？","options":["(A) 中醫醫療院所處方調製，如確經中醫師處方，且係由院內調劑人員調製，供特定病患服用，得視為調劑之範圍","(B) 中醫師經常性處方藥品將其商品化，供售予不特定對象，涉違反有關劣藥之規定","(C) 為減少病患等待時間，得於昨天先行將今天預約門診就診者之處方包裝好並寫上姓名","(D) 中醫診所得進行藥品分裝"],"answer":0,"image":""},{"id":"ph6-112-2-17","subject":"ph6","topic":"藥事法規-藥師法與執業管理","meta":"112年第2次第17題","year":112,"session":2,"number":17,"question":"某藥師於民國107年6月畢業，同年10月1日取得藥師證書，下列敘述何者錯誤？","options":["(A) 若進入藥廠擔任藥品行銷人員，藥廠向當地衛生主管機關進行藥品推銷員登錄時，不須申請執業登記","(B) 若在民國109年5月2日首次申請藥師執業登記，其執業執照更新日不得逾民國114年10月1日","(C) 若於民國112年9月30日前首次執業，不須提出繼續教育證明文件","(D) 若於民國113年10月1日首次執業，必須具備登記日前一年內繼續教育至少二十積分數"],"answer":1,"image":""},{"id":"ph6-112-2-18","subject":"ph6","topic":"藥事法規-新藥臨床試驗與安全監視","meta":"112年第2次第18題","year":112,"session":2,"number":18,"question":"藥品上市後相關之管理及規範，下列何者不需予以考慮？","options":["(A) 藥物非臨床試驗優良操作規範","(B) 藥品安全監視管理辦法","(C) 西藥優良運銷準則","(D) 藥物優良製造準則"],"answer":0,"image":""},{"id":"ph6-112-2-19","subject":"ph6","topic":"藥事法規-新藥臨床試驗與安全監視","meta":"112年第2次第19題","year":112,"session":2,"number":19,"question":"下列有關某抗癌新藥臨床試驗的敘述，何者最適當？","options":["(A) 如試驗結果已顯示該新藥安全有效，試驗委託者可不需依原核准之計畫執行完畢，可逕行申請提前結案，並申請查驗登記","(B) 於該試驗期間，如醫療機構發現有特殊結果，即可對外公開發表成果","(C) 如因納入之受試者人數嚴重不足，試驗委託者經主持人同意後，方能終止該試驗","(D) 該試驗新藥，屬尚未核發藥證之試用產品，得不受藥品優良製造規範之規範"],"answer":[0,1,2,3],"image":"","answer_note":"送分:第19題一律給分 (原公告答案 A)"},{"id":"ph6-112-2-20","subject":"ph6","topic":"藥事法規-新藥臨床試驗與安全監視","meta":"112年第2次第20題","year":112,"session":2,"number":20,"question":"某藥廠發明可治療憂鬱症的新藥，其有無可能在八里療養院，進行臨床試驗？","options":["(A) 否；該療養院非屬教學醫院，與現行法規之規定不符","(B) 是；若該療養院經衛生福利部同意，可施行此臨床試驗","(C) 是；經該療養院之倫理委員會認證通過，即可施行","(D) 是；若該療養院與醫學中心合作，則可使用該醫學中心之受試者同意書，施行此臨床試驗"],"answer":1,"image":""},{"id":"ph6-112-2-21","subject":"ph6","topic":"調劑學-處方判讀與調劑作業","meta":"112年第2次第21題","year":112,"session":2,"number":21,"question":"依據藥品優良調劑作業準則之規定，藥局供調劑之中藥，自拆封至調劑期間應注意之事項，下列敘述何者錯誤？","options":["(A) 中藥製劑應注意專業包裝藥品之包裝材料","(B) 中藥飲片應注意專業藥品之貯存環境","(C) 中藥飲片只須標示飲片名稱","(D) 中藥製劑應標示藥品名稱、保存期限及單位含量"],"answer":2,"image":""},{"id":"ph6-112-2-22","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"112年第2次第22題","year":112,"session":2,"number":22,"question":"依據藥事法，對於藥局的管理規定，下列敘述何者錯誤？","options":["(A) 藥師親自主持之藥局，具有鑑定設備者，得執行藥品之鑑定業務","(B) 藥局如要販售第一等級之醫療器材，得免請領醫療器材販賣業許可執照","(C) 凡取得藥師執照之藥師所親自主持之藥局，即可兼營中藥之零售業務","(D) 無論是藥師或藥劑生，親自主持且有二年以上實際調劑執業經驗者，都可向轄區衛生局請領藥局執照"],"answer":2,"image":""},{"id":"ph6-112-2-23","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"112年第2次第23題","year":112,"session":2,"number":23,"question":"有關藥事法對於藥品回收之規定，下列敘述何者錯誤？","options":["(A) 屬於依法認定之偽藥或禁藥，其製造或輸入之業者，應即通知醫療機構、藥局及藥商，並於依法認定應回收之日起一個月內收回市售品","(B) 屬於依法認定之劣藥，經中央衛生主管機關認定對使用者生命、身體或健康有發生重大損害之虞者，應即通知醫療機構、藥局及藥商，並於依法認定應回收之日起一個月內收回市售品","(C) 屬於藥品許可證不准展延者，其製造或輸入之業者，應即通知醫療機構、藥局及藥商，並於依法認定應回收之日起二個月內收回市售品","(D) 屬於藥品包裝經核准變更登記者，應即通知醫療機構、藥局及藥商，並於依法認定應回收之日起六個月內收回市售品"],"answer":2,"image":""},{"id":"ph6-112-2-24","subject":"ph6","topic":"藥事法規-藥物廣告與稽查","meta":"112年第2次第24題","year":112,"session":2,"number":24,"question":"有關藥事法對於藥品廣告之規定，下列敘述何者錯誤？","options":["(A) 領有藥品許可證之藥商於刊播前，應填具申請書申請","(B) 藥品廣告於核准後，有任何變更內容也要再申請","(C) 只有指示藥及成藥，可以刊登於電視廣告","(D) 中藥材之廣告應於刊播前申請，其效能以本草備要所載者為限"],"answer":3,"image":""},{"id":"ph6-112-2-25","subject":"ph6","topic":"藥事法規-藥物廣告與稽查","meta":"112年第2次第25題","year":112,"session":2,"number":25,"question":"有關藥事法對於藥品廣告之規定，下列敘述何者正確？","options":["(A) 接受委託刊播之傳播業者，應自廣告之日起一年，保存委託刊播廣告者之姓名、身分證或事業登記證字號、住居所及電話等資料","(B) 接受委託刊播之傳播業者，對於主管機關要求提供委託刊播廣告者之姓名、身分證及電話等資料，因屬客戶個人資料，得不予提供","(C) 藥品廣告在核准登載、刊播期間不得變更原核准事項","(D) 藥品廣告原核准機關發現已核准之藥品廣告內容或刊播方式危害民眾健康時，因藥品廣告已有核准有效期間，須待原核准之廣告屆期展延時，始得令藥商改善"],"answer":2,"image":""},{"id":"ph6-112-2-26","subject":"ph6","topic":"臨床藥學-藥物不良反應與交互作用","meta":"112年第2次第26題","year":112,"session":2,"number":26,"question":"診所得知下列何項嚴重藥物不良反應致生之情形，須於七日內依法進行通報？","options":["(A) 胎嬰兒先天性畸形","(B) 導致病人住院","(C) 延長病人住院時間","(D) 死亡"],"answer":3,"image":""},{"id":"ph6-112-2-27","subject":"ph6","topic":"藥事法規-新藥臨床試驗與安全監視","meta":"112年第2次第27題","year":112,"session":2,"number":27,"question":"藥商應自中央衛生主管機關核發新藥藥品許可證之日起多少年內，繳交藥品安全性定期報告？","options":["(A) 一年","(B) 三年","(C) 五年","(D) 七年"],"answer":2,"image":""},{"id":"ph6-112-2-28","subject":"ph6","topic":"藥事法規-醫療器材管理法","meta":"112年第2次第28題","year":112,"session":2,"number":28,"question":"依據醫療器材管理法及醫療器材品質管理系統準則，下列何者錯誤？","options":["(A) 醫療器材品質管理系統準則規範，係參照國際標準組織醫療器材品質管理系統ISO13485之內容訂定","(B) 醫療器材製造業者應以書面訂定產品設計開發之程序及要求","(C) 醫療器材製造業者應訂定供應商之評估及選擇基準","(D) 經公告之醫療器材品項，其製造業者應建立醫療器材品質管理系統"],"answer":3,"image":""},{"id":"ph6-112-2-29","subject":"ph6","topic":"藥事法規-醫療器材管理法","meta":"112年第2次第29題","year":112,"session":2,"number":29,"question":"有關醫療器材登錄及年度申報，下列何者錯誤？","options":["(A) 製造、輸入醫療器材，應向中央主管機關申請查驗登記，經核准發給醫療器材許可證後，始得為之。但第一等級之醫療器材品項，其製造、輸入應以登錄方式為之","(B) 醫療器材登錄之事項，經中央主管機關指定者，其變更應報中央主管機關核准後，始得為之","(C) 醫療器材商完成醫療器材登錄者，每年應向中央主管機關辦理年度申報","(D) 申請醫療器材登錄者，應於中央主管機關建置之醫療器材登錄系統登錄"],"answer":0,"image":""},{"id":"ph6-112-2-30","subject":"ph6","topic":"藥事法規-新藥臨床試驗與安全監視","meta":"112年第2次第30題","year":112,"session":2,"number":30,"question":"依據藥品查驗登記審查準則，某一輸入新成分（化學小分子）新藥查驗登記申請案，檢附資料得不包含下列何者？","options":["(A) 賦形劑檢驗規格、方法及檢驗成績書","(B) 處方依據","(C) 分析方法確效資料","(D) 符合藥品優良製造規範之證明文件影本"],"answer":1,"image":""},{"id":"ph6-112-2-31","subject":"ph6","topic":"調劑學-藥品包裝標示與儲存","meta":"112年第2次第31題","year":112,"session":2,"number":31,"question":"依據藥品查驗登記審查準則，關於標籤、仿單及包裝之敘述，下列何者正確？","options":["(A) 仿單應詳實刊載禁忌、警語、副作用及注意事項，但不應使用紅字或加印紅框或使用粗黑異體字，以免影響病患用藥順從性","(B) 中文品名之字體應小於外文字體，但須清晰可辨，並以單一中文品名字體高度與單一外文字母之高度為比對標準","(C) 鋁箔盒裝之每一片鋁箔紙上，均應刊印藥品名稱且應以中文為主；並得刊印其廠名及許可證字號","(D) 藥品之標籤或包裝關於刊載批號、製造日期、有效期間、保存期限之方式，若僅能顯示兩項目，則須刊載批號與製造日期"],"answer":2,"image":""},{"id":"ph6-112-2-32","subject":"ph6","topic":"藥事法規-新藥臨床試驗與安全監視","meta":"112年第2次第32題","year":112,"session":2,"number":32,"question":"依據人體試驗管理辦法，人體試驗計畫審查應注意之事項，不包含下列何者？","options":["(A) 人體試驗設計應符合最低風險原則，並考量合理之風險、利益","(B) 易受傷害族群之排除","(C) 受試者之醫療照護及損害補償或其他救濟機制","(D) 受試者同意書內容及告知程序"],"answer":1,"image":""},{"id":"ph6-112-2-33","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"112年第2次第33題","year":112,"session":2,"number":33,"question":"依藥事法之規定，下列有關藥品追溯或追蹤之敘述，何者錯誤？","options":["(A) 應於每月十日前，將上月份資訊，以電子方式申報至追溯或追蹤申報系統","(B) 適用中央衛生主管機關公告類別之品項","(C) 管制藥品已納入藥品追溯或追蹤系統管理","(D) 疫苗、血液製劑及肉毒桿菌毒素，皆應以電子方式申報至追溯或追蹤申報系統"],"answer":2,"image":""},{"id":"ph6-112-2-34","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"112年第2次第34題","year":112,"session":2,"number":34,"question":"下列有關偽藥之處理，何者錯誤？","options":["(A) 直轄市或縣（市）衛生主管機關對於涉嫌之偽藥，應先行就地封存，並抽取樣品檢驗","(B) 依法認定為偽藥，回收期限由直轄市或縣（市）衛生主管機關依個案性質決定，最長不得超過二個月","(C) 製造或輸入業者執行偽藥回收作業前，應訂定回收作業計畫書，報中央衛生主管機關備查後，依計畫書執行","(D) 查獲之偽藥應沒入銷燬"],"answer":1,"image":""},{"id":"ph6-112-2-35","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"112年第2次第35題","year":112,"session":2,"number":35,"question":"依藥事法之規定，學名藥藥品許可證申請人，向中央衛生主管機關聲明未侵害該新藥對應之專利權，其申請資料齊備日最早者，取得多少個月之銷售專屬期間？","options":["(A) 6","(B) 9","(C) 12","(D) 18"],"answer":2,"image":""},{"id":"ph6-112-2-36","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"112年第2次第36題","year":112,"session":2,"number":36,"question":"某藥品成分為aspirin，核定之適應症為「解熱鎮痛」，經稽查發現製造者擅自將適應症增加「冠狀動脈疾病」，此藥品係屬藥事法所稱之：","options":["(A) 劣藥","(B) 偽藥","(C) 禁藥","(D) 管制藥品"],"answer":0,"image":""},{"id":"ph6-112-2-37","subject":"ph6","topic":"藥事法規-醫療器材管理法","meta":"112年第2次第37題","year":112,"session":2,"number":37,"question":"有關醫療器材之敘述，下列何者錯誤？","options":["(A) 性能或有效成分之質、量或強度，與核准不符者，其製造或輸入者，處行政罰鍰","(B) 超過有效期間者，其製造或輸入者，移送檢察機關偵辦","(C) 經依法認定為第三級應回收之醫療器材，回收期限最長不超過六個月","(D) 含有害物質致使用時有損人體健康者，其製造或輸入者，移送檢察機關偵辦"],"answer":1,"image":""},{"id":"ph6-112-2-38","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"112年第2次第38題","year":112,"session":2,"number":38,"question":"某報刊載國內某廠製造之「活鳥茶」飲料廣告，其刊載之文字暗示性功能療效，經衛生局抽驗檢出達到治療劑量之威而鋼成分，該品應依下列何者處理？","options":["(A) 廣告誇大不實之食品","(B) 違法食品","(C) 禁藥","(D) 偽藥"],"answer":3,"image":""},{"id":"ph6-112-2-39","subject":"ph6","topic":"藥事法規-管制藥品與毒品危害防制","meta":"112年第2次第39題","year":112,"session":2,"number":39,"question":"依據管制藥品管理條例，下列何者不得使用管制藥品？","options":["(A) 醫師","(B) 牙醫師","(C) 藥師","(D) 獸醫師"],"answer":2,"image":""},{"id":"ph6-112-2-40","subject":"ph6","topic":"藥事法規-管制藥品與毒品危害防制","meta":"112年第2次第40題","year":112,"session":2,"number":40,"question":"下列管制藥品相關文件之使用，何者非以1次為限？","options":["(A) 製造同意書","(B) 輸出入同意書","(C) 管制藥品專用處方箋","(D) 輸出入憑照"],"answer":[0,1,2,3],"image":"","answer_note":"送分:第40題一律給分 (原公告答案 C)"},{"id":"ph6-112-2-41","subject":"ph6","topic":"藥事法規-管制藥品與毒品危害防制","meta":"112年第2次第41題","year":112,"session":2,"number":41,"question":"下列何藥之輸入、輸出應向衛生福利部食品藥物管理署申請核發憑照，且其輸入、輸出口岸，由中央衛生主管機關核定之？","options":["(A) 氟硝西泮（flunitrazepam）","(B) 硫美妥（thiamylal）","(C) 美沙冬（methadone）","(D) 丁基原啡因（buprenorphine）"],"answer":2,"image":""},{"id":"ph6-112-2-42","subject":"ph6","topic":"藥事法規-化粧品衛生安全管理法","meta":"112年第2次第42題","year":112,"session":2,"number":42,"question":"依據化粧品衛生安全管理法，下列何者非屬化粧品之外包裝或容器，應明顯標示之事項？","options":["(A) 批號","(B) 登錄字號","(C) 用法及保存方法","(D) 全成分名稱"],"answer":1,"image":""},{"id":"ph6-112-2-43","subject":"ph6","topic":"藥事法規-藥害救濟與罕見疾病","meta":"112年第2次第43題","year":112,"session":2,"number":43,"question":"依據藥害救濟法，藥害救濟審議委員會的組成，不包含下列何者？","options":["(A) 法學專家","(B) 政府官員代表","(C) 醫藥學專家","(D) 社會公正人士"],"answer":1,"image":""},{"id":"ph6-112-2-44","subject":"ph6","topic":"藥事法規-藥害救濟與罕見疾病","meta":"112年第2次第44題","year":112,"session":2,"number":44,"question":"關於預防接種受害救濟案件，下列何者非屬不予救濟之情形？","options":["(A) 常見、輕微之可預期預防接種不良反應","(B) 轉化症或其他心理因素所致之障礙","(C) 不良反應與預防接種確定無關","(D) 母體因預防接種而發生嚴重疾病"],"answer":3,"image":""},{"id":"ph6-112-2-45","subject":"ph6","topic":"藥事法規-藥害救濟與罕見疾病","meta":"112年第2次第45題","year":112,"session":2,"number":45,"question":"下列何者不是藥害救濟法第13條所列之排除條款？","options":["(A) 常見且可預期之藥物不良反應","(B) 因接受預防接種而受害","(C) 有事實足以認定藥害之產生應由其他人負責","(D) 因使用管制藥品而受害"],"answer":3,"image":""},{"id":"ph6-112-2-46","subject":"ph6","topic":"藥事法規-全民健康保險與藥事作業","meta":"112年第2次第46題","year":112,"session":2,"number":46,"question":"依據全民健康保險法，有關保險對象於保險醫事服務機構就醫時應自行負擔費用之敘述，下列何者錯誤？","options":["(A) 應自行負擔門診或急診費用之百分之二十","(B) 應自行負擔居家照護醫療費用之百分之五","(C) 未經轉診，於醫學中心門診就醫者，應自行負擔門診或急診費用之百分之五十","(D) 未經轉診，於區域醫院門診就醫者，應自行負擔門診或急診費用之百分之三十"],"answer":[0,3],"image":"","answer_note":"更正:第46題答Ａ或Ｄ或AD者均給分"},{"id":"ph6-112-2-47","subject":"ph6","topic":"藥事法規-全民健康保險與藥事作業","meta":"112年第2次第47題","year":112,"session":2,"number":47,"question":"依據全民健康保險藥品價格調整作業辦法，關於保險人進行藥價調整之敘述，下列何者錯誤？","options":["(A) 得對具標準包裝之藥品訂定基本價及下限價","(B) 下限價即最低調整價格，保險人於價格調整過程中調整前支付價格低於下限價者，不予調整","(C) 指示用藥之品項如為健保已經收載品項，適用藥品價格調整作業辦法所訂之下限價","(D) 經專家認定之劑型或包裝不具臨床意義者，不訂基本價"],"answer":2,"image":""},{"id":"ph6-112-2-48","subject":"ph6","topic":"藥事法規-全民健康保險與藥事作業","meta":"112年第2次第48題","year":112,"session":2,"number":48,"question":"依據全民健康保險法，對於家庭責任醫師制度之設計，下列何者錯誤？","options":["(A) 為了促進預防醫學","(B) 為了落實轉診制度","(C) 透過轉診，被保險人至各層級保險醫事服務機構就醫得享減免部分負擔","(D) 提升醫療品質與醫病關係"],"answer":[0,1,2,3],"image":"","answer_note":"送分:第48題一律給分 (原公告答案 C)"},{"id":"ph6-112-2-49","subject":"ph6","topic":"藥事法規-藥師法與執業管理","meta":"112年第2次第49題","year":112,"session":2,"number":49,"question":"某藥師登記執業於臺北市，但於桃園市某建築物之看板代言某藥品，超出該藥品核定之適應症，致誤導消費者誤信而購買。有關上開情事之懲戒，下列敘述何者正確？","options":["(A) 可由臺北市藥師公會移付懲戒","(B) 可由桃園市政府衛生局移付懲戒","(C) 藥師不服懲戒委員會之決議，應向衛生福利部請求覆審","(D) 藥師懲戒委員會之懲戒決議，應送由台北市政府衛生局處以罰鍰"],"answer":0,"image":""},{"id":"ph6-112-2-50","subject":"ph6","topic":"藥事法規-全民健康保險與藥事作業","meta":"112年第2次第50題","year":112,"session":2,"number":50,"question":"依全民健康保險法之規定，保險人應依下列何者合理調整藥品價格？","options":["(A) 市場交易情形","(B) 藥品研發成本","(C) 藥品逾專利期第五年起","(D) 政府採購法及公平交易法"],"answer":0,"image":""},{"id":"ph6-113-1-1","subject":"ph6","topic":"藥事法規-藥政管理組織與衛生行政","meta":"113年第1次第1題","year":113,"session":1,"number":1,"question":"為提升醫療機構之服務品質，政府必須辦理醫療機構評鑑或督導考核，下列敘述何者錯誤？","options":["(A) 醫院接受評鑑每4年1次，不需要接受督導考核","(B) 診所接受督導考核每年1次，不需要接受評鑑","(C) 醫院評鑑由衛生福利部辦理","(D) 診所督導考核由地方衛生主管機關辨理"],"answer":0,"image":""},{"id":"ph6-113-1-2","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"113年第1次第2題","year":113,"session":1,"number":2,"question":"衛生福利部疾病管制署為推動國民預防接種政策，訂定相關管理措施，下列敘述何者正確？","options":["(A) 設置疫苗基金，並接受企業捐款指定購買特定新冠病毒疫苗","(B) 預防接種服務可由經過訓練認可之護理師執行，疫苗不需經藥師調劑","(C) 民眾因自費接受預防接種而受害者，政府不予補償","(D) 因預防接種而受害者，應於受害發生日起2年內提出請求補償"],"answer":1,"image":""},{"id":"ph6-113-1-3","subject":"ph6","topic":"藥事法規-藥政管理組織與衛生行政","meta":"113年第1次第3題","year":113,"session":1,"number":3,"question":"下列何者不是藥事法之衛生主管機關？","options":["(A) 衛生福利部","(B) 財團法人醫藥品查驗中心","(C) 臺北市政府","(D) 基隆市政府"],"answer":1,"image":""},{"id":"ph6-113-1-4","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"113年第1次第4題","year":113,"session":1,"number":4,"question":"下列何者不是藥局依藥事法執行之業務？","options":["(A) 藥品調劑","(B) 中央衛生主管機關所定之第一等級醫療器材零售","(C) 藥品零售","(D) 藥品分裝"],"answer":3,"image":""},{"id":"ph6-113-1-5","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"113年第1次第5題","year":113,"session":1,"number":5,"question":"藥商持有經中央衛生主管機關公告為必要藥品之許可證，如有不足供應該藥品之虞時，應至少於幾個月前向中央衛生主管機關通報？","options":["(A) 3","(B) 6","(C) 9","(D) 12"],"answer":1,"image":""},{"id":"ph6-113-1-6","subject":"ph6","topic":"藥事法規-藥物廣告與稽查","meta":"113年第1次第6題","year":113,"session":1,"number":6,"question":"有關網路販售之敘述，下列何者錯誤？","options":["(A) 網路販售藥品，其網頁登載之資訊內容，涉及藥品廣告者，應依藥事法規定申請核准","(B) 網路平台業者，不得刊播未經衛生主管機關核准、與核准事項不符之廣告","(C) 僅藥商或藥局可於網路販售乙類成藥","(D) 應於網頁明顯可見之處，以消費者得清楚辨識之方式，揭露藥品許可證所載核准字號、品名、適應症、藥商名稱等資訊"],"answer":2,"image":""},{"id":"ph6-113-1-7","subject":"ph6","topic":"藥事法規-藥政管理組織與衛生行政","meta":"113年第1次第7題","year":113,"session":1,"number":7,"question":"衛生福利部於民國109年指定COVID-19為第幾類傳染病？","options":["(A) 第一類","(B) 第三類","(C) 第四類","(D) 第五類"],"answer":3,"image":""},{"id":"ph6-113-1-8","subject":"ph6","topic":"藥事法規-全民健康保險與藥事作業","meta":"113年第1次第8題","year":113,"session":1,"number":8,"question":"某藥局藥師租借另一藥師之證照，向衛生福利部中央健康保險署申報健保醫療費用。下列敘述何者最不適當？","options":["(A) 依規定得由藥師公會移付懲戒","(B) 衛生福利部中央健康保險署得停止特約，並追扣詐領款項","(C) 該藥師雖經法院緩起訴處分，依規定仍可移付懲戒","(D) 該藥師經法院判定需參加法治教育2小時，此可抵藥師懲戒之繼續教育時數"],"answer":3,"image":""},{"id":"ph6-113-1-9","subject":"ph6","topic":"藥事法規-藥師法與執業管理","meta":"113年第1次第9題","year":113,"session":1,"number":9,"question":"下列何者非屬藥師執行藥師法施行細則所定藥事照護相關業務之處所？","options":["(A) 愛心藥房","(B) 安心診所","(C) 健康醫院","(D) 開心護理之家"],"answer":0,"image":""},{"id":"ph6-113-1-10","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"113年第1次第10題","year":113,"session":1,"number":10,"question":"依據藥事法，須由醫師處方之藥品，非經醫師處方，不得調劑供應。下列那些情形不受上述限制？①同業藥商之批發、販賣 ②學術研究機構之購買 ③依中華藥典、國民處方選輯處方之調劑 ④獸醫診所之購買","options":["(A) ①②④","(B) ①②③","(C) ①③④","(D) ②③④"],"answer":1,"image":""},{"id":"ph6-113-1-11","subject":"ph6","topic":"調劑學-藥品包裝標示與儲存","meta":"113年第1次第11題","year":113,"session":1,"number":11,"question":"依據藥品優良調劑作業準則，下列何者錯誤？","options":["(A) 飲片自拆封至調劑期間保存應注意包裝之材料及儲存環境","(B) 藥品以原包裝為主，不論排裝、散裝、飲片皆以拆封後6個月為有效期限","(C) 中西藥製劑及飲片拆封後應標示藥品名稱及保存期限","(D) 調劑藥品進貨來源憑證及其他相關文件、資料，至少保存三年"],"answer":1,"image":""},{"id":"ph6-113-1-12","subject":"ph6","topic":"臨床藥學-藥事照護與用藥評估","meta":"113年第1次第12題","year":113,"session":1,"number":12,"question":"為增進藥物療程之效益及生活品質，近年來藥師致力於執行藥事照護相關業務，下列那一項為藥事法施行細則第13條第1款所明定之職責？","options":["(A) 考量藥物使用情形及評估藥品差額負擔之藥事服務事項","(B) 考量藥物使用情形及評估療效之藥事服務事項","(C) 考量藥物使用情形及通報藥品不良反應之藥事服務事項","(D) 考量藥物使用情形及調劑藥品之藥事服務事項"],"answer":1,"image":""},{"id":"ph6-113-1-13","subject":"ph6","topic":"藥事法規-藥師法與執業管理","meta":"113年第1次第13題","year":113,"session":1,"number":13,"question":"某藥學系畢業生取得藥師考試及格證書後即出國進修，4年後取得博士學位後回國至某醫學中心擔任藥師，有關須辦理之相關行政程序，下列敘述何者錯誤？","options":["(A) 須先向衛生福利部食品藥物管理署取得藥師證書","(B) 須加入該醫學中心所在地藥師公會","(C) 不需要提供繼續教育之證明文件","(D) 取得執業執照後之更新日期為取得藥師證書後屆滿第六年之翌日"],"answer":0,"image":""},{"id":"ph6-113-1-14","subject":"ph6","topic":"藥事法規-藥師法與執業管理","meta":"113年第1次第14題","year":113,"session":1,"number":14,"question":"藥師因業務上重大或重複發生過失行為須移付懲戒，下列敘述何者錯誤？","options":["(A) 由藥師公會移付懲戒","(B) 懲戒之方式可廢止藥師證書","(C) 藥師移付懲戒事件，由藥師懲戒委員會處理之","(D) 藥師對於懲戒結果不服可以向縣市政府懲戒覆審委員會提出"],"answer":3,"image":""},{"id":"ph6-113-1-15","subject":"ph6","topic":"藥事法規-藥物廣告與稽查","meta":"113年第1次第15題","year":113,"session":1,"number":15,"question":"依據藥事法施行細則，下列何者不是藥物廣告應一併登載或宣播之內容？","options":["(A) 廠商名稱","(B) 藥物許可證","(C) 藥品有效成分","(D) 廣告核准文件字號"],"answer":2,"image":""},{"id":"ph6-113-1-16","subject":"ph6","topic":"藥事法規-藥師法與執業管理","meta":"113年第1次第16題","year":113,"session":1,"number":16,"question":"下列有關藥師於診所執業之敘述，何者錯誤？","options":["(A) 於診所執業登記之藥師，如欲在其他診所支援，必須事先向執業所在地主管機關報准","(B) 藥師休息時間不在場，不可由非藥師調劑並申報健保情事","(C) 若診所第二位藥師要請產假，可找藥師支援，惟支援藥師須事先向所在地主管機關報准","(D) 若診所藥師全部離職，可請其他診所藥師事先向所在地主管機關報准支援"],"answer":3,"image":""},{"id":"ph6-113-1-17","subject":"ph6","topic":"藥事法規-藥師法與執業管理","meta":"113年第1次第17題","year":113,"session":1,"number":17,"question":"依藥師法之規定，下列敘述何者錯誤？","options":["(A) 藥師非加入所在地藥師公會，不得執業","(B) 藥師停業或歇業時，應自事實發生之日起十五日內，報請原發執業執照之主管機關備查","(C) 因業務而知悉他人之秘密，不得無故洩漏","(D) 藥師執業執照，應向所在地直轄市或縣（市）主管機關申請"],"answer":1,"image":""},{"id":"ph6-113-1-18","subject":"ph6","topic":"藥事法規-新藥臨床試驗與安全監視","meta":"113年第1次第18題","year":113,"session":1,"number":18,"question":"下列有關臨床試驗的敘述，何者最不適當？","options":["(A) 人體試驗委員會之委員組成中，至少一位為非科學背景者","(B) 試驗機構應接受試驗委託者之監測與稽核","(C) 試驗委託者應負責甄選試驗主持人，並對試驗機構執行計畫監測","(D) 管理藥師應持續進行試驗藥品之安全性評估"],"answer":3,"image":""},{"id":"ph6-113-1-19","subject":"ph6","topic":"藥事法規-新藥臨床試驗與安全監視","meta":"113年第1次第19題","year":113,"session":1,"number":19,"question":"依據藥品優良試驗作業準則，有關藥品臨床試驗之紀錄與報告的敘述，下列何者最適當？","options":["(A) 個案報告表如有修正，得以修正帶覆蓋之，但須簽章並註記修正原因","(B) 個案報告表中的資料，如與原始資料有差異，應解釋其原因","(C) 試驗主持人應妥善保存所有臨床試驗相關重要文件至試驗藥品於我國獲准上市後至少五年","(D) 僅試驗主持人有權修正電子資料"],"answer":1,"image":""},{"id":"ph6-113-1-20","subject":"ph6","topic":"藥事法規-全民健康保險與藥事作業","meta":"113年第1次第20題","year":113,"session":1,"number":20,"question":"依據全民健康保險醫事服務機構特約及管理辦法，有關不予特約之規定，下列何者錯誤？","options":["(A) 與保險人有未結案件，且拒絕配合辦結","(B) 負責醫事人員執業執照逾有效期限，未辦理更新","(C) 負責醫師具中醫師及藥事人員資格者，僅得依其執業執照登記之類別，申請特約","(D) 違反醫事法令，受停業處分期間未屆滿，或受罰鍰處分未繳清"],"answer":2,"image":""},{"id":"ph6-113-1-21","subject":"ph6","topic":"藥事法規-藥物廣告與稽查","meta":"113年第1次第21題","year":113,"session":1,"number":21,"question":"依據藥事法、醫療器材管理法與化粧品衛生安全管理法，下列與廣告相關之敘述何者正確？","options":["(A) 中藥廣告有效期間為二年","(B) 醫療器材廣告有效期間為三年","(C) 化粧品廣告應由化粧品業者於廣告前向衛生單位申請核准，才能刊播","(D) 處方藥向衛生單位申請後可在電視台廣告"],"answer":1,"image":""},{"id":"ph6-113-1-22","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"113年第1次第22題","year":113,"session":1,"number":22,"question":"下列何者不得於網路販售？","options":["(A) 化粧品","(B) 乙類成藥","(C) 甲類成藥","(D) 第一等級醫療器材"],"answer":2,"image":""},{"id":"ph6-113-1-23","subject":"ph6","topic":"藥事法規-新藥臨床試驗與安全監視","meta":"113年第1次第23題","year":113,"session":1,"number":23,"question":"藥商得知下列何項嚴重藥物不良反應致生之情事，須於十五日內進行通報？①死亡 ②危及生命 ③造成永久性殘疾 ④胎嬰兒先天性畸形 ⑤導致病人住院","options":["(A) 僅①②","(B) 僅③④⑤","(C) 僅⑤","(D) ①②③④⑤"],"answer":3,"image":""},{"id":"ph6-113-1-24","subject":"ph6","topic":"藥事法規-醫療器材管理法","meta":"113年第1次第24題","year":113,"session":1,"number":24,"question":"依據醫療器材許可證核發與登錄及年度申報準則，醫療器材之標籤、說明書或包裝變更時，有下列何種情形者，許可證所有人得自行變更，並製作變更紀錄？","options":["(A) 變更產品效能、用途","(B) 變更經中央主管機關核准變更之醫療器材製造業者名稱","(C) 變更產品型號、規格","(D) 變更產品中文品名"],"answer":1,"image":""},{"id":"ph6-113-1-25","subject":"ph6","topic":"藥事法規-醫療器材管理法","meta":"113年第1次第25題","year":113,"session":1,"number":25,"question":"依據醫療器材管理法、醫療器材優良運銷準則及醫療器材優良運銷檢查及運銷許可核發辦法規定，下列敘述何者錯誤？","options":["(A) 所有醫療器材及其販賣業者，皆應建立醫療器材優良運銷系統，並應符合醫療器材優良運銷準則","(B) 醫療器材販賣業者，依醫療器材優良運銷準則規定，建立醫療器材優良運銷系統，並報中央主管機關檢查合格，取得運銷許可後，始得批發、輸入或輸出","(C) 運銷許可有效期間為三年","(D) 醫療器材販賣業者，應就運銷系統，依醫療器材產品要求，以書面訂定防護程序，確保產品之品質不受儲存、搬運或運輸過程之影響"],"answer":0,"image":""},{"id":"ph6-113-1-26","subject":"ph6","topic":"藥事法規-醫療器材管理法","meta":"113年第1次第26題","year":113,"session":1,"number":26,"question":"依醫療器材管理法規定，有關醫療器材臨床試驗，下列何者錯誤？","options":["(A) 臨床試驗機構或試驗委託者發起醫療器材臨床試驗，應申請中央主管機關核准後，始得為之。但無顯著風險經中央主管機關公告者，不在此限","(B) 臨床試驗機構執行醫療器材臨床試驗，應善盡醫療上必要之注意，並務必先取得受試者之同意","(C) 醫療器材臨床試驗之受試者，於臨床試驗施行期間，發生需住院情事者，臨床試驗機構及試驗委託者應通報中央主管機關","(D) 中央主管機關認醫療器材臨床試驗有危害人體健康之虞者，得令試驗之機構中止或終止試驗"],"answer":1,"image":""},{"id":"ph6-113-1-27","subject":"ph6","topic":"藥事法規-醫療器材管理法","meta":"113年第1次第27題","year":113,"session":1,"number":27,"question":"醫療器材商甲公司登記之營業地址位於臺北市，其輸入已取得醫療器材許可證之手術用手套，輸入後經衛生局檢驗發現，某批號產品之性能與查驗登記之內容不符，依醫療器材管理法規定，下列何者錯誤？","options":["(A) 該批號手術用手套為不良醫療器材","(B) 甲公司應即通知醫事機構、其他醫療器材商及藥局，並依規定期限回收處理該批號手術用手套之市售品及庫存品","(C) 該批號手術用手套經檢驗後仍可改製使用，應由臺北市政府衛生局派員監督甲公司限期改製；屆期未改製者，沒入銷燬之","(D) 甲公司如再次違反規定，得由原核准機關廢止其各該醫療器材許可證或登錄、醫療器材製造許可或令其停止營業"],"answer":2,"image":""},{"id":"ph6-113-1-28","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"113年第1次第28題","year":113,"session":1,"number":28,"question":"依據藥品查驗登記審查準則，關於原料藥申請案之敘述，下列何者錯誤？","options":["(A) 製劑申請新增或變更原料藥來源，若依劑型特性之製劑成品檢驗結果比對評估不一致者，應立即駁回其申請","(B) 原料藥指一種經物理、化學處理或生物技術過程製造所得具藥理作用之活性物或成分，常用於藥品、生物藥品或生物技術產品之製造","(C) 外銷專用之製劑及原料藥查驗登記申請案，除經中央衛生主管機關認有必要送驗者外，得以書面審核而免送驗樣品","(D) 原料藥查驗登記檢送資料應以通用技術文件格式呈現"],"answer":0,"image":""},{"id":"ph6-113-1-29","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"113年第1次第29題","year":113,"session":1,"number":29,"question":"依據藥品查驗登記審查準則，關於某注射液查驗登記申請案之敘述，下列何者錯誤？","options":["(A) 該注射液有兩種不同的濃度，兩種濃度之製劑應分別申請","(B) 申請書之原料名稱及分量欄，應記載該注射液所使用之溶劑、溶解輔助劑，但不應包含安定劑或其他賦形劑","(C) 若該注射液屬於新療效新藥，則不須檢附安全性試驗報告","(D) 分段委託製造之注射液，其安定性試驗之執行，不限由分段委託製造製程之受託製造廠執行"],"answer":1,"image":""},{"id":"ph6-113-1-30","subject":"ph6","topic":"藥事法規-新藥臨床試驗與安全監視","meta":"113年第1次第30題","year":113,"session":1,"number":30,"question":"依據藥品生體可用率及生體相等性試驗作業準則，下列敘述何者錯誤？","options":["(A) 生體可用率（bioavailability）係指藥品有效成分由製劑中吸收進入全身血液循環或作用部位之速率（rate）與程度（extent）之指標","(B) 如係不具全身性吸收之藥品，其生體可用率（bioavailability）係指以有效成分到達作用部位之速率與程度作評估之指標","(C) 生體相等性（bioequivalence）係指藥品有效成分由製劑中吸收進入全身血液循環或作用部位之時間（time）與程度（extent）之指標","(D) 生體相等性（bioequivalence）係指二個藥劑相等品或藥劑替代品，於適當研究設計下，以相同條件、相同莫耳劑量給與人體時，具有相同之生體可用率"],"answer":2,"image":""},{"id":"ph6-113-1-31","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"113年第1次第31題","year":113,"session":1,"number":31,"question":"核准之藥品經稽查或檢驗所含有效成分之質、量或強度與核准不符者，係屬藥事法所稱之：","options":["(A) 偽藥","(B) 劣藥","(C) 禁藥","(D) 不良藥品"],"answer":1,"image":""},{"id":"ph6-113-1-32","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"113年第1次第32題","year":113,"session":1,"number":32,"question":"依藥事法規定，有關原料藥之敘述，下列何者錯誤？","options":["(A) 原料藥應先申請中央衛生主管機關核准後，方得由符合藥品優良製造規範之藥品製造業者分裝","(B) 藥品製造業者輸入自用原料，應向中央衛生主管機關申請核准","(C) 原料藥經加工調製，製成一定劑型及劑量之藥品，即稱製劑","(D) 原料藥包含載於中華藥典或經中央衛生主管機關認定之其他各國藥典、公定之國家處方集，或各該補充典籍者"],"answer":0,"image":""},{"id":"ph6-113-1-33","subject":"ph6","topic":"藥事法規-醫療器材管理法","meta":"113年第1次第33題","year":113,"session":1,"number":33,"question":"依醫療器材管理法規定，有關醫療器材製造業者之敘述，下列何者正確？","options":["(A) 從事醫療器材製造、包裝、貼標、滅菌或最終驗放","(B) 販售自製醫療器材仍須另行請領醫療器材販賣業藥商執照","(C) 委託他廠製造應經當地衛生主管機關核准","(D) 應視其產品風險程度，向中央主管機關申請製造業藥商許可執照"],"answer":0,"image":""},{"id":"ph6-113-1-34","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"113年第1次第34題","year":113,"session":1,"number":34,"question":"依藥事法及其施行細則規定，有關藥品製造業之敘述，下列何者正確？","options":["(A) 販賣他廠製造之藥品，無須再聘請不同藥師管理","(B) 自製藥品之零售，得由其監製藥師兼為管理","(C) 分設經銷處所，應由同一監製藥師負責管理所買賣之藥品","(D) 分設製造處所，應由同一監製藥師負責所有產品製造之責任"],"answer":1,"image":""},{"id":"ph6-113-1-35","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"113年第1次第35題","year":113,"session":1,"number":35,"question":"中央衛生主管機關為維護公益之目的，於必要時，得公開所持有及保管藥商申請藥物查驗登記所檢附之資料，但不包括下列何項？","options":["(A) 藥物成分及仿單","(B) 藥物安全相關資訊","(C) 藥商營業秘密資料","(D) 藥物臨床試驗計畫摘要"],"answer":2,"image":""},{"id":"ph6-113-1-36","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"113年第1次第36題","year":113,"session":1,"number":36,"question":"某藥品製造工廠於臺南市新設，下列敘述何者正確？","options":["(A) 應向臺南市政府申請核發工廠登記證明文件","(B) 應向衛生福利部食品藥物管理署申請核發製造業藥商許可執照","(C) 經檢查符合藥品優良製造規範，由臺南市政府核發符合藥品優良製造規範之藥物製造許可","(D) 不論是否符合人用藥品規格，製造動物用藥品均須與製造人用藥品之製造場所設備分開"],"answer":0,"image":""},{"id":"ph6-113-1-37","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"113年第1次第37題","year":113,"session":1,"number":37,"question":"電視廣告常見之「維士比液」，其類別應屬：","options":["(A) 食品","(B) 醫師藥師藥劑生指示藥品","(C) 成藥","(D) 固有成方製劑"],"answer":1,"image":""},{"id":"ph6-113-1-38","subject":"ph6","topic":"藥事法規-藥師法與執業管理","meta":"113年第1次第38題","year":113,"session":1,"number":38,"question":"下列敘述何者錯誤？","options":["(A) 醫療機構之護理人員兼任調劑工作，應依藥師法處罰該護理人員","(B) 醫療機構交付之藥劑，其容器、包裝之標示不完整，應依醫療法處罰該醫療機構","(C) 藥劑生得販賣或管理一定等級之醫療器材","(D) 依藥師法受廢止藥師證書處分者，如再經考試及格，仍得再充任藥師"],"answer":3,"image":""},{"id":"ph6-113-1-39","subject":"ph6","topic":"藥事法規-管制藥品與毒品危害防制","meta":"113年第1次第39題","year":113,"session":1,"number":39,"question":"濫用藥物尿液檢驗作業準則之法源依據為何？","options":["(A) 藥事法","(B) 藥師法","(C) 管制藥品管理條例","(D) 毒品危害防制條例"],"answer":3,"image":""},{"id":"ph6-113-1-40","subject":"ph6","topic":"藥事法規-管制藥品與毒品危害防制","meta":"113年第1次第40題","year":113,"session":1,"number":40,"question":"下列何種毒品品項，不屬於第二級毒品？","options":["(A) 海洛因","(B) 大麻","(C) 安非他命","(D) 罌粟"],"answer":0,"image":""},{"id":"ph6-113-1-41","subject":"ph6","topic":"藥事法規-管制藥品與毒品危害防制","meta":"113年第1次第41題","year":113,"session":1,"number":41,"question":"下列有關管制藥品辨識與管理之敘述，何者錯誤？","options":["(A) 管制藥品之標籤，應以中文載明管制級別及警語","(B) 麻醉藥品之標幟，應以中文標示","(C) 標籤之中文品名，其字體不得小於外文字體","(D) 標籤如受空間限制，無法依規定刊載者，得向當地衛生局申請核定"],"answer":3,"image":""},{"id":"ph6-113-1-42","subject":"ph6","topic":"藥事法規-化粧品衛生安全管理法","meta":"113年第1次第42題","year":113,"session":1,"number":42,"question":"依據化粧品衛生安全管理法規定，下列何者非屬化粧品之嚴重不良反應？","options":["(A) 危及生命","(B) 暫時性失能","(C) 胎嬰兒先天性畸形","(D) 導致使用者就醫"],"answer":3,"image":""},{"id":"ph6-113-1-43","subject":"ph6","topic":"藥事法規-藥害救濟與罕見疾病","meta":"113年第1次第43題","year":113,"session":1,"number":43,"question":"關於罕見疾病防治及藥物法（以下簡稱本法）之敘述，下列何者錯誤？","options":["(A) 本法明文規範罕見疾病之疾病盛行率為萬分之一以下","(B) 罕見疾病及藥物審議會應辦理罕見疾病藥物查驗登記之審議","(C) 本法所稱主管機關，在中央為衛生福利部；在直轄市為直轄市政府","(D) 中央主管機關應辦理罕見疾病之防治與研究"],"answer":0,"image":""},{"id":"ph6-113-1-44","subject":"ph6","topic":"藥事法規-藥害救濟與罕見疾病","meta":"113年第1次第44題","year":113,"session":1,"number":44,"question":"依據罕見疾病防治及藥物法（以下簡稱本法）及其施行細則，本法所指之同類藥物，不包含下列何者？","options":["(A) 主分子結構及適應症與依本法查驗登記發給許可證之生物製劑或大分子藥物相同者","(B) 適應症與依本法查驗登記發給許可證之一般化學藥物相同，有效成分為依本法查驗登記發給許可證之一般化學藥物之共價鍵衍生物","(C) 適應症與依本法查驗登記發給許可證之一般化學藥物相同，有效成分為依本法查驗登記發給許可證之一般化學藥物之鹽類","(D) 適應症與依本法查驗登記發給許可證之一般化學藥物相同，有效成分為依本法查驗登記發給許可證之一般化學藥物之錯化物"],"answer":1,"image":""},{"id":"ph6-113-1-45","subject":"ph6","topic":"藥事法規-藥害救濟與罕見疾病","meta":"113年第1次第45題","year":113,"session":1,"number":45,"question":"中央主管機關補助全民健康保險法未能給付之罕見疾病居家醫療照護器材費用，其經費來源不包括下列何者？","options":["(A) 接受機構、團體捐助","(B) 衛生福利部編列預算","(C) 藥害救濟徵收金","(D) 菸品健康福利捐分配收入"],"answer":2,"image":""},{"id":"ph6-113-1-46","subject":"ph6","topic":"藥事法規-全民健康保險與藥事作業","meta":"113年第1次第46題","year":113,"session":1,"number":46,"question":"依據全民健康保險法，下列部分負擔之敘述何者錯誤？","options":["(A) 急診為被保險人之緊急就醫，得免部分負擔","(B) 於醫療資源缺乏地區，得予減免部分負擔","(C) 不經轉診，於地區醫院、區域醫院、醫學中心門診就醫者，應分別負擔門診或急診費用之百分之三十、百分之四十及百分之五十","(D) 保險人已收載之藥品，特約院所不得向被保險對象收取部分負擔"],"answer":0,"image":""},{"id":"ph6-113-1-47","subject":"ph6","topic":"藥事法規-全民健康保險與藥事作業","meta":"113年第1次第47題","year":113,"session":1,"number":47,"question":"依據全民健康保險醫療辦法，病人於民國112/8/23由醫師開立慢性病連續處方箋且於當日領藥，該處方每次開藥30日，總用藥量90日，下列相關敘述何者正確？","options":["(A) 第一次領藥一定要在就診醫院領藥，不可選擇到社區藥局領藥","(B) 第二次憑原處方領藥，最快可以領藥日期為民國112/9/9","(C) 領完第一次處方後，因故忘記第二次領藥，想起來時已是民國112/11/15，還可以領藥","(D) 第三次領藥一定要回醫院領藥，下次看診才能順利掛號"],"answer":2,"image":""},{"id":"ph6-113-1-48","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"113年第1次第48題","year":113,"session":1,"number":48,"question":"關於中醫師處方箋之調劑資格，下列何者正確？①中醫診所之中醫師 ②中醫師監督助理為之 ③修習中藥課程達適當標準之藥師","options":["(A) 僅①②","(B) 僅②③","(C) 僅①③","(D) ①②③"],"answer":2,"image":""},{"id":"ph6-113-1-49","subject":"ph6","topic":"藥事法規-全民健康保險與藥事作業","meta":"113年第1次第49題","year":113,"session":1,"number":49,"question":"依據全民健康保險醫事服務機構特約及管理辦法，下列有關特約醫事服務機構之敘述，何者正確？","options":["(A) 對於未能提供健保卡的病患可以不用提供醫療服務","(B) 報經衛生福利部中央健康保險署同意後即可指派醫師至護理之家提供一般診療服務","(C) 須將提供醫療服務的照護機構內所有住民名冊，報經保險人備查","(D) 醫師至照護機構提供醫療服務，同一時段只能限制1位"],"answer":3,"image":""},{"id":"ph6-113-1-50","subject":"ph6","topic":"藥事法規-全民健康保險與藥事作業","meta":"113年第1次第50題","year":113,"session":1,"number":50,"question":"某保險特約藥局違反藥事法之規定，受衛生主管機關廢止藥局執照之處分，依全民健康保險醫事服務機構特約及管理辦法之規定，應如何處辦？","options":["(A) 停止特約一年","(B) 違約記點","(C) 受申報費用十倍罰鍰處分","(D) 終止特約"],"answer":3,"image":""},{"id":"ph6-113-2-1","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"113年第2次第1題","year":113,"session":2,"number":1,"question":"依據健康食品管理法，關於健康食品管理方式之敘述，下列何者錯誤？","options":["(A) 健康食品必須先經查驗登記許可，才可以製造販賣","(B) 健康食品之保健功效係指增進民眾健康、減少疾病危害風險，且具有實質科學證據之功效，非屬治療、矯正人類疾病之醫療效能，並經中央主管機關公告者","(C) 為評估健康食品之保健功效，均需進行人體食用試驗","(D) 健康食品可以在包裝上標示經核准的保健功效，並作為廣告宣稱"],"answer":2,"image":""},{"id":"ph6-113-2-2","subject":"ph6","topic":"藥事法規-全民健康保險與藥事作業","meta":"113年第2次第2題","year":113,"session":2,"number":2,"question":"政府推動糖尿病共同照護網，並配合衛生福利部中央健康保險署品質支付制度，下列何者非屬衛生福利部中央健康保險署品質支付制度所指照護品質監測指標？","options":["(A) 血液HbA1c檢查率","(B) 空腹血糖檢查率","(C) 眼底視網膜檢查率","(D) 接受共同照護比率"],"answer":1,"image":""},{"id":"ph6-113-2-3","subject":"ph6","topic":"藥事法規-管制藥品與毒品危害防制","meta":"113年第2次第3題","year":113,"session":2,"number":3,"question":"嗎啡（morphine）注射劑之輸入、輸出、製造、販賣，應由下列何單位為之？","options":["(A) 領有許可證之代理商","(B) 榮民製藥廠","(C) 衛生福利部食品藥物管理署之管制藥品製藥工廠","(D) 國家衛生研究院之製藥工廠"],"answer":2,"image":""},{"id":"ph6-113-2-4","subject":"ph6","topic":"藥事法規-藥政管理組織與衛生行政","meta":"113年第2次第4題","year":113,"session":2,"number":4,"question":"B公司要申請成為藥商，要向下列何單位提出申請，核准登記後領得許可執照後，方准營業？","options":["(A) 衛生福利部","(B) 衛生福利部中央健康保險署","(C) 衛生福利部食品藥物管理署","(D) 直轄市或縣（市）政府"],"answer":3,"image":""},{"id":"ph6-113-2-5","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"113年第2次第5題","year":113,"session":2,"number":5,"question":"下列何者不是藥事法所稱製劑之分類？","options":["(A) 醫師處方藥品","(B) 醫師藥師藥劑生指示藥品","(C) 固有成方製劑","(D) 調製藥品"],"answer":3,"image":""},{"id":"ph6-113-2-6","subject":"ph6","topic":"臨床藥學-藥物不良反應與交互作用","meta":"113年第2次第6題","year":113,"session":2,"number":6,"question":"某診所藥師調劑時，將aminopyrine誤當aminophylline交付給氣喘病人，經病人發現，未服用該藥物。下列敘述何者最適當？","options":["(A) 該病人在接受藥品時，亦應負檢查藥品內容之法律責任","(B) 若係機器包藥時發生辨識錯誤，該藥師可免除懲戒","(C) 該藥師不得以業務過重為由，發生此類之處方調劑錯誤","(D) 本案屬業務重大過失，藥師公會得依法執行懲戒決議"],"answer":2,"image":""},{"id":"ph6-113-2-7","subject":"ph6","topic":"臨床藥學-藥事照護與用藥評估","meta":"113年第2次第7題","year":113,"session":2,"number":7,"question":"下列何者是藥師依據藥師法相關規定所執行之藥事照護業務？","options":["(A) 於藥局執行處方調劑","(B) 於醫療機構執行藥品安全監視","(C) 於藥廠執行藥品鑑定","(D) 於藥廠執行藥品品質之監督"],"answer":1,"image":""},{"id":"ph6-113-2-8","subject":"ph6","topic":"藥事法規-藥師法與執業管理","meta":"113年第2次第8題","year":113,"session":2,"number":8,"question":"依據藥師法，藥師執業以一處為限，並應在所在地主管機關核准登記之醫療機構、依據藥事法規定之執業處所或其他經主管機關認可之機構為之。但於醫療機構、藥局執業者，下列何種情形不得於執業處所外執行業務？","options":["(A) 藥癮治療","(B) 傳染病防治服務","(C) 於矯正機關，執行調劑業務","(D) 於矯正機關，執行菸癮治療業務"],"answer":3,"image":""},{"id":"ph6-113-2-9","subject":"ph6","topic":"藥事法規-藥師法與執業管理","meta":"113年第2次第9題","year":113,"session":2,"number":9,"question":"劉藥師為基隆市社區藥局之執業藥師，假日要前往同縣市陽光護理機構支援藥事照護業務，他需事先向何單位申請核准，才得以於執業處所外執行藥事照護業務？","options":["(A) 基隆市藥師公會","(B) 基隆市政府","(C) 衛生福利部食品藥物管理署","(D) 衛生福利部醫事司"],"answer":1,"image":""},{"id":"ph6-113-2-10","subject":"ph6","topic":"藥事法規-藥師法與執業管理","meta":"113年第2次第10題","year":113,"session":2,"number":10,"question":"藥師只能在執業登記的場所中執業，但經衛生主管機關核准後可於執業處所外執行業務，下列敘述何者錯誤？","options":["(A) 藥師經報准後，可以於中央主管機關公告之無藥事人員執業之偏遠地區，執行調劑業務","(B) 藥師在連鎖藥局體系內各藥局執業仍需經報准始得執行業務","(C) 學校診療所的藥師經報准後，可以在下班時間參與偏遠地區巡迴醫療服務","(D) 藥師報備支援的診所一定要聘有專任藥事人員"],"answer":3,"image":""},{"id":"ph6-113-2-11","subject":"ph6","topic":"藥事法規-藥師法與執業管理","meta":"113年第2次第11題","year":113,"session":2,"number":11,"question":"依據藥師法，有關藥師執業之相關規定，下列何者錯誤？","options":["(A) 藥師應向執業所在地直轄市、縣（市）主管機關申請執業登記，領有執業執照，始得執業","(B) 藥師執業，應接受繼續教育，並每六年提出完成繼續教育證明文件，辦理執業執照更新","(C) 醫事人員辦理執業執照更新，應於其執業執照應更新日期屆滿前六個月內，填具申請書，並檢具相關文件及繳納執業執照費，向原發執業執照機關申請換領執業執照","(D) 藥師停業或歇業時，應自事實發生之日起三十日內，報請原發執業執照之主管機關備查。前項停業之期間，以二年為限；逾二年者，應辦理歇業"],"answer":3,"image":""},{"id":"ph6-113-2-12","subject":"ph6","topic":"藥事法規-藥師法與執業管理","meta":"113年第2次第12題","year":113,"session":2,"number":12,"question":"依據藥師法，藥師執行業務行為，下列何者錯誤？","options":["(A) 藥師執行調劑業務，非有正當理由，不得拒絕為調劑","(B) 藥局雖標示為日夜調劑者，仍可暫停調劑至少八小時","(C) 藥師受有關機關詢問或委託鑑定時，不得為虛偽之陳述或報告","(D) 藥師對於因業務而知悉他人之秘密，不得無故洩漏"],"answer":1,"image":""},{"id":"ph6-113-2-13","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"113年第2次第13題","year":113,"session":2,"number":13,"question":"下列何者非屬藥事法所稱之新藥？","options":["(A) 新成分","(B) 新劑量","(C) 新療效複方","(D) 新使用途徑"],"answer":1,"image":""},{"id":"ph6-113-2-14","subject":"ph6","topic":"藥事法規-管制藥品與毒品危害防制","meta":"113年第2次第14題","year":113,"session":2,"number":14,"question":"藥師小明與藥劑生小華一同於某藥局工作，某日小華接受民眾處方箋要求調劑，結果小華將處方箋轉請小明調劑，則下列何者可能是民眾要求調劑的藥品？","options":["(A) phenobarbital","(B) triazolam","(C) buprenorphine","(D) methylphenidate"],"answer":2,"image":""},{"id":"ph6-113-2-15","subject":"ph6","topic":"調劑學-處方判讀與調劑作業","meta":"113年第2次第15題","year":113,"session":2,"number":15,"question":"依據藥師法，有關藥師調劑作業之敘述，下列何者錯誤？","options":["(A) 對於處方內容如有可疑之點，應詢明原處方醫師確認後方得調劑","(B) 處方調劑時，如藥品未備或缺乏時，應通知原處方醫師，請其更換","(C) 調劑處方不得任意代以他藥","(D) 調劑後之處方箋，均應保存五年"],"answer":3,"image":""},{"id":"ph6-113-2-16","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"113年第2次第16題","year":113,"session":2,"number":16,"question":"依藥事法之規定，下列敘述何者錯誤？","options":["(A) 調劑處所應有六平方公尺以上之作業面積，並應與其他作業處所明顯區隔","(B) 在管理藥師同意及指導下，得由藥師助理調劑","(C) 藥師交付藥品時應確認所交付之對象為交付處方箋者","(D) 交付藥品之包裝或容器不得重複使用"],"answer":1,"image":""},{"id":"ph6-113-2-17","subject":"ph6","topic":"臨床藥學-藥事照護與用藥評估","meta":"113年第2次第17題","year":113,"session":2,"number":17,"question":"下列何者屬藥師法所稱之藥事照護相關業務？","options":["(A) 於衛生福利部執行新藥安全評估事項","(B) 執行教育部之藥物濫用評估事項","(C) 於教學醫院執行用藥諮詢服務事項","(D) 執行國防部之軍中藥物濫用尿液篩檢事項"],"answer":2,"image":""},{"id":"ph6-113-2-18","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"113年第2次第18題","year":113,"session":2,"number":18,"question":"我國與國際之藥品優良製造規範（PIC/S GMP），主要都是在規範下列何階段？","options":["(A) 生產源頭控管","(B) 第一期臨床試驗","(C) 新藥監視","(D) 上市後監控"],"answer":0,"image":""},{"id":"ph6-113-2-19","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"113年第2次第19題","year":113,"session":2,"number":19,"question":"下列何者非屬藥廠執行PIC/S GMP之缺失範圍？","options":["(A) 接收區與外界直接相通","(B) 未成立數據安全監測委員會","(C) 原料倉庫溫度記錄放置點未經溫度測繪圖評估","(D) 放置有半成品之場所無24小時溫濕度管控"],"answer":1,"image":""},{"id":"ph6-113-2-20","subject":"ph6","topic":"藥事法規-新藥臨床試驗與安全監視","meta":"113年第2次第20題","year":113,"session":2,"number":20,"question":"某受試者參與藥品臨床試驗時，不幸導致顎骨壞死。下列敘述何者最適當？","options":["(A) 試驗同意書已清楚告知該嚴重副作用，試驗委託者不需負損害補償","(B) 試驗委託者應即刻通報衛生福利部，並更換試驗主持人","(C) 試驗主持人及試驗機構，應提供該受試者充分醫療照護","(D) 主管機關應即刻終止該臨床試驗"],"answer":2,"image":""},{"id":"ph6-113-2-21","subject":"ph6","topic":"調劑學-處方判讀與調劑作業","meta":"113年第2次第21題","year":113,"session":2,"number":21,"question":"依據藥品優良調劑作業準則之規定，有關處方調劑交付藥品時，應核對之事項，下列何者錯誤？","options":["(A) 處方指示之正確性","(B) 藥品種類","(C) 藥品數量","(D) 醫療機構及醫師簽章"],"answer":3,"image":""},{"id":"ph6-113-2-22","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"113年第2次第22題","year":113,"session":2,"number":22,"question":"依據藥事法，對於藥商停歇業的管理規定，下列敘述何者正確？","options":["(A) 向當地衛生主管機關申請停業後，藥商應自行保管好其所持有的藥品許可證","(B) 可一次向當地衛生主管機關申請停業二年","(C) 藥商持有的藥品許可證，應在申請歇業時一併繳銷","(D) 要先向當地衛生主管機關申請停業經核准後，才可以再申請歇業"],"answer":2,"image":""},{"id":"ph6-113-2-23","subject":"ph6","topic":"藥事法規-藥師法與執業管理","meta":"113年第2次第23題","year":113,"session":2,"number":23,"question":"小美是某醫學院藥學系民國109年的畢業生，在畢業次年即取得藥師證書並進入某醫學中心擔任藥師，她計畫民國110年在社區自行開設藥局，依據藥師法與藥事法，下列敘述何者正確？","options":["(A) 民國110年向衛生主管機關請領藥局執照後即可調劑處方","(B) 因其已修習並取得16學分中藥課程，可於請領藥局執照後，執行中藥之調劑或零售業務","(C) 要另外向衛生主管機關申請醫療器材販賣業許可執照，才能販售醫療器材","(D) 其開設之藥局，不用另請藥商許可執照就可以經營藥品輸入業務"],"answer":1,"image":""},{"id":"ph6-113-2-24","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"113年第2次第24題","year":113,"session":2,"number":24,"question":"依據藥事法，對於中藥販售的規定，下列敘述何者正確？","options":["(A) 中藥廠不可以在其製造廠兼營自製產品之零售業務","(B) 中藥製造業者出售毒劇性中藥，應將此藥品名稱及數量，詳列簿冊","(C) 凡中藥販賣業者均不得售賣毒劇性之中藥","(D) 凡藥師親自主持之藥局，都可以零售中藥"],"answer":1,"image":""},{"id":"ph6-113-2-25","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"113年第2次第25題","year":113,"session":2,"number":25,"question":"下列何者非屬藥事法之劣藥？","options":["(A) 所含有效成分之質、量或強度，與核准不符者","(B) 超過有效期間或保存期限者","(C) 所含有效成分之名稱，與核准不符者","(D) 主治效能與核准不符者"],"answer":2,"image":""},{"id":"ph6-113-2-26","subject":"ph6","topic":"藥事法規-藥物廣告與稽查","meta":"113年第2次第26題","year":113,"session":2,"number":26,"question":"有關藥事法對於藥品廣告之規定，下列敘述何者錯誤？","options":["(A) 非藥事法所稱之藥品，不得為醫療效能之標示或宣傳","(B) 藥局可以賣血氧機搭配贈送消炎止痛藥，以協助民眾對抗疫情","(C) 藥品廣告之刊登內容，不得超過衛生機關原核准之內容","(D) 藥品廣告之有效期間，是自證明文件之核發日起算"],"answer":1,"image":""},{"id":"ph6-113-2-27","subject":"ph6","topic":"藥事法規-新藥臨床試驗與安全監視","meta":"113年第2次第27題","year":113,"session":2,"number":27,"question":"藥商如知悉藥品於十大醫藥先進國家因不良反應暫停使用或下市，應自知悉後多久內向主管機關建置之網路系統通報？","options":["(A) 24小時","(B) 3日","(C) 5日","(D) 7日"],"answer":1,"image":""},{"id":"ph6-113-2-28","subject":"ph6","topic":"藥事法規-新藥臨床試驗與安全監視","meta":"113年第2次第28題","year":113,"session":2,"number":28,"question":"藥商如發現藥品有未預期或超出預期發生頻率之嚴重藥品不良反應，中央衛生主管機關得要求藥商執行下列何項風險管控措施？ ①發布警訊 ②修訂仿單 ③暫停使用 ④產品回收","options":["(A) 僅①②③","(B) ①②③④","(C) 僅②③④","(D) 僅①②④"],"answer":1,"image":""},{"id":"ph6-113-2-29","subject":"ph6","topic":"藥事法規-新藥臨床試驗與安全監視","meta":"113年第2次第29題","year":113,"session":2,"number":29,"question":"某醫院發現病人使用A藥品後產生文獻尚未記載之急性胰臟炎而危及生命住院治療，院內評估後懷疑急性胰臟炎與A藥品具高度關連性，該醫院應依法於幾日內向中央衛生主管機關通報，並副知持有藥物許可證之藥商？","options":["(A) 三日","(B) 七日","(C) 十五日","(D) 三十日"],"answer":1,"image":""},{"id":"ph6-113-2-30","subject":"ph6","topic":"藥事法規-醫療器材管理法","meta":"113年第2次第30題","year":113,"session":2,"number":30,"question":"依醫療器材管理法規定，除中央主管機關免予刊載者外，下列何者不是醫療器材標籤、說明書或包裝應刊載事項？","options":["(A) 許可證字號或登錄字號","(B) 批號或序號","(C) 型號、規格或主要成分","(D) 製造許可編號"],"answer":3,"image":""},{"id":"ph6-113-2-31","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"113年第2次第31題","year":113,"session":2,"number":31,"question":"依據藥品查驗登記審查準則，關於生物藥品之敘述，下列何者錯誤？","options":["(A) 生物藥品指依據微生物學、免疫學學理製造之血清、抗毒素、疫苗、類毒素及菌液等","(B) 生物藥品查驗登記申請案，除經中央衛生主管機關認有必要送驗者外，得以書面審核而免送驗樣品","(C) 如我國已有類似（同來源、同成分）疫苗上市，則疫苗查驗登記申請案之出產國許可製售證明得替代採用證明","(D) 生物相似性藥品指以生物技術衍生之生物藥品，於品質、安全及功效上，與原本作為參考並已獲得我國上市許可之生物藥品相似"],"answer":1,"image":""},{"id":"ph6-113-2-32","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"113年第2次第32題","year":113,"session":2,"number":32,"question":"依據生物藥品檢驗封緘作業辦法，下列敘述何者錯誤？","options":["(A) 中央衛生主管機關得依抽驗生物藥品類別及實際需要執行檢驗項目","(B) 中央衛生主管機關受理檢驗封緘申請後，經派員查核生物藥品運送及貯存之溫度符合貯藏條件者，即抽取適量生物藥品供檢驗或留樣所需；剩餘生物藥品則應予封存，並交由藥商自行保管","(C) 因應緊急醫療需要之生物藥品，藥商得檢附地區醫院以上之主治醫師出具之切結書或醫院申請書，向中央衛生主管機關申請緊急放行所需要之數量","(D) 屬防疫或外銷用生物藥品，無須檢附生物藥品之製程、檢驗方法、規格、標準品及有關文獻"],"answer":3,"image":""},{"id":"ph6-113-2-33","subject":"ph6","topic":"藥事法規-新藥臨床試驗與安全監視","meta":"113年第2次第33題","year":113,"session":2,"number":33,"question":"依據藥品生體可用率及生體相等性試驗作業準則，關於生體可用率及生體相等性試驗設計之敘述，下列何者正確？","options":["(A) 抽血時間至少應持續至到達最高血中濃度（Cmax）後五倍以上之藥品排除半衰期；取尿應有適當之採樣時間","(B) 交叉試驗中，服藥前之藥品血中濃度不得超過最高血中濃度（Cmax）之百分之一","(C) 交叉試驗中，二次處理期間（treatment period）應有適當之藥品洗除期間（washout period），原則上至少應為該藥品排除半衰期之十倍","(D) 多劑量試驗之採樣時間，應達到足以測定其穩定狀態（steady state）之血中濃度"],"answer":3,"image":""},{"id":"ph6-113-2-34","subject":"ph6","topic":"藥事法規-醫療器材管理法","meta":"113年第2次第34題","year":113,"session":2,"number":34,"question":"下列何項醫療器材，尚未開放可於網路販售？","options":["(A) 衛生棉條","(B) 隱形眼鏡","(C) 手術用口罩","(D) 體脂計"],"answer":1,"image":""},{"id":"ph6-113-2-35","subject":"ph6","topic":"藥事法規-藥物廣告與稽查","meta":"113年第2次第35題","year":113,"session":2,"number":35,"question":"新竹市藥商勝利公司欲刊播A感冒膠囊之藥品廣告，應於刊播前將所有文字、圖畫或言詞，向下列何者申請核准，才能提供傳播業者刊登？","options":["(A) 新竹市政府","(B) 公平交易委員會","(C) 行政院消費者保護處","(D) 衛生福利部"],"answer":3,"image":""},{"id":"ph6-113-2-36","subject":"ph6","topic":"藥事法規-新藥臨床試驗與安全監視","meta":"113年第2次第36題","year":113,"session":2,"number":36,"question":"依照嚴重藥物不良反應通報辦法，下列有關嚴重藥物不良反應之敘述，何者錯誤？","options":["(A) 中央衛生主管機關必要時得向醫療機構、藥局及藥商請求提供嚴重藥物不良反應病人之就醫紀錄、給藥紀錄或產品資料","(B) 包括死亡及危及生命等6款情形","(C) 死亡或危及生命之嚴重藥物不良反應，通報後可立即獲得藥害救濟補償","(D) 醫療機構、藥局、藥商應填具通報書，連同相關資料，向中央衛生主管機關或其委託機構通報"],"answer":2,"image":""},{"id":"ph6-113-2-37","subject":"ph6","topic":"藥事法規-醫療器材管理法","meta":"113年第2次第37題","year":113,"session":2,"number":37,"question":"下列那些產品列屬醫療器材管理？①隱形眼鏡鏡片消毒藥水 ②驗孕試紙 ③血糖機 ④含藥痠痛貼布","options":["(A) ②③④","(B) ①②④","(C) ①②③","(D) ①③④"],"answer":2,"image":""},{"id":"ph6-113-2-38","subject":"ph6","topic":"藥事法規-藥政管理組織與衛生行政","meta":"113年第2次第38題","year":113,"session":2,"number":38,"question":"下列何者非屬中央衛生主管機關權責？","options":["(A) 核發藥品許可證","(B) 核發藥商許可執照","(C) 監視藥品上市後安全性","(D) 藥品安全性評估"],"answer":1,"image":""},{"id":"ph6-113-2-39","subject":"ph6","topic":"藥事法規-管制藥品與毒品危害防制","meta":"113年第2次第39題","year":113,"session":2,"number":39,"question":"依據管制藥品管理條例，有關銷燬未調劑之管制藥品應注意事項，下列何者正確？","options":["(A) 應申請當地衛生主管機關核准後，會同該衛生主管機關為之","(B) 應申請當地衛生主管機關核准後，會同其管制藥品管理人為之","(C) 應申請中央衛生主管機關核准後，會同當地衛生主管機關為之","(D) 應申請中央衛生主管機關核准後，會同其管制藥品管理人為之"],"answer":0,"image":""},{"id":"ph6-113-2-40","subject":"ph6","topic":"藥事法規-管制藥品與毒品危害防制","meta":"113年第2次第40題","year":113,"session":2,"number":40,"question":"下列各法規之主管機關，何者錯誤？","options":["(A) 毒品危害防制條例：法務部","(B) 濫用藥物尿液檢驗作業準則：法務部","(C) 管制藥品管理條例：衛生福利部","(D) 藥事法：衛生福利部"],"answer":1,"image":""},{"id":"ph6-113-2-41","subject":"ph6","topic":"藥事法規-管制藥品與毒品危害防制","meta":"113年第2次第41題","year":113,"session":2,"number":41,"question":"有關易濫用之愷他命（ketamine），下列敘述何者正確？","options":["(A) 本藥結構與藥理作用均類似安非他命，故以第二級管制藥品列管","(B) 本藥活性源自S式組態結構，故其R式組態異構物以第四級管制藥品列管","(C) 製造及輸入本藥，限由衛生福利部食品藥物管理署之製藥工廠為之","(D) 本藥非屬麻醉藥品，依法可由藥劑生調劑"],"answer":3,"image":""},{"id":"ph6-113-2-42","subject":"ph6","topic":"藥事法規-化粧品衛生安全管理法","meta":"113年第2次第42題","year":113,"session":2,"number":42,"question":"依據特定用途化粧品許可證核發辦法，下列何者非屬申請查驗登記應檢附之文件、資料？","options":["(A) 公司登記或商業登記證明文件影本","(B) 最近三年內出具之成分表","(C) 產品標籤、仿單及包裝設計稿樣","(D) 最近二年內出具之出產國許可製售證明"],"answer":[0,1,2,3],"image":"","answer_note":"送分:第42題一律給分 (原公告答案 B)"},{"id":"ph6-113-2-43","subject":"ph6","topic":"藥事法規-藥害救濟與罕見疾病","meta":"113年第2次第43題","year":113,"session":2,"number":43,"question":"依據藥害救濟法，藥害救濟基金之主要來源為何？","options":["(A) 全民健保安全準備金","(B) 藥物製造及輸入業者繳納之徵收金","(C) 醫療院所依比例繳納之徵收金","(D) 民眾部分負擔"],"answer":1,"image":""},{"id":"ph6-113-2-44","subject":"ph6","topic":"藥事法規-藥害救濟與罕見疾病","meta":"113年第2次第44題","year":113,"session":2,"number":44,"question":"依據藥害救濟法，下列何種情事得申請藥害救濟？","options":["(A) 使用臨床試驗用藥而受害","(B) 施打疫苗而受害","(C) 因急救使用超量藥物而受害","(D) 使用化療藥品而受害"],"answer":3,"image":""},{"id":"ph6-113-2-45","subject":"ph6","topic":"藥事法規-藥害救濟與罕見疾病","meta":"113年第2次第45題","year":113,"session":2,"number":45,"question":"罕見疾病藥物申請查驗登記，下列何者不得申請為主要適應症？","options":["(A) 營養","(B) 預防","(C) 診斷","(D) 治療"],"answer":0,"image":""},{"id":"ph6-113-2-46","subject":"ph6","topic":"藥事法規-全民健康保險與藥事作業","meta":"113年第2次第46題","year":113,"session":2,"number":46,"question":"依全民健康保險藥品價格調整作業辦法，所稱之「同分組｣係指下列何者？","options":["(A) 藥品主成分藥理機轉相同之品項","(B) 同一臨床治療類別之品項","(C) 同成分、同含量、同規格且同劑型之品項","(D) 同主成分、同單位含量的品項"],"answer":2,"image":""},{"id":"ph6-113-2-47","subject":"ph6","topic":"藥事法規-全民健康保險與藥事作業","meta":"113年第2次第47題","year":113,"session":2,"number":47,"question":"依據全民健康保險醫療辦法，下列敘述何者錯誤？","options":["(A) 保險對象持特約醫院、診所醫師交付之處方箋，應在該特約醫院、診所或至特約藥局調劑","(B) 保險對象罹患慢性病，經診斷須長期使用同一第二級管制藥品治療，醫師得開給慢性病連續處方箋","(C) 同一慢性病連續處方箋，應分次調劑","(D) 醫師處方之藥物未註明不可替代者，藥師得以相同價格或低於原處方藥物價格之同成分、同劑型、同含量其他廠牌藥品替代，並應告知保險對象"],"answer":1,"image":""},{"id":"ph6-113-2-48","subject":"ph6","topic":"藥事法規-全民健康保險與藥事作業","meta":"113年第2次第48題","year":113,"session":2,"number":48,"question":"依據全民健康保險法及相關法規，如虛報或浮報健保醫療費用，下列敘述何者錯誤？","options":["(A) 處以其領取之保險給付、申請核退或申報之醫療費用2倍至20倍罰鍰","(B) 若經檢察官提起公訴，保險人應於扣減及應核扣金額之範圍內，停止醫療費用之暫付及核付","(C) 如民眾自願提供健保卡過卡虛報慢性病處方藥品，視同共犯亦有被核扣健保費用之處分","(D) 情節重大者，應公告其名稱、負責醫事人員或行為人姓名及違法事實"],"answer":2,"image":""},{"id":"ph6-113-2-49","subject":"ph6","topic":"藥事法規-全民健康保險與藥事作業","meta":"113年第2次第49題","year":113,"session":2,"number":49,"question":"依據全民健康保險醫事服務機構特約及管理辦法，健保特約藥局如聘請不具藥師資格的助理代為調劑健保處方箋，下列敘述何者正確？","options":["(A) 停止合約2個月","(B) 扣減所申報費用的10倍金額","(C) 違規警告","(D) 修習健保相關法規學分"],"answer":1,"image":""},{"id":"ph6-113-2-50","subject":"ph6","topic":"藥事法規-全民健康保險與藥事作業","meta":"113年第2次第50題","year":113,"session":2,"number":50,"question":"依全民健康保險醫事服務機構特約及管理辦法之規定，下列何種情事非屬應處違約記點一點之處分？","options":["(A) 未將全民健康保險醫事服務機構之標誌，懸掛於明顯處所","(B) 不當招攬病人接受處方調劑，經衛生主管機關處分","(C) 提供服務之帳冊未保存五年","(D) 拒絕提供調劑服務"],"answer":3,"image":""},{"id":"ph6-114-1-1","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"114年第1次第1題","year":114,"session":1,"number":1,"question":"依據安寧緩和醫療條例，關於得立意願書之敘述，下列何者錯誤？","options":["(A) 意願人接受安寧緩和醫療或維生醫療抉擇之意願及其內容應載明於意願書上","(B) 經意願人於意願書表示同意，中央主管機關應將其意願註記於健保卡上","(C) 不論老少病殘，任何民眾都可以預先簽署意願書","(D) 意願人得自行以書面撤回其意願之意思表示"],"answer":2,"image":""},{"id":"ph6-114-1-2","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"114年第1次第2題","year":114,"session":1,"number":2,"question":"自人體細胞、組織、器官、體液等生物檢體之採集及參與者之保護，係規定於下列何項法規？","options":["(A) 人體細胞組織優良操作規範","(B) 人體器官移植條例","(C) 醫療法","(D) 人體生物資料庫管理條例"],"answer":3,"image":""},{"id":"ph6-114-1-3","subject":"ph6","topic":"藥事法規-藥師法與執業管理","meta":"114年第1次第3題","year":114,"session":1,"number":3,"question":"臺北市及金門縣的藥師懲戒委員會分別由何機關設置之？","options":["(A) 臺北市政府、金門縣政府","(B) 臺北市政府、衛生福利部","(C) 都是衛生福利部","(D) 臺北市政府、臺北市政府"],"answer":1,"image":""},{"id":"ph6-114-1-4","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"114年第1次第4題","year":114,"session":1,"number":4,"question":"依據藥事法，具有實體店面之藥商，並經衛生機關核准登記，可以在網路上販售下列何種藥品給一般民眾？","options":["(A) 有處方箋之高血壓藥","(B) 在藥局可以開架擺放之胃乳片","(C) 乙類成藥","(D) 解熱鎮痛劑"],"answer":2,"image":""},{"id":"ph6-114-1-5","subject":"ph6","topic":"藥事法規-新藥臨床試驗與安全監視","meta":"114年第1次第5題","year":114,"session":1,"number":5,"question":"依藥事法第7條之規定，下列藥品何者非屬中央衛生主管機關審查認定之新藥？","options":["(A) 新成分","(B) 新單位含量","(C) 新療效複方","(D) 新使用途徑"],"answer":1,"image":""},{"id":"ph6-114-1-6","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"114年第1次第6題","year":114,"session":1,"number":6,"question":"依長期照顧服務申請及給付辦法，長照服務給付項目，不包括下列何者？","options":["(A) 家庭照顧者支持服務之喘息服務","(B) 居家護理服務","(C) 個人居家無障礙環境改善服務","(D) 個人交通接送服務"],"answer":1,"image":""},{"id":"ph6-114-1-7","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"114年第1次第7題","year":114,"session":1,"number":7,"question":"依據中醫藥發展法，下列敘述何者錯誤？","options":["(A) 中藥，係指以中藥學理論為基礎，應用於診斷、治療、減輕或預防人類疾病之中藥材及中藥製劑","(B) 中央主管機關應每二年訂定中醫藥發展計畫","(C) 中央主管機關應強化中藥材源頭管理，積極發展及輔導國內中藥藥用植物種植","(D) 主管機關應加強中藥上市後之監測，並公布執行結果"],"answer":1,"image":""},{"id":"ph6-114-1-8","subject":"ph6","topic":"藥事法規-藥師法與執業管理","meta":"114年第1次第8題","year":114,"session":1,"number":8,"question":"某兼領藥劑生證書之藥師，受廢止藥師證書處分時，下列何者最適當？","options":["(A) 領有國內藥劑生證書者，需處以中止效期三年以上之處罰","(B) 需在規定時間內，接受規定繼續教育之額外時數","(C) 一併廢止其藥劑生證書，無論該證書是否遺失或毀損","(D) 若其配偶也具藥師資格，則該受處分藥師於廢證後，僅可協助其配偶，擔任調劑助理"],"answer":2,"image":""},{"id":"ph6-114-1-9","subject":"ph6","topic":"調劑學-藥品包裝標示與儲存","meta":"114年第1次第9題","year":114,"session":1,"number":9,"question":"依據藥品優良調劑作業準則，下列敘述何者錯誤？","options":["(A) ® Xalatan（lansoprost）眼藥水應放置於調劑處所冷藏櫃中","(B) 為記錄冷藏藥品溫度，應置放溫度計在冰箱內","(C) 冷藏藥品應每日作溫度監測並記錄成冊，此紀錄至少保存3年","(D) 冰箱中藥品應定期檢視是否逾期"],"answer":2,"image":""},{"id":"ph6-114-1-10","subject":"ph6","topic":"藥事法規-全民健康保險與藥事作業","meta":"114年第1次第10題","year":114,"session":1,"number":10,"question":"依據全民健康保險醫療辦法，關於保險對象罹患慢性病，經診斷須長期使用同一處方藥品治療之規定，下列何者正確？","options":["(A) 第三級管制藥品，不得開給慢性病連續處方箋","(B) 未攜帶健保卡就醫，得開給慢性病連續處方箋","(C) 同一慢性病，以開立一張慢性病連續處方箋為限","(D) 保險對象領藥後，因藥品遺失或毀損，得免費再就醫"],"answer":2,"image":""},{"id":"ph6-114-1-11","subject":"ph6","topic":"調劑學-處方判讀與調劑作業","meta":"114年第1次第11題","year":114,"session":1,"number":11,"question":"依據藥品優良調劑作業準則，下列何者錯誤？","options":["(A) 可依醫師所開具之處方箋，將錠劑磨成粉劑","(B) 可調製全靜脈營養輸注液","(C) 可調製核醫放射性藥品","(D) atropine有0.1％及0.5％濃度眼藥水之許可證，醫師處方為0.1％ atropine眼藥水，但因院內缺貨，可以0.5％稀釋製成"],"answer":3,"image":""},{"id":"ph6-114-1-12","subject":"ph6","topic":"藥事法規-藥師法與執業管理","meta":"114年第1次第12題","year":114,"session":1,"number":12,"question":"藥師辦理執業登記時需提供繼續教育積分證明，下列敘述何者錯誤？","options":["(A) 執業藥師每6年執業執照更新時須完成120點積分數","(B) 繼續教育課程中必須包括藥學專業課程、藥學倫理及藥學相關法規課程證明達12點以上，最高不超過24點","(C) 繼續教育課程中必須包括性別議題及感染管制課程","(D) 領取藥師證書5年後才首次申請執業登記，只要提供申請執業前1年內接受20點積分證明"],"answer":1,"image":""},{"id":"ph6-114-1-13","subject":"ph6","topic":"調劑學-藥品包裝標示與儲存","meta":"114年第1次第13題","year":114,"session":1,"number":13,"question":"依據藥師法，藥師交付藥劑時，應於容器或包裝上記明之事項，下列何者錯誤？","options":["(A) 病人姓名、性別、年齡、出生年月日","(B) 藥品名稱、劑量、數量、用法","(C) 作用或適應症、警語或副作用","(D) 藥局地點、名稱及調劑者姓名"],"answer":0,"image":""},{"id":"ph6-114-1-14","subject":"ph6","topic":"藥事法規-藥師法與執業管理","meta":"114年第1次第14題","year":114,"session":1,"number":14,"question":"依據藥師法，下列敘述何者錯誤？","options":["(A) 藥師對於醫師所開處方，祇許調劑一次，其處方箋應於調劑後簽名蓋章，添記調劑年、月、日","(B) 負責主持經營藥局之藥師，應具備二年以上實際調劑執業經驗，始得提供藥品調劑服務","(C) 醫療機構聘藥師提供藥事服務者，其藥師至少應有一人具備二年以上實際調劑執業經驗，始得提供藥品調劑服務","(D) 藥師移付懲戒事項，應由藥師公會或主管機關處理"],"answer":3,"image":""},{"id":"ph6-114-1-15","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"114年第1次第15題","year":114,"session":1,"number":15,"question":"藥事法所稱之劣藥，係指核准之藥品經稽查或檢驗之情形，不包括下列何者？","options":["(A) 藥品中一部或全部含有污穢或異物者","(B) 超過有效期間或保存期限者","(C) 所含有效成分之質、量或強度，與核准不符者","(D) 塗改或更換有效期間之標示者"],"answer":3,"image":""},{"id":"ph6-114-1-16","subject":"ph6","topic":"調劑學-處方判讀與調劑作業","meta":"114年第1次第16題","year":114,"session":1,"number":16,"question":"依藥品優良調劑作業準則，有關藥事人員調劑之行為，不包括下列何者？","options":["(A) 處方確認","(B) 用藥適當性評估","(C) 缺藥訂購藥品","(D) 藥品調配或調製"],"answer":2,"image":""},{"id":"ph6-114-1-17","subject":"ph6","topic":"藥事法規-藥師法與執業管理","meta":"114年第1次第17題","year":114,"session":1,"number":17,"question":"依藥師法規定，藥師懲戒委員會、藥師懲戒覆審委員會之委員，其中法學專家學者及社會人士之比例不得少於多少？","options":["(A) 五分之一","(B) 二分之一","(C) 四分之一","(D) 三分之一"],"answer":3,"image":""},{"id":"ph6-114-1-18","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"114年第1次第18題","year":114,"session":1,"number":18,"question":"下列何者符合藥廠PIC/S GMP執行之規範？","options":["(A) 生產區內必須設有升降梯，運送原物料","(B) 無菌試驗與微生物試驗共用操作室","(C) 執行持續性安定性試驗產品，不需置於溫濕度控制區","(D) 製造區應依需求設置潔淨區"],"answer":3,"image":""},{"id":"ph6-114-1-19","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"114年第1次第19題","year":114,"session":1,"number":19,"question":"依照PIC/S GMP，有關藥品之製造，下列何者最不適當？","options":["(A) 青黴素類藥品應有專用獨立空氣處理系統","(B) 雌激素類藥品應有專用生產區","(C) 抗癌藥製造，僅當與注射劑共用廠房時，方可不需另完成確效","(D) 高血壓藥品，如有特別預防措施並經確效，可採時段切換生產"],"answer":2,"image":""},{"id":"ph6-114-1-20","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"114年第1次第20題","year":114,"session":1,"number":20,"question":"依據藥事法，在下列何種情況下，醫師得親自為藥品之調劑？","options":["(A) 需病人簽署同意書","(B) 管制藥品之調劑","(C) 藥師請假時","(D) 醫療急迫情形"],"answer":3,"image":""},{"id":"ph6-114-1-21","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"114年第1次第21題","year":114,"session":1,"number":21,"question":"下列有關臺灣清冠一號之敘述，何者錯誤？","options":["(A) 中藥行以臺灣清冠一號之配方為依據，以中藥飲片調製即飲包，告知患者此即為政府核定之臺灣清冠一號，此舉可能違反藥事法","(B) 中藥房開發食品級防疫茶，號稱「類清冠一號」，宣稱效果更溫和可以平日服用，有預防及治療之效果，此舉可能違反藥事法","(C) 中藥行廣告宣稱「本店會員可享有臺灣清冠一號買一送一之優惠」，此舉恐違反消費者保護法","(D) 某中藥行大量囤積臺灣清冠一號，並哄抬價格賣給中醫診所，此舉恐違反公平交易法"],"answer":2,"image":""},{"id":"ph6-114-1-22","subject":"ph6","topic":"藥事法規-藥師法與執業管理","meta":"114年第1次第22題","year":114,"session":1,"number":22,"question":"下列有關藥師執行業務，何者錯誤？","options":["(A) 執行藥品鑑定業務，應作成鑑定書，由藥師簽章","(B) 對於處方有可疑之處，應詢明原處方醫師確認","(C) 販售醫師處方藥品，以提高患者用藥可近性","(D) 藥局標示為日夜調劑者，其藥師應日夜為之"],"answer":2,"image":""},{"id":"ph6-114-1-23","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"114年第1次第23題","year":114,"session":1,"number":23,"question":"依據藥事法，藥商持有經中央衛生主管機關公告為必要藥品之許可證，如有無法繼續製造、輸入或不足供應該藥品之虞時，應至少於多久前向中央衛生主管機關通報？","options":["(A) 30天","(B) 2個月","(C) 3個月","(D) 6個月"],"answer":3,"image":""},{"id":"ph6-114-1-24","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"114年第1次第24題","year":114,"session":1,"number":24,"question":"小明無藥師及藥劑生資格，若想要經營西藥零售業務，依據藥事法規定，下列敘述何者錯誤？","options":["(A) 領有藥商許可執照後可以販售成藥","(B) 應聘專任藥師或藥劑生駐店管理","(C) 應向衛生局請領藥局執照","(D) 領有藥商許可執照後可以申請網路販售乙類成藥"],"answer":2,"image":""},{"id":"ph6-114-1-25","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"114年第1次第25題","year":114,"session":1,"number":25,"question":"依據藥事法，下列對於偽藥之敘述，何者錯誤？","options":["(A) 舉發或緝獲偽藥，應予獎勵","(B) 販賣或意圖販賣而陳列偽藥者，由直轄市或縣（市）衛生主管機關，公告其公司或商號之名稱、地址、負責人姓名、藥品名稱及違反情節","(C) 明知為偽藥而販賣、供應、調劑或意圖販賣而陳列者，處刑罰得併科罰金","(D) 查獲之偽藥，如係本國製造，經檢驗後仍可改製使用者，可由直轄市或縣（市）衛生主管機關，派員監督原製造廠商限期改製"],"answer":3,"image":""},{"id":"ph6-114-1-26","subject":"ph6","topic":"藥事法規-藥物廣告與稽查","meta":"114年第1次第26題","year":114,"session":1,"number":26,"question":"依據藥事法，下列有關藥品廣告之敘述，何者錯誤？","options":["(A) 非藥事法所稱之藥品，不得為醫療效能之標示或宣傳","(B) 利用傳播方法，宣傳醫療效能，以達招徠銷售為目的之行為，為藥品廣告","(C) 可藉由採訪美國科學家研發之某藥品來宣傳此藥品之效果","(D) 藥品廣告刊登時，廠商名稱、藥品許可證及廣告核准文件字號，也要一併刊登"],"answer":2,"image":""},{"id":"ph6-114-1-27","subject":"ph6","topic":"藥事法規-新藥臨床試驗與安全監視","meta":"114年第1次第27題","year":114,"session":1,"number":27,"question":"依藥品嚴重不良反應通報辦法，知悉藥品引起嚴重不良反應發生時，下列何者應填具通報書，連同相關資料，向中央衛生主管機關或其委託機構通報？①藥師 ②醫師 ③護理師 ④藥商 ⑤產生不良反應之民眾","options":["(A) 僅①②","(B) 僅①②③","(C) ①②③④⑤","(D) 僅④"],"answer":3,"image":""},{"id":"ph6-114-1-28","subject":"ph6","topic":"藥事法規-新藥臨床試驗與安全監視","meta":"114年第1次第28題","year":114,"session":1,"number":28,"question":"下列何者為藥商對於藥品安全監視的職責？①針對所蒐集的藥品安全性資訊進行評估及分析 ②繳交藥品安全性定期報告 ③針對有安全疑慮之藥品採取風險管控措施 ④執行藥品風險評估及管控計畫","options":["(A) 僅①②","(B) 僅③④","(C) ①②③④","(D) 僅①③"],"answer":2,"image":""},{"id":"ph6-114-1-29","subject":"ph6","topic":"藥事法規-新藥臨床試驗與安全監視","meta":"114年第1次第29題","year":114,"session":1,"number":29,"question":"依據藥品安全監視管理辦法，藥商自藥品許可證發證日起五年內，繳交藥品安全性定期報告之方式，下列何者正確？","options":["(A) 以每一年為一期繳交","(B) 以每六個月為一期繳交","(C) 第一年、第二年，以每六個月為一期，其餘三年，以每年為一期繳交","(D) 前三年以每六個月為一期，之後兩年，以每年為一期繳交"],"answer":2,"image":""},{"id":"ph6-114-1-30","subject":"ph6","topic":"藥事法規-醫療器材管理法","meta":"114年第1次第30題","year":114,"session":1,"number":30,"question":"依據醫療器材管理法及醫療器材安全監視管理辦法，下列敘述何者錯誤？","options":["(A) 醫療器材經核准製造、輸入或完成登錄者，中央主管機關得指定品項、期間，令醫療器材商依公告或核定之安全監視計畫，監視其安全性","(B) 醫療器材商應定期製作安全監視報告繳交中央主管機關","(C) 醫療器材安全監視之期間，自發證日、登錄日、公告日或指定日起五年；必要時，中央主管機關得延長之","(D) 醫療器材安全監視計畫執行之方式、內容與原公告或核定不符者，中央主管機關得令醫療器材商限期改善或延長監視期間"],"answer":2,"image":""},{"id":"ph6-114-1-31","subject":"ph6","topic":"藥事法規-醫療器材管理法","meta":"114年第1次第31題","year":114,"session":1,"number":31,"question":"依據醫療器材管理法及特定醫療器材專案核准製造及輸入辦法規定，關於因應新型冠狀病毒肺炎COVID-19期間申請家用抗原檢測試劑之製造或輸入，下列何者正確？","options":["(A) 中央及地方主管機關皆得專案核准該試劑之製造或輸入","(B) 學校不得為該試劑之專案核准製造或輸入者","(C) 醫療器材商資本額未達新台幣五億元以上，不得為該試劑專案核准製造或輸入者","(D) 該試劑專案核准國內製造者，應檢附工廠登記證資料，但依工廠管理輔導法規定，免辦理工廠登記者，不在此限"],"answer":3,"image":""},{"id":"ph6-114-1-32","subject":"ph6","topic":"藥事法規-新藥臨床試驗與安全監視","meta":"114年第1次第32題","year":114,"session":1,"number":32,"question":"依據人體試驗管理辦法，下列敘述何者錯誤？","options":["(A) 受試者於人體試驗施行期間發生可能導致永久性傷害之併發症時，醫療機構應通報中央主管機關","(B) 醫療機構得因受試者隱私，拒絕中央主管機關所令提供人體試驗計畫摘要及可能風險等有關資料","(C) 醫療機構於人體試驗期間，不得對外發表成果或為宣傳","(D) 醫療機構不得向受試者收取人體試驗有關之任何費用"],"answer":1,"image":""},{"id":"ph6-114-1-33","subject":"ph6","topic":"藥事法規-新藥臨床試驗與安全監視","meta":"114年第1次第33題","year":114,"session":1,"number":33,"question":"依據藥品生體可用率及生體相等性試驗作業準則，關於生體可用率及生體相等性試驗設計之敘述，下列何者錯誤？","options":["(A) 健康受試者於參加試驗前，應禁服任何藥品二週以上","(B) 服藥前，應禁食十小時以上","(C) 服藥後，應再繼續禁食十小時","(D) 藥品如係速放製劑者，應執行單劑量禁食試驗。但其仿單用藥指示必須與食物併服時，應改以執行單劑量食物影響試驗"],"answer":2,"image":""},{"id":"ph6-114-1-34","subject":"ph6","topic":"藥事法規-新藥臨床試驗與安全監視","meta":"114年第1次第34題","year":114,"session":1,"number":34,"question":"依據藥品生體可用率及生體相等性試驗作業準則，符合下列何種情形者，不得免除生體相等性試驗？","options":["(A) 眼用、耳用製劑之學名藥","(B) 學名藥口服溶液劑且賦形劑不影響主成分吸收者","(C) 皮下及皮內吸收製劑之學名藥","(D) 供吸入之氣體"],"answer":2,"image":""},{"id":"ph6-114-1-35","subject":"ph6","topic":"藥事法規-新藥臨床試驗與安全監視","meta":"114年第1次第35題","year":114,"session":1,"number":35,"question":"依藥品嚴重不良反應通報辦法及相關法規，下列敘述何者錯誤？","options":["(A) 無論藥品或醫療器材，發生嚴重不良反應皆應依法定程序通報","(B) 發生死亡或危及生命，醫療機構及藥局依法應於得知後，在7天內向衛生福利部疾病管制署通報","(C) 未依藥品嚴重不良反應通報辦法執行，應處行政罰鍰","(D) 於緊急時，得先行以口頭方式通報，並應於期限內完成書面通報"],"answer":1,"image":""},{"id":"ph6-114-1-36","subject":"ph6","topic":"藥事法規-新藥臨床試驗與安全監視","meta":"114年第1次第36題","year":114,"session":1,"number":36,"question":"依藥品安全監視管理辦法之規定，下列敘述何者錯誤？","options":["(A) 依藥事法之規定訂定","(B) 藥品之安全監視指定期間，以藥品許可證有效期間為準","(C) 發現未預期之嚴重藥品不良反應時，藥商應自知悉之日起十五日內至中央衛生主管機關建置之網路系統通報","(D) 中央衛生主管機關接獲新藥安全性總結報告，認有必要時得指定期間要求藥商續行資料蒐集及報告繳交"],"answer":2,"image":""},{"id":"ph6-114-1-37","subject":"ph6","topic":"藥事法規-藥物廣告與稽查","meta":"114年第1次第37題","year":114,"session":1,"number":37,"question":"須由醫師處方之藥品，僅可於下列何者廣告？","options":["(A) 電視","(B) 廣播","(C) 報紙","(D) 學術性醫療刊物"],"answer":3,"image":""},{"id":"ph6-114-1-38","subject":"ph6","topic":"藥事法規-新藥臨床試驗與安全監視","meta":"114年第1次第38題","year":114,"session":1,"number":38,"question":"下列何者屬於藥品安定性試驗內容？","options":["(A) 加速試驗","(B) 溶離度試驗","(C) 生體相等性試驗","(D) 崩散度試驗"],"answer":0,"image":""},{"id":"ph6-114-1-39","subject":"ph6","topic":"藥事法規-管制藥品與毒品危害防制","meta":"114年第1次第39題","year":114,"session":1,"number":39,"question":"依據管制藥品管理條例施行細則，有關管制藥品購買人簽名之單據應載明之內容為何？①買、賣雙方之名稱、管制藥品登記證字號及地址 ②買賣日期 ③品項、單價及總金額 ④品名、許可證字號、製造廠名稱 ⑤管制藥品成分含量、管制級別、批號及數量","options":["(A) ①②③④⑤","(B) 僅①②④⑤","(C) 僅④⑤","(D) 僅③"],"answer":0,"image":""},{"id":"ph6-114-1-40","subject":"ph6","topic":"藥事法規-管制藥品與毒品危害防制","meta":"114年第1次第40題","year":114,"session":1,"number":40,"question":"目前經衛生福利部核准用於鴉片類物質成癮替代治療之第二級管制藥品，其使用時應在醫事人員監督下服用之藥品為何？","options":["(A) 丁基原啡因（buprenorphine）","(B) 美沙冬（methadone）","(C) 嗎啡（morphine）","(D) 可待因（codeine）"],"answer":1,"image":""},{"id":"ph6-114-1-41","subject":"ph6","topic":"藥事法規-管制藥品與毒品危害防制","meta":"114年第1次第41題","year":114,"session":1,"number":41,"question":"有關使用第一級至第三級管制藥品，下列何者錯誤？","options":["(A) 醫師、牙醫師、獸醫師或獸醫佐須領有衛生福利部食品藥物管理署核發之管制藥品使用執照","(B) 醫師、牙醫師應開立管制藥品專用處方箋","(C) 調劑管制藥品專用處方箋，均只能調劑一次","(D) 調劑後，應由領受人憑身分證明簽名領受"],"answer":2,"image":""},{"id":"ph6-114-1-42","subject":"ph6","topic":"藥事法規-化粧品衛生安全管理法","meta":"114年第1次第42題","year":114,"session":1,"number":42,"question":"依化粧品衛生安全管理法之規定，下列何種情形非屬所稱之嚴重不良反應？","options":["(A) 皮膚過敏","(B) 暫時性失能","(C) 永久性失能","(D) 導致使用者住院治療"],"answer":0,"image":""},{"id":"ph6-114-1-43","subject":"ph6","topic":"藥事法規-藥害救濟與罕見疾病","meta":"114年第1次第43題","year":114,"session":1,"number":43,"question":"依據藥害救濟法，下列何者非屬藥害救濟之範圍？","options":["(A) 成藥","(B) 新上市藥品","(C) 公費疫苗","(D) 自費藥品"],"answer":2,"image":""},{"id":"ph6-114-1-44","subject":"ph6","topic":"藥事法規-藥害救濟與罕見疾病","meta":"114年第1次第44題","year":114,"session":1,"number":44,"question":"下列何者屬藥害救濟法所指正當使用合法藥品之範疇？","options":["(A) 自行使用國外攜回之藥品","(B) 依處方使用緊急授權之藥品","(C) 依藥師指示服用成藥","(D) 未依處方指示而服用過量藥品"],"answer":2,"image":""},{"id":"ph6-114-1-45","subject":"ph6","topic":"藥事法規-藥害救濟與罕見疾病","meta":"114年第1次第45題","year":114,"session":1,"number":45,"question":"依據罕見疾病防治及藥物法，下列有關罕見疾病藥物查驗登記之敘述，何者正確？","options":["(A) 罕見疾病藥物經查驗登記發給藥物許可證者，其許可證有效期間為七年，較一般新藥之有效期間長","(B) 罕見疾病藥物因性質特殊，申請罕見疾病藥物查驗登記者，中央主管機關不得要求其進行國內臨床試驗","(C) 若持有罕見疾病藥物許可證者無法供應該藥物之需求，中央主管機關得於其許可證有效期間內，受理其他同類藥物之查驗登記申請","(D) 罕見疾病藥物於許可證有效期間期滿後，若已有同類藥物申請查驗登記，不得向中央主管機關申請展延"],"answer":2,"image":""},{"id":"ph6-114-1-46","subject":"ph6","topic":"藥事法規-全民健康保險與藥事作業","meta":"114年第1次第46題","year":114,"session":1,"number":46,"question":"依據全民健康保險藥品價格調整作業辦法，下列有關藥品支付價格調整之敘述，何者錯誤？","options":["(A) 藥商及保險醫事服務機構，應向保險人申報市場實際交易價格，作為調整藥品支付價格之依據","(B) 全民健康保險實施藥品費用分配比率目標制，該年度藥費核付金額超出前一年預先設定之目標值時，調整專利期內藥品之支付價格","(C) 保險人進行藥價調整時，得對藥品訂定基本價及下限價","(D) 罕見疾病用藥之支付價格應每五年檢討一次"],"answer":3,"image":""},{"id":"ph6-114-1-47","subject":"ph6","topic":"藥事法規-全民健康保險與藥事作業","meta":"114年第1次第47題","year":114,"session":1,"number":47,"question":"某年長者因糖尿病，使用慢性病連續處方箋之藥品。下列敘述何者最適當？","options":["(A) 如某日該病人因極端不適，送急診處置。急診醫師僅能加開麻醉鎮痛劑處方箋","(B) 開立慢性病連續處方箋之藥品，不得為管制藥品管理條例規定之第二級管制藥品","(C) 該病人因故未攜帶健保卡，醫師仍可以請病人以自費方式開給慢性病連續處方箋","(D) 依衛生福利部規定，僅慢性病連續處方箋必須調劑三次"],"answer":1,"image":""},{"id":"ph6-114-1-48","subject":"ph6","topic":"藥事法規-全民健康保險與藥事作業","meta":"114年第1次第48題","year":114,"session":1,"number":48,"question":"某病人罹患有高血壓與失智症，最近又診斷出狹心症，醫師分別開立了valsartan、memantine與nitroglycerin。依據全民健康保險醫療辦法，有關上述處方用藥之敘述，下列何者最適當？","options":["(A) 因屬同一人罹患的慢性病，valsartan與memantine可開立在同一張慢性病連續處方箋","(B) 年長者可憑身分證明，至藥局自費購買nitroglycerin","(C) 保險對象領藥後，因藥品遺失或毀損，再就醫之醫療費用，由中央健康保險署負擔","(D) 慢性病連續處方箋，總用藥量至多90日"],"answer":3,"image":""},{"id":"ph6-114-1-49","subject":"ph6","topic":"藥事法規-全民健康保險與藥事作業","meta":"114年第1次第49題","year":114,"session":1,"number":49,"question":"下列何者非屬全民健康保險醫療辦法規定，得一次領取有效期間內之慢性病連續處方箋總用量之保險對象？","options":["(A) 預定出國","(B) 妊娠期間","(C) 遠洋漁船船員出海作業","(D) 國際航線船舶船員出海服務"],"answer":1,"image":""},{"id":"ph6-114-1-50","subject":"ph6","topic":"藥事法規-全民健康保險與藥事作業","meta":"114年第1次第50題","year":114,"session":1,"number":50,"question":"依據全民健康保險醫療服務給付項目及支付標準，藥事服務費之成本，不包含下列那個項目？","options":["(A) 處方確認","(B) 藥品調配","(C) 用藥指導","(D) 藥品運輸"],"answer":3,"image":""},{"id":"ph6-114-2-1","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"114年第2次第1題","year":114,"session":2,"number":1,"question":"依據長期照顧服務法，下列何者應以長照機構法人方式設立？","options":["(A) 居家式服務機構","(B) 住宿式服務機構","(C) 綜合式服務機構","(D) 社區式日間照顧中心"],"answer":1,"image":""},{"id":"ph6-114-2-2","subject":"ph6","topic":"藥事法規-藥政管理組織與衛生行政","meta":"114年第2次第2題","year":114,"session":2,"number":2,"question":"下列何者非屬衛生福利部掌理事項中之重要政策？","options":["(A) 中醫藥發展政策","(B) 醫事人員及醫事機構管理政策","(C) 家庭暴力、性侵害及性騷擾防治政策","(D) 食品、藥物、化粧品管理政策"],"answer":[0,1,2,3],"image":"","answer_note":"送分:第2題一律給分 (原公告答案 D)"},{"id":"ph6-114-2-3","subject":"ph6","topic":"藥事法規-藥害救濟與罕見疾病","meta":"114年第2次第3題","year":114,"session":2,"number":3,"question":"藥害救濟及預防接種救濟之中央衛生主管機關分別為何？","options":["(A) 藥害救濟基金會、衛生福利部食品藥物管理署","(B) 藥害救濟基金會、衛生福利部疾病管制署","(C) 衛生福利部、衛生福利部","(D) 衛生福利部食品藥物管理署、衛生福利部國民健康署"],"answer":2,"image":""},{"id":"ph6-114-2-4","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"114年第2次第4題","year":114,"session":2,"number":4,"question":"依據藥事法，對於涉嫌之偽藥、禁藥應先行就地封存，這個任務應由下列何者執行？","options":["(A) 法院強制執行處","(B) 直轄市或縣（市）衛生主管機關","(C) 衛生福利部食品藥物管理署","(D) 直轄市或縣（市）警察局"],"answer":1,"image":""},{"id":"ph6-114-2-5","subject":"ph6","topic":"藥事法規-藥物廣告與稽查","meta":"114年第2次第5題","year":114,"session":2,"number":5,"question":"依據藥事法，降血壓藥廣告可以在下列何種刊物刊登？","options":["(A) 消費者雜誌","(B) 台灣醫學會期刊","(C) 健康世界雜誌","(D) 運動健美雜誌"],"answer":1,"image":""},{"id":"ph6-114-2-6","subject":"ph6","topic":"藥事法規-藥政管理組織與衛生行政","meta":"114年第2次第6題","year":114,"session":2,"number":6,"question":"依傳染病防治法，為因應COVID-19公共衛生事件，得報請行政院同意設置下列何者？","options":["(A) 中央流行疫情指揮中心","(B) 中央傳染病防治中心","(C) 中央傳染病管制局","(D) 中央緊急應變局"],"answer":0,"image":""},{"id":"ph6-114-2-7","subject":"ph6","topic":"藥事法規-全民健康保險與藥事作業","meta":"114年第2次第7題","year":114,"session":2,"number":7,"question":"依據全民健康保險法，醫療服務給付項目及支付標準應以相對點數反應各項服務成本及以同病、同品質同酬為原則，下列何者非屬得以訂定之方式？","options":["(A) 論量","(B) 論年","(C) 論品質","(D) 論病例"],"answer":1,"image":""},{"id":"ph6-114-2-8","subject":"ph6","topic":"藥事法規-新藥臨床試驗與安全監視","meta":"114年第2次第8題","year":114,"session":2,"number":8,"question":"依據藥事法及藥品安全監視管理辦法，藥品安全監視範圍及期間分別為何？","options":["(A) 藥事法所稱之新藥：5年","(B) 所有領有許可證之藥品：藥品許可證有效期間","(C) 所有領有藥品許可證之西藥及中藥屬藥事法所稱之新藥，或公告須執行藥品安全性監視者：藥品許可證有效期間","(D) 所有領有藥品許可證之西藥及中藥屬藥事法所稱之新藥，或公告須執行藥品安全性監視者：5年"],"answer":2,"image":""},{"id":"ph6-114-2-9","subject":"ph6","topic":"藥事法規-藥師法與執業管理","meta":"114年第2次第9題","year":114,"session":2,"number":9,"question":"關於藥局憑證保存規定，下列何者錯誤？","options":["(A) 調劑zolpidem之處方箋，至少保存5年","(B) 調劑valsartan之處方箋，至少保存3年","(C) 調劑pseudoephedrine類製劑之來源憑證，至少保存5年","(D) 調劑amlodipine之來源憑證，至少保存3年"],"answer":2,"image":""},{"id":"ph6-114-2-10","subject":"ph6","topic":"藥事法規-藥師法與執業管理","meta":"114年第2次第10題","year":114,"session":2,"number":10,"question":"小明為剛畢業取得資格之藥師，大明為醫院中醫部門藥局執業20年的藥劑生，二人合作開設藥局，下列敘述何者正確？","options":["(A) 小明可為藥局之負責藥師，與衛生福利部中央健康保險署簽訂特約","(B) 大明可以設立執行中藥業務之藥局，調劑中藥處方","(C) 大明可以調劑丁基原啡因（Buprenorphine）處方","(D) 大明可以負責人身分向金融機構申請專屬帳戶，提供衛生福利部中央健康保險署撥付健保帳款"],"answer":1,"image":""},{"id":"ph6-114-2-11","subject":"ph6","topic":"藥事法規-藥師法與執業管理","meta":"114年第2次第11題","year":114,"session":2,"number":11,"question":"民國110年入學之藥學系學生，如畢業後欲從事中藥製劑製造供應及調劑，應修習中藥課程標準為何？","options":["(A) 中藥16學分及中藥場域實習80小時","(B) 中藥16學分及中藥場域實習160小時","(C) 中藥17學分及中藥場域實習80小時","(D) 中藥17學分及中藥場域實習160小時"],"answer":3,"image":""},{"id":"ph6-114-2-12","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"114年第2次第12題","year":114,"session":2,"number":12,"question":"藥局設置平面圖如下，甲範圍是藥事作業處所，乙範圍是調劑處所，A、B、C、D、E、F皆為置放處，下列敘述何者錯誤？","options":["(A) 醫師處方藥可放在A處","(B) 乙範圍僅得從事處方調劑","(C) B處可置放醫療器材","(D) 供處方調劑之冷鏈藥品冰箱應設置於乙範圍"],"answer":0,"image":"ph6-114-2-12.jpeg"},{"id":"ph6-114-2-13","subject":"ph6","topic":"藥事法規-管制藥品與毒品危害防制","meta":"114年第2次第13題","year":114,"session":2,"number":13,"question":"小明藥師開設藥局，並找了藥劑生大明一同經營，下列敘述何者錯誤？","options":["(A) fentanyl只有小明可調劑，且只能調劑一次","(B) tramadol只有小明可調劑，且要注意處方箋上是否載有管制藥品使用執照號碼","(C) zopiclone大明可調劑，且本藥品不須使用管制藥品專用處方箋","(D) zolpidem大明、小明皆可調劑，本處方箋應妥善保存5年"],"answer":1,"image":""},{"id":"ph6-114-2-14","subject":"ph6","topic":"藥事法規-藥師法與執業管理","meta":"114年第2次第14題","year":114,"session":2,"number":14,"question":"下列關於藥師執業執照更新之敘述，何者正確？","options":["(A) 須在執業執照更新日前2個月內辦理更新作業","(B) 領取藥師證書未超過5年申請執業登記，其執業執照之更新日期為自藥師證書發證屆滿第6年之翌日","(C) 歇業後重新申請執業登記，無論是否逾原發執業執照日期，其執業執照之更新日期一律為自執業登記日起算6年","(D) 藥師申請執業執照更新，應檢具綜合臨床藥學訓練證明文件"],"answer":1,"image":""},{"id":"ph6-114-2-15","subject":"ph6","topic":"藥事法規-藥師法與執業管理","meta":"114年第2次第15題","year":114,"session":2,"number":15,"question":"下列有關藥師調劑之敘述，何者錯誤？","options":["(A) 藥師應按處方調劑，不得錯誤","(B) 藥品未備或缺乏時，應通知原處方醫師，請其更換，不得任意省略或代以他藥","(C) 藥師執業執照應懸掛於調劑處所","(D) 非有正當理由，不得拒絕為調劑"],"answer":2,"image":""},{"id":"ph6-114-2-16","subject":"ph6","topic":"藥事法規-藥師法與執業管理","meta":"114年第2次第16題","year":114,"session":2,"number":16,"question":"依藥師法之規定，下列何者為藥師業務？","options":["(A) 施打疫苗","(B) 毒癮戒治","(C) 藥品販賣","(D) 抽血"],"answer":2,"image":""},{"id":"ph6-114-2-17","subject":"ph6","topic":"藥事法規-藥師法與執業管理","meta":"114年第2次第17題","year":114,"session":2,"number":17,"question":"下列有關藥師懲戒委員會之敘述，何者錯誤？","options":["(A) 藥師懲戒委員會之委員，應就不具民意代表身分之藥學、法學專家學者及社會人士遴聘之，其中法學專家學者及社會人士之比例不得少於三分之二","(B) 藥師懲戒委員會由中央或直轄市、縣（市）主管機關設置","(C) 藥師懲戒委員會應將移付懲戒事件，通知被付懲戒之藥師，並限其於通知送達之翌日起二十日內提出答辯或於指定期日到會陳述；未依限提出答辯或到會陳述者，藥師懲戒委員會得逕行決議","(D) 被懲戒人對於藥師懲戒委員會之決議有不服者，得於決議書送達翌日起二十日內，向藥師懲戒覆審委員會請求覆審"],"answer":0,"image":""},{"id":"ph6-114-2-18","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"114年第2次第18題","year":114,"session":2,"number":18,"question":"若在夜市之檳榔攤販賣保力達B液，下列敘述何者最適當？","options":["(A) 該檳榔攤販若依成藥及固有成方製劑管理辦法規定，將保力達B液置於乙類成藥專設櫥櫃內，並妥善貯藏，則可依法販賣之","(B) 該檳榔攤得依大法官釋字第711號解釋，宣告藥師法第11條「藥師執業以一處為限」違憲，可聘管理藥師兼管攤位，以調劑保力達B液","(C) 衛生主管機關取締該檳榔攤，主要因該檳榔攤無藥商執照而販售藥品","(D) 目前保力達B液與維士比液，均以藥食兩用管理，但販賣仍需向衛生福利部食品藥物管理署登記備查"],"answer":2,"image":""},{"id":"ph6-114-2-19","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"114年第2次第19題","year":114,"session":2,"number":19,"question":"日前發生某藥商，將藥品「正露丸」過期品重新包裝、更改標籤及有效期間標示。對於該業者之查處，下列何者最適當？","options":["(A) 塗改或更換藥品有效期間標示者，可處10年以下有期徒刑","(B) 該藥品因係過期品，應屬於劣藥管理","(C) 本案涉案行為屬仿製藥，以偽造文書論罪","(D) 業者須提出藥品性狀、成分、質、量或強度等化驗鑑定數據"],"answer":0,"image":""},{"id":"ph6-114-2-20","subject":"ph6","topic":"藥事法規-藥師法與執業管理","meta":"114年第2次第20題","year":114,"session":2,"number":20,"question":"依據藥師法及管制藥品管理條例，下列敘述何者正確？","options":["(A) 麻醉藥品得由藥師及藥劑生調劑","(B) 藥師調劑，如藥品未備或缺乏時，得以他藥替代","(C) 藥師應親自主持其所經營之藥局業務，受理醫師處方或依中華藥典、國民處方選輯之處方調劑","(D) 藥師執業以一處為限，報備支援以藥商為限"],"answer":2,"image":""},{"id":"ph6-114-2-21","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"114年第2次第21題","year":114,"session":2,"number":21,"question":"依據藥事法，有關西藥、中藥販賣業者之敘述，下列何者正確？","options":["(A) 兼任藥師可以駐店管理西藥販賣業者之藥品及其買賣","(B) 專任藥劑生可以駐店管理西藥販賣業者售賣麻醉藥品","(C) 專任中醫師可以駐店管理中藥販賣業者之藥品及其買賣","(D) 分設營業處所，得無需聘請藥師駐店管理"],"answer":2,"image":""},{"id":"ph6-114-2-22","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"114年第2次第22題","year":114,"session":2,"number":22,"question":"依據藥事法，下列有關藥商僱用推銷員執行推銷業務之敘述，何者正確？","options":["(A) 推銷員可以向藥局推銷非受僱藥商所製造之藥品","(B) 推銷員可以向醫學研究機構推銷臨床試驗藥品","(C) 為利推銷受僱藥商所經銷之藥品，得將藥品拆封販售","(D) 不得沿途推銷受僱藥商所製售之藥品"],"answer":3,"image":""},{"id":"ph6-114-2-23","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"114年第2次第23題","year":114,"session":2,"number":23,"question":"依據藥事法，對於藥商的管理規定，下列敘述何者正確？","options":["(A) 藥商申請停業，應將藥商許可執照及藥物許可證隨繳當地衛生主管機關，每次停業期間最長不得超過半年","(B) 民國82年2月5日前列冊登記之中藥商，得從事非屬中醫師處方藥品之零售業務","(C) 藥商持有經中央衛生主管機關公告為必要藥品之許可證，如有無法繼續製造、輸入或不足供應該藥品之虞時，應至少於三個月前向中央衛生主管機關通報","(D) 凡取得藥師執照者，即可於中藥製造業擔任駐廠監製藥師"],"answer":1,"image":""},{"id":"ph6-114-2-24","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"114年第2次第24題","year":114,"session":2,"number":24,"question":"某君想要經營西藥零售及輸入業務，依據藥事法規定，下列敘述何者正確？","options":["(A) 應向衛生福利部食品藥物管理署申請藥商許可執照","(B) 申請藥商許可執照時，營業場所的範圍也包括貯存藥品倉庫","(C) 輸入之製劑，可直接委託符合藥品優良製造規範之藥廠分裝後出售","(D) 領有藥商許可執照後可以兼售農藥"],"answer":1,"image":""},{"id":"ph6-114-2-25","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"114年第2次第25題","year":114,"session":2,"number":25,"question":"依據藥事法，下列敘述何者錯誤？","options":["(A) 未經核准擅自製造者為偽藥","(B) 所含有效成分之質、量或強度與核准不符者為劣藥","(C) 將他人產品抽換或摻雜者為劣藥","(D) 塗改或更換有效期間之標示者為偽藥"],"answer":2,"image":""},{"id":"ph6-114-2-26","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"114年第2次第26題","year":114,"session":2,"number":26,"question":"下列違反藥事法之情事，何者屬行政罰？","options":["(A) 擅用或冒用他人藥品之名稱、仿單或標籤者","(B) 輸入禁藥","(C) 製造藥品擅自添加非法定防腐劑者","(D) 製造之藥品，被查獲有顯明變色、混濁、沈澱、潮解或已腐化分解者"],"answer":3,"image":""},{"id":"ph6-114-2-27","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"114年第2次第27題","year":114,"session":2,"number":27,"question":"根據藥事法，下列敘述何者錯誤？","options":["(A) 製造或輸入偽藥、禁藥者，應由原核准機關，廢止其全部藥物許可證、藥商許可執照、藥物製造許可及公司、商業、工廠之全部或部分登記事項","(B) 藥品許可證未申請展延者，其製造或輸入之業者，應即通知醫療機構、藥局及藥商，並於依法認定應回收之日起二個月內收回市售品","(C) 查獲之劣藥如為核准輸入者，應即封存，並由直轄市或縣（市）衛生主管機關責令原進口商限期退運出口，屆期未能退貨者，沒入銷燬之","(D) 查獲之偽藥或禁藥，沒入銷燬之"],"answer":1,"image":""},{"id":"ph6-114-2-28","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"114年第2次第28題","year":114,"session":2,"number":28,"question":"依藥事法規定，藥品之標籤、仿單或包裝，下列何者為應刊載事項？①廠商地址 ②批號 ③主治效能或適應症 ④藥品許可證字號","options":["(A) 僅①②③","(B) 僅②③④","(C) 僅①②④","(D) ①②③④"],"answer":3,"image":""},{"id":"ph6-114-2-29","subject":"ph6","topic":"藥事法規-藥物廣告與稽查","meta":"114年第2次第29題","year":114,"session":2,"number":29,"question":"高博士與其研發團隊開發出治療心臟病之處方藥順利上市，有關藥事法對於此藥品廣告之規定，下列敘述何者錯誤？①得藉採訪或報導開發過程為宣傳 ②藥品廣告核准之有效期間是一年 ③不得於廣播及電視廣告 ④高博士可用個人名義向衛生單位申請藥品廣告","options":["(A) 僅②③","(B) ①②③","(C) ②③④","(D) ①④"],"answer":3,"image":""},{"id":"ph6-114-2-30","subject":"ph6","topic":"藥事法規-藥物廣告與稽查","meta":"114年第2次第30題","year":114,"session":2,"number":30,"question":"有關藥事法對於藥品廣告之規定，下列敘述何者錯誤？","options":["(A) 某報社於報紙刊播與衛生主管機關原核准不符之藥品廣告，可對該報社處行政罰鍰","(B) 因藥品許可證已由中央主管機關核准，故藥商可截取藥品許可證之處方內容、效能及注意事項之文字圖畫，作為藥品廣告自行刊登","(C) 某報社接受委託刊登藥品廣告，轄區衛生主管機關因稽查之需要，要求其提供委託刊播廣告者之姓名、身分證字號及電話等資料時，報社不可拒絕","(D) 醫師處方藥之廣告，只能刊登於學術性醫療刊物"],"answer":1,"image":""},{"id":"ph6-114-2-31","subject":"ph6","topic":"藥事法規-新藥臨床試驗與安全監視","meta":"114年第2次第31題","year":114,"session":2,"number":31,"question":"依藥品嚴重不良反應通報辦法，藥商得知所持許可證藥品疑似發生導致死亡之不良反應，應於多久內辦理通報？","options":["(A) 24小時","(B) 3日","(C) 7日","(D) 15日"],"answer":3,"image":""},{"id":"ph6-114-2-32","subject":"ph6","topic":"藥事法規-醫療器材管理法","meta":"114年第2次第32題","year":114,"session":2,"number":32,"question":"依據輸入醫療器材邊境抽查檢驗辦法，下列何者無須實施邊境查驗？","options":["(A) 衛生套（保險套）","(B) 耳溫槍","(C) 一般醫用口罩","(D) COVID-19家用型抗原檢測試劑"],"answer":1,"image":""},{"id":"ph6-114-2-33","subject":"ph6","topic":"藥事法規-醫療器材管理法","meta":"114年第2次第33題","year":114,"session":2,"number":33,"question":"下列何種情況，非屬醫療器材管理法規定應回收者？","options":["(A) 原領有許可證或完成登錄，經公告禁止製造或輸入","(B) 非於醫療器材製造許可有效期間內製造或輸入","(C) 未經中央主管機關核准即變更中文品名","(D) 於醫療器材製造後，原領有之許可證逾期但未申請展延者"],"answer":3,"image":""},{"id":"ph6-114-2-34","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"114年第2次第34題","year":114,"session":2,"number":34,"question":"依據藥品查驗登記審查準則，關於學名藥查驗登記申請案之敘述，下列何者錯誤？","options":["(A) 監視藥品之學名藥仿單，應依已核准之首家仿單核定方式記載","(B) 中央衛生主管機關曾核准相同有效成分、劑型、劑量之藥品許可證，如其廢止或註銷之原因與藥品療效安全性無關者，日後首家申請案得依學名藥規定辦理查驗登記","(C) 醫用氣體中，二氧化碳及氧氣之製造方法係源自大氣分離者，得免附安定性試驗資料，惟須留廠備查","(D) 微脂粒（liposome）學名藥查驗登記申請案，除主成分須與已核准之首家相同之外，賦形劑成分及其比例亦皆須相同"],"answer":3,"image":""},{"id":"ph6-114-2-35","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"114年第2次第35題","year":114,"session":2,"number":35,"question":"依據西藥優良運銷準則，下列敘述何者錯誤？","options":["(A) 品質風險管理係指於藥品生命週期間針對藥品品質風險之評估、管制、溝通及審查之系統化流程","(B) 驗證係指證明任何設備之運轉正常且確實能達到預期結果之行為；確效一詞有時會廣義包含驗證之概念","(C) 公共服務責任係指執照持有者／許可證持有者對於已上市且於職責範圍內之藥品應確保適當並持續供應，以涵蓋病患之需求","(D) 實質檢核係專指簽署契約後對企業或人員進行之調查，或確認其符合特定標準"],"answer":3,"image":""},{"id":"ph6-114-2-36","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"114年第2次第36題","year":114,"session":2,"number":36,"question":"® 稽查發現冠脂妥（Crestor 10mg）膜衣錠有下列何種情事，即屬藥事法所稱之偽藥？","options":["(A) 其主治效能與核准不符","(B) 所含成分rosuvastatin，其質、量或強度，與核准不符","(C) 經檢驗所含成分為atorvastatin，與核准不符","(D) 超過有效期間"],"answer":2,"image":""},{"id":"ph6-114-2-37","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"114年第2次第37題","year":114,"session":2,"number":37,"question":"下列有關網路販售藥品及醫療器材之敘述，何者錯誤？","options":["(A) 百貨店、雜貨店及餐旅服務商皆可在網路販賣綠油精","(B) 藥妝店可事前申請核准，在網路販售第一等級醫療器材","(C) 衛生棉條及月亮杯，可在網路上販賣","(D) 甲類成藥可在網路上販售"],"answer":3,"image":""},{"id":"ph6-114-2-38","subject":"ph6","topic":"藥事法規-醫療器材管理法","meta":"114年第2次第38題","year":114,"session":2,"number":38,"question":"醫療器材品質管理系統準則有關醫療器材製造業者之場所、品質管制、運銷等事項之規範，係參照下列何項國際標準組織之標準內容訂定？","options":["(A) ISO 14971","(B) ISO 13485","(C) ISO 10993","(D) ISO 13488"],"answer":1,"image":""},{"id":"ph6-114-2-39","subject":"ph6","topic":"藥事法規-管制藥品與毒品危害防制","meta":"114年第2次第39題","year":114,"session":2,"number":39,"question":"依據管制藥品管理條例，醫師應領有下列何者方得使用嗎啡藥品？","options":["(A) 管制藥品登記證","(B) 管制藥品輸入同意書","(C) 管制藥品使用執照","(D) 管制藥品製造同意書"],"answer":2,"image":""},{"id":"ph6-114-2-40","subject":"ph6","topic":"藥事法規-管制藥品與毒品危害防制","meta":"114年第2次第40題","year":114,"session":2,"number":40,"question":"依據管制藥品管理條例施行細則，有關管制藥品輸出、輸入同意書，下列敘述何者錯誤？","options":["(A) 其輸出期限，自簽發日起不得超過三個月","(B) 其輸入期限，自簽發日起不得超過六個月","(C) 通關時同意書第二聯須經海關核驗簽署","(D) 以使用一次為限"],"answer":1,"image":""},{"id":"ph6-114-2-41","subject":"ph6","topic":"藥事法規-管制藥品與毒品危害防制","meta":"114年第2次第41題","year":114,"session":2,"number":41,"question":"小飛患有過動症，想隨身攜帶第三級管制藥品methylphenidate出國，以便持續治療，依管制藥品管理條例施行細則，應提具下列何種資料報請衛生福利部食品藥物管理署備查？①載明病名、治療經過及必須施用管制藥品理由之醫師診斷證明書 ②出國期間 ③機票影本 ④出國口岸 ⑤攜帶數量及規格","options":["(A) 僅①②④⑤","(B) 僅②④⑤","(C) 僅①⑤","(D) ①②③④⑤"],"answer":0,"image":""},{"id":"ph6-114-2-42","subject":"ph6","topic":"藥事法規-化粧品衛生安全管理法","meta":"114年第2次第42題","year":114,"session":2,"number":42,"question":"下列有關化粧品廣告之敘述，何者正確？","options":["(A) 應事先申請中央或直轄市衛生主管機關核准","(B) 應事先申請中央或直轄市傳播主管機關核准","(C) 化粧品廣告核准文件，其有效期間為一年","(D) 登載、宣播化粧品廣告不得有虛偽誇大之情事"],"answer":3,"image":""},{"id":"ph6-114-2-43","subject":"ph6","topic":"藥事法規-藥害救濟與罕見疾病","meta":"114年第2次第43題","year":114,"session":2,"number":43,"question":"依據藥害救濟法，藥害救濟的請求權時效為自請求權人知有藥害時起幾年？","options":["(A) 1","(B) 3","(C) 5","(D) 10"],"answer":1,"image":""},{"id":"ph6-114-2-44","subject":"ph6","topic":"藥事法規-藥害救濟與罕見疾病","meta":"114年第2次第44題","year":114,"session":2,"number":44,"question":"關於罕見疾病防治及藥物法及其施行細則之敘述，下列何者錯誤？","options":["(A) 疾病盛行率，指中央主管機關參照醫事人員依規定報告之資料及全民健康保險就醫資料所計算之年盛行率","(B) 至少每三年檢討一次疾病盛行率","(C) 中央主管機關應將罕見疾病人口之變遷資料，納入衛生統計","(D) 醫事人員發現罹患罕見疾病之病人或因而致死者，應自發現之日起七日內向中央主管機關報告"],"answer":3,"image":""},{"id":"ph6-114-2-45","subject":"ph6","topic":"藥事法規-藥害救濟與罕見疾病","meta":"114年第2次第45題","year":114,"session":2,"number":45,"question":"有關藥害救濟制度之立法宗旨，下列何者正確？","options":["(A) 為使正當使用合法藥物而受害者，獲得及時救濟","(B) 強化上市後品質監測，保障病人用藥安全","(C) 與藥品優良製造準則競合，精進法規科學進步","(D) 整合藥廠自主管理，促使國際多邊醫療合作"],"answer":0,"image":""},{"id":"ph6-114-2-46","subject":"ph6","topic":"藥事法規-全民健康保險與藥事作業","meta":"114年第2次第46題","year":114,"session":2,"number":46,"question":"全民健康保險醫事服務提供者向保險人申報其所提供之醫療服務點數及藥物費用，在無不可抗力因素時，其申報期限應為：","options":["(A) 提供醫療服務後之三個月內","(B) 提供醫療服務之次月一日起六個月內","(C) 提供醫療服務之當月即可申報","(D) 提供醫療服務後之七日內"],"answer":1,"image":""},{"id":"ph6-114-2-47","subject":"ph6","topic":"藥事法規-全民健康保險與藥事作業","meta":"114年第2次第47題","year":114,"session":2,"number":47,"question":"依全民健康保險醫療辦法，有關醫師處方藥品，如未註明不可替代時之調劑，下列何者最適當？","options":["(A) 僅在缺藥時，得以外銷專用藥取代","(B) 藥師得依法，逕以學名藥替代","(C) 可徵得病人同意自付差額後，以較高價他廠牌藥替代，但不包括癌症用藥","(D) 若未告知保險對象，則不得以同成分、同劑型、同含量其他廠牌藥品替代"],"answer":3,"image":""},{"id":"ph6-114-2-48","subject":"ph6","topic":"藥事法規-全民健康保險與藥事作業","meta":"114年第2次第48題","year":114,"session":2,"number":48,"question":"依據全民健康保險醫事服務機構特約及管理辦法，醫事服務機構可向保險對象收取之費用，下列何者正確？","options":["(A) 衛生福利部中央健康保險署給付的藥品費用","(B) 應自付差額之特殊材料","(C) 衛生福利部中央健康保險署核可給付的檢查頂目","(D) 醫療服務費用"],"answer":1,"image":""},{"id":"ph6-114-2-49","subject":"ph6","topic":"藥事法規-全民健康保險與藥事作業","meta":"114年第2次第49題","year":114,"session":2,"number":49,"question":"依全民健康保險醫療辦法，下列敘述何者錯誤？","options":["(A) 處方箋之有效期間，自開立之日起算三日","(B) 慢性病連續處方箋每次處方之總用藥量至多九十日","(C) 調劑慢性病連續處方箋時，須俟上次給藥期間屆滿之日，始得再次調劑","(D) 罕見疾病病人得出具切結文件，一次領取慢性病連續處方箋之總用藥量"],"answer":2,"image":""},{"id":"ph6-114-2-50","subject":"ph6","topic":"藥事法規-全民健康保險與藥事作業","meta":"114年第2次第50題","year":114,"session":2,"number":50,"question":"依全民健康保險醫療辦法之規定，下列何種情事可開立慢性病連續處方箋？","options":["(A) 保險對象罹患高血壓，經診斷須長期使用相同抗高血壓處方藥品治療","(B) 癌症末期需要嗎啡類第一級管制藥品止痛之病人","(C) 未攜帶健保卡就醫，再依法定期限補卡者","(D) 拔牙後止痛"],"answer":0,"image":""},{"id":"ph6-115-1-1","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"115年第1次第1題","year":115,"session":1,"number":1,"question":"政府為維護民眾飲食安全，要求所有食品業者均須遵守的事項，下列敘述何者錯誤？","options":["(A) 從業人員、作業場所、設施衛生管理及其品保制度，均應符合食品良好衛生規範準則","(B) 訂定食品安全監測計畫","(C) 應保存產品原材料、半成品及成品之來源文件","(D) 須向主管機關申請登錄始得營業"],"answer":[0,1,2,3],"image":"","answer_note":"送分:第1題一律給分 (原公告答案 D)"},{"id":"ph6-115-1-2","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"115年第1次第2題","year":115,"session":1,"number":2,"question":"政府為推動菸害防制，制定相關規範以防止青少年吸菸行為，下列敘述何者錯誤？","options":["(A) 禁止以自動販賣、郵購、電子購物或其他無法辨識消費者年齡之方式販賣菸品","(B) 菸品容器最大正面及反面明顯位置處，應以中文標示吸菸有害健康之警示圖文及戒菸相關資訊，其標示不得低於該面積百分之五十","(C) 菸品促銷及廣告不得以折扣方式銷售或搭配其他物品作為贈品或獎品","(D) 專供外銷之菸品其所含尼古丁及焦油不得逾最高含量"],"answer":3,"image":""},{"id":"ph6-115-1-3","subject":"ph6","topic":"藥事法規-藥政管理組織與衛生行政","meta":"115年第1次第3題","year":115,"session":1,"number":3,"question":"衛部藥製字第OOOOOO號許可證是由下列何單位審核？","options":["(A) 衛生福利部食品藥物管理署","(B) 財團法人醫藥品查驗中心","(C) 衛生福利部中央健康保險署","(D) 衛生福利部國民健康署"],"answer":0,"image":""},{"id":"ph6-115-1-4","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"115年第1次第4題","year":115,"session":1,"number":4,"question":"依據藥事法，新藥許可證持有人認有藥品專利權，應向中央衛生主管機關提報者，不包括下列何項發明？","options":["(A) 物質","(B) 組合物或配方","(C) 醫藥用途","(D) 新劑型"],"answer":3,"image":""},{"id":"ph6-115-1-5","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"115年第1次第5題","year":115,"session":1,"number":5,"question":"學名藥藥品許可證申請案如涉及藥事法第48條之9第4款之聲明（例如：該新藥對應之專利權應撤銷者），申請人應自中央衛生主管機關就藥品許可證申請資料齊備通知送達之次日起幾日內，以書面通知新藥藥品許可證所有人（含與許可證所有人與所登載不同之專利權人、專屬被授權人）及中央衛生主管機關？","options":["(A) 15","(B) 20","(C) 35","(D) 45"],"answer":1,"image":""},{"id":"ph6-115-1-6","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"115年第1次第6題","year":115,"session":1,"number":6,"question":"政府建構完整的醫療體系以提升民眾良好的醫療服務，下列敘述何者正確？","options":["(A) 依據評鑑等級將醫療體系分為醫學中心、區域醫院、地區醫院及診所","(B) 緊急醫療體系中之急救責任醫院分為重度級、中度級及一般級","(C) 二家以上診所不得於同一場所設置聯合診所","(D) 依據醫療網計畫將臺灣地區分為北、中、南、東4個區域醫療體系"],"answer":1,"image":""},{"id":"ph6-115-1-7","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"115年第1次第7題","year":115,"session":1,"number":7,"question":"為滿足身心失能者的照顧需求，下列有關制定長期照顧服務法之敘述，何者錯誤？","options":["(A) 係為健全長期照顧服務體系，提供長期照顧服務","(B) 發展普及、多元及可負擔之服務","(C) 保障接受服務者與照顧者之尊嚴及權益","(D) 得因年齡及居住地域之差別，提供不同之服務"],"answer":3,"image":""},{"id":"ph6-115-1-8","subject":"ph6","topic":"藥事法規-藥師法與執業管理","meta":"115年第1次第8題","year":115,"session":1,"number":8,"question":"若藥師懲戒委員會對某藥師之懲戒決議為廢止執業執照，應送由下列何者執行？","options":["(A) 衛生福利部","(B) 該直轄市或縣（市）主管機關","(C) 中華民國藥師公會全國聯合會","(D) 該藥師執業所在地之藥師公會"],"answer":1,"image":""},{"id":"ph6-115-1-9","subject":"ph6","topic":"藥事法規-藥師法與執業管理","meta":"115年第1次第9題","year":115,"session":1,"number":9,"question":"依據藥師懲戒及懲戒覆審委員會設置審議辦法，有關藥師懲戒委員會之敘述，下列何者最不適當？","options":["(A) 藥師懲戒委員會委員中，法學專家學者及社會人士比例，不得少於1/3","(B) 若縣市藥師執業人數，合計未滿100人，得與鄰近縣市合併設置藥師懲戒委員會","(C) 藥師懲戒覆審委員會，由衛生福利部設置之","(D) 藥師懲戒委員會議之審議及決議，委員應親自出席，不得委託行使決議"],"answer":1,"image":""},{"id":"ph6-115-1-10","subject":"ph6","topic":"藥事法規-藥師法與執業管理","meta":"115年第1次第10題","year":115,"session":1,"number":10,"question":"依據藥師法，醫療機構聘藥師提供藥事服務者，其藥師至少應有多少人具備多少年以上實際調劑執業經驗，始得提供藥品調劑服務？","options":["(A) 1人、1年","(B) 1人、2年","(C) 2人、各2年","(D) 2人、各1年"],"answer":1,"image":""},{"id":"ph6-115-1-11","subject":"ph6","topic":"調劑學-處方判讀與調劑作業","meta":"115年第1次第11題","year":115,"session":1,"number":11,"question":"社區藥局藥師受理以下處方箋時，下列作法何者錯誤？ ®","options":["(A) Strocaine目前缺貨，因未註明不可替代，故可於告知病人後，以相同價格之同成分、同劑型、同含量其他廠牌藥品取代","(B) Ibuprofen與Acetaminophen有明顯重複作用，應拒絕處方 ®®","(C) Paxlovid與NONCOUGH cap有明顯交互作用，應詢明原處方醫師確認 ®","(D) Strocaine目前缺貨，因未註明不可替代，故可於告知病人後，以低於原處方藥物價格之同成分、同劑型、同含量其他廠牌藥品取代 ®"],"answer":1,"image":"ph6-115-1-11.jpeg"},{"id":"ph6-115-1-12","subject":"ph6","topic":"臨床藥學-藥物不良反應與交互作用","meta":"115年第1次第12題","year":115,"session":1,"number":12,"question":"藥師受理Paxlovid抗病毒藥品處方箋時，發現病人正在服用其他藥品，下列敘述何者錯誤？","options":["(A) 病人正在服用清冠一號，建議兩者不要同時期服用","(B) 病人正在服用lovastatin，不建議併用，並詢明原處方醫師調整","(C) 病人正在服用amiodarone，不建議併用，並詢明原處方醫師調整","(D) 病人正在服用verapamil，不建議併用，並詢明原處方醫師調整"],"answer":3,"image":""},{"id":"ph6-115-1-13","subject":"ph6","topic":"藥事法規-藥師法與執業管理","meta":"115年第1次第13題","year":115,"session":1,"number":13,"question":"下列那一項非屬藥師法施行細則第13條第2款所明定之藥事照護相關職責？","options":["(A) 執行關懷給藥","(B) 執行藥品安全監視","(C) 執行給藥流程評估","(D) 執行用藥諮詢"],"answer":0,"image":""},{"id":"ph6-115-1-14","subject":"ph6","topic":"藥事法規-藥師法與執業管理","meta":"115年第1次第14題","year":115,"session":1,"number":14,"question":"依據藥師法，下列何者非為藥師處方調劑之依據？","options":["(A) 醫師處方","(B) 中華藥典","(C) 國家處方集","(D) 國民處方選輯"],"answer":2,"image":""},{"id":"ph6-115-1-15","subject":"ph6","topic":"藥事法規-藥師法與執業管理","meta":"115年第1次第15題","year":115,"session":1,"number":15,"question":"郝藥師於臺北市開設藥健康藥局，並且擔任負責藥師。但郝藥師想出國深造，預計2年後回國執業，下列敘述何者正確？","options":["(A) 出國前應先向臺北市政府衛生局辦理停業，2年後回國重新辦理復業","(B) 出國前應先向臺北市政府衛生局辦理停業，2年後回國自行復業","(C) 出國前應先向臺北市政府衛生局辦理歇業，2年後回國重新辦理開業","(D) 出國前應先向臺北市政府衛生局辦理歇業，2年後回國自行開業"],"answer":2,"image":""},{"id":"ph6-115-1-16","subject":"ph6","topic":"藥事法規-藥師法與執業管理","meta":"115年第1次第16題","year":115,"session":1,"number":16,"question":"依藥師法之規定，下列何者非屬藥師懲戒之方式？","options":["(A) 警告","(B) 命接受額外之一定時數臨床進修","(C) 限制執業範圍或停業六個月以上二年以下","(D) 命接受額外之一定時數繼續教育"],"answer":2,"image":""},{"id":"ph6-115-1-17","subject":"ph6","topic":"調劑學-處方判讀與調劑作業","meta":"115年第1次第17題","year":115,"session":1,"number":17,"question":"下列有關受理處方調劑作業之敘述，何者正確？","options":["(A) 藥事人員於藥事作業處所，應佩戴有照片之識別證","(B) 補充藥品前，須確認其與受補充之藥瓶顏色相符","(C) 藥事人員交付藥品時，應確認所交付之對象為病人本人","(D) 為防止兒童取得藥品，藥事人員必要時，應使用有安全瓶蓋之容器"],"answer":3,"image":""},{"id":"ph6-115-1-18","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"115年第1次第18題","year":115,"session":1,"number":18,"question":"某藥商將降血脂藥atorvastatin冒充rosuvastatin成品出售，下列敘述何者最適當？","options":["(A) 二成分同屬HMG-CoA還原酶抑制劑，臨床上醫師也常相互替代使用，故尚未構成偽藥條件","(B) 民眾若有發現藥品包裝或外觀有異，得依藥物製造業者檢查辦法施行細則之檢舉案件獎勵","(C) 直轄市衛生主管機關得設置查緝中心查緝","(D) 此案民眾可藉藥品許可證字號「衛署成製字第OOOOOO號」，辨認本藥之真偽"],"answer":2,"image":""},{"id":"ph6-115-1-19","subject":"ph6","topic":"藥事法規-新藥臨床試驗與安全監視","meta":"115年第1次第19題","year":115,"session":1,"number":19,"question":"在臨床試驗中，若受試者發生未預期之嚴重藥品不良反應，且非為試驗計畫書或其他文件明確排除者，試驗主持人應：","options":["(A) 立即通知人體試驗委員會","(B) 七日內通報主管機關","(C) 七日內提供主管機關詳細書面報告","(D) 停止所有受試者的相關試驗"],"answer":0,"image":""},{"id":"ph6-115-1-20","subject":"ph6","topic":"藥事法規-全民健康保險與藥事作業","meta":"115年第1次第20題","year":115,"session":1,"number":20,"question":"依據藥事法及其相關規定，所稱無藥事人員執業之醫療偏遠地區，係指：","options":["(A) 西醫診所1.6公里內無藥局之地區","(B) 西醫診所1.8公里內無藥局之地區","(C) 西醫診所2.0公里內無藥局之地區","(D) 西醫診所2.4公里內無藥局之地區"],"answer":1,"image":""},{"id":"ph6-115-1-21","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"115年第1次第21題","year":115,"session":1,"number":21,"question":"依據藥品回收處理辦法，藥品製造業者回收藥品應訂定藥品回收作業規定，據以執行。下列規定之內容，何者正確？①回收作業之組織 ②回收人員及任務 ③回收之通知方式 ④回收及處理方式 ⑤銷燬機關","options":["(A) 僅①④⑤","(B) 僅②③⑤","(C) 僅①②③④","(D) ①②③④⑤"],"answer":2,"image":""},{"id":"ph6-115-1-22","subject":"ph6","topic":"藥事法規-藥師法與執業管理","meta":"115年第1次第22題","year":115,"session":1,"number":22,"question":"對於醫療機構、藥局執業藥師經事先報准，得於執業處所外執行之業務，下列何者錯誤？","options":["(A) 於義診時開立處方業務","(B) 於護理機構執行藥事照護相關業務","(C) 執行藥癮治療業務","(D) 執行傳染病防治服務"],"answer":0,"image":""},{"id":"ph6-115-1-23","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"115年第1次第23題","year":115,"session":1,"number":23,"question":"依據藥事法，有關藥品製造業者之敘述，下列何者錯誤？","options":["(A) 係指經營藥品之製造、加工與其產品批發、輸出及自用原料輸入之業者","(B) 輸入自用原料，應於首次進口時向中央衛生主管機關申請核准","(C) 已進口之自用原料，未經中央衛生主管機關核准不得轉售或轉讓","(D) 得兼營自製產品之零售業務"],"answer":1,"image":""},{"id":"ph6-115-1-24","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"115年第1次第24題","year":115,"session":1,"number":24,"question":"依據藥事法，有關西藥、中藥製造業者之敘述，下列何者正確？","options":["(A) 中藥製造業者摻入西藥製造中藥時，得由兼任中醫師駐廠監製","(B) 中藥製造業者以西藥劑型製造中藥，得由專任修習中藥課程達適當標準之藥劑生駐廠監製","(C) 西藥製造業者，得由兼任藥師駐廠監製","(D) 西藥製造業者聘用之監製人員，因辭聘而未另行聘置時，應即停止營業，並申請停業或歇業之登記"],"answer":3,"image":""},{"id":"ph6-115-1-25","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"115年第1次第25題","year":115,"session":1,"number":25,"question":"衛生福利部及衛生局配合地檢署查獲某藥廠將廠內已過期之藥品塗改貼標之有效期間，依藥事法對於此情事之規範，下列何者錯誤？","options":["(A) 因過失而販賣、供應或意圖販賣而陳列此藥品者，也有刑事責任","(B) 衛生福利部應廢止此藥廠之全部許可證","(C) 此藥品認屬劣藥","(D) 此藥品應依規定期限收回市售品"],"answer":2,"image":""},{"id":"ph6-115-1-26","subject":"ph6","topic":"藥事法規-醫療器材管理法","meta":"115年第1次第26題","year":115,"session":1,"number":26,"question":"依據藥事法與醫療器材管理法及相關規定，下列何者得於網路販售？①隱形眼鏡 ②綠油精 ③體脂計 ④ 撒隆巴斯","options":["(A) 僅③④","(B) 僅①②","(C) 僅②③","(D) ①②③④"],"answer":2,"image":""},{"id":"ph6-115-1-27","subject":"ph6","topic":"藥事法規-新藥臨床試驗與安全監視","meta":"115年第1次第27題","year":115,"session":1,"number":27,"question":"如發現未預期之嚴重藥品不良反應，持有該藥品許可證之藥商應自知悉之日起多久，至中央衛生主管機關建置之網路系統通報？","options":["(A) 24小時","(B) 3日","(C) 7日","(D) 15日"],"answer":1,"image":""},{"id":"ph6-115-1-28","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"115年第1次第28題","year":115,"session":1,"number":28,"question":"藥事法對於偽藥及禁藥之罰則，下列敘述何者錯誤？","options":["(A) 製造或輸入偽藥或禁藥者，處十年以下有期徒刑，得併科新臺幣一億元以下罰金","(B) 明知為偽藥或禁藥，而販賣、供應、調劑、運送、寄藏、牙保、轉讓或意圖販賣而陳列者，處七年以下有期徒刑，得併科新臺幣五千萬元以下罰金","(C) 依法查獲供製造、調劑偽藥、禁藥之器材，不問屬於犯罪行為人與否，沒收之","(D) 未遂犯不罰"],"answer":3,"image":""},{"id":"ph6-115-1-29","subject":"ph6","topic":"藥事法規-新藥臨床試驗與安全監視","meta":"115年第1次第29題","year":115,"session":1,"number":29,"question":"有關新藥及學名藥查驗登記之敘述，下列何者錯誤？","options":["(A) 查驗登記所應檢附之資料不同","(B) 新成分新藥應檢附安全性及有效性之技術性資料","(C) 所有學名藥皆應執行臨床試驗來驗證安全性及有效性","(D) 新成分新藥應檢附藥理毒理試驗、藥動試驗、臨床試驗等技術性資料"],"answer":2,"image":""},{"id":"ph6-115-1-30","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"115年第1次第30題","year":115,"session":1,"number":30,"question":"依藥事法之規定，下列敘述何者錯誤？","options":["(A) 輸入之製劑應申請中央衛生主管機關核准後，由符合藥品優良製造規範之藥品製造業者分裝","(B) 輸入之原料藥，應由符合藥品優良製造規範之藥品製造業者分裝後，報請中央衛生主管機關備查","(C) 藥品販賣業輸入之藥品，應事先取得藥品許可證","(D) 經分裝之原料藥，其銷售對象不以藥品製造業者為限"],"answer":3,"image":""},{"id":"ph6-115-1-31","subject":"ph6","topic":"藥事法規-醫療器材管理法","meta":"115年第1次第31題","year":115,"session":1,"number":31,"question":"依據醫療器材分類分級管理辦法，下列何者非屬醫療器材之分類依據？","options":["(A) 功能、用途","(B) 使用方法","(C) 適應症","(D) 工作原理"],"answer":2,"image":""},{"id":"ph6-115-1-32","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"115年第1次第32題","year":115,"session":1,"number":32,"question":"某製藥廠生產降血壓藥的原料藥valsartan，發現含動物致癌成分N-亞硝基二甲胺（NDMA），下列敘述何者正確？","options":["(A) 該製藥廠所有供製造的原料藥，都禁止使用於製劑","(B) N-亞硝基二甲胺經光照後，才對實驗鼠致癌，歐美規定須避光貯存","(C) 國內使用該批次valsartan原料藥者，經衛生福利部評估確定有安全疑慮，得限期令該製藥廠改善，屆期未改善者，廢止其許可證","(D) N-亞硝基二甲胺對人體尚無確切致癌證據，應加強valsartan原料藥之電子登錄審核"],"answer":2,"image":""},{"id":"ph6-115-1-33","subject":"ph6","topic":"藥事法規-藥物廣告與稽查","meta":"115年第1次第33題","year":115,"session":1,"number":33,"question":"依藥事法之規定，下列有關藥品廣告之敘述，何者錯誤？","options":["(A) 藥品廣告在核准登載、宣播期間，發現其內容或刊播方式危害民眾健康或有重大危害之虞時，原核准機關應令藥商立即停止刊播並限期改善，屆期未改善者，廢止其廣告核准文件","(B) 藥品廣告應將廠商名稱、藥品許可證及廣告核准文件字號，一併登載或宣播","(C) 核准之藥品廣告，自核發證明文件之日起算，其有效期間為三年","(D) 登載或宣播藥品廣告，應由領有藥品許可證之藥商，填具申請書，連同藥品許可證影本、核定之標籤、仿單或包裝影本、廣告內容及審查費，申請中央或直轄市衛生主管機關核准後為之"],"answer":2,"image":""},{"id":"ph6-115-1-34","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"115年第1次第34題","year":115,"session":1,"number":34,"question":"有關藥品查驗登記之敘述，下列何者錯誤？","options":["(A) 某藥品曾因藥品療效安全性有關原因被廢止該許可證，日後首家申請相同成分、劑型、劑量之藥品許可證，得依學名藥規定辦理查驗登記","(B) 同一品名有二種以上劑型者，應分別辦理查驗登記","(C) 不同內容量之乾粉注射劑，除注射液濃度不同者外，得以一案申請","(D) 製藥工廠之劑型，應取得中央衛生主管機關核發之藥物製造許可或核定文件"],"answer":0,"image":""},{"id":"ph6-115-1-35","subject":"ph6","topic":"藥事法規-藥物廣告與稽查","meta":"115年第1次第35題","year":115,"session":1,"number":35,"question":"下列何者得申請電視廣告？","options":["(A) 流感疫苗 ®","(B) 威而鋼錠劑（Viagra tablet）","(C) 日拋型拋棄式隱形眼鏡","(D) 抗生素製劑"],"answer":2,"image":""},{"id":"ph6-115-1-36","subject":"ph6","topic":"藥事法規-藥物廣告與稽查","meta":"115年第1次第36題","year":115,"session":1,"number":36,"question":"甲藥商設立於臺北市，將所持藥品許可證委託設立於臺中市之乙藥廠製造，並委託乙藥廠代其申請藥品廣告，下列申請程序何者正確？","options":["(A) 乙藥廠不得受甲藥商委託申請廣告","(B) 乙藥廠應於臺中市代甲藥商申請藥品廣告","(C) 甲藥商得同時於臺中市申請藥品廣告","(D) 乙藥廠應於臺北市代甲藥商申請藥品廣告"],"answer":3,"image":""},{"id":"ph6-115-1-37","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"115年第1次第37題","year":115,"session":1,"number":37,"question":"依據藥品回收處理辦法，下列有關製造或輸入業者回收藥品完畢之期限，何者錯誤？","options":["(A) 經依法認定為劣藥，回收期限最長不得超過三個月","(B) 製造藥物許可證未申請展延，應自許可證到期之日起六個月內","(C) 包裝經核准變更登記，應自包裝經核准變更之日起六個月內","(D) 原領有藥物許可證，經公告禁止製造或輸入，自公告之次日起一個月內"],"answer":0,"image":""},{"id":"ph6-115-1-38","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"115年第1次第38題","year":115,"session":1,"number":38,"question":"某中藥廠生產之治療關節炎中藥貼布驗出cortisol成分，下列敘述何者錯誤？","options":["(A) cortisol若未經核准擅自製造，屬藥事法之偽藥","(B) cortisol為人與植物共有成分，即使該貼布含量不超出體內平均濃度，未經核准依法仍應處罰","(C) 含cortisol貼布屬醫療器材，非屬衛生福利部業務範圍","(D) 該廠製造中藥貼布摻入cortisol，除須經核准外，應由專任藥師監製"],"answer":2,"image":""},{"id":"ph6-115-1-39","subject":"ph6","topic":"藥事法規-管制藥品與毒品危害防制","meta":"115年第1次第39題","year":115,"session":1,"number":39,"question":"依據管制藥品管理條例，下列何者不得擔任管制藥品管理人？","options":["(A) 醫師","(B) 牙醫師","(C) 藥師","(D) 護理師"],"answer":3,"image":""},{"id":"ph6-115-1-40","subject":"ph6","topic":"藥事法規-管制藥品與毒品危害防制","meta":"115年第1次第40題","year":115,"session":1,"number":40,"question":"依據管制藥品濫用通報及獎勵辦法，管制藥品濫用通報之程序，可由各醫療（事）機構或戒癮輔導機構、團體之何種人員進行通報？①戒癮輔導團體負責人 ②醫療機構管制藥品管理人 ③醫療機構之醫事人員","options":["(A) 僅①②","(B) 僅①③","(C) 僅②③","(D) ①②③"],"answer":3,"image":""},{"id":"ph6-115-1-41","subject":"ph6","topic":"藥事法規-管制藥品與毒品危害防制","meta":"115年第1次第41題","year":115,"session":1,"number":41,"question":"下列有關管制藥品簿冊登載及申報之敘述，何者正確？","options":["(A) 應於業務處所設置簿冊，詳實登載每月之收支及結存情形","(B) 每年一月辦理前一年管制藥品之申報，該期間無任何收支或結存者，則不需申報","(C) 管制藥品相關之簿冊、單據及專用處方箋，均應保存五年","(D) 登載簿冊時，若支出原因為調劑、使用第四級管制藥品者，應逐日詳實登載病人及其領用數量"],"answer":2,"image":""},{"id":"ph6-115-1-42","subject":"ph6","topic":"藥事法規-化粧品衛生安全管理法","meta":"115年第1次第42題","year":115,"session":1,"number":42,"question":"依化粧品衛生安全管理法之規定，有關化粧品廣告之敘述，下列何者正確？","options":["(A) 應事前申請中央或直轄市衛生主管機關核准","(B) 業者於刊播前應向傳播機構繳驗核准之證明文件","(C) 登載宣播內容虛偽誇大，情節重大者，得令其歇業及廢止其公司、商業、工廠之全部或部分登記事項","(D) 有虛偽或誇大之情事者，應處一年以下有期徒刑"],"answer":2,"image":""},{"id":"ph6-115-1-43","subject":"ph6","topic":"藥事法規-藥害救濟與罕見疾病","meta":"115年第1次第43題","year":115,"session":1,"number":43,"question":"依據藥害救濟法，藥害救濟之申請人對救濟給付之審定如有不服，可以如何續處？","options":["(A) 至主管機關抗議","(B) 提起訴願及行政訴訟","(C) 依法要求重新審議","(D) 訴訟提告"],"answer":1,"image":""},{"id":"ph6-115-1-44","subject":"ph6","topic":"藥事法規-藥害救濟與罕見疾病","meta":"115年第1次第44題","year":115,"session":1,"number":44,"question":"依據罕見疾病防治及藥物法及其施行細則，須經罕見疾病及藥物審議會審議認定者，不包括下列何者？","options":["(A) 疾病盛行率","(B) 罕見疾病","(C) 罕見疾病藥物","(D) 維持生命所需之特殊營養食品"],"answer":0,"image":""},{"id":"ph6-115-1-45","subject":"ph6","topic":"藥事法規-藥害救濟與罕見疾病","meta":"115年第1次第45題","year":115,"session":1,"number":45,"question":"下列何者符合申請藥害救濟之要件？","options":["(A) 王先生父親用藥致死，經法院判決醫師有明顯醫療疏失","(B) 吳先生哥哥因敗血症，在急診室急救時，注射超量抗生素致死","(C) 黃女士小孩因注射疫苗，造成肢體障礙","(D) 曾小姐去年退休前，因肺結核使用isoniazid致永久肝功能受損"],"answer":3,"image":""},{"id":"ph6-115-1-46","subject":"ph6","topic":"藥事法規-全民健康保險與藥事作業","meta":"115年第1次第46題","year":115,"session":1,"number":46,"question":"依據全民健康保險法，下列何者不予保險給付？","options":["(A) 流行性感冒","(B) 車禍骨折","(C) 生育事故","(D) 新型冠狀病毒之疫苗接種"],"answer":3,"image":""},{"id":"ph6-115-1-47","subject":"ph6","topic":"藥事法規-全民健康保險與藥事作業","meta":"115年第1次第47題","year":115,"session":1,"number":47,"question":"依據全民健康保險醫療辦法，醫院醫師於1月5日開立慢性病連續處方箋，每次開藥30日，總用藥量90日，病人就診當日於醫院第一次領藥，下列敘述何者正確？","options":["(A) 第二次領藥日最早為1月20日","(B) 1月30日可領第二次藥","(C) 第三次領藥最後期限為2月25日","(D) 2月4日可領第三次藥"],"answer":1,"image":""},{"id":"ph6-115-1-48","subject":"ph6","topic":"藥事法規-全民健康保險與藥事作業","meta":"115年第1次第48題","year":115,"session":1,"number":48,"question":"下列何者非屬全民健康保險法所訂章名？","options":["(A) 保險人、保險對象及投保單位","(B) 醫事人力及設施分布","(C) 醫療費用支付","(D) 保險醫事服務機構"],"answer":1,"image":""},{"id":"ph6-115-1-49","subject":"ph6","topic":"藥事法規-全民健康保險與藥事作業","meta":"115年第1次第49題","year":115,"session":1,"number":49,"question":"依全民健康保險醫療辦法之規定，病人自保險特約藥局領取處方藥後，藥品遺失或毀損之處理，下列何者正確？","options":["(A) 再就醫，醫療費用由病人自行負擔","(B) 由保險特約藥局再依原處方調劑給藥申報","(C) 由病人自費向所在地保險特約藥局購買","(D) 由保險特約藥局以相同或低於原處方藥品價格之同成分、同劑型、同含量其他廠牌藥品替代，藥品費用由病人自行負擔"],"answer":0,"image":""},{"id":"ph6-115-1-50","subject":"ph6","topic":"藥事法規-全民健康保險與藥事作業","meta":"115年第1次第50題","year":115,"session":1,"number":50,"question":"下列有關全民健康保險藥物給付項目及支付標準共同擬訂會議之敘述，何者正確？","options":["(A) 應至少每季召開一次會議，必要時召開臨時會","(B) 召開會議，應邀請中華民國藥師公會全國聯合會代表至少二人出席","(C) 討論特定藥物是否納入給付時，得邀請該藥物提供者列席會議表示意見","(D) 會議議程及醫療科技評估報告，應於開會前一日前對外公開"],"answer":2,"image":""},{"id":"ph6-115-2-1","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"115年第2次第1題","year":115,"session":2,"number":1,"question":"依特定醫療技術檢查檢驗醫療儀器施行或使用管理辦法，某醫師要施行非人體試驗之自體免疫細胞治療技術，以治療病人，則其所屬醫療機構必須分別向何者申請核准與登記後，始得施行？","options":["(A) 衛生福利部食品藥物管理署；直轄市、縣（市）主管機關","(B) 衛生福利部；直轄市、縣（市）主管機關","(C) 財團法人醫藥品查驗中心；直轄市、縣（市）主管機關","(D) 衛生福利部食品藥物管理署；財團法人醫藥品查驗中心"],"answer":1,"image":""},{"id":"ph6-115-2-2","subject":"ph6","topic":"藥事法規-全民健康保險與藥事作業","meta":"115年第2次第2題","year":115,"session":2,"number":2,"question":"依衛生福利部國民健康署「戒菸服務補助計畫」，有關社區藥局提供戒菸服務之敘述，下列何者錯誤？","options":["(A) 藥師可以同時提供戒菸治療及戒菸衛教服務","(B) 社區藥局必須為全民健康保險特約醫事機構且過去5年內未曾受健保停約一年以上","(C) 藥師須具有戒菸服務人員資格","(D) 藥師可直接提供衛生福利部國民健康署補助的所有戒菸藥品"],"answer":3,"image":""},{"id":"ph6-115-2-3","subject":"ph6","topic":"藥事法規-全民健康保險與藥事作業","meta":"115年第2次第3題","year":115,"session":2,"number":3,"question":"依全民健康保險法，保險對象不經轉診，則於地區醫院、區域醫院、醫學中心門診就醫者，應分別負擔的百分比為何？","options":["(A) 25％、35％、45％","(B) 30％、40％、50％","(C) 40％、50％、60％","(D) 45％、55％、65％"],"answer":1,"image":""},{"id":"ph6-115-2-4","subject":"ph6","topic":"藥事法規-藥害救濟與罕見疾病","meta":"115年第2次第4題","year":115,"session":2,"number":4,"question":"住在臺南市的A先生，因施打新冠肺炎疫苗產生不良反應，可向下列何者申請預防接種救濟？","options":["(A) 衛生福利部食品藥物管理署","(B) 藥害救濟基金會","(C) 衛生福利部中央健康保險署","(D) 臺南市政府衛生局"],"answer":3,"image":""},{"id":"ph6-115-2-5","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"115年第2次第5題","year":115,"session":2,"number":5,"question":"藥事法所定之罰鍰，除另有規定外，由下列何機關處罰之？","options":["(A) 直轄市、縣（市）政府","(B) 地方法院","(C) 衛生福利部","(D) 法務部行政執行署"],"answer":0,"image":""},{"id":"ph6-115-2-6","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"115年第2次第6題","year":115,"session":2,"number":6,"question":"依長期照顧服務法，下列敘述何者錯誤？","options":["(A) 長期照顧為身心失能持續已達或預期達六個月以上者，依其個人之需要，所提供之生活支持、協助、社會參與、照顧及相關之醫護服務","(B) 中央主管機關為衛生福利部，直轄市及縣市主管機關分別為直轄市政府及縣市政府","(C) 民眾可透過經中央主管機關指定之長期照顧管理中心，尋求長照需要之評估及連結服務","(D) 長期照顧服務之財源主要來自全民健康保險費，由衛生福利部中央健康保險署統籌管理長照服務發展基金"],"answer":3,"image":""},{"id":"ph6-115-2-7","subject":"ph6","topic":"藥事法規-管制藥品與毒品危害防制","meta":"115年第2次第7題","year":115,"session":2,"number":7,"question":"有關管制藥品管理之敘述，下列何者正確？","options":["(A) 「管制藥品管理條例」係依據「毒品危害防制條例」訂定","(B) 我國將安非他命納入第一級管制藥品","(C) 藥師執行美沙冬替代治療業務，應每年接受至少八小時成癮治療繼續教育訓練","(D) 我國將古柯鹼納入第二級管制藥品"],"answer":2,"image":""},{"id":"ph6-115-2-8","subject":"ph6","topic":"藥事法規-藥師法與執業管理","meta":"115年第2次第8題","year":115,"session":2,"number":8,"question":"依藥師法，有關藥師懲戒程序之敘述，下列何者錯誤？","options":["(A) 被懲戒人對於藥師懲戒委員會之決議有不服者，得於決議書送達翌日起二十日內請求覆審","(B) 被懲戒人未依限提出答辯或到會陳述者，藥師懲戒委員會得逕行決議","(C) 藥師懲戒委員會由中央或直轄市、縣（市）主管機關設置","(D) 藥師懲戒覆審委員會由各直轄市、縣（市）主管機關分別設置"],"answer":3,"image":""},{"id":"ph6-115-2-9","subject":"ph6","topic":"藥事法規-藥師法與執業管理","meta":"115年第2次第9題","year":115,"session":2,"number":9,"question":"依藥師法施行細則，有關藥事照護服務之敘述，下列何者錯誤？","options":["(A) 藥師於社區藥局執行血壓量測後，調整藥品劑量","(B) 藥師於護理之家執行藥物治療流程評估","(C) 藥師於老人之家執行藥品安全監視","(D) 藥師於社區藥局執行給藥流程評估"],"answer":0,"image":""},{"id":"ph6-115-2-10","subject":"ph6","topic":"藥事法規-藥師法與執業管理","meta":"115年第2次第10題","year":115,"session":2,"number":10,"question":"依藥師法施行細則，考量藥物使用情形及評估療效之藥事服務事項，其目的為何？①為增進藥物療程之效益 ②為減低健保的支出 ③為增進生活品質","options":["(A) 僅①②","(B) 僅②③","(C) ①②③","(D) 僅①③"],"answer":3,"image":""},{"id":"ph6-115-2-11","subject":"ph6","topic":"藥事法規-藥師法與執業管理","meta":"115年第2次第11題","year":115,"session":2,"number":11,"question":"某藥師居住於新北市，預計於臺北市某診所擔任藥師。依藥師法，應加入下列何公會？","options":["(A) 新北市藥師公會或臺北市藥師公會","(B) 新北市藥師公會","(C) 臺北市藥師公會","(D) 藥師公會全國聯合會"],"answer":2,"image":""},{"id":"ph6-115-2-12","subject":"ph6","topic":"藥事法規-藥師法與執業管理","meta":"115年第2次第12題","year":115,"session":2,"number":12,"question":"依藥師法，藥師應親自主持其所經營之藥局業務，下列何情況不可提供藥品調劑服務？","options":["(A) 依國民處方選輯之處方調劑","(B) 依中華藥典之處方調劑","(C) 受理醫師處方調劑","(D) 依國民藥典之處方調劑"],"answer":3,"image":""},{"id":"ph6-115-2-13","subject":"ph6","topic":"藥事法規-藥師法與執業管理","meta":"115年第2次第13題","year":115,"session":2,"number":13,"question":"依藥師法，有關藥師被移付懲戒之敘述，下列何者正確？","options":["(A) 撤銷藥師證書由直轄市及縣（市）主管機關為之","(B) 廢止執業執照由中央主管機關為之","(C) 藥師懲戒覆審委員會之懲戒決議，應送由藥師公會執行之","(D) 藥師懲戒委員會之委員，其中法學專家學者及社會人士之比例不得少於三分之一"],"answer":3,"image":""},{"id":"ph6-115-2-14","subject":"ph6","topic":"調劑學-處方判讀與調劑作業","meta":"115年第2次第14題","year":115,"session":2,"number":14,"question":"依藥品優良調劑作業準則，調劑處所藥品品質管控之注意事項，下列何者錯誤？","options":["(A) 藥品應依貯存條件存放，避免光線直射，並有防鼠、防蟲措施","(B) 藥品庫存處所如與調劑處所合併設置時，其庫存品應明顯標示","(C) 中藥飲片自拆封至調劑之期間，應注意專業包裝藥品之包裝材料及貯存環境，並標示藥品名稱及保存期限","(D) 補充調劑檯上藥品前後，都要確認其與受補充之藥品容器標示相符"],"answer":1,"image":""},{"id":"ph6-115-2-15","subject":"ph6","topic":"藥事法規-藥師法與執業管理","meta":"115年第2次第15題","year":115,"session":2,"number":15,"question":"依藥師法，宜蘭市好棒棒診所的藥師因出國須請假5天，其請假期間該診所之調劑業務應如何處理？","options":["(A) 醫師親自調劑","(B) 請經核准報備之醫療機構藥師協助","(C) 請藥廠藥師或具藥師資格之藥師予以支援協助","(D) 請診所之護理人員在醫師監督下執行"],"answer":1,"image":""},{"id":"ph6-115-2-16","subject":"ph6","topic":"藥事法規-藥師法與執業管理","meta":"115年第2次第16題","year":115,"session":2,"number":16,"question":"依藥師法，藥師有下列情事者，得由藥師公會移付懲戒，何者除外？","options":["(A) 藥師交付藥劑時，未於包裝上載明警語或副作用","(B) 因業務知悉他人隱私而揭露者","(C) 代言保健食品，誇大不實，致誤導消費者誤信購買","(D) 無處方販賣fentanyl針劑經依販賣毒品罪判刑確定者"],"answer":0,"image":""},{"id":"ph6-115-2-17","subject":"ph6","topic":"藥事法規-藥師法與執業管理","meta":"115年第2次第17題","year":115,"session":2,"number":17,"question":"下列何者非屬藥師法載明之藥師業務？","options":["(A) 藥品鑑定","(B) 藥品販賣或管理","(C) 藥品製造之監製","(D) 醫療器材之監製"],"answer":3,"image":""},{"id":"ph6-115-2-18","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"115年第2次第18題","year":115,"session":2,"number":18,"question":"依藥事法，製造或輸入劣藥，下列何者應負刑事責任？","options":["(A) 擅自添加非法定著色劑、防腐劑、香料、矯味劑及賦形劑者","(B) 藥品中一部或全部含有污穢或異物者","(C) 超過有效期間或保存期限者","(D) 所含有效成分之質、量或強度，與核准不符者"],"answer":0,"image":""},{"id":"ph6-115-2-19","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"115年第2次第19題","year":115,"session":2,"number":19,"question":"依藥事法，某學名藥藥品許可證申請人，如已向中央衛生主管機關聲明，其申請藥品許可證之學名藥未侵害該新藥對應之專利權。依其申請資料齊備日最早者，可取得十二個月之何種專屬期間？","options":["(A) 資料專屬","(B) 專利專屬","(C) 銷售專屬","(D) 智慧權專屬"],"answer":2,"image":""},{"id":"ph6-115-2-20","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"115年第2次第20題","year":115,"session":2,"number":20,"question":"依藥事法，新藥藥品許可證申請人與藥品專利權人間，所簽訂之和解協議，涉及藥品之製造專屬期間規定者，雙方當事人除應通報中央衛生主管機關外，如涉及逆向給付利益協議者，應另行通報何單位？","options":["(A) 經濟部智慧財產局","(B) 公平交易委員會","(C) 消費爭議調解委員會","(D) 衛生福利部中央健康保險署"],"answer":1,"image":""},{"id":"ph6-115-2-21","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"115年第2次第21題","year":115,"session":2,"number":21,"question":"安安出國旅遊返國後，將其於國外購買之藥品轉賣給別人，上述行為違反了何項法規？","options":["(A) 醫師法","(B) 藥事法","(C) 藥物樣品贈品管理辦法","(D) 特定藥品專案核准製造及輸入辦法"],"answer":1,"image":""},{"id":"ph6-115-2-22","subject":"ph6","topic":"藥事法規-新藥臨床試驗與安全監視","meta":"115年第2次第22題","year":115,"session":2,"number":22,"question":"依藥品查驗登記審查準則，未在我國進行臨床試驗之新成分新藥，若已在十大醫藥先進國家二國以上上市者，在臺灣申請查驗登記時，下列何者不是一定要檢附的資料？","options":["(A) 銜接性試驗","(B) 上市後風險管理計畫","(C) 採用證明","(D) 分析方法確效資料"],"answer":1,"image":""},{"id":"ph6-115-2-23","subject":"ph6","topic":"藥事法規-新藥臨床試驗與安全監視","meta":"115年第2次第23題","year":115,"session":2,"number":23,"question":"依藥品優良臨床試驗作業準則，有關藥品臨床試驗執行之敘述，下列何者錯誤？","options":["(A) 試驗主持人不得強迫或不當影響受試者參與臨床試驗之意願","(B) 受試者須持有正當理由時，可隨時退出臨床試驗","(C) 受試者退出臨床試驗時，試驗主持人應在尊重其權利及意願之條件下，盡量確認其退出試驗之原因","(D) 受試者之補助，應按臨床試驗進行之進度依比例給付之，不得於試驗完成後方為給付"],"answer":1,"image":""},{"id":"ph6-115-2-24","subject":"ph6","topic":"藥事法規-新藥臨床試驗與安全監視","meta":"115年第2次第24題","year":115,"session":2,"number":24,"question":"依藥品優良臨床試驗作業準則，試驗委託者或其他數據所有者，應保存所有試驗委託者應負責與試驗相關之必要文件，其保存期限，下列何者正確？","options":["(A) 至試驗藥品於我國核准上市後至少二年","(B) 至試驗藥品於我國核准上市後至少五年","(C) 至臨床試驗結束後至少二年","(D) 至臨床試驗結束後至少五年"],"answer":0,"image":""},{"id":"ph6-115-2-25","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"115年第2次第25題","year":115,"session":2,"number":25,"question":"某甲至國外旅遊，回國通關行李檢查時，發現有數量計30瓶共3,000粒含處方藥成分之藥品，經通報主管機關進行處置。甲到場說明，表示該藥品屬自用藥品，但未提供醫師處方箋。依藥事法，下列敘述何者錯誤？","options":["(A) 涉屬藥事法禁藥之定義","(B) 可處以有期徒刑","(C) 查獲藥品沒入銷燬","(D) 因屬自用，不違法"],"answer":3,"image":""},{"id":"ph6-115-2-26","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"115年第2次第26題","year":115,"session":2,"number":26,"question":"依藥事法，維士比液、保力達B液可以在下列那些地點販賣？①藥師主持之藥局 ②藥劑生主持之藥局 ③ 百貨店 ④雜貨店 ⑤餐旅服務商","options":["(A) 僅①②","(B) ②⑤","(C) ①②④","(D) ①②③"],"answer":0,"image":""},{"id":"ph6-115-2-27","subject":"ph6","topic":"藥事法規-醫療器材管理法","meta":"115年第2次第27題","year":115,"session":2,"number":27,"question":"依醫療器材管理法，應聘僱技術人員之醫療器材商類別，不包含下列何者？","options":["(A) 從事醫療器材設計，並以其名義於市場流通之製造業者","(B) 從事醫療器材製造、滅菌或最終驗放之製造業者","(C) 從事醫療器材批發、零售或輸出之販賣業者","(D) 從事醫療器材輸入或維修之販賣業者"],"answer":2,"image":""},{"id":"ph6-115-2-28","subject":"ph6","topic":"藥事法規-醫療器材管理法","meta":"115年第2次第28題","year":115,"session":2,"number":28,"question":"依醫療器材管理法，有關醫療器材商管理之相關規定，下列何者錯誤？","options":["(A) 直轄市、縣（市）主管機關應至少每年辦理醫療器材商普查","(B) 非醫療器材商不得為醫療器材廣告","(C) 醫療器材商發現醫療器材嚴重不良事件，應通知中央主管機關","(D) 申請為醫療器材商者，應經直轄市、縣（市）主管機關核准登記，領得許可執照後，始得營業"],"answer":0,"image":""},{"id":"ph6-115-2-29","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"115年第2次第29題","year":115,"session":2,"number":29,"question":"依藥事法，如有無法繼續製造、輸入或不足供應該藥品之虞時，藥商持有以下許可證應限期向中央衛生主管機關通報，下列何者正確？","options":["(A) 經中央衛生主管機關核准之所有藥品許可證；6個月","(B) 經中央衛生主管機關公告為必要藥品許可證；6個月","(C) 經中央衛生主管機關核准之所有藥品許可證；3個月","(D) 經中央衛生主管機關公告為必要藥品許可證；3個月"],"answer":1,"image":""},{"id":"ph6-115-2-30","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"115年第2次第30題","year":115,"session":2,"number":30,"question":"依藥事法，有關藥商僱用之推銷員的敘述，下列何者錯誤？","options":["(A) 推銷員應向衛生主管機關登記後，方准執行推銷工作","(B) 推銷員推銷以向藥局、藥商、衛生醫療機構、醫學研究機構及經衛生主管機關准予登記為兼售藥物者為限","(C) 推銷員以推銷其受僱藥商所製售或經銷之藥物為限","(D) 推銷員不得有沿途推銷、設攤出售或擅將藥物拆封、改裝或非法廣告之行為"],"answer":0,"image":""},{"id":"ph6-115-2-31","subject":"ph6","topic":"藥事法規-新藥臨床試驗與安全監視","meta":"115年第2次第31題","year":115,"session":2,"number":31,"question":"小明因使用carbamazepine造成史蒂文生氏強森症候群（Stevens-Johnson Syndrome）導致住院，依藥品嚴重不良反應通報辦法，此藥品嚴重不良反應之通報期限，下列何者正確？","options":["(A) 如小明於醫學中心住院，該醫院應自知悉此不良反應之次日起七日內辦理通報","(B) 如小明於區域醫院住院，該醫院應自知悉此不良反應之次日起十五日內辦理通報","(C) 如小明於地區醫院住院，該醫院應自知悉此不良反應之次日起三十日內辦理通報","(D) 藥商應自知悉此不良反應之次日起三十日內辦理通報"],"answer":2,"image":""},{"id":"ph6-115-2-32","subject":"ph6","topic":"藥事法規-醫療器材管理法","meta":"115年第2次第32題","year":115,"session":2,"number":32,"question":"依通訊交易通路販售醫療器材之品項及應遵行事項，下列敘述何者正確？","options":["(A) 廣播提供之資訊涉及醫療器材廣告者，毋須向相關主管機關申請刊播","(B) 依藥事法規定核准登記之藥局，透過型錄販賣保險套","(C) 取得販賣業許可執照之醫療器材商，透過傳單販賣呼吸器","(D) 民眾在網路上販賣未經開封之衛生棉條"],"answer":1,"image":""},{"id":"ph6-115-2-33","subject":"ph6","topic":"藥事法規-醫療器材管理法","meta":"115年第2次第33題","year":115,"session":2,"number":33,"question":"依醫療器材管理法施行細則，下列何者未涉及宣傳醫療效能之刊登事項，仍視為醫療器材廣告？","options":["(A) 衛教宣導與醫療器材平面廣告，刊登於具連續性質之版面","(B) 完整刊登依本法核准之標籤及說明書","(C) 針對特殊事件之聲明啟事","(D) 辨別醫療器材真偽之差異圖片或說明"],"answer":0,"image":""},{"id":"ph6-115-2-34","subject":"ph6","topic":"藥事法規-醫療器材管理法","meta":"115年第2次第34題","year":115,"session":2,"number":34,"question":"依醫療器材管理法施行細則，核准刊播之醫療器材廣告，其內容應包括下列那些事項？①許可證或登錄之產品名稱 ②醫療器材廣告核准刊播文件字號 ③醫療器材許可證或登錄字號 ④許可證所有人或登錄者之名稱","options":["(A) 僅①②④","(B) 僅①③","(C) 僅②④","(D) ①②③④"],"answer":3,"image":""},{"id":"ph6-115-2-35","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"115年第2次第35題","year":115,"session":2,"number":35,"question":"依藥物優良製造準則，有關中藥廠之相關規定，下列何者錯誤？","options":["(A) 中藥廠廠房之製造、加工、分裝之作業場所，應與事務所完全隔離","(B) 中藥廠廠房之製造、加工、分裝之作業場所，應與研究室完全隔離","(C) 中藥廠兼製含藥物飼料添加物者，其飼料添加物之作業場所，應獨立設置","(D) 中藥廠兼製含環境衛生用藥者，其環境衛生用藥之製造場所，應與藥品製造作業場所距離六公尺以上"],"answer":3,"image":""},{"id":"ph6-115-2-36","subject":"ph6","topic":"藥事法規-新藥臨床試驗與安全監視","meta":"115年第2次第36題","year":115,"session":2,"number":36,"question":"依藥品安全監視管理辦法，下列敘述何者錯誤？","options":["(A) 經中央衛生主管機關審查認定屬新成分之中藥藥品，適用本辦法規定","(B) 藥商得知藥品於美國因不良反應被暫停使用，應自知悉之日起三日內，至中央衛生主管機關建置之網路系統通報","(C) 本辦法所定藥品安全性監視相關資料，藥商應於藥品許可證核發之日起保存五年","(D) 中央衛生主管機關接獲新藥藥品安全性總結報告，認有必要者得指定期間要求藥商續行資料蒐集及報告繳交"],"answer":2,"image":""},{"id":"ph6-115-2-37","subject":"ph6","topic":"藥事法規-藥事法及子法","meta":"115年第2次第37題","year":115,"session":2,"number":37,"question":"依藥事法施行細則，有關藥商辦理登記事項之敘述，下列何者錯誤？","options":["(A) 藥商應辦理變更登記之事項，包括藥商登記事項之變更及自行停業、復業或歇業","(B) 藥商遷址變更登記，應先向原核准登記之衛生主管機關申請","(C) 藥商辦理變更登記，應自事實發生之日起15日內，向原核准登記之衛生主管機關申請","(D) 藥商辦理公司組織或商業登記事項之變更，應先向原核准登記之衛生主管機關申請"],"answer":3,"image":""},{"id":"ph6-115-2-38","subject":"ph6","topic":"藥事法規-管制藥品與毒品危害防制","meta":"115年第2次第38題","year":115,"session":2,"number":38,"question":"依管制藥品管理條例，申請管制藥品使用執照之資格，不包括下列何者？","options":["(A) 藥師","(B) 牙醫師","(C) 獸醫師","(D) 醫師"],"answer":0,"image":""},{"id":"ph6-115-2-39","subject":"ph6","topic":"藥事法規-管制藥品與毒品危害防制","meta":"115年第2次第39題","year":115,"session":2,"number":39,"question":"依管制藥品管理條例，有關管制藥品管理之敘述，下列何者錯誤？","options":["(A) 管制藥品減損時，管制藥品管理人應立即報請當地衛生主管機關查核，並自減損之日起七日內，將減損藥品品量，檢同當地衛生主管機關證明文件，向衛生福利部食品藥物管理署申報","(B) 領有管制藥品登記證者，其受停業處分時，應自受處分之日起十五日內，將管制藥品收支、銷燬、減損及結存情形，分別向當地衛生主管機關及衛生福利部食品藥物管理署申報","(C) 為辦理第三級管制藥品銷燬作業而運輸，應檢同當地衛生主管機關證明文件，向衛生福利部食品藥物管理署申請核發憑照","(D) 領有管制藥品登記證者，其申請歇業時，可將結存之管制藥品轉讓予其他領有管制藥品登記證者，並報請當地衛生主管機關查核無誤"],"answer":2,"image":""},{"id":"ph6-115-2-40","subject":"ph6","topic":"藥事法規-管制藥品與毒品危害防制","meta":"115年第2次第40題","year":115,"session":2,"number":40,"question":"有關「管制藥品」與「毒品」的列管標準與程序，以及其分級品項，下列敘述何者錯誤？","options":["(A) 「管制藥品」與「毒品」均分四級管理","(B) 「管制藥品」與「毒品」的分級與品項，均由法務部會同衛生福利部組成審議委員會，每三個月定期檢討","(C) 毒品審議委員會得將具有成癮性、濫用性、對社會危害性顧慮之虞之麻醉藥品與其製品進行審議","(D) 部分「管制藥品」與「毒品」之分級與品項並不相同"],"answer":1,"image":""},{"id":"ph6-115-2-41","subject":"ph6","topic":"藥事法規-化粧品衛生安全管理法","meta":"115年第2次第41題","year":115,"session":2,"number":41,"question":"依化粧品衛生安全管理法之相關規定，下列敘述何者錯誤？","options":["(A) 主管機關得派員進入化粧品業者之處所，抽查其設施、產品資訊檔案、產品供應來源與流向資料、相關紀錄及文件等資料","(B) 化粧品業者應建立與保存產品直接供應來源及流向之資料，亦包含直接販賣至消費者之產品流向資料","(C) 為加強輸入化粧品之邊境管理，衛生福利部得對有害衛生安全之虞之化粧品，公告一定種類或品項，經抽查、抽樣檢驗合格後，始得輸入","(D) 化粧品製造場所應符合化粧品製造工廠設廠標準"],"answer":1,"image":""},{"id":"ph6-115-2-42","subject":"ph6","topic":"藥事法規-化粧品衛生安全管理法","meta":"115年第2次第42題","year":115,"session":2,"number":42,"question":"依化粧品衛生安全管理法，有關化粧品之外包裝或容器應明顯標示事項之規定，下列何者錯誤？","options":["(A) 應以中文或國際通用符號標示，但全成分名稱，得以英文標示","(B) 因外包裝或容器表面積過小致不能標示者，應於標籤、仿單或以其他方式刊載","(C) 標示格式、方式及其他應遵行事項，由地方衛生主管機關公告之","(D) 應明顯標示製造或輸入業者之名稱、地址及電話號碼"],"answer":2,"image":""},{"id":"ph6-115-2-43","subject":"ph6","topic":"藥事法規-藥害救濟與罕見疾病","meta":"115年第2次第43題","year":115,"session":2,"number":43,"question":"依罕見疾病防治及藥物法，有關罕見疾病及藥物審議會之辦理事項，下列何者錯誤？","options":["(A) 罕見疾病認定之審議及防治之諮詢","(B) 罕見疾病藥物致生藥害之救濟申請案之審議","(C) 治療特定疾病之非罕見疾病藥物之審議","(D) 罕見疾病藥物及維持生命所需之特殊營養食品認定之審議"],"answer":1,"image":""},{"id":"ph6-115-2-44","subject":"ph6","topic":"藥事法規-藥害救濟與罕見疾病","meta":"115年第2次第44題","year":115,"session":2,"number":44,"question":"某病人依醫師處方使用A藥後，發生皮膚紅疹，惟經查A藥仿單上未刊載相關不良反應，病人經停藥後，紅疹即獲緩解。當病人提出藥害救濟申請時，被判定不予救濟。該判定最可能是根據下列何種情事？","options":["(A) 因急救使用超量藥物致生損害","(B) 藥物不良反應未達死亡、障礙或嚴重疾病之程度","(C) 因使用試驗用藥物而受害","(D) 常見且可預期之藥物不良反應"],"answer":1,"image":""},{"id":"ph6-115-2-45","subject":"ph6","topic":"藥事法規-藥害救濟與罕見疾病","meta":"115年第2次第45題","year":115,"session":2,"number":45,"question":"因使用下列何者藥品所生之藥害，得依藥害救濟法之規定請求救濟？","options":["(A) 經主管機關核准輸入之COVID-19人體試驗用藥","(B) 領有藥品許可證之公費流感疫苗","(C) 因應緊急公共衛生情事之需要，經主管機關專案核准輸入之COVID-19疫苗","(D) 領有藥品許可證之流感抗病毒藥劑"],"answer":3,"image":""},{"id":"ph6-115-2-46","subject":"ph6","topic":"藥事法規-全民健康保險與藥事作業","meta":"115年第2次第46題","year":115,"session":2,"number":46,"question":"依全民健康保險藥物給付項目及支付標準，下列何者非屬全民健康保險給付之品項？①戒菸用貼片 ②預防接種所用之疫苗 ③避孕用藥 ④生髮劑","options":["(A) 僅③④","(B) 僅①②④","(C) 僅①②③","(D) ①②③④"],"answer":3,"image":""},{"id":"ph6-115-2-47","subject":"ph6","topic":"藥事法規-全民健康保險與藥事作業","meta":"115年第2次第47題","year":115,"session":2,"number":47,"question":"依全民健康保險法，藥物給付項目及支付標準，由保險人與相關代表共同擬訂，下列何者除外？","options":["(A) 被保險人","(B) 雇主","(C) 保險醫事服務提供者","(D) 藥物提供者"],"answer":3,"image":""},{"id":"ph6-115-2-48","subject":"ph6","topic":"藥事法規-全民健康保險與藥事作業","meta":"115年第2次第48題","year":115,"session":2,"number":48,"question":"依全民健康保險醫事服務機構特約及管理辦法，有關醫事機構與健保之特約，下列何者正確？","options":["(A) 藥局申請辦理健保給付之特約，應經藥事機構評鑑通過","(B) 精神復健醫事機構申請辦理精神疾病患者社區復健服務之特約，應經醫事機構評鑑通過","(C) 醫院於評鑑效期屆滿，未再參加評鑑時，應予終止特約","(D) 新設立之醫院未及參加當年主管機關依法令規定辦理之評鑑時，須經醫院評鑑通過再予特約"],"answer":1,"image":""},{"id":"ph6-115-2-49","subject":"ph6","topic":"藥事法規-全民健康保險與藥事作業","meta":"115年第2次第49題","year":115,"session":2,"number":49,"question":"依全民健康保險法，我國全民健康保險每年度醫療給付費用總額，由主管機關於年度開始六個月前擬訂其範圍，下列接續流程之敘述何者正確？","options":["(A) 經諮詢衛生福利部，報總統府核定","(B) 經諮詢衛生福利部，報立法院核定","(C) 經諮詢衛生福利部全民健康保險會，報行政院核定","(D) 經諮詢衛生福利部全民健康保險會，報立法院核定"],"answer":2,"image":""},{"id":"ph6-115-2-50","subject":"ph6","topic":"藥事法規-全民健康保險與藥事作業","meta":"115年第2次第50題","year":115,"session":2,"number":50,"question":"依全民健康保險藥物給付項目及支付標準，下列特殊材料何者得予支付？","options":["(A) 義眼","(B) 助聽器","(C) 輪椅","(D) 無菌注射針"],"answer":3,"image":""}];
